window.SAA_EXAMS = [{"id":"exam-set-01","file":"set-01.md","num":"問題セット01","title":"第1分野：セキュアなアーキテクチャの設計","questions":[{"n":1,"topic":"アクセス管理","level":2,"body":["EC2インスタンス上で稼働するアプリケーションが、Amazon S3バケットへファイルを書き込んでいます。現在はIAMユーザーのアクセスキーをアプリケーションの設定ファイルに記載しており、セキュリティ監査で是正を求められました。運用負荷を最小限に抑えつつ、この指摘に対応する方法はどれですか。"],"options":[{"l":"A","html":"アクセスキーを設定ファイルから環境変数へ移し、90日ごとに手動でローテーションする"},{"l":"B","html":"アクセスキーをAWS Secrets Managerに保存し、アプリケーション起動時にSDKで取得して、コードや設定ファイルには残さないよう変更する"},{"l":"C","html":"IAMロールをEC2にアタッチし、設定ファイルからアクセスキーを削除する"},{"l":"D","html":"S3バケットポリシーで、EC2インスタンスのパブリックIPアドレスからのアクセスのみを許可する"}],"answer":["C"],"multi":false,"req":"","key":"AWS上で動くコンピューティング（EC2・Lambda・ECS）に権限を与える手段は<b>IAMロール</b>です。ロールが配布する認証情報は一時的なもので自動的にローテーションされるため、長期のアクセスキーそのものが不要になります。","kw":"","reasons":[{"l":"A","html":"保管場所が変わっただけで長期認証情報は残り、手動ローテーションという運用負荷も残ります。"},{"l":"B","html":"Secrets Managerは「AWSの外部にある資格情報（DBのパスワードなど）」を管理する仕組みです。IAMロールを使えばアクセスキー自体が不要になるため、取得処理を実装する分だけ余計です。"},{"l":"D","html":"IPアドレスによる制限は認証ではありません。EIPの付け替えやSSRFによる悪用に耐えられず、監査指摘（長期認証情報の埋め込み）への回答にもなっていません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":2,"topic":"クロスアカウント","level":2,"body":["外部のコンサルティング会社に、本番AWSアカウントのリソース構成を読み取り専用で調査してもらうことになりました。相手先は自社のAWSアカウントを保有しています。最も安全な方法はどれですか。"],"options":[{"l":"A","html":"本番アカウントにIAMユーザーを作成し、アクセスキーをメールで共有する"},{"l":"B","html":"読み取り専用のIAMロールを作成し、信頼ポリシーで相手のアカウントIDを指定して、外部ID（External ID）の指定を必須にする"},{"l":"C","html":"ルートユーザーの認証情報を一時的に共有し、作業後にパスワードを変更する"},{"l":"D","html":"対象リソースのリソースポリシーで、すべてのプリンシパル（<code>\"Principal\": \"*\"</code>）からの読み取りを許可し、書き込みと削除は明示的に拒否する"}],"answer":["B"],"multi":false,"req":"","key":"別アカウントへのアクセス提供は<b>ロールの引き受け（AssumeRole）</b>が基本形です。相手が他社（第三者）の場合は<b>外部ID</b>を必須にして、「混乱した代理人（Confused Deputy）問題」を防ぎます。","kw":"外部ID（External ID）","reasons":[{"l":"A","html":"長期のアクセスキーが社外に渡り、失効管理もできません。"},{"l":"C","html":"ルートユーザーは最初の設定以降は使用せず、共有は論外です。"},{"l":"D","html":"インターネット全体へ公開することになり、要件（特定の相手に限定）を満たしません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":3,"topic":"組織統制","level":3,"body":["ある企業はAWS Organizationsで50個のアカウントを管理しています。データ主権の要件から、承認された3つのリージョン以外ではリソースを作成できないようにしたいと考えています。各メンバーアカウントには管理者権限を持つ開発者が存在し、<b>その開発者自身が制限を解除できてはなりません</b>。適切な方法はどれですか。"],"options":[{"l":"A","html":"各アカウントのIAMポリシーに、未承認リージョンを拒否する条件を追加する"},{"l":"B","html":"AWS Configルールで未承認リージョンのリソースを検出し、通知する"},{"l":"C","html":"各アカウントのIAMユーザーとロールに、未承認リージョンを含まないアクセス許可境界（Permissions Boundary）を設定する"},{"l":"D","html":"SCPで未承認リージョンのアクションを拒否し、OUに適用する"}],"answer":["D"],"multi":false,"req":"","key":"「<b>組織全体</b>に」「<b>メンバーアカウントの管理者でも解除できない</b>」上限を課せるのはSCPだけです。SCPはメンバーアカウントのルートユーザーにも効きます。","kw":"","reasons":[{"l":"A","html":"アカウント内の管理者が自分でポリシーを編集できるため、制限として成立しません。"},{"l":"B","html":"Configは<b>検出と是正</b>の仕組みであり、作成そのものを<b>予防</b>できません。設問は予防を求めています。"},{"l":"C","html":"アクセス許可境界は個々のIAMエンティティに付ける上限で、アカウント全体・組織全体への強制にはなりません（設定漏れも起こります）。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.5 AWS Organizations</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":4,"topic":"データ保護","level":1,"body":["非公開のS3バケットに保管しているレポートPDFを、取引先の担当者1名に対し、<b>24時間だけ</b>ダウンロードさせたいと考えています。取引先はAWSアカウントを持っていません。最小の手間で実現する方法はどれですか。"],"options":[{"l":"A","html":"有効期限付きの事前署名URLを発行して渡す"},{"l":"B","html":"バケットポリシーで当該オブジェクトだけをパブリック読み取り可能にし、24時間後にポリシーから削除して元に戻す"},{"l":"C","html":"CloudFrontディストリビューションを作成し、OACでバケットに接続する"},{"l":"D","html":"取引先向けのIAMユーザーを作成し、24時間後に削除する"}],"answer":["A"],"multi":false,"req":"","key":"「<b>特定のオブジェクト</b>を」「<b>期限付きで</b>」「<b>AWSアカウントを持たない相手に</b>」渡す要件は事前署名URLの定番です。","kw":"","reasons":[{"l":"B","html":"公開期間中は誰でもアクセスでき、設定の戻し忘れという運用事故も招きます。"},{"l":"C","html":"CloudFront＋OACはバケットを非公開のままCDN配信する構成で、1回限りの共有には過剰です（期限付き配布をCloudFrontで行うなら署名付きURL／Cookieを併用します）。"},{"l":"D","html":"AWSアカウントを持たない相手にIAMユーザーを発行する運用は負荷が高く、削除漏れのリスクもあります。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":5,"topic":"暗号化","level":2,"body":["本番稼働中のAmazon RDS for MySQLインスタンスが、作成時に暗号化を有効化していなかったことが判明しました。コンプライアンス要件を満たすため、保存データを暗号化する必要があります。適切な手順はどれですか。"],"options":[{"l":"A","html":"RDSコンソールで対象インスタンスの設定を変更し、暗号化を有効にする"},{"l":"B","html":"スナップショットを暗号化を指定してコピーし、そこから新しいインスタンスを復元して接続先を切り替える"},{"l":"C","html":"マルチAZ配置に変更する。スタンバイ作成時に暗号化が適用される"},{"l":"D","html":"暗号化を有効にしたリードレプリカを同一リージョンに作成し、同期が追いついた時点でプライマリへ昇格させる"}],"answer":["B"],"multi":false,"req":"","key":"RDS・EBSとも、<b>暗号化は作成時にしか指定できません</b>。既存リソースの暗号化は「スナップショット → 暗号化を指定してコピー → 復元」が定石です。","kw":"","reasons":[{"l":"A","html":"稼働中インスタンスの暗号化設定を後から有効化することはできません。"},{"l":"C","html":"マルチAZは可用性のための構成で、暗号化とは無関係です。"},{"l":"D","html":"未暗号化のインスタンスから暗号化されたリードレプリカを作成することはできません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":6,"topic":"暗号化","level":2,"body":["大量の小さなオブジェクトをS3に書き込むアプリケーションで、SSE-KMSを使用しています。AWS KMSのリクエスト数が急増して料金が膨らみ、スロットリングも発生し始めました。監査要件があるため、キーの利用履歴は引き続き記録する必要があります。適切な対処はどれですか。"],"options":[{"l":"A","html":"暗号化方式をSSE-S3に変更する"},{"l":"B","html":"暗号化をやめ、バケットポリシーでHTTPS通信のみ許可する"},{"l":"C","html":"カスタマー管理キーを複数作成し、オブジェクトごとに使い分ける"},{"l":"D","html":"S3バケットキー（S3 Bucket Keys）を有効化する"}],"answer":["D"],"multi":false,"req":"","key":"S3バケットキーはバケット単位で短期間有効なキーを生成し、<b>KMSへのリクエスト数を大幅に削減</b>します。SSE-KMSのままなので監査要件も維持できます。","kw":"","reasons":[{"l":"A","html":"SSE-S3ではCloudTrailにキー利用が記録されず、キーの管理・制御もできないため監査要件を満たせません。"},{"l":"B","html":"保存時の暗号化要件を放棄しており、要件違反です（HTTPSは転送時の保護）。"},{"l":"C","html":"キーを増やしてもリクエスト数の総量は変わらず、管理対象が増えるだけです。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.8 AWS KMS</a>"},{"n":7,"topic":"検出と監視","level":2,"body":["セキュリティチームから次の3つの要望が挙がりました。それぞれに最も適したサービスの組み合わせはどれですか。","1. S3バケット内に個人情報（クレジットカード番号など）が保存されていないか継続的に確認したい","2. EC2インスタンスのOSやライブラリに既知の脆弱性（CVE）がないか継続的に確認したい","3. 通常と異なる地域からのAPI呼び出しや、既知の不正IPとの通信を検知したい"],"options":[{"l":"A","html":"1: Amazon Macie ／ 2: Amazon Inspector ／ 3: Amazon GuardDuty"},{"l":"B","html":"1: Amazon GuardDuty ／ 2: Amazon Macie ／ 3: Amazon Inspector"},{"l":"C","html":"1: AWS Config ／ 2: Amazon Macie ／ 3: AWS CloudTrail"},{"l":"D","html":"1: Amazon Inspector ／ 2: Amazon GuardDuty ／ 3: AWS Security Hub"}],"answer":["A"],"multi":false,"req":"","key":"検出系の役割分担は固定です。<b>Macie＝S3の機密データ発見／Inspector＝脆弱性（CVE）診断／GuardDuty＝不審な振る舞いの検知</b>。","kw":"","reasons":[{"l":"B","html":"3つのサービスの役割がすべて入れ替わっています。"},{"l":"C","html":"Configは「リソース設定の変更履歴と準拠状況」、CloudTrailは「誰がAPIを呼んだかの記録」であり、機密データの発見や脅威検知そのものは行いません。"},{"l":"D","html":"Security Hubは各種検出結果を<b>集約</b>するサービスで、単独で脅威を検知するものではありません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.13 検出系の整理</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A セキュリティ・運用管理</a>"},{"n":8,"topic":"多層防御","level":2,"body":["Network Load Balancer（NLB）の背後で稼働するWebアプリケーションに対し、SQLインジェクションとクロスサイトスクリプティングの防御を追加するよう指示されました。適切な構成はどれですか。"],"options":[{"l":"A","html":"NLBの前段にCloudFrontまたはALBを置き、そこにWeb ACLを関連付ける"},{"l":"B","html":"NLBにAWS WAFのWeb ACLを関連付け、SQLインジェクション対策のマネージドルールを有効にする"},{"l":"C","html":"AWS Shield Standardを有効化する"},{"l":"D","html":"ネットワークACLで、攻撃元のIPアドレスを拒否する"}],"answer":["A"],"multi":false,"req":"","key":"AWS WAFを関連付けられるのは<b>CloudFront／ALB／API Gateway／AppSync／Cognitoユーザープール</b>です。<b>NLBやEC2には直接付けられない</b>ため、WAFを適用できる層を前段に置きます。","kw":"","reasons":[{"l":"B","html":"NLBはL4のロードバランサーで、WAF（L7）を関連付けられません。"},{"l":"C","html":"Shieldが守るのはDDoS攻撃であり、SQLインジェクションのようなアプリケーション層の攻撃には対応しません。"},{"l":"D","html":"NACLはIPアドレス単位の遮断で、リクエストの中身を検査できません。攻撃元IPが変わるたびに後追いになります。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.5 AWS WAF</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.3 多層防御</a>"},{"n":9,"topic":"多層防御","level":2,"body":["プライベートサブネット上のEC2インスタンスに対し、運用担当者がシェル接続して調査を行う必要があります。セキュリティポリシーにより、SSHキーの配布、踏み台ホストの設置、22番ポートの開放はいずれも認められていません。また、誰がいつ接続したかの記録が必要です。適切な方法はどれですか。"],"options":[{"l":"A","html":"クライアントVPNを構築し、VPN経由でSSH接続する"},{"l":"B","html":"パブリックサブネットに踏み台ホストを設置し、セキュリティグループで社内IPからのSSHのみ許可する"},{"l":"C","html":"AWS Systems Manager Session Managerを使用する"},{"l":"D","html":"インスタンスにパブリックIPを割り当て、EC2 Instance Connectで接続する"}],"answer":["C"],"multi":false,"req":"","key":"「<b>SSHキー不要・踏み台不要・インバウンドポート開放不要</b>」に「<b>操作ログが残る</b>」が揃えばSession Managerです。接続はSSMのアウトバウンド経路（またはVPCエンドポイント）を通ります。","kw":"","reasons":[{"l":"A","html":"VPNを経由しても、最終的にSSHキーと22番ポートが必要になります。"},{"l":"B","html":"踏み台の設置と22番ポートの開放という、禁止されている条件そのものです。"},{"l":"D","html":"パブリックIPの割り当てはプライベートサブネットの前提に反し、インバウンド許可も必要になります。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.4 AWS Systems Manager</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.3 多層防御</a>"},{"n":10,"topic":"責任共有モデル","level":1,"body":["AWSの責任共有モデルにおいて、<b>利用者（顧客）側の責任</b>に含まれるものはどれですか。"],"options":[{"l":"A","html":"RDSが稼働する物理ホストのハードウェアの保守と、故障した部品の交換"},{"l":"B","html":"IAMポリシーの設計と、保存データを暗号化するかどうかの判断"},{"l":"C","html":"S3の物理ディスクの廃棄・消磁"},{"l":"D","html":"Lambda関数が動作する実行環境の基盤OSへのセキュリティパッチの適用"}],"answer":["B"],"multi":false,"req":"","key":"マネージドの度合いが上がるほどAWS側の責任は増えますが、<b>データの分類・暗号化の要否・アクセス制御（IAM）は常に利用者の責任</b>です。","kw":"","reasons":[{"l":"A","html":"物理ハードウェアの保守は「クラウド<b>の</b>セキュリティ」としてAWSの責任です。"},{"l":"C","html":"データセンター内の物理媒体の処分もAWSの責任範囲です。"},{"l":"D","html":"Lambdaは実行環境そのものがマネージドであり、基盤OSのパッチはAWSが行います（EC2であれば利用者の責任になります）。"}],"refs":"<a href=\"#d1\" data-go=\"d1\">第11章 11.4 責任共有モデル</a>"}]},{"id":"exam-set-02","file":"set-02.md","num":"問題セット02","title":"第2分野：弾力性に優れたアーキテクチャの設計","questions":[{"n":1,"topic":"スケーリング","level":2,"body":["Auto Scalingグループ配下のEC2インスタンスで動くWebアプリケーションが、メモリリークにより応答しなくなる事象が発生しています。OSは起動したままでHTTPリクエストに500エラーを返し続けますが、Auto Scalingはインスタンスを置き換えません。ALBのターゲットグループでは当該インスタンスが<code>unhealthy</code>と表示されています。適切な対処はどれですか。"],"options":[{"l":"A","html":"スケーリングポリシーのクールダウン期間を短縮する"},{"l":"B","html":"EC2の詳細モニタリングを有効化し、ヘルスチェックに使うメトリクスの取得間隔を1分にする"},{"l":"C","html":"ヘルスチェックタイプを「ELB」に変更する"},{"l":"D","html":"ALBのアイドルタイムアウト値を延長する"}],"answer":["C"],"multi":false,"req":"","key":"Auto Scalingの既定のヘルスチェックは<b>EC2ステータスチェックのみ</b>で、「OSは生きているがアプリが異常」という状態を検知できません。<b>ELBヘルスチェックを有効化</b>して初めて、ロードバランサーの判定に基づく置き換えが行われます。","kw":"","reasons":[{"l":"A","html":"クールダウンは連続したスケーリング動作の間隔であり、異常インスタンスの検知とは無関係です。"},{"l":"B","html":"メトリクスの粒度が上がるだけで、置き換えの判断基準は変わりません。"},{"l":"D","html":"アイドルタイムアウトは接続の維持時間であり、異常の検知・置き換えには影響しません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.2 EC2 Auto Scaling</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a>"},{"n":2,"topic":"疎結合","level":2,"body":["ECサイトの注文APIが、セール開始直後の数分間にリクエストが急増し、バックエンドのRDSへの書き込みが追いつかずエラーを返しています。注文処理は即時応答が必須ではなく、数十秒以内に完了すれば許容されます。最も適切な設計変更はどれですか。"],"options":[{"l":"A","html":"ALBでスティッキーセッションを有効化する"},{"l":"B","html":"RDSインスタンスを、過去最大のピーク時の書き込みにも耐えられるサイズへ常時スケールアップしておく"},{"l":"C","html":"APIとバックエンドの間にSQSキューを挟み、ワーカーをキューの滞留数でAuto Scalingさせる"},{"l":"D","html":"CloudFrontを前段に配置し、注文APIのレスポンスをキャッシュする"}],"answer":["C"],"multi":false,"req":"","key":"「<b>急増を吸収したい</b>」「<b>即時応答は不要</b>」はキューによる<b>バッファリング</b>の典型です。ワーカー数は<code>ApproximateNumberOfMessagesVisible</code>などキューの滞留量を基準にスケールさせます。","kw":"","reasons":[{"l":"A","html":"スティッキーセッションは同一クライアントを同じターゲットへ固定する仕組みで、書き込み負荷は軽減しません。"},{"l":"B","html":"ピークに合わせた常時スケールアップは、平常時のコストが無駄になります。急増の度合いによっては上限にも当たります。"},{"l":"D","html":"書き込み（注文登録）はキャッシュできません。CloudFrontは読み取り配信の高速化のための仕組みです。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.2 疎結合アーキテクチャ</a>"},{"n":3,"topic":"疎結合","level":3,"body":["Amazon SQS標準キューからメッセージを取得して処理するワーカーで、<b>同じ注文が2回処理される</b>事象が発生しています。処理時間はメッセージによって異なり、長いものでは10分近くかかります。キューの可視性タイムアウトは既定の30秒のままです。根本的な対処はどれですか。"],"options":[{"l":"A","html":"可視性タイムアウトを最大処理時間より長くし（必要なら処理中に延長）、処理を冪等にする"},{"l":"B","html":"ロングポーリングを有効化し、受信待機時間を20秒にする"},{"l":"C","html":"デッドレターキュー（DLQ）を設定して<code>maxReceiveCount</code>を1にし、再配信されたメッセージを即座に隔離する"},{"l":"D","html":"FIFOキューへ移行する"}],"answer":["A"],"multi":false,"req":"","key":"重複処理の原因は、<b>処理が終わる前に可視性タイムアウトが切れて、同じメッセージが別のワーカーに再配信されること</b>です。タイムアウトを処理時間に合わせるのが直接の対処で、標準キューは「最低1回」の配信であるため冪等な実装も必要です。","kw":"","reasons":[{"l":"B","html":"ロングポーリングは空受信を減らしてAPIコール料金とレイテンシを改善する設定で、重複の原因には触れていません。"},{"l":"C","html":"DLQは失敗メッセージの隔離先です。<code>maxReceiveCount</code>を1にすると、一度でも再配信されたメッセージが即座に隔離され、正常な処理まで失われます。"},{"l":"D","html":"FIFOキューは順序保証と重複排除を提供しますが、スループット上限（300 TPS）という制約が付きます。可視性タイムアウトが処理時間より短い問題は解決せず、原因への対処になっていません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a>"},{"n":4,"topic":"イベント駆動","level":2,"body":["S3バケットに画像がアップロードされたことを契機に、<b>サムネイル生成</b>と<b>検索インデックスの更新</b>という2つの独立した処理を実行したいと考えています。一方の処理が失敗しても、もう一方に影響せず、それぞれ独立して再試行できる必要があります。適切な構成はどれですか。"],"options":[{"l":"A","html":"S3イベント通知をSNSへ送り、2つのSQSキューで受ける（ファンアウト）"},{"l":"B","html":"S3イベント通知で単一のLambda関数を起動し、その関数内で両方の処理を順番に実行する"},{"l":"C","html":"S3イベント通知を1つのSQSキューへ送り、2種類のワーカーが同じキューをポーリングする"},{"l":"D","html":"同じイベント種別・同じプレフィックスに対してS3イベント通知を2つ設定し、それぞれ別のLambda関数を起動する"}],"answer":["A"],"multi":false,"req":"","key":"1つのイベントを複数の処理系へ配り、<b>各処理系が独立して再試行できる</b>形が<b>SNSファンアウト（SNS＋複数SQS）</b>です。","kw":"","reasons":[{"l":"B","html":"1つの関数に両処理を同居させると、片方の失敗がもう片方の再実行を巻き込みます（独立性がありません）。"},{"l":"C","html":"SQSのメッセージは1つのコンシューマーが取得すると他からは見えなくなるため、2種類の処理へ同じメッセージを届けられません。"},{"l":"D","html":"S3イベント通知は、同じイベント種別・同じプレフィックス範囲に対して重複する設定を作成できません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.2 Amazon SNS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.4 イベント駆動型アーキテクチャ</a>"},{"n":5,"topic":"災害対策","level":3,"body":["基幹システムのDR要件が「<b>RTO 10分以内、RPO 1分以内</b>」と定められました。コストは要件を満たす範囲で可能な限り低く抑える方針です。最も適切なDR戦略はどれですか。"],"options":[{"l":"A","html":"バックアップ＆リストア"},{"l":"B","html":"パイロットライト"},{"l":"C","html":"マルチサイト（アクティブ/アクティブ）"},{"l":"D","html":"ウォームスタンバイ"}],"answer":["D"],"multi":false,"req":"","key":"<b>要件を満たす戦略のうち、最も安価なものを選ぶ</b>のが原則です。ウォームスタンバイは縮小版の環境が常時稼働しているため、切り替えとスケールアウトで数分、非同期レプリケーションでRPOは数秒〜数分となり、要件を満たします。","kw":"","reasons":[{"l":"A","html":"被災後に環境を構築するためRTOは数時間〜数日となり、要件を満たしません。"},{"l":"B","html":"コンピュート層が停止状態のため、起動とプロビジョニングに数十分かかり、RTO 10分を満たせません。"},{"l":"C","html":"要件は満たしますが、両リージョンで本番環境を常時稼働させるため最もコストが高く、「可能な限り低く」という方針に反します。"}],"refs":"<a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a> ／ <a href=\"#foundations\" data-go=\"foundations\">第0章 0.3 RTOとRPOの指標</a>"},{"n":6,"topic":"高可用性","level":2,"body":["Amazon RDS for PostgreSQLで、日中に実行される集計レポートのクエリが重く、通常のトランザクション処理まで遅延しています。現在このDBはマルチAZ配置です。アプリケーションの変更は許容されます。適切な対処はどれですか。"],"options":[{"l":"A","html":"マルチAZ配置に変更し、スタンバイインスタンスへレポート用のクエリを向ける"},{"l":"B","html":"リードレプリカを作成し、レポートクエリの接続先をリードレプリカに変更する"},{"l":"C","html":"インスタンスクラスをより大きなものへ変更する"},{"l":"D","html":"毎朝スナップショットから別インスタンスを復元し、そこへレポートクエリを向ける"}],"answer":["B"],"multi":false,"req":"","key":"<b>読み取りのスケールはリードレプリカ</b>、<b>可用性はマルチAZ</b>という役割分担が頻出の対比です。分析系クエリをレプリカへ逃がせば、本番トランザクションへの影響を切り離せます。","kw":"","reasons":[{"l":"A","html":"マルチAZのスタンバイインスタンスは<b>読み取りにも使用できません</b>（待機専用）。"},{"l":"C","html":"一時的には改善しますが、負荷の性質が異なる処理が同居する構造は変わらず、コストも増え続けます。"},{"l":"D","html":"復元したインスタンスのデータは取得時点のもので、最新のデータを参照できません。運用も煩雑です。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":7,"topic":"ステートレス化","level":2,"body":["Auto Scalingグループで運用しているWebアプリケーションで、スケールインが発生するたびに一部の利用者がログアウトされてしまいます。セッション情報は各EC2インスタンスのローカルディスクに保存されています。根本的な解決策はどれですか。"],"options":[{"l":"A","html":"ALBのスティッキーセッションを有効化する"},{"l":"B","html":"セッション情報をElastiCache for RedisまたはDynamoDBへ外部化する"},{"l":"C","html":"セッション情報の保存先をEBSボリュームに変更する"},{"l":"D","html":"Auto Scalingグループの最小台数をピーク時に近い台数まで引き上げ、スケールインを起こりにくくする"}],"answer":["B"],"multi":false,"req":"","key":"水平スケーリングの前提は<b>ステートレス</b>であることです。セッションを共有ストアへ外出しすれば、どのインスタンスが終了しても利用者の状態は失われません。","kw":"","reasons":[{"l":"A","html":"スティッキーセッションは同じインスタンスへ誘導するだけで、そのインスタンスが終了すればセッションは失われます。"},{"l":"C","html":"EBSもインスタンスに紐づくため、終了時に同じ問題が起きます（単一AZの制約もあります）。"},{"l":"D","html":"台数を増やしてもスケールインは発生し、コストが増えるだけで根本原因は残ります。"}],"refs":"<a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a> ／ <a href=\"#database\" data-go=\"database\">第4章 4.4 Amazon ElastiCache</a>"},{"n":8,"topic":"高可用性","level":2,"body":["3つのアベイラビリティゾーンにまたがるVPCで、プライベートサブネットのEC2インスタンスがNAT Gateway経由で外部APIを呼び出しています。あるAZでNAT Gatewayに障害が発生したところ、<b>すべてのAZ</b>のインスタンスが外部と通信できなくなりました。再発を防ぐ構成はどれですか。"],"options":[{"l":"A","html":"NAT Gatewayをプライベートサブネットへ移動する"},{"l":"B","html":"NAT GatewayをNATインスタンスに置き換え、Auto Scalingグループ（最小1台）で自動復旧させる"},{"l":"C","html":"インターネットゲートウェイをAZごとに追加する"},{"l":"D","html":"各AZにNAT Gatewayを置き、各AZのルートテーブルを自AZのNAT Gatewayに向ける"}],"answer":["D"],"multi":false,"req":"","key":"NAT Gatewayは<b>AZ単位のサービス</b>です。1台を全AZで共用すると、そのAZの障害が全体に波及します。<b>AZごとに配置し、ルートテーブルも自AZ向きにする</b>のが定石です。","kw":"","reasons":[{"l":"A","html":"NAT Gatewayはパブリックサブネットに配置する必要があります。プライベートサブネットに置くと外部へ出られません。"},{"l":"B","html":"NATインスタンスは自前でパッチ・スケール・冗長化を管理する必要があり、可用性の観点でマネージドのNAT Gatewayより不利です。"},{"l":"C","html":"インターネットゲートウェイはVPCに1つで、AZの概念を持たず、AWS側で冗長化されています。増設という概念がありません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.1 VPCの基礎</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":9,"topic":"高可用性","level":3,"body":["オンラインゲームのマッチングサーバー（TCP/UDPを使用）を2つのリージョンで運用しています。現在はRoute 53のフェイルオーバールーティングで切り替えていますが、<b>DNSキャッシュの影響で切り替えに数分かかる</b>ことが問題視されています。より短時間で切り替える方法はどれですか。"],"options":[{"l":"A","html":"Route 53のレコードのTTLを0秒に設定する"},{"l":"B","html":"AWS Global Acceleratorを導入する"},{"l":"C","html":"Amazon CloudFrontを前段に配置し、2つのリージョンのオリジンでオリジンフェイルオーバーを設定する"},{"l":"D","html":"ALBのクロスゾーン負荷分散を有効化する"}],"answer":["B"],"multi":false,"req":"","key":"Global Acceleratorは<b>固定のAnycast IP</b>を入口とし、ヘルスチェックに基づいてAWSバックボーン内で転送先を切り替えるため、<b>DNSのTTLに依存せず数十秒で</b>フェイルオーバーできます。TCP/UDPにも対応します。","kw":"","reasons":[{"l":"A","html":"TTLを短くしてもクライアントやリゾルバのキャッシュ挙動に依存し、確実な短縮にはなりません。クエリ料金と負荷も増えます。"},{"l":"C","html":"CloudFrontはHTTP/HTTPSの配信を対象とするサービスで、TCP/UDPのゲームトラフィックには適しません。"},{"l":"D","html":"クロスゾーン負荷分散はAZ間の分散設定であり、リージョン間の切り替えとは無関係です。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFrontとGlobal Accelerator</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":10,"topic":"イベント駆動","level":2,"body":["Amazon S3のイベント通知で起動されるLambda関数が、下流サービスの一時障害で失敗しました。障害の復旧後に確認すると、<b>その間のイベントが失われていた</b>ことが判明しました。再発を防ぐ設定はどれですか。"],"options":[{"l":"A","html":"Lambda関数に送信先（Destinations）のonFailure、またはDLQを設定する"},{"l":"B","html":"Lambda関数のタイムアウト値を最大の15分に延長する"},{"l":"C","html":"予約済み同時実行数を引き上げる"},{"l":"D","html":"S3イベント通知からのLambda関数の呼び出しを同期呼び出しに変更し、失敗を即時に検知する"}],"answer":["A"],"multi":false,"req":"","key":"S3イベント通知は<b>非同期呼び出し</b>です。非同期呼び出しは自動で2回再試行されますが、それでも失敗したイベントは<b>破棄されます</b>。失われないようにするにはDLQまたはLambda Destinations（onFailure）で受け皿を用意します。","kw":"","reasons":[{"l":"B","html":"失敗の原因は下流サービスの障害であり、実行時間の不足ではありません。"},{"l":"C","html":"同時実行数はスロットリング対策で、失敗イベントの保全とは別問題です。"},{"l":"D","html":"S3イベント通知の呼び出しモデルは非同期で固定されており、利用者が同期呼び出しへ変更することはできません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.6 AWS Lambda</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.4 イベント駆動型アーキテクチャ</a>"}]},{"id":"exam-set-03","file":"set-03.md","num":"問題セット03","title":"第3分野：高パフォーマンスなアーキテクチャの設計","questions":[{"n":1,"topic":"データベース性能","level":2,"body":["Amazon DynamoDBをバックエンドに使うモバイルアプリで、商品マスタへの同じ読み取りリクエストが大量に発生しています。現在の応答時間は一桁ミリ秒ですが、<b>マイクロ秒台</b>まで短縮したいという要件が出ました。アプリケーションの改修は最小限に抑えたいと考えています。適切な対処はどれですか。"],"options":[{"l":"A","html":"グローバルセカンダリインデックス（GSI）を追加する"},{"l":"B","html":"Amazon ElastiCache for Memcachedを導入し、アプリケーション側にキャッシュ読み書きのロジックを実装する"},{"l":"C","html":"DynamoDB Accelerator（DAX）を導入する"},{"l":"D","html":"読み取りを強い整合性（Strongly Consistent Read）に変更する"}],"answer":["C"],"multi":false,"req":"","key":"<b>DynamoDB専用のインメモリキャッシュがDAX</b>です。DynamoDBと互換のAPIを持つため、アプリケーションの改修が最小限で済み、キャッシュヒット時はマイクロ秒台で応答します。","kw":"","reasons":[{"l":"A","html":"GSIは別のキーで検索するための仕組みで、同一データの読み取りを高速化するものではありません。"},{"l":"B","html":"実現は可能ですが、キャッシュの読み書きと無効化のロジックをアプリ側に実装する必要があり、「改修は最小限」という要件に反します。"},{"l":"D","html":"強い整合性の読み取りは<b>消費キャパシティが2倍</b>になり、レイテンシも改善しません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":2,"topic":"データベース性能","level":2,"body":["トラフィック増加にともない、AWS LambdaからAmazon RDS for MySQLへの接続が急増し、<code>Too many connections</code>エラーが発生するようになりました。クエリ自体は軽量です。適切な対処はどれですか。"],"options":[{"l":"A","html":"RDS Proxyを導入し、Lambdaの接続先をプロキシに変更する"},{"l":"B","html":"リードレプリカを追加し、参照クエリを分散する"},{"l":"C","html":"Lambda関数のメモリ割り当てを増やす"},{"l":"D","html":"Lambda関数の予約済み同時実行数を上限まで引き上げ、スロットリングによる失敗をなくす"}],"answer":["A"],"multi":false,"req":"","key":"Lambdaは同時実行のたびに新しい接続を張るため、<b>接続数の枯渇</b>が起こります。RDS Proxyが接続をプールして再利用するため、DB側の接続数を抑えられます（フェイルオーバー時間の短縮という利点もあります）。","kw":"","reasons":[{"l":"B","html":"レプリカを増やしても、Lambdaが張る接続の総数が減るわけではありません。書き込みは依然としてプライマリに集中します。"},{"l":"C","html":"メモリ増強はCPU性能に比例しますが、接続数の問題とは無関係です。"},{"l":"D","html":"同時実行数を増やすと接続数はさらに増え、問題が悪化します。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":3,"topic":"ストレージ性能","level":2,"body":["大量の並列ジョブが、S3バケットの単一プレフィックス配下（<code>s3://bucket/data/</code>）へ毎秒数千件の書き込みを行った結果、<code>503 Slow Down</code>エラーが返るようになりました。適切な対処はどれですか。"],"options":[{"l":"A","html":"バケットのバージョニングを無効化する"},{"l":"B","html":"S3 Transfer Accelerationを有効化する"},{"l":"C","html":"ストレージクラスをS3 Intelligent-Tieringに変更する"},{"l":"D","html":"オブジェクトキーを複数のプレフィックスへ分散させる"}],"answer":["D"],"multi":false,"req":"","key":"S3の性能上限は<b>プレフィックス単位</b>（毎秒3,500 PUT／5,500 GET が目安）です。プレフィックスを分散させれば、その分だけ並列度を上げられます。","kw":"","reasons":[{"l":"A","html":"バージョニングはリクエストレートの制限とは無関係です。"},{"l":"B","html":"Transfer Accelerationは<b>地理的に遠い場所からの転送</b>をエッジ経由で高速化する機能で、プレフィックス単位のスロットリングには効きません。"},{"l":"C","html":"ストレージクラスは保管コストと取り出し特性の話で、リクエストレートの上限は変わりません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":4,"topic":"ストレージ性能","level":2,"body":["ゲノム解析のHPCワークロードで、数百台のEC2インスタンスが<b>数百GB/秒</b>のスループットで同一のデータセットへアクセスする必要があります。元データはS3バケットに保管されており、解析結果もS3へ書き戻します。適切なストレージはどれですか。"],"options":[{"l":"A","html":"Amazon EFS（汎用パフォーマンスモード）"},{"l":"B","html":"Amazon FSx for Lustre（S3と連携）"},{"l":"C","html":"Amazon EBS io2 Block Express"},{"l":"D","html":"各インスタンスからS3 APIで直接読み書きする"}],"answer":["B"],"multi":false,"req":"","key":"<b>HPC・機械学習・数百GB/秒・S3との連携</b>というキーワードはFSx for Lustreです。S3バケットをリンクしてデータを遅延ロードし、結果を書き戻せます。","kw":"","reasons":[{"l":"A","html":"EFSは汎用の共有ファイルストレージで、HPC向けの数百GB/秒には設計されていません。"},{"l":"C","html":"EBSは<b>単一インスタンスにアタッチする</b>ブロックストレージで、数百台からの同時共有には使えません。"},{"l":"D","html":"オブジェクトAPIでの直接アクセスは、POSIXファイルシステムを前提とする解析ソフトの要件を満たさず、要求スループットにも届きません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.4 Amazon FSx</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":5,"topic":"コンピューティング性能","level":2,"body":["t3.mediumインスタンスで稼働する分析バッチが、実行開始から数十分後に極端に遅くなる事象が繰り返し発生しています。CloudWatchで確認したところ、CPUクレジット残高がゼロになっていました。処理は常時CPUを高使用率で消費します。適切な対処はどれですか。"],"options":[{"l":"A","html":"Auto Scalingグループの最小台数を増やして負荷を分散する"},{"l":"B","html":"メモリ最適化インスタンス（R系）へ変更し、メモリを増やす"},{"l":"C","html":"EBSボリュームをgp2からgp3へ変更し、IOPSを上げる"},{"l":"D","html":"コンピューティング最適化インスタンス（C系）へ変更する"}],"answer":["D"],"multi":false,"req":"","key":"T系はバースト可能な汎用インスタンスで、<b>継続的に高いCPU使用率が必要なワークロードには不向き</b>です。常時CPUを使う処理はC系へ移します（暫定的にはT系のアンリミテッドモードでも回避できますが、追加料金が発生します）。","kw":"","reasons":[{"l":"A","html":"台数を増やしても1台あたりのCPUクレジット枯渇は起き続け、コストだけが増えます。"},{"l":"B","html":"ボトルネックはCPUでありメモリではありません。"},{"l":"C","html":"ストレージI/Oではなく、CPUクレジットの枯渇が原因です。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.2 コンピューティングとパフォーマンス</a>"},{"n":6,"topic":"ネットワーク性能","level":2,"body":["東京リージョンでホストしているWebアプリケーション（HTTPS）を、欧州と北米の利用者にも高速に提供したいと考えています。コンテンツは画像などの静的アセットと、APIによる動的レスポンスの両方を含みます。オリジンは東京リージョンのまま維持します。適切な構成はどれですか。"],"options":[{"l":"A","html":"AWS Global Acceleratorを導入する"},{"l":"B","html":"Amazon CloudFrontを導入し、静的アセットをキャッシュしつつ動的コンテンツも配信する"},{"l":"C","html":"各リージョンにEC2インスタンスを立て、Route 53のレイテンシーベースルーティングで振り分ける"},{"l":"D","html":"ALBのクロスゾーン負荷分散を有効化する"}],"answer":["B"],"multi":false,"req":"","key":"HTTP/HTTPSで、<b>静的アセットのキャッシュ</b>が効く構成ではCloudFrontが第一候補です。動的コンテンツもエッジからオリジンまでAWSバックボーンを経由するため高速化されます。","kw":"","reasons":[{"l":"A","html":"Global Acceleratorは<b>キャッシュを行いません</b>。静的アセットのオフロード効果が得られず、この要件ではCloudFrontに劣ります（TCP/UDPや固定IPが要件のときに選びます）。"},{"l":"C","html":"要件は「オリジンは東京のまま」です。マルチリージョン展開はデータ同期を含めて大掛かりで、前提に反します。"},{"l":"D","html":"クロスゾーン負荷分散はAZ間の均等分散の設定で、地理的なレイテンシとは無関係です。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFrontとGlobal Accelerator</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.4 ネットワークパフォーマンスの最適化</a>"},{"n":7,"topic":"分析性能とコスト","level":2,"body":["S3に日次で蓄積されるCSV形式のアクセスログ（合計数TB）に対し、Amazon Athenaで日付を絞った集計を実行していますが、クエリが遅く課金額も大きくなっています。最も効果的な改善策はどれですか。"],"options":[{"l":"A","html":"データをParquet形式へ変換し、日付でパーティション分割する"},{"l":"B","html":"Amazon Redshiftクラスターを構築し、全データをロードする"},{"l":"C","html":"Athenaのワーカー数（並列度）を引き上げる"},{"l":"D","html":"対象バケットのストレージクラスをS3 Standard-IAへ変更する"}],"answer":["A"],"multi":false,"req":"","key":"Athenaは<b>スキャンしたデータ量</b>で課金されます。列指向フォーマット（Parquet／ORC）への変換と圧縮、そして<b>パーティション分割</b>でスキャン量そのものを減らすのが、速度とコストの両方に効く定石です。","kw":"","reasons":[{"l":"B","html":"Redshiftは継続的・大規模なBI向けで、日次のアドホック集計には過剰です。クラスターの運用コストも発生します。"},{"l":"C","html":"Athenaはサーバーレスで、利用者が並列度を設定する仕組みはありません。"},{"l":"D","html":"ストレージクラスの変更は保管コストにしか影響せず、スキャン量もクエリ速度も変わりません。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.3 Amazon Athena</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":8,"topic":"データベース性能","level":3,"body":["Amazon DynamoDBのテーブルで、プロビジョニングされたキャパシティには十分な余裕があるにもかかわらず、特定の時間帯に<code>ProvisionedThroughputExceededException</code>が頻発します。調査の結果、書き込みの大半が同一のパーティションキー値（当日の日付）に集中していました。適切な対処はどれですか。"],"options":[{"l":"A","html":"プロビジョニングされた書き込みキャパシティを2倍に増やし、Auto Scalingの上限も引き上げる"},{"l":"B","html":"パーティションキーのカーディナリティを高める（ランダムなサフィックスの付与など）"},{"l":"C","html":"読み取りを強い整合性に変更する"},{"l":"D","html":"ローカルセカンダリインデックス（LSI）を追加する"}],"answer":["B"],"multi":false,"req":"","key":"DynamoDBのキャパシティは<b>パーティションごとに分配</b>されます。特定のキーに書き込みが集中する「ホットパーティション」では、テーブル全体に余裕があってもスロットリングします。<b>キー設計の見直し</b>が根本対処です。","kw":"","reasons":[{"l":"A","html":"全体のキャパシティを増やしても、偏った1つのパーティションに割り当てられる分は限られるため、根本的な解決になりません。"},{"l":"C","html":"整合性モデルは読み取りの設定であり、書き込みの偏りとは無関係です（消費キャパシティが増えるだけです）。"},{"l":"D","html":"LSIは同一パーティションキー内で別のソートキーを使うための仕組みで、書き込みの集中をむしろ助長します。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":9,"topic":"検索性能","level":2,"body":["ECサイトの商品検索が、RDS上で<code>LIKE '%キーワード%'</code>による全件走査を行っているため非常に遅く、表記ゆれにも対応できていません。検索語のハイライトや関連度順の並び替えも求められています。適切なサービスはどれですか。"],"options":[{"l":"A","html":"RDSのリードレプリカ"},{"l":"B","html":"Amazon Athena"},{"l":"C","html":"Amazon OpenSearch Service"},{"l":"D","html":"Amazon ElastiCache for Redis"}],"answer":["C"],"multi":false,"req":"","key":"<b>全文検索・あいまい検索・関連度順</b>という要件はOpenSearch Serviceです（ログのリアルタイム分析にも使われます）。","kw":"","reasons":[{"l":"A","html":"レプリカを追加しても全件走査というクエリの性質は変わらず、表記ゆれにも対応できません。"},{"l":"B","html":"AthenaはS3上のデータへアドホックにSQLを実行するサービスで、対話的な検索機能の基盤には向きません。"},{"l":"D","html":"ElastiCacheはキーに対する高速な読み書きが得意で、全文検索エンジンではありません。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.6 Amazon OpenSearch Service</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":10,"topic":"ネットワーク性能","level":3,"body":["数値流体解析（CFD）のHPCジョブを、MPIで通信する多数のEC2インスタンス上で実行します。ノード間通信のレイテンシが実行時間を左右するため、これを最小化する必要があります。適切な構成はどれですか。"],"options":[{"l":"A","html":"クラスタープレイスメントグループに配置し、Elastic Fabric Adapter（EFA）を利用する"},{"l":"B","html":"スプレッドプレイスメントグループに配置する"},{"l":"C","html":"インスタンスを複数のアベイラビリティゾーンへ分散配置する"},{"l":"D","html":"AWS Global Acceleratorを経由させる"}],"answer":["A"],"multi":false,"req":"","key":"<b>HPC・MPI・ノード間の低レイテンシ</b>は、クラスタープレイスメントグループ（単一AZ内で近接配置）とEFA（OSカーネルを迂回する高速なノード間通信）の組み合わせです。","kw":"","reasons":[{"l":"B","html":"スプレッドは少数の重要インスタンスを<b>別々のハードウェアへ分散</b>する配置で、可用性のための選択です。レイテンシはむしろ不利になります。"},{"l":"C","html":"AZ分散は可用性を高めますが、AZ間の物理距離のぶんレイテンシが増えます。"},{"l":"D","html":"Global Acceleratorはインターネット経由の利用者アクセスを高速化するサービスで、VPC内のノード間通信には関与しません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.4 ネットワークパフォーマンスの最適化</a>"}]},{"id":"exam-set-04","file":"set-04.md","num":"問題セット04","title":"第4分野：コストを最適化したアーキテクチャの設計","questions":[{"n":1,"topic":"ストレージのコスト","level":2,"body":["医療系の企業が、診断画像をS3に保存しています。アップロードから30日間は頻繁に参照されますが、その後はほとんど参照されません。ただし監査対応のため、<b>まれに発生する照会には数分以内に取り出せる</b>必要があり、データは7年間保持しなければなりません。最もコスト効率の高い構成はどれですか。"],"options":[{"l":"A","html":"すべてのオブジェクトをS3 Standardのまま保持し、7年後に削除する"},{"l":"B","html":"ライフサイクルポリシーで、30日後にS3 Glacier Deep Archiveへ移行し、7年後に失効させる"},{"l":"C","html":"ライフサイクルポリシーで、30日後にS3 Standard-IA、90日後にS3 Glacier Flexible Retrievalへ移行し、7年後に失効させる"},{"l":"D","html":"ライフサイクルポリシーで、30日後にS3 One Zone-IAへ移行して7年間保持する"}],"answer":["C"],"multi":false,"req":"","key":"取り出し要件が「<b>数分以内</b>」なので、Glacier Flexible Retrievalの迅速取り出し（1〜5分）で満たせます。段階的に安いクラスへ落とすのがライフサイクルの基本形です。","kw":"","reasons":[{"l":"A","html":"最も高価なクラスのまま7年間保持することになり、コスト最適化になっていません。"},{"l":"B","html":"Deep Archiveの取り出しは標準12時間・大容量48時間で、「数分以内」を満たせません。"},{"l":"D","html":"One Zone-IAは単一AZ保管のため、AZ障害でデータが失われます。監査対応の長期保管には適しません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":2,"topic":"コンピューティングのコスト","level":2,"body":["動画変換のバッチ処理を、EC2インスタンス群で毎晩実行しています。処理は<b>中断されても最初からやり直せる</b>設計で、完了までの時間には余裕があります。コストを最小化する方法はどれですか。"],"options":[{"l":"A","html":"スポットインスタンスを利用する（中断通知を受けたら処理を退避する）"},{"l":"B","html":"オンデマンドインスタンスで3年間のリザーブドインスタンスを購入する"},{"l":"C","html":"Savings Plansを1年分購入する"},{"l":"D","html":"Dedicated Hostを利用する"}],"answer":["A"],"multi":false,"req":"","key":"「<b>中断されても良い</b>」「時間に余裕がある」はスポットインスタンスの適用条件です。最大90%の割引が得られます。","kw":"","reasons":[{"l":"B","html":"RIは「常時稼働するワークロード」に対する前払い割引です。夜間のみの実行では稼働率が低く、割引を活かせません。"},{"l":"C","html":"Savings Plansも継続利用へのコミットメントで、中断可能なバッチには過剰です（ベース負荷があるならスポットと併用します）。"},{"l":"D","html":"Dedicated Hostは物理サーバーの専有で、ライセンス持ち込み等が目的です。最も高価な選択肢です。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":3,"topic":"ネットワークのコスト","level":3,"body":["プライベートサブネットの数百台のEC2インスタンスが、S3バケットへ毎日数TBのログを書き込んでいます。請求を確認すると、NAT Gatewayのデータ処理料金が突出していました。この費用を削減する方法はどれですか。"],"options":[{"l":"A","html":"S3用のゲートウェイ型VPCエンドポイントを作成する"},{"l":"B","html":"S3用のインターフェース型VPCエンドポイント（PrivateLink）を作成する"},{"l":"C","html":"NAT Gatewayの台数を1台に集約する"},{"l":"D","html":"EC2インスタンスにパブリックIPを割り当て、IGW経由で直接S3へ書き込む"}],"answer":["A"],"multi":false,"req":"","key":"S3とDynamoDB向けの<b>ゲートウェイ型エンドポイントは追加料金が無料</b>で、通信がNAT Gatewayを経由しなくなるため、処理料金とデータ転送料の両方を削減できます。作成時に対象のルートテーブルを選ぶと、S3のプレフィックスリスト宛ての経路が自動で追加されます。","kw":"","reasons":[{"l":"B","html":"インターフェース型はENIの時間料金とデータ処理料金が発生します。S3宛てならゲートウェイ型のほうが安く、要件に合致します。"},{"l":"C","html":"台数を減らすと単一AZ障害の影響範囲が広がるうえ、削減されるのは時間料金だけで、支配的なデータ処理料金は変わりません。"},{"l":"D","html":"プライベートサブネットの前提に反し、セキュリティが大きく後退します。データ転送料も発生します。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":4,"topic":"データベースのコスト","level":2,"body":["社内の申請システムのデータベースが、平日の日中のみ利用され、夜間と週末はまったくアクセスがありません。現在はAurora PostgreSQLのプロビジョニング済みインスタンス（db.r6g.large）が24時間稼働しています。可用性要件は変わりません。最もコスト効率の高い構成はどれですか。"],"options":[{"l":"A","html":"Amazon DynamoDBへ移行する"},{"l":"B","html":"インスタンスサイズをdb.t4g.mediumへ変更する"},{"l":"C","html":"夜間と週末はAuroraクラスターを停止し、平日の朝に自動で起動する運用をスクリプト化する"},{"l":"D","html":"Aurora Serverless v2に変更する"}],"answer":["D"],"multi":false,"req":"","key":"「<b>利用が断続的で、無負荷の時間帯が長い</b>」場合はAurora Serverless v2が適します。ACU単位で細かく増減し、アイドル時のコストを抑えられます。","kw":"","reasons":[{"l":"A","html":"リレーショナルな申請ワークフローをDynamoDBへ移すのはアプリケーションの全面改修を伴い、コスト最適化の手段としては過剰です。"},{"l":"B","html":"サイズを下げても24時間分の課金は続き、ピーク時の性能も落ちます。"},{"l":"C","html":"Auroraクラスターの停止は最長7日で自動的に再開されるため、週末をまたぐ運用では停止し続けられません。スクリプトの保守も必要です。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.2 Amazon Aurora</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.4 データベースのコスト最適化</a>"},{"n":5,"topic":"コスト管理ツール","level":2,"body":["経理部門から次の2つの要望がありました。<b>2つ選択してください。</b>","1. 今月の利用額が予算の80%に達した時点でメール通知を受け取りたい","2. 過去12か月の推移をサービス別・タグ別に分析し、来月の利用額の予測を見たい","それぞれに適したサービスはどれですか。"],"options":[{"l":"A","html":"AWS Budgets（要望1）"},{"l":"B","html":"AWS Cost and Usage Report（要望1）"},{"l":"C","html":"AWS Cost Explorer（要望2）"},{"l":"D","html":"AWS Trusted Advisor（要望2）"},{"l":"E","html":"AWS Compute Optimizer（要望1）"}],"answer":["A","C"],"multi":true,"req":"","key":"<b>事前に止める＝Budgets（しきい値でアラート）／使った結果を分析する＝Cost Explorer（推移の可視化と予測）</b>という役割分担です。","kw":"","reasons":[{"l":"B","html":"CURは時間単位・リソース単位の最も詳細な請求データをS3へ出力する仕組みで、それ自体に通知機能はありません（Athena等で分析します）。"},{"l":"D","html":"Trusted Advisorはコスト・性能・セキュリティ・耐障害性・クォータの5観点の点検で、予算超過の通知や推移分析は行いません。"},{"l":"E","html":"Compute Optimizerは機械学習でEC2などの適正サイズを推奨するサービスで、予算アラートの機能はありません。"}],"refs":"<a href=\"#d4\" data-go=\"d4\">第14章 14.1 コスト管理ツールの使い分け</a> ／ <a href=\"#others\" data-go=\"others\">第10章 10.9〜10.11 コスト管理サービス</a>"},{"n":6,"topic":"コンピューティングのコスト","level":2,"body":["スタートアップが、1日あたり数千回だけ実行される画像リサイズ処理をEC2の常時稼働インスタンス（t3.small × 2台）で運用しています。1回の処理は3秒以内に完了します。運用の手間とコストの両方を下げたいと考えています。適切な移行先はどれですか。"],"options":[{"l":"A","html":"AWS Batchへ移行する"},{"l":"B","html":"EC2をスポットインスタンスへ変更する"},{"l":"C","html":"Auto Scalingグループを設定し、最小台数を1に下げる"},{"l":"D","html":"AWS Lambdaへ移行し、S3イベントで起動する"}],"answer":["D"],"multi":false,"req":"","key":"「<b>短時間・イベント駆動・実行回数が限られる</b>」ワークロードでは、アイドル時間に課金されないLambdaが最もコスト効率に優れ、サーバー管理も不要になります。","kw":"","reasons":[{"l":"A","html":"Batchは15分を超えるような長時間のバッチ計算向けです。3秒の処理には過剰で、裏側のコンピュート費用も発生します。"},{"l":"B","html":"スポットでも常時稼働のアイドル時間には課金され、中断対応の実装も必要になります。"},{"l":"C","html":"1台分のアイドルコストは残り、サーバー管理の手間も減りません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.6 AWS Lambda</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":7,"topic":"ストレージのコスト","level":3,"body":["データ分析チームが利用するS3バケットには、<b>アクセスパターンがまったく予測できない</b>オブジェクトが数億件あります。運用の手間をかけずにコストを最適化したいと考えています。適切な方法はどれですか。"],"options":[{"l":"A","html":"ライフサイクルポリシーで、30日後に一律でStandard-IAへ移行する"},{"l":"B","html":"S3 Intelligent-Tieringを適用する"},{"l":"C","html":"CloudWatchメトリクスでアクセス頻度を毎月分析し、手動でクラスを変更する"},{"l":"D","html":"すべてをS3 Glacier Instant Retrievalへ移行する"}],"answer":["B"],"multi":false,"req":"","key":"「<b>アクセスパターンが不明・変動する</b>」「<b>運用の手間をかけたくない</b>」はIntelligent-Tieringの適用条件です。監視料金のみで自動的に階層を移動し、取り出し料金はかかりません。","kw":"","reasons":[{"l":"A","html":"一律移行すると、頻繁にアクセスされるオブジェクトでは取り出し料金がかさみ、かえって高くつく場合があります。"},{"l":"C","html":"数億件を手動で分類する運用は現実的ではなく、「手間をかけずに」という要件に反します。"},{"l":"D","html":"Glacier Instant Retrievalは最低90日の保存期間があり、早期削除では残期間分が課金されます。頻繁にアクセスされるオブジェクトでは取り出し料金も発生します。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":8,"topic":"ネットワークのコスト","level":2,"body":["動画配信サービスで、S3に置いた動画ファイルを世界中の視聴者へ直接配信しています。S3からインターネットへのデータ転送料金が急増しました。視聴される動画には強い偏りがあり、上位1%のファイルが再生回数の大半を占めています。コスト削減に最も効果的な方法はどれですか。"],"options":[{"l":"A","html":"S3 Transfer Accelerationを有効化し、エッジロケーション経由で配信する"},{"l":"B","html":"S3のストレージクラスをOne Zone-IAへ変更する"},{"l":"C","html":"CloudFrontを前段に配置して配信し、S3バケットはOACで非公開にする"},{"l":"D","html":"リクエスタ支払い（Requester Pays）を有効化する"}],"answer":["C"],"multi":false,"req":"","key":"CloudFrontはエッジでキャッシュするためオリジン（S3）へのリクエストとデータ転送が大幅に減り、<b>CloudFrontからの配信単価はS3からの直接配信より安い</b>のが一般的です。アクセスに偏りがあるほどキャッシュヒット率が上がり効果的です。","kw":"","reasons":[{"l":"A","html":"Transfer Accelerationは遠距離からの<b>アップロード</b>を高速化する機能で、追加料金が発生します。配信コストは下がりません。"},{"l":"B","html":"ストレージクラスは<b>保管</b>コストの話で、インターネットへのデータ転送料は変わりません。"},{"l":"D","html":"リクエスタ支払いは転送料金を取得側に負担させる仕組みで、一般の視聴者向け配信には適用できません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFrontとGlobal Accelerator</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":9,"topic":"コンピューティングのコスト","level":3,"body":["3年間の運用実績があるWebサービスで、ベースとなる負荷は常時一定、日中のみ負荷が1.5倍になり、月末のバッチ処理では一時的に3倍まで増加します。バッチ処理は中断可能です。最もコスト効率の高い購入方法の組み合わせはどれですか。<b>2つ選択してください。</b>"],"options":[{"l":"A","html":"ベース負荷分にスポットインスタンスを利用する"},{"l":"B","html":"ベース負荷分に Compute Savings Plans（またはリザーブドインスタンス）を適用する"},{"l":"C","html":"すべての負荷をオンデマンドインスタンスでまかなう"},{"l":"D","html":"月末のバッチ処理分にスポットインスタンスを利用する"},{"l":"E","html":"月末のバッチ処理分に3年間のリザーブドインスタンスを購入する"}],"answer":["B","D"],"multi":true,"req":"","key":"<b>ベース負荷はコミットメント割引（Savings Plans／RI）、変動分はオンデマンド、中断可能なバースト分はスポット</b>という重ね方が定石です。","kw":"","reasons":[{"l":"A","html":"ベース負荷は常時必要な処理です。中断の可能性があるスポットをサービスの土台に使うのは適しません。"},{"l":"C","html":"常時一定の負荷にオンデマンドを使い続けるのは、割引の機会を捨てていることになります。"},{"l":"E","html":"月末のみの一時的な負荷に3年コミットするのは、稼働率が低く割引を活かせません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":10,"topic":"データベースのコスト","level":2,"body":["IoTプラットフォームがDynamoDBにセンサーデータを保存しています。データは直近90日間のみ照会され、それ以前のデータは年に数回の分析でしか使われませんが、テーブルの容量が増え続けコストを圧迫しています。適切な対処はどれですか。"],"options":[{"l":"A","html":"プロビジョニングされた読み取りキャパシティを引き下げる"},{"l":"B","html":"TTLで90日を過ぎた項目を自動削除し、削除前にS3へエクスポートしてAthenaで分析する"},{"l":"C","html":"テーブルをオンデマンドキャパシティモードへ変更する"},{"l":"D","html":"グローバルセカンダリインデックスを追加して古いデータを分離し、ベーステーブルの読み取り負荷を下げる"}],"answer":["B"],"multi":false,"req":"","key":"DynamoDBのストレージ費用は項目数に比例します。<b>TTLで自動削除</b>して容量を抑え、めったに使わない履歴は<b>S3に退避してAthenaで分析</b>するのが定石です。","kw":"","reasons":[{"l":"A","html":"キャパシティの調整はスループット課金の話で、増え続けるストレージ費用には効きません。"},{"l":"C","html":"課金方式が変わるだけで、保存しているデータ量そのものは減りません。"},{"l":"D","html":"GSIはインデックス分のストレージとキャパシティを<b>追加で消費</b>するため、コストはむしろ増えます。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.4 データベースのコスト最適化</a>"}]},{"id":"exam-set-05","file":"set-05.md","num":"問題セット05","title":"総合（本番の分野比率に合わせた混合セット）","questions":[{"n":1,"topic":"マルチアカウント統制","level":2,"body":["企業が新規事業ごとにAWSアカウントを発行する方針を決めました。各アカウントには、ログの集約、ガードレールの適用、標準的なネットワーク構成が最初から備わっている必要があります。アカウント発行のたびに手作業で設定する運用は避けたいと考えています。適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS Control Towerでランディングゾーンを構築する"},{"l":"B","html":"AWS Organizationsを有効化し、アカウント作成後にSCPを手動で適用する"},{"l":"C","html":"AWS CloudFormation StackSetsで、ログ集約やネットワークの標準構成を各アカウントへ展開する"},{"l":"D","html":"AWS Service Catalogで承認済みのアカウント設定を配布する"}],"answer":["A"],"multi":false,"req":"","key":"「<b>マルチアカウント基盤をベストプラクティス構成で自動的に立ち上げる</b>」のがControl Towerです。Organizations、SCP、ログ集約、アカウント発行（Account Factory）を一括で用意します。","kw":"","reasons":[{"l":"B","html":"Organizations単体では請求統合とSCPの適用まで。ログ集約やネットワークの標準化、発行の自動化は自前で組む必要があります。"},{"l":"C","html":"StackSetsはリソースの展開手段であり、アカウントそのものの発行やガードレールの枠組みは提供しません（Control Towerの内部でも使われます）。"},{"l":"D","html":"Service Catalogは利用者に承認済みの構成テンプレートを配布する仕組みで、アカウント基盤の構築とは目的が異なります。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.5 AWS Organizations</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":2,"topic":"オンプレミス接続","level":3,"body":["本社データセンターとAWS間を、<b>帯域が安定した専用線</b>で接続しています。監査部門から「経路上のデータはすべて暗号化されていること」という指摘を受けました。既存の接続方式は維持したまま、最小の変更で対応する方法はどれですか。"],"options":[{"l":"A","html":"転送するデータをアプリケーション側でS3へアップロードしてから処理する"},{"l":"B","html":"Direct Connectを解約し、暗号化されるSite-to-Site VPNだけに切り替える"},{"l":"C","html":"Direct Connect Gatewayを追加する"},{"l":"D","html":"Direct Connectの上にIPsec VPN（またはMACsec）を構成する"}],"answer":["D"],"multi":false,"req":"","key":"<b>Direct Connectは既定では暗号化されません</b>。専用線の帯域特性を保ったまま暗号化要件を満たすには、その上にIPsec VPNを重ねるか、対応回線でMACsecを使います。","kw":"","reasons":[{"l":"A","html":"経路の暗号化要件に対する回答になっておらず、アプリケーションの作り替えも必要になります。"},{"l":"B","html":"VPNはインターネット経由のため、専用線の「安定した帯域・低レイテンシ」という前提を失います。"},{"l":"C","html":"DX Gatewayは複数リージョン・複数VPCへ接続を広げる仕組みで、暗号化とは無関係です。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":3,"topic":"暗号鍵の管理","level":3,"body":["金融機関のシステムで、規制により「<b>暗号鍵は専有のハードウェアで管理し、FIPS 140-2 レベル3の検証を受けていること</b>」「鍵素材はクラウド事業者にも一切触らせないこと」が求められています。適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS Secrets Manager"},{"l":"B","html":"AWS KMSのカスタマー管理キー（自動ローテーション有効）"},{"l":"C","html":"AWS KMSのAWSマネージドキー"},{"l":"D","html":"AWS CloudHSM"}],"answer":["D"],"multi":false,"req":"","key":"<b>専有（シングルテナント）HSM・鍵素材の完全な自己管理</b>という要件はCloudHSMです（KMSのカスタムキーストアと組み合わせることもできます）。なお現在はKMSのHSMもFIPS レベル3の認証を受けているため、決め手は「レベル3」ではなく「<b>専有</b>」と「<b>事業者に触らせない</b>」の側です。","kw":"","reasons":[{"l":"A","html":"Secrets Managerは資格情報の保管とローテーションのサービスで、暗号鍵のハードウェア要件とは関係ありません。"},{"l":"B","html":"KMSはマネージドな共有HSM基盤で、専有ハードウェアの要件を満たしません。"},{"l":"C","html":"AWSマネージドキーはポリシーの変更もできず、要件から最も遠い選択肢です。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.8 AWS KMS</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":4,"topic":"API設計","level":2,"body":["社内向けのモノリシックなアプリケーションから、参照系の機能だけを切り出してAPIとして外部パートナーへ公開することになりました。パートナーごとに<b>呼び出し回数の上限</b>を設け、超過分は遮断する必要があります。バックエンドはLambda関数で実装します。適切な構成はどれですか。"],"options":[{"l":"A","html":"Lambda関数URLを発行し、関数内で呼び出し回数をカウントする"},{"l":"B","html":"Application Load BalancerのターゲットにLambdaを登録し、WAFのレートベースルールで制限する"},{"l":"C","html":"API GatewayのAPIキーと使用量プランで上限を設定する"},{"l":"D","html":"CloudFrontを前段に置き、キャッシュのTTLを長くする"}],"answer":["C"],"multi":false,"req":"","key":"<b>利用者ごとの流量制御（APIキー＋使用量プラン）</b>はAPI Gatewayの標準機能です。スロットリングでバックエンドも保護できます。","kw":"","reasons":[{"l":"A","html":"カウント処理を自前で実装・保守することになり、超過時の遮断やプラン管理も作り込みが必要です。"},{"l":"B","html":"WAFのレートベースルールは主にIP単位の制限で、パートナー単位の契約上限を管理する仕組みとしては粗すぎます。"},{"l":"D","html":"キャッシュは負荷軽減には効きますが、契約上の呼び出し回数の上限管理にはなりません。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.1 Amazon API Gateway</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.2 疎結合アーキテクチャ</a>"},{"n":5,"topic":"コンテナ移行","level":2,"body":["オンプレミスで稼働するDockerアプリケーションをAWSへ移行します。開発チームにKubernetesの運用経験はなく、<b>EC2インスタンスの管理も避けたい</b>と考えています。既存のDockerfileはそのまま使う方針です。適切な構成はどれですか。"],"options":[{"l":"A","html":"Amazon EKS on Amazon EC2（マネージドノードグループ）"},{"l":"B","html":"Amazon ECS on AWS Fargate"},{"l":"C","html":"Amazon EC2上にDockerを導入して直接実行する"},{"l":"D","html":"AWS Lambdaのコンテナイメージサポートを利用する"}],"answer":["B"],"multi":false,"req":"","key":"<b>Kubernetesの記述がない＋サーバー管理をしたくない</b>＝ECS on Fargateです。AWSサービスとの統合が容易で、運用負荷が最も低くなります。","kw":"","reasons":[{"l":"A","html":"Kubernetesの学習・運用コストが発生し、EC2ノードの管理も残ります。要件と逆方向です。"},{"l":"C","html":"OSのパッチ適用、スケーリング、障害対応をすべて自前で担うことになります。"},{"l":"D","html":"Lambdaは15分の実行時間制限とイベント駆動の実行モデルが前提です。常時稼働するWebアプリケーションの移行先としては制約が大きすぎます。"}],"refs":"<a href=\"#container\" data-go=\"container\">第9章 9.3 AWS Fargate</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.3 サーバーレステクノロジーの活用</a>"},{"n":6,"topic":"高可用性","level":3,"body":["単一AZのEC2インスタンス1台とRDSシングルAZ構成で動いているアプリケーションを、<b>AZ障害が起きてもサービスを継続できる</b>構成に変更します。実施すべき対策はどれですか。<b>2つ選択してください。</b>"],"options":[{"l":"A","html":"EC2のインスタンスタイプを1つ大きいサイズへ変更する"},{"l":"B","html":"RDSのリードレプリカを同一AZに1台追加する"},{"l":"C","html":"EC2をAuto Scalingグループに入れ、複数AZのサブネットにまたがってALB配下で最低2台稼働させる"},{"l":"D","html":"EBSのスナップショットを1時間おきに取得する"},{"l":"E","html":"RDSをマルチAZ配置に変更する"}],"answer":["C","E"],"multi":true,"req":"","key":"AZ障害への耐性は「<b>複数AZに冗長化する</b>」ことでしか得られません。アプリ層はASG＋ELB＋マルチAZ、DB層はマルチAZ配置が定型です。","kw":"","reasons":[{"l":"A","html":"スケールアップは処理能力の話で、AZ障害時には同じように停止します。"},{"l":"B","html":"同一AZにレプリカを置いても、そのAZが落ちれば同時に失われます（別AZへ置けば可用性にも寄与しますが、自動フェイルオーバーはマルチAZ配置の役割です）。"},{"l":"D","html":"スナップショットは復旧の材料であり、障害時にサービスを継続させるものではありません（RPOの改善にとどまります）。"}],"refs":"<a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a> ／ <a href=\"#foundations\" data-go=\"foundations\">第0章 0.2 可用性と耐久性</a>"},{"n":7,"topic":"データ取り込み","level":2,"body":["数万台のIoTデバイスから送られるテレメトリを、<b>追加のコードを書かずに</b>S3へ集約し、Parquet形式に変換して保存したいと考えています。取り込みは数分程度の遅延が許容されます。運用負荷を最小にする構成はどれですか。"],"options":[{"l":"A","html":"Kinesis Data Streamsで受け、独自のコンシューマーアプリケーションでS3へ書き出す"},{"l":"B","html":"Amazon Data Firehoseで受け、形式変換を有効にしてS3へ配信する"},{"l":"C","html":"Amazon SQSで受け、Lambdaで変換してS3へ書き出す"},{"l":"D","html":"Amazon EMRクラスターを常時稼働させ、デバイスから直接書き込ませる"}],"answer":["B"],"multi":false,"req":"","key":"「<b>S3などへ配送するだけ</b>」「<b>コード不要・完全マネージド</b>」「数分の遅延が許容」はFirehoseの適用条件です。Parquetへの形式変換も組み込み機能で行えます。","kw":"","reasons":[{"l":"A","html":"Data Streamsはコンシューマーを自分で実装・運用する前提で、順序保証や再処理が必要な場合に選びます。今回は要件に含まれていません。"},{"l":"C","html":"実装と運用が必要になり、「追加のコードを書かずに」という要件に反します。"},{"l":"D","html":"常時稼働のEMRはコストが高く、取り込みの入口としても適しません。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.1 Amazon Kinesis</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":8,"topic":"データ変換と分析","level":2,"body":["S3に蓄積した生ログに対し、<b>スキーマを自動的に推論してカタログ化</b>し、ETL処理を行ったうえで、アナリストがSQLでアドホックに分析できるようにしたいと考えています。サーバーの管理は避けたい方針です。適切な組み合わせはどれですか。"],"options":[{"l":"A","html":"AWS Glue（クローラーとETLジョブ）＋ Amazon Athena"},{"l":"B","html":"Amazon EMR（Spark）＋ Amazon Redshift"},{"l":"C","html":"AWS Lambda（変換）＋ Amazon RDS"},{"l":"D","html":"Amazon Kinesis Data Streams ＋ Amazon QuickSight"}],"answer":["A"],"multi":false,"req":"","key":"<b>スキーマ推論とカタログ化＝Glueクローラー／サーバーレスETL＝Glueジョブ／S3への直接SQL＝Athena</b>。いずれもサーバー管理が不要です。","kw":"","reasons":[{"l":"B","html":"EMRはクラスターの構成管理が必要で、Redshiftも常時稼働のクラスター運用を伴います。「サーバー管理を避けたい」に反します。"},{"l":"C","html":"Lambdaでの大規模ETLは実行時間の制約があり、RDSはアドホックな大規模分析の基盤には適しません。"},{"l":"D","html":"Data Streamsはリアルタイム取り込みの仕組みで、蓄積済みデータのカタログ化・変換は行いません。QuickSightは可視化であり、データを取得する層が別途必要です。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.2 AWS Glue</a> ／ <a href=\"#analytics\" data-go=\"analytics\">第7章 7.3 Amazon Athena</a>"},{"n":9,"topic":"ロードバランサーの選択","level":2,"body":["サードパーティ製の仮想ファイアウォールアプライアンスを導入し、VPCへ出入りするトラフィックをすべて検査したうえで転送する構成を作ります。アプライアンスは複数台で冗長化し、スケールさせる必要があります。適切なサービスはどれですか。"],"options":[{"l":"A","html":"Network Load Balancer"},{"l":"B","html":"Application Load Balancer"},{"l":"C","html":"Gateway Load Balancer"},{"l":"D","html":"Amazon Route 53の加重ルーティング"}],"answer":["C"],"multi":false,"req":"","key":"<b>サードパーティの仮想アプライアンス（ファイアウォール、IDS/IPS）を透過的に挟み込み、冗長化・スケールさせる</b>のがGateway Load Balancerの役割です（GENEVEプロトコルでカプセル化します）。","kw":"","reasons":[{"l":"A","html":"NLBはL4の負荷分散で、アプライアンスへの透過的な引き込み（ミラーではなくインライン挿入）の仕組みは持ちません。"},{"l":"B","html":"ALBはL7のHTTP/HTTPS向けで、すべてのトラフィックを透過的に検査する用途には使えません。"},{"l":"D","html":"Route 53はDNSレベルの振り分けで、パケットの検査経路を構成するものではありません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.5 負荷分散（ELB）</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A ネットワーク</a>"},{"n":10,"topic":"ストレージのコスト","level":2,"body":["数百台のEC2インスタンスで、汎用SSD（gp2）のEBSボリュームを使用しています。現在のIOPS使用状況を調べたところ、多くのボリュームで割り当てIOPSを持て余している一方、一部のボリュームではIOPS不足のためにサイズだけを大きくして対応していました。コストと性能の両面で最も適切な対処はどれですか。"],"options":[{"l":"A","html":"gp3へ変更し、IOPSとスループットを個別に設定する"},{"l":"B","html":"すべてのボリュームをio2 Block Expressへ変更し、IOPSを個別に設定する"},{"l":"C","html":"IOPS不足のボリュームだけをさらに大きなサイズへ拡張する"},{"l":"D","html":"スループット最適化HDD（st1）へ変更する"}],"answer":["A"],"multi":false,"req":"","key":"gp3は<b>IOPSとスループットを容量から切り離して設定</b>できます。容量を増やしてIOPSを稼ぐ必要がなくなり、gp2より単価も安くなります。","kw":"","reasons":[{"l":"B","html":"io2 Block Expressは最高水準の性能を要するDB向けで、単価が高くコスト最適化に反します。"},{"l":"C","html":"容量課金が増え続けるうえ、余っているボリュームの無駄は解消されません。"},{"l":"D","html":"st1はシーケンシャルなスループット向けのHDDで、ブートボリュームにも使えず、ランダムIOPSを要する用途には不適です。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.2 Amazon EBS</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"}]},{"id":"exam-set-06","file":"set-06.md","num":"問題セット06","title":"複合問題（分野をまたぐ設計判断）","questions":[{"n":1,"topic":"セキュリティ × コスト","level":3,"body":["医療情報を含む監査ログをS3に保管します。要件は次の3つです。(1) 保存データは<b>キーの利用履歴を追跡できる方式</b>で暗号化する、(2) 法定保存期間は7年で、<b>照会は年に1回程度、取り出しに数時間かかっても構わない</b>、(3) 7年間の総コストを最小化する。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"SSE-KMSで暗号化し、S3 Standardのまま7年間保管する"},{"l":"B","html":"SSE-S3で暗号化し、ライフサイクルポリシーで30日後にS3 Glacier Deep Archiveへ移行する"},{"l":"C","html":"SSE-KMS（バケットキー有効）で暗号化し、30日後にGlacier Deep Archiveへ移行、7年後に失効させる"},{"l":"D","html":"SSE-KMS（S3バケットキー有効）で暗号化し、ライフサイクルポリシーで30日後にS3 One Zone-IAへ移行する"}],"answer":["C"],"multi":false,"req":"①キー利用履歴の追跡＝<b>SSE-KMS</b>（第1分野）／②取り出しは数時間でよい＝<b>Deep Archiveが許容できる</b>（第3分野）／③7年の総コスト最小（第4分野）","key":"3つすべてを満たす選択肢は1つだけです。SSE-KMSで監査要件を満たしつつ、<b>S3バケットキー</b>でKMSリクエスト料金を抑え、取り出し時間の許容度を使ってDeep Archiveまで落とします。","kw":"","reasons":[{"l":"A","html":"要件(1)は満たしますが、最も高いクラスで7年間保管するため要件(3)に反します。"},{"l":"B","html":"SSE-S3はCloudTrailにキーの利用が記録されず、要件(1)を満たしません。コストだけを見て暗号化方式の要件を落とした典型例です。"},{"l":"D","html":"One Zone-IAは単一AZ保管でAZ障害時にデータが失われ、法定保存の要件に耐えません。コストもDeep Archiveより高くなります。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.8 AWS KMS</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":2,"topic":"可用性 × コスト","level":3,"body":["基幹システムのDR要件が「<b>RPO 5分以内、RTO 30分以内</b>」に決まりました。現在は東京リージョンのAurora MySQLで稼働しています。コストは要件を満たす範囲で最小にする方針です。適切な構成はどれですか。"],"options":[{"l":"A","html":"東京リージョン内でAuroraクラスターを3つのAZに拡張し、リードレプリカを2台追加する"},{"l":"B","html":"大阪リージョンに本番同等のAuroraクラスターとアプリ層を常時稼働させ、Route 53で両系へ振り分ける"},{"l":"C","html":"Auroraの自動バックアップを大阪リージョンへコピーし、被災時にCloudFormationで環境一式を構築して復元する"},{"l":"D","html":"Auroraグローバルデータベースで大阪にセカンダリクラスターを置き、アプリ層はAMIとIaCで被災時に起動する"}],"answer":["D"],"multi":false,"req":"①RPO 5分以内＝<b>継続的なレプリケーションが必須</b>（第2分野）／②RTO 30分以内＝<b>DB以外は被災後の起動で間に合う</b>（第2分野）／③コスト最小（第4分野）","key":"RPOの要件がデータ層の常時レプリケーションを要求し、RTO 30分という緩さがアプリ層の事前起動を不要にします。この組み合わせが<b>パイロットライト</b>で、Auroraグローバルデータベース（通常1秒未満のレプリケーション）がそれを実現します。","kw":"","reasons":[{"l":"A","html":"マルチAZとリードレプリカは<b>同一リージョン内</b>の可用性・性能対策です。リージョン障害に対するDRにはなりません。"},{"l":"B","html":"要件は満たしますが、本番環境を二重に常時稼働させるため最も高コストで、方針③に反します。"},{"l":"C","html":"バックアップからの復元はRPOがバックアップ間隔に縛られ、構築・復元にも時間がかかるため①②の双方を満たせません。"}],"refs":"<a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a> ／ <a href=\"#database\" data-go=\"database\">第4章 4.2 Amazon Aurora</a> ／ <a href=\"#foundations\" data-go=\"foundations\">第0章 0.3 RTOとRPOの指標</a>"},{"n":3,"topic":"パフォーマンス × コスト","level":3,"body":["ゲームのランキング機能をDynamoDBで実装しています。トラフィックは<b>毎日ほぼ同じ形で推移し、予測可能</b>です。要件は (1) 読み取りレイテンシをマイクロ秒台にする、(2) 同じ上位100件が繰り返し読まれる、(3) キャパシティ料金を最小化する、の3つです。適切な構成はどれですか。"],"options":[{"l":"A","html":"オンデマンドキャパシティモードに変更し、DAXを前段に置く"},{"l":"B","html":"プロビジョニング済みキャパシティ＋Auto Scalingにし、DAXを前段に置く"},{"l":"C","html":"プロビジョニング済みキャパシティ＋Auto Scalingを使い、読み取りを強い整合性に変更する"},{"l":"D","html":"グローバルテーブルを有効化し、最寄りリージョンから読み取る"}],"answer":["B"],"multi":false,"req":"①マイクロ秒＝<b>DAX</b>（第3分野）／②同一データの繰り返し読み取り＝キャッシュが効く（第3分野）／③負荷が予測可能＝<b>プロビジョニング済みが最安</b>（第4分野）","key":"レイテンシ要件はDAXが、コスト要件はプロビジョニング済み＋Auto Scalingが満たします。<b>性能の手段とコストの手段は別々に選ぶ</b>のがこの種の設問の解き方です。","kw":"","reasons":[{"l":"A","html":"オンデマンドは負荷が読めない場合に適し、予測可能な負荷ではプロビジョニング済みより割高になります（要件③に反する）。"},{"l":"C","html":"強い整合性は消費キャパシティが2倍になり、レイテンシも改善しません。①③の両方に反します。"},{"l":"D","html":"グローバルテーブルは地理的な分散とマルチリージョンの可用性のための機能で、マイクロ秒のレイテンシ要件には応えず、コストも増えます。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.4 データベースのコスト最適化</a>"},{"n":4,"topic":"セキュリティ × 弾力性","level":3,"body":["決済処理をSQSキュー経由の非同期処理に変更します。要件は (1) メッセージ本文に含まれるカード情報を<b>保存時に暗号化し、キーへのアクセスを制御する</b>、(2) 下流の障害で処理に失敗したメッセージを<b>失わずに隔離する</b>、(3) 処理は最長10分かかることがあり、<b>二重決済は許されない</b>、の3つです。適切な構成はどれですか。"],"options":[{"l":"A","html":"FIFOキューをSSE-KMSで暗号化し、可視性タイムアウトを30秒のままにする"},{"l":"B","html":"SSE-SQS（SQS管理キー）のキューを使い、可視性タイムアウトを既定の30秒のままにし、失敗時はアプリケーションから再送する"},{"l":"C","html":"SSE-KMS（カスタマー管理キー）のキューにDLQを設定し、可視性タイムアウトを処理時間より長くして、処理を冪等にする"},{"l":"D","html":"メッセージ本文をアプリケーション側で暗号化し、デッドレターキューの代わりにCloudWatchアラームで失敗を検知する"}],"answer":["C"],"multi":false,"req":"①キー制御が必要＝<b>SSE-KMS（カスタマー管理キー）</b>（第1分野）／②失敗メッセージの保全＝<b>DLQ</b>（第2分野）／③処理10分・二重決済不可＝<b>可視性タイムアウトの延長＋冪等性</b>（第2分野）","key":"3つの要件がそれぞれ別の機能に対応します。<b>要件ごとに担当する機能を割り当てられるか</b>が問われています。","kw":"","reasons":[{"l":"A","html":"FIFOは順序と重複排除を提供しますが、<b>重複排除の対象は5分以内の送信</b>であり、処理中の可視性タイムアウト切れによる再配信は防げません（③未達）。DLQもなく②も満たしません。"},{"l":"B","html":"SSE-SQSではキーのアクセス制御ができず①を満たしません。可視性タイムアウト30秒のままでは10分の処理中に再配信され、③にも反します。"},{"l":"D","html":"独自の暗号化実装は鍵管理の負担が大きく、アラームは通知であって<b>メッセージの保全にはならない</b>ため②を満たしません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.8 AWS KMS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.4 イベント駆動型アーキテクチャ</a>"},{"n":5,"topic":"セキュリティ × パフォーマンス","level":3,"body":["有料会員向けの動画をS3から配信します。要件は (1) 世界中の会員に低遅延で配信する、(2) <b>契約期間中の会員だけ</b>が視聴でき、URLを共有されても第三者は視聴できない、(3) S3バケットは<b>インターネットから直接アクセスできない</b>、の3つです。適切な構成はどれですか。"],"options":[{"l":"A","html":"CloudFrontとOACでS3を非公開にし、視聴者には有効期限付きの署名付きCookieを発行する"},{"l":"B","html":"CloudFrontを配置し、S3バケットをパブリック読み取りにして、CloudFrontの地理的制限で国を限定する"},{"l":"C","html":"S3の静的ウェブサイトホスティングを有効にし、事前署名URLを都度発行する"},{"l":"D","html":"CloudFrontを配置し、OACでS3を非公開にしたうえで、WAFのレートベースルールで過剰なアクセスを遮断する"}],"answer":["A"],"multi":false,"req":"①世界中へ低遅延＝<b>CloudFront</b>（第3分野）／②視聴者の限定＝<b>署名付きURL／Cookie</b>（第1分野）／③オリジンの非公開＝<b>OAC</b>（第1分野）","key":"<b>OACは「CloudFrontだけがS3を読める」ための仕組み、署名付きURL／Cookieは「正当な視聴者だけが配信を受けられる」ための仕組み</b>で、役割が異なります。複数ファイルからなる動画配信ではCookieが適します。","kw":"","reasons":[{"l":"B","html":"バケットをパブリックにすると③に反します。地理的制限は国単位のフィルタであり、会員かどうかの判定にはなりません（②未達）。"},{"l":"C","html":"静的ウェブサイトホスティングはCDNを経由しないため①を満たさず、パブリックアクセスの設定も③に反します。"},{"l":"D","html":"①③は満たしますが、WAFのレート制限は流量の制御であって会員の識別ではないため②を満たしません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFrontとGlobal Accelerator</a> ／ <a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":6,"topic":"弾力性 × パフォーマンス","level":3,"body":["ALBとAuto Scalingグループで動くWebアプリケーションで、次の2つの問題が同時に起きています。(1) スケールインのたびに利用者がログアウトされる、(2) ピーク時にRDSのCPU使用率が100%に張り付き、参照系のクエリが詰まる。<b>それぞれに対する適切な対処を2つ選択してください。</b>"],"options":[{"l":"A","html":"セッション情報をAmazon ElastiCache for RedisまたはDynamoDBへ外部化する"},{"l":"B","html":"RDSをマルチAZ配置に変更し、スタンバイへ参照系クエリを向ける"},{"l":"C","html":"ALBでスティッキーセッションを有効にし、スケールイン保護をすべてのインスタンスに設定する"},{"l":"D","html":"RDSにリードレプリカを追加し、参照系クエリの接続先をレプリカへ向ける"},{"l":"E","html":"Auto Scalingグループの最小台数をピーク時の台数に固定する"}],"answer":["A","D"],"multi":true,"req":"①スケールインで状態が消える＝<b>ステートレス化</b>（第2分野）／②参照系でDBが詰まる＝<b>読み取りのスケール</b>（第3分野）","key":"症状が2つあるときは<b>それぞれ別の層の問題</b>として切り分けます。状態はアプリ層の外へ、読み取り負荷はレプリカへ、が定型です。","kw":"","reasons":[{"l":"B","html":"マルチAZ配置のスタンバイは<b>読み取りにも使えません</b>。可用性の対策であり、②の解決にはなりません。"},{"l":"C","html":"スティッキーセッションは同じインスタンスへ誘導するだけで、そのインスタンスが終了すればセッションは失われます。スケールイン保護を常時掛けるのは弾力性そのものを捨てる対処です。"},{"l":"E","html":"ピーク台数に固定すると常時コストが増えるうえ、①の原因（ローカルにセッションを持つ設計）は残ります。"}],"refs":"<a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a> ／ <a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":7,"topic":"コスト × 運用","level":2,"body":["開発・検証用のAWSアカウントで請求が想定を超えました。調査の結果、(1) 開発用EC2が夜間と週末も稼働している、(2) gp2ボリュームが大量にあり、IOPSを持て余している、(3) 使われていないElastic IPが数十個ある、ことが分かりました。<b>すぐに効果が出る対処を2つ選択してください。</b>"],"options":[{"l":"A","html":"EC2インスタンスをより小さいインスタンスタイプへ変更する"},{"l":"B","html":"夜間と週末はスケジュールでインスタンスを停止する"},{"l":"C","html":"すべてのEC2に3年間のリザーブドインスタンスを購入する"},{"l":"D","html":"アカウントにコスト配分タグを設定する"},{"l":"E","html":"gp2ボリュームをgp3へ変更する"}],"answer":["B","E"],"multi":true,"req":"①稼働時間の無駄＝<b>止める</b>（第4分野）／②過剰なプロビジョニング＝<b>適正化する</b>（第4分野・第3分野）／③「すぐに効果が出る」＝実施が容易で即座に請求に反映されるもの","key":"コスト削減の基本は「<b>止める・落とす・コミットする</b>」の3手。開発環境では<b>止める</b>が最も効果的で、gp2→gp3は性能を落とさずに単価が下がります。","kw":"","reasons":[{"l":"A","html":"性能要件を確認せずサイズを下げると開発効率を損ないます。Compute Optimizerの推奨を確認してから行う手順です。なお未使用のElastic IPは、アタッチされていない状態で課金されるため削除が必要です。"},{"l":"C","html":"開発環境は停止・廃止の可能性が高く、3年コミットは無駄になるリスクが大きい選択です。"},{"l":"D","html":"タグは可視化と配賦のための準備で、それ自体は請求額を下げません（次の打ち手を決めるためには有用です）。"}],"refs":"<a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a> ／ <a href=\"#management\" data-go=\"management\">第8章 8.6 AWS Trusted Advisor</a>"},{"n":8,"topic":"セキュリティ × 可用性 × コスト","level":3,"body":["Organizationsで管理する50アカウントのAPI操作ログを一元管理します。要件は (1) <b>全アカウント・全リージョン</b>の操作を漏れなく記録する、(2) ログは<b>アカウント管理者でも改ざん・削除できない</b>、(3) 保管は5年間で、コストを抑える、の3つです。適切な構成はどれですか。"],"options":[{"l":"A","html":"CloudWatch Logsに全アカウントのログを集約し、保持期間を5年に設定する"},{"l":"B","html":"各アカウントで個別にCloudTrailを有効化し、それぞれのアカウントのS3バケットへ保存する。バケットポリシーで削除を禁止する"},{"l":"C","html":"管理アカウントで組織証跡を作成し、管理アカウントのS3バケットへ集約する。バージョニングを有効にし、S3 Standardのまま5年間保管する"},{"l":"D","html":"管理アカウントで組織証跡を作り、専用のログアカウントのバケット（オブジェクトロックのコンプライアンスモード）へ集約し、Glacierへ移行する"}],"answer":["D"],"multi":false,"req":"①全アカウント・全リージョンの記録＝<b>組織証跡</b>（第1分野）／②管理者でも消せない＝<b>オブジェクトロック（コンプライアンスモード）＋アカウント分離</b>（第1分野）／③5年保管のコスト＝<b>ライフサイクルでGlacierへ</b>（第4分野）","key":"「<b>改ざんできない</b>」という要件は、バケットポリシーのような<b>変更できる防御</b>では満たせません。コンプライアンスモードのオブジェクトロックと、証跡アカウントの分離（権限の分離）が答えになります。","kw":"","reasons":[{"l":"A","html":"CloudWatch Logsは検索・アラート向けで、長期保管のコスト効率ではS3＋Glacierに劣り、改ざん防止の要件も満たしません。"},{"l":"B","html":"個別設定は設定漏れが起きやすく、同一アカウント内にログがあるため、そのアカウントの管理者がポリシーを変更して削除できてしまいます（①②未達）。"},{"l":"C","html":"集約はできますが、バージョニングは削除を防ぐ仕組みではなく（権限があれば完全削除が可能）、5年間Standardで保管するためコストにも反します。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.2 AWS CloudTrail</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":9,"topic":"パフォーマンス × 弾力性","level":3,"body":["工場のセンサーから送られるデータを、リアルタイム処理と日次のバッチ分析の<b>両方</b>で使っています。要件は (1) センサーごとの<b>時系列の順序</b>を保つ、(2) リアルタイム処理と分析処理が<b>同じデータを独立して読める</b>、(3) 障害時は<b>過去24時間分を再処理</b>できる、の3つです。取り込みの入口として適切なサービスはどれですか。"],"options":[{"l":"A","html":"Amazon Kinesis Data Streams"},{"l":"B","html":"Amazon SQS標準キューを2本用意し、送信側が両方へ送る"},{"l":"C","html":"Amazon Data Firehose（旧 Kinesis Data Firehose）でS3へ配信し、各処理はS3を読む"},{"l":"D","html":"Amazon SNSトピックに発行し、2つのSQSキューをサブスクライブさせる"}],"answer":["A"],"multi":false,"req":"①センサーごとの順序＝<b>パーティションキー単位の順序保証</b>（第3分野）／②複数のコンシューマーが同じデータを読む＝<b>ストリームの保持</b>（第2分野）／③再処理＝<b>保持期間内の巻き戻し</b>（第2分野）","key":"<b>「同じデータを複数のアプリが何度でも読める」「順序が保たれる」「再処理できる」</b>の3点が揃うのはKinesis Data Streamsです。SQSはメッセージを取得すると他から見えなくなり、再処理もできません。","kw":"","reasons":[{"l":"B","html":"標準キューは順序を保証せず（①未達）、消費したメッセージは再取得できません（③未達）。送信側で二重送信する設計も壊れやすくなります。"},{"l":"C","html":"Firehoseは配送専用で<b>データを保持せず</b>、コンシューマーがストリームを読み直すこともできません。順序の保証もありません。"},{"l":"D","html":"ファンアウトで②は満たせますが、SQSに入った時点で順序保証と再処理性は失われます（①③未達）。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.1 Amazon Kinesis</a> ／ <a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.4 イベント駆動型アーキテクチャ</a>"},{"n":10,"topic":"全分野","level":3,"body":["社内の申請システムをAWSへ移行します。要件は (1) 利用は<b>平日日中のみ</b>で、夜間・週末はアクセスがない、(2) AZ障害時もサービスを継続する、(3) 保存データは暗号化し、DBはインターネットから到達できない、(4) 運用要員が少ないため<b>管理の手間を最小化</b>する、の4つです。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"ALB＋EC2 Auto ScalingをマルチAZに配置し、DBはEC2上にMySQLを構築して暗号化する"},{"l":"B","html":"ALB＋ECS on Fargate（Auto Scaling）をマルチAZに配置し、DBはAurora Serverless v2をプライベートサブネットで暗号化して構成する"},{"l":"C","html":"単一AZのEC2にアプリとMySQLを同居させ、夜間は停止するスクリプトを組む"},{"l":"D","html":"ALB＋EC2 Auto ScalingをマルチAZに配置し、DBはRDSシングルAZをパブリックサブネットに配置して暗号化する"}],"answer":["B"],"multi":false,"req":"①日中のみ利用＝<b>アイドル時のコストを抑えたい</b>（第4分野）／②AZ障害への耐性＝<b>マルチAZ</b>（第2分野）／③暗号化とプライベート配置（第1分野）／④管理の手間＝<b>マネージド／サーバーレス</b>（第2・4分野）","key":"4つすべてを満たす選択肢は1つだけです。<b>Fargateでサーバー管理をなくし、Aurora Serverless v2でアイドル時のコストを抑え、マルチAZとプライベートサブネットで可用性とセキュリティを確保</b>します。複数要件の設問では、1つでも落とす選択肢を機械的に外していくのが最短です。","kw":"","reasons":[{"l":"A","html":"EC2上のMySQLはパッチ適用・バックアップ・フェイルオーバーをすべて自前で運用することになり、④に反します。DB層の可用性も担保されません。"},{"l":"C","html":"単一AZ構成のため②を満たしません。同居構成は障害の影響範囲も広がります。"},{"l":"D","html":"RDSシングルAZは②を満たさず、パブリックサブネットへの配置は③に反します。"}],"refs":"<a href=\"#container\" data-go=\"container\">第9章 9.3 AWS Fargate</a> ／ <a href=\"#database\" data-go=\"database\">第4章 4.2 Amazon Aurora</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"}]},{"id":"exam-set-07","file":"set-07.md","num":"問題セット07","title":"頻出①：ネットワークと名前解決","questions":[{"n":1,"topic":"SG と NACL","level":2,"body":["プライベートサブネットのEC2インスタンスから外部APIへのHTTPS通信が失敗します。セキュリティグループはアウトバウンドをすべて許可しており、ルートテーブルにはNAT Gateway宛てのデフォルトルートがあります。ネットワークACLではアウトバウンドでポート443を許可していますが、インバウンドはHTTPの80番のみ許可しています。原因として最も適切なものはどれですか。"],"options":[{"l":"A","html":"セキュリティグループのインバウンドで、外部APIから戻る443番の通信を許可していないため"},{"l":"B","html":"ネットワークACLのインバウンドで、戻り通信のエフェメラルポートを許可していないため"},{"l":"C","html":"NAT Gatewayがパブリックサブネットではなく、プライベートサブネットに配置されているため"},{"l":"D","html":"ルートテーブルにインターネットゲートウェイ宛ての経路がないため"}],"answer":["B"],"multi":false,"req":"","key":"<b>セキュリティグループはステートフル（戻りは自動許可）／ネットワークACLはステートレス（往路と復路を別々に許可）</b>。NACLを触った直後の疎通不良は、まずエフェメラルポートの許可漏れを疑います。","kw":"ステートレス","reasons":[{"l":"A","html":"SGはステートフルなので、アウトバウンドで開始した通信の戻りはインバウンド許可がなくても通ります。"},{"l":"C","html":"NAT Gatewayの配置が誤っていれば通信は一切成立しません。設問はNACLの443アウトバウンドだけを許可した状態を示しており、原因の切り分けとして整合しません。"},{"l":"D","html":"プライベートサブネットのルートはNAT Gateway宛てが正しく、IGW宛てを設定するとプライベートサブネットの定義に反します。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.2 通信制御</a> ／ <a href=\"#foundations\" data-go=\"foundations\">第0章 0.4 通信経路と認可の区別</a>"},{"n":2,"topic":"SG と NACL","level":2,"body":["特定の国から不正アクセスが集中しており、判明している数個の<b>送信元IPアドレスからのアクセスをサブネット単位で遮断</b>したいと考えています。適切な方法はどれですか。"],"options":[{"l":"A","html":"ネットワークACLのインバウンドルールで、対象IPを拒否（DENY）する"},{"l":"B","html":"セキュリティグループのインバウンドルールで、対象IPを拒否（DENY）する"},{"l":"C","html":"セキュリティグループから、対象IP以外をすべて許可するルールを作成する"},{"l":"D","html":"ルートテーブルで対象IP宛ての経路をブラックホールにする"}],"answer":["A"],"multi":false,"req":"","key":"<b>「拒否（DENY）ルールを書けるのはNACLだけ」「NACLはサブネット単位」</b>。特定IPの遮断はNACLの典型的な用途です。","kw":"","reasons":[{"l":"B","html":"セキュリティグループは<b>許可ルールしか書けません</b>。拒否ルールという概念がありません。"},{"l":"C","html":"「対象IP以外をすべて許可」はSGでは事実上表現できず（許可の列挙になる）、運用も破綻します。"},{"l":"D","html":"ルートテーブルは宛先による経路制御で、送信元IPによる遮断はできません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.2 通信制御</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A ネットワーク</a>"},{"n":3,"topic":"Route 53","level":3,"body":["同じWebアプリケーションを東京・アイルランド・オレゴンの3リージョンで運用しています。要件は「<b>利用者が最も応答の速いリージョンへ接続される</b>こと」です。適切なルーティングポリシーはどれですか。"],"options":[{"l":"A","html":"位置情報ルーティング（Geolocation）"},{"l":"B","html":"レイテンシーベースルーティング"},{"l":"C","html":"加重ルーティング"},{"l":"D","html":"複数値回答ルーティング"}],"answer":["B"],"multi":false,"req":"","key":"<b>「速い＝レイテンシーベース」「どこの国の人か＝位置情報」</b>。物理的な近さと実際の遅延は一致しないため、応答速度が要件ならレイテンシーベースです。","kw":"","reasons":[{"l":"A","html":"位置情報は利用者の所在地で振り分ける方式で、<b>言語別サイトの出し分けや法規制によるアクセス制限</b>が用途です。必ずしも最速のリージョンにはなりません。"},{"l":"C","html":"加重は割合の指定で、A/Bテストや段階的な移行に使います。"},{"l":"D","html":"複数値回答は複数のIPをヘルスチェック付きで返す簡易な分散で、遅延の最小化は行いません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.4 名前解決：Route 53 と Resolver</a>"},{"n":4,"topic":"Route 53","level":2,"body":["<code>example.com</code>（ゾーン頂点／Zone Apex）へのアクセスを、Application Load Balancerへ向ける必要があります。追加のクエリ料金は避けたいと考えています。適切な設定はどれですか。"],"options":[{"l":"A","html":"ALBのIPアドレスを調べてAレコードに静的に設定する"},{"l":"B","html":"ALBのDNS名を指すCNAMEレコードを作成する"},{"l":"C","html":"ALBを指すエイリアスレコード（Aレコード）を作成する"},{"l":"D","html":"<code>www.example.com</code> へのリダイレクト用にNSレコードを作成する"}],"answer":["C"],"multi":false,"req":"","key":"<b>CNAMEはゾーン頂点に設定できません</b>。AWSリソース（ALB・CloudFront・S3・API Gatewayなど）へはエイリアスレコードを使い、これは<b>クエリ料金も無料</b>です。","kw":"","reasons":[{"l":"A","html":"ALBのIPアドレスは動的に変化するため、静的な設定は障害の原因になります。"},{"l":"B","html":"DNSの仕様上、ゾーン頂点にCNAMEは設定できません（サブドメインなら可）。"},{"l":"D","html":"NSレコードはゾーンの委任に使うもので、リダイレクトの手段ではありません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.4 名前解決：Route 53 と Resolver</a>"},{"n":5,"topic":"VPC間接続","level":3,"body":["3つの部門VPC（A・B・C）があり、AとB、AとCの間でVPCピアリングを構成済みです。新たに<b>BとCの間でも通信</b>したいという要望が出ました。さらに今後VPCは20以上に増える見込みです。適切な対応はどれですか。"],"options":[{"l":"A","html":"各VPCにNAT Gatewayを配置し、インターネット経由でVPC同士をHTTPSで相互接続する"},{"l":"B","html":"VPC Aのルートテーブルに、BとCの間の通信をAで中継する経路を追加する"},{"l":"C","html":"BとCの間に新たなVPCピアリング接続を作成する"},{"l":"D","html":"AWS Transit Gatewayを導入し、各VPCをアタッチする"}],"answer":["D"],"multi":false,"req":"","key":"VPCピアリングは<b>推移的ルーティングができず</b>、接続数はVPC数の増加に対して急激に増えます（n×(n-1)/2）。<b>多数のVPCを相互接続するならTransit Gateway</b>が定石です。","kw":"","reasons":[{"l":"A","html":"インターネット経由は遅延・コスト・セキュリティのいずれでも不利で、プライベート接続の要件を満たしません。"},{"l":"B","html":"ピアリングでは中継（推移的ルーティング）ができないため、この設定は機能しません。"},{"l":"C","html":"今回は動作しますが、20以上のVPCでは管理すべきピアリング接続が爆発的に増え、要件に耐えません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A ネットワーク</a>"},{"n":6,"topic":"ネットワーク監視","level":2,"body":["セキュリティ調査のため、特定のEC2インスタンスに出入りする通信を分析する必要があります。要件は (1) 拒否された通信も含めて<b>接続の記録</b>を残す、(2) 疑わしい通信については<b>パケットの中身</b>まで確認する、の2つです。適切な組み合わせはどれですか。"],"options":[{"l":"A","html":"接続記録はVPCフローログ、パケットの中身はトラフィックミラーリングで取得する"},{"l":"B","html":"VPCフローログのみを有効化し、ログに含まれるペイロードをAthenaで抽出する"},{"l":"C","html":"CloudTrailのデータイベントで両方を記録する"},{"l":"D","html":"AWS Configで両方を記録する"}],"answer":["A"],"multi":false,"req":"","key":"<b>VPCフローログはメタデータ（送信元・宛先・ポート・許可/拒否）だけで、ペイロードは記録しません</b>。中身が必要ならトラフィックミラーリングです。","kw":"","reasons":[{"l":"B","html":"フローログにはパケットの中身が含まれないため、要件(2)を満たせません。"},{"l":"C","html":"CloudTrailは<b>AWSのAPI呼び出し</b>の記録で、インスタンス間のネットワーク通信は対象外です。"},{"l":"D","html":"Configはリソースの設定状態と変更履歴を扱うサービスで、通信の記録はしません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.1 VPCの基礎</a> ／ <a href=\"#management\" data-go=\"management\">第8章 8.2 AWS CloudTrail</a>"},{"n":7,"topic":"ロードバランサー","level":2,"body":["Auto Scalingグループのスケールインが発生すると、<b>処理中のリクエストが途中で切断される</b>という苦情が出ています。1リクエストの処理には最大60秒かかります。適切な対処はどれですか。"],"options":[{"l":"A","html":"Auto Scalingグループのクールダウン期間を、処理の最大所要時間より長く延長する"},{"l":"B","html":"ALBのアイドルタイムアウトを60秒未満に短縮する"},{"l":"C","html":"スティッキーセッションを有効にする"},{"l":"D","html":"登録解除の遅延を、処理の最大時間より長くする"}],"answer":["D"],"multi":false,"req":"","key":"<b>登録解除の遅延（既定300秒）</b>は、ターゲットを外す際に処理中のリクエストが完了するのを待つ設定です。「スケールイン時に通信が切れる」はこの値を疑います。","kw":"","reasons":[{"l":"A","html":"クールダウンは次のスケーリング動作までの待機時間で、進行中のリクエストには影響しません。"},{"l":"B","html":"アイドルタイムアウトは無通信状態の接続を切るまでの時間で、短くすると切断は増えます。"},{"l":"C","html":"スティッキーセッションは振り分け先の固定であり、終了処理中の完了待ちとは無関係です。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.5 負荷分散（ELB）</a> ／ <a href=\"#compute\" data-go=\"compute\">第1章 1.2 EC2 Auto Scaling</a>"},{"n":8,"topic":"エッジでの処理","level":3,"body":["CloudFrontで配信しているサイトに、次の2つの処理を追加します。それぞれに適したサービスはどれですか。","1. すべてのビューアリクエストに対し、<b>HTTPヘッダーを書き換え、URLを正規化する</b>（数万リクエスト/秒、1ミリ秒未満で完結）","2. オリジンへ転送する直前に、<b>外部の認可APIを呼び出して</b>アクセス可否を判定する"],"options":[{"l":"A","html":"1: CloudFront Functions ／ 2: Lambda@Edge"},{"l":"B","html":"1: Lambda@Edge ／ 2: CloudFront Functions"},{"l":"C","html":"1: CloudFront Functions ／ 2: CloudFront Functions"},{"l":"D","html":"1: AWS WAF ／ 2: Lambda@Edge"}],"answer":["A"],"multi":false,"req":"","key":"<b>CloudFront Functionsはビューア側のみ・JavaScript・サブミリ秒・超高頻度で安価</b>、ヘッダー操作やURL書き換えに使います。<b>Lambda@Edgeはオリジン側でも動作し、ネットワークアクセスや重い処理が可能</b>です。","kw":"","reasons":[{"l":"B","html":"役割が逆です。CloudFront Functionsは外部へのネットワークアクセスができません。"},{"l":"C","html":"要件2は外部API呼び出しを含むため、CloudFront Functionsでは実現できません。"},{"l":"D","html":"WAFはリクエストの検査と遮断を行うもので、ヘッダーの書き換えやURL正規化の用途ではありません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFrontとGlobal Accelerator</a> ／ <a href=\"#compute\" data-go=\"compute\">第1章 1.6 AWS Lambda</a>"},{"n":9,"topic":"ハイブリッドDNS","level":3,"body":["オンプレミスのデータセンターとAWSをDirect Connectで接続しています。要件は (1) <b>オンプレミスのサーバーから、VPC内のプライベートホストゾーンの名前を解決</b>できるようにする、(2) <b>VPC内のEC2から、オンプレミスのADドメインの名前を解決</b>できるようにする、の2つです。適切な構成はどれですか。"],"options":[{"l":"A","html":"各EC2の <code>/etc/hosts</code> にオンプレミスのホスト名を記載し、オンプレ側のDNSにVPCのIPを静的登録する"},{"l":"B","html":"Route 53のパブリックホストゾーンに、両方のレコードを登録する"},{"l":"C","html":"Route 53 Resolverのインバウンドエンドポイントと、アウトバウンドエンドポイント＋転送ルールを構成する"},{"l":"D","html":"AWS Directory Serviceの Simple AD を構築する"}],"answer":["C"],"multi":false,"req":"","key":"<b>インバウンド＝オンプレからAWSへ問い合わせる入口／アウトバウンド＝AWSからオンプレへ問い合わせる出口</b>。方向で名前が決まります。","kw":"Route 53 Resolverのインバウンドエンドポイント／アウトバウンドエンドポイント／転送ルール","reasons":[{"l":"A","html":"台数が増えるほど保守が破綻し、動的な変更にも追随できません。"},{"l":"B","html":"プライベートホストゾーンの名前をパブリックDNSに公開することになり、内部情報の露出という別の問題を生みます。"},{"l":"D","html":"Simple ADはディレクトリサービスであり、双方向のDNS転送を構成する仕組みではありません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.4 名前解決：Route 53 と Resolver</a>"},{"n":10,"topic":"IPv6とアウトバウンド","level":2,"body":["IPv6のみで構成したプライベートサブネットのEC2インスタンスから、<b>インターネット上のパッケージリポジトリへアウトバウンド通信のみ</b>を許可したいと考えています。インターネット側からの接続開始は拒否する必要があります。適切な構成はどれですか。"],"options":[{"l":"A","html":"NAT Gatewayを作成し、<code>::/0</code> の経路を向ける"},{"l":"B","html":"Egress-Only インターネットゲートウェイに <code>::/0</code> を向ける"},{"l":"C","html":"インターネットゲートウェイを作成し、<code>::/0</code> の経路を向ける"},{"l":"D","html":"NATインスタンスを作成し、IPv6のNAT変換を有効にして <code>::/0</code> の経路を向ける"}],"answer":["B"],"multi":false,"req":"","key":"<b>IPv6にはNATの概念がありません</b>。アウトバウンド専用の出口は<b>Egress-Only インターネットゲートウェイ</b>（ステートフル）を使います。","kw":"","reasons":[{"l":"A","html":"NAT GatewayはIPv4専用です（IPv6のトラフィックは扱いません）。"},{"l":"C","html":"IGWを向けると双方向に到達可能となり、インターネット側からの接続開始を拒否する要件に反します。"},{"l":"D","html":"IPv6でのNAT変換という仕組み自体がなく、NATインスタンスの運用負荷も要件に合いません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.1 VPCの基礎</a>"}]},{"id":"exam-set-08","file":"set-08.md","num":"問題セット08","title":"頻出②：ストレージの選択とデータ移行","questions":[{"n":1,"topic":"共有ストレージの選択","level":2,"body":["Linux上で動くコンテンツ管理システムを、複数のEC2インスタンスへスケールアウトします。各インスタンスは<b>同じディレクトリを同時に読み書き</b>する必要があり、容量は使用量に応じて自動的に増減してほしいと考えています。適切なストレージはどれですか。"],"options":[{"l":"A","html":"Amazon S3をファイルシステムとしてマウントする"},{"l":"B","html":"Amazon EBS（gp3）を各インスタンスにアタッチする"},{"l":"C","html":"Amazon EBS Multi-Attach（io2）"},{"l":"D","html":"Amazon EFS"}],"answer":["D"],"multi":false,"req":"","key":"<b>「複数のインスタンスから同時にマウント」「Linux／NFS」「容量の自動拡張」＝EFS</b>。マルチAZに分散配置されるため可用性も高まります。","kw":"","reasons":[{"l":"A","html":"S3はオブジェクトストレージで、POSIXのファイルロックや部分更新を前提とするCMSの用途には向きません。"},{"l":"B","html":"EBSは単一インスタンスにアタッチするブロックストレージで、別々のボリュームになるため内容を共有できません。"},{"l":"C","html":"Multi-Attachは<b>io1/io2かつ同一AZ限定</b>で、さらにクラスタ対応ファイルシステムの導入が前提です。一般的なファイル共有には適しません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.3 Amazon EFS</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A ストレージ</a>"},{"n":2,"topic":"共有ストレージの選択","level":2,"body":["社内の<b>Windowsファイルサーバー</b>をAWSへ移行します。要件は (1) SMBプロトコルで既存のクライアントからそのまま接続できる、(2) <b>Active Directoryのユーザー権限（NTFS ACL）をそのまま使う</b>、(3) サーバーの運用をやめたい、の3つです。適切なサービスはどれですか。"],"options":[{"l":"A","html":"Amazon FSx for Lustre"},{"l":"B","html":"Amazon EFS"},{"l":"C","html":"Amazon FSx for Windows File Server"},{"l":"D","html":"EC2にWindows Serverを構築してファイルサーバーにする"}],"answer":["C"],"multi":false,"req":"","key":"<b>Windows・SMB・Active Directory統合・NTFS ACL</b>というキーワードが揃えばFSx for Windows File Serverです。","kw":"","reasons":[{"l":"A","html":"FSx for LustreはHPC・機械学習向けの高スループット並列ファイルシステムで、用途が異なります。"},{"l":"B","html":"EFSはLinux向けのNFSで、SMBやNTFS ACLには対応しません。"},{"l":"D","html":"OSのパッチ適用やバックアップなど運用が残り、要件(3)に反します。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.4 Amazon FSx</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A ストレージ</a>"},{"n":3,"topic":"ハイブリッドストレージ","level":3,"body":["オンプレミスのバックアップソフトウェアが、物理テープライブラリへバックアップを書き出しています。テープ装置を廃止したいものの、<b>バックアップソフトウェアは変更したくありません</b>。適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS DataSync"},{"l":"B","html":"AWS Storage Gateway の S3 File Gateway"},{"l":"C","html":"Storage Gateway の Tape Gateway"},{"l":"D","html":"AWS Backup"}],"answer":["C"],"multi":false,"req":"","key":"<b>「既存のバックアップソフトのテープ装置をそのまま置き換える」＝Tape Gateway（VTL）</b>。バックアップソフトからは従来のテープ装置に見え、実体はS3／Glacierに保管されます。","kw":"","reasons":[{"l":"A","html":"DataSyncはファイルの転送サービスで、テープ装置としては振る舞いません。"},{"l":"B","html":"File GatewayはNFS/SMBのファイル共有として見せる方式で、テープインターフェースは提供しません。"},{"l":"D","html":"AWS BackupはAWSリソースのバックアップを一元管理するサービスで、オンプレのバックアップソフトのテープ出力先にはなりません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.6 AWS Storage Gateway</a>"},{"n":4,"topic":"移行方式の選択","level":3,"body":["オンプレミスのNASに蓄積された<b>300 TB</b>のデータをS3へ移行します。拠点のインターネット回線は実効 <b>100 Mbps</b> で、業務時間帯は帯域を空けられません。移行はできるだけ短期間で完了させたい考えです。適切な方法はどれですか。"],"options":[{"l":"A","html":"S3 Transfer Acceleration を有効化してアップロードする"},{"l":"B","html":"AWS DataSync でインターネット経由の転送をスケジュール実行する"},{"l":"C","html":"AWS Transfer Family のSFTPエンドポイントへアップロードする"},{"l":"D","html":"AWS Snowball Edge を利用して物理デバイスで移送する"}],"answer":["D"],"multi":false,"req":"","key":"<b>回線容量と転送量の比</b>で判断します。100 Mbps で 300 TB は、理論値でも <b>270日以上</b>（300 TB ÷ 100 Mbps ≒ 6,600時間超）かかります。<b>回線が細い／データが大きい／期限がある</b>ならSnow Familyの物理移送です。※Snowball Edgeは2025年11月7日から既存顧客のみの提供です（新規にはDataSyncやAWS Data Transfer Terminalが案内されています）。試験では今も「帯域が足りない大容量移送＝Snowball」の対応で出るため、判断の手順として押さえます。","kw":"","reasons":[{"l":"A","html":"Transfer Accelerationは遠距離のレイテンシを改善する機能で、帯域そのものを増やすわけではありません。"},{"l":"B","html":"DataSyncは転送を効率化しますが、<b>物理的な回線容量の上限は超えられません</b>。"},{"l":"C","html":"Transfer Familyは既存のSFTP運用を維持するためのサービスで、大容量の一括移行手段ではありません。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.15 その他の移行サービス</a> ／ <a href=\"#others\" data-go=\"others\">第10章 10.13 AWS DataSync</a>"},{"n":5,"topic":"移行方式の選択","level":2,"body":["オンプレミスのNFSサーバーにある <b>2 TB</b> のファイルを、毎晩Amazon EFSへ同期します。差分のみを効率よく転送し、転送後にデータの整合性も検証したいと考えています。適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS DataSync"},{"l":"B","html":"AWS Storage Gateway の S3 File Gateway"},{"l":"C","html":"rsync を cron で実行するスクリプトをEC2上に構築する"},{"l":"D","html":"AWS Snowcone"}],"answer":["A"],"multi":false,"req":"","key":"<b>「オンプレ↔AWSの定期的なファイル同期」「増分転送」「整合性チェック」＝DataSync</b>。NFS/SMB/HDFSからS3・EFS・FSxへ転送できます。","kw":"","reasons":[{"l":"B","html":"Storage Gatewayは<b>オンプレから使い続ける</b>ためのハイブリッド運用の仕組みで、同期ジョブの管理は行いません。"},{"l":"C","html":"自前実装は保守・監視・再試行・整合性検証をすべて自分で担うことになります。"},{"l":"D","html":"Snowconeは物理デバイスによる少量データの移送用で、毎晩の同期には使えません（2024年11月に提供終了済み）。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.13 AWS DataSync</a> ／ <a href=\"#storage\" data-go=\"storage\">第2章 2.6 AWS Storage Gateway</a>"},{"n":6,"topic":"データベース移行","level":3,"body":["オンプレミスのOracleデータベース（4 TB）をAmazon Aurora PostgreSQLへ移行します。要件は (1) <b>停止時間を数分以内</b>に抑える、(2) スキーマとストアドプロシージャを変換する、の2つです。適切な組み合わせはどれですか。"],"options":[{"l":"A","html":"AWS DMSのフルロードを週末に実行し、完了後にアプリケーションの接続先を切り替える"},{"l":"B","html":"AWS SCTでスキーマを変換し、DMSの継続的レプリケーション（CDC）で同期してから切り替える"},{"l":"C","html":"Oracleのデータポンプでエクスポートし、S3経由でインポートする"},{"l":"D","html":"AWS DataSyncでデータファイルを転送する"}],"answer":["B"],"multi":false,"req":"","key":"<b>異種DB移行＝SCT（スキーマ変換）＋DMS（データ移行）</b>、<b>停止時間の最小化＝CDCによる継続的レプリケーション</b>。この組み合わせが定番です。","kw":"","reasons":[{"l":"A","html":"フルロードのみでは、ロード中の更新が反映されず、停止時間もデータ量に比例して長くなります。"},{"l":"C","html":"データポンプは同種DB間の手段で、PostgreSQLへの異種移行ではスキーマ変換の問題が残り、停止時間も長くなります。"},{"l":"D","html":"DataSyncはファイル転送サービスで、稼働中のDBの論理的な移行には使えません。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.12 AWS Database Migration Service</a>"},{"n":7,"topic":"外部連携","level":2,"body":["取引先30社が、毎日<b>SFTPクライアント</b>でファイルを送信してきます。現在はEC2上にSFTPサーバーを構築して運用していますが、パッチ適用と可用性の確保が負担です。取引先の接続方法は変更できません。適切な移行先はどれですか。"],"options":[{"l":"A","html":"AWS Transfer FamilyのSFTPサーバー（保存先はS3）"},{"l":"B","html":"S3の事前署名URLを毎日発行して取引先へ配布する"},{"l":"C","html":"AWS DataSyncのエージェントを取引先に導入してもらい、毎日S3へ転送させる"},{"l":"D","html":"Amazon AppFlowで取引先のシステムと連携し、ファイルをS3へ取り込む"}],"answer":["A"],"multi":false,"req":"","key":"<b>「取引先の既存SFTPクライアントを変えられない」「サーバー運用をやめたい」＝Transfer Family</b>。認証はIAM・Active Directory・カスタムIDプロバイダーと連携でき、保存先はS3またはEFSです。","kw":"","reasons":[{"l":"B","html":"接続方法の変更を取引先に強いることになり、前提に反します。"},{"l":"C","html":"取引先側にエージェント導入を求めるのは現実的でなく、DataSyncの用途とも異なります。"},{"l":"D","html":"AppFlowはSaaS（SalesforceやZendeskなど）との連携用で、SFTPの受け口にはなりません。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.14 AWS Transfer Family</a>"},{"n":8,"topic":"S3のデータ保護","level":3,"body":["コンプライアンス要件により、S3バケットのオブジェクトを<b>別リージョンへ複製</b>することになりました。設定後に確認すると、<b>既存のオブジェクトが複製されていません</b>。原因と対処として正しいものはどれですか。<b>2つ選択してください。</b>"],"options":[{"l":"A","html":"レプリケーションは設定後に作成・更新されたオブジェクトが対象のため、既存分はS3バッチレプリケーションで複製する"},{"l":"B","html":"既存オブジェクトを複製するには、バケットのリージョンを変更する必要がある"},{"l":"C","html":"レプリケーション先のストレージクラスをGlacierにすれば既存オブジェクトも複製される"},{"l":"D","html":"レプリケーションはライフサイクルポリシーで設定するため、移行日数を0日にすれば既存分も対象になる"},{"l":"E","html":"レプリケーションにはソースと宛先の両方のバケットでバージョニングの有効化が必要である"}],"answer":["A","E"],"multi":true,"req":"","key":"レプリケーションの前提は<b>バージョニング</b>、対象は<b>設定後の変更分</b>。既存オブジェクトは<b>バッチレプリケーション</b>で別途複製します。","kw":"バージョニング","reasons":[{"l":"B","html":"バケットのリージョンは作成後に変更できません。"},{"l":"C","html":"宛先のストレージクラスは複製対象の範囲とは無関係です。"},{"l":"D","html":"レプリケーションとライフサイクルは別の機能で、ライフサイクルで複製を起こすことはできません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":9,"topic":"EC2のストレージ","level":2,"body":["動画のトランスコード処理を行うEC2インスタンスで、<b>処理中の一時ファイル</b>を最速のディスクに置きたいと考えています。一時ファイルは処理が終われば不要で、インスタンスの停止・終了時に失われても構いません。適切なストレージはどれですか。"],"options":[{"l":"A","html":"EBS gp3"},{"l":"B","html":"インスタンスストア（NVMe SSD）"},{"l":"C","html":"EBS st1"},{"l":"D","html":"Amazon EFS（Elastic スループットモード）"}],"answer":["B"],"multi":false,"req":"","key":"<b>インスタンスストアは物理サーバー直結で最速</b>。<b>停止・終了でデータが消える</b>（再起動では消えない）という性質が、一時ファイルの用途と一致します。","kw":"","reasons":[{"l":"A","html":"gp3は永続ストレージで十分高速ですが、ネットワーク越しのためインスタンスストアのレイテンシには及びません。"},{"l":"C","html":"st1はHDDでシーケンシャルなスループット向け、ランダムI/Oの多い一時領域には不適です。"},{"l":"D","html":"EFSはネットワーク共有ファイルシステムで、一時ファイル用途では遅く、コストも無駄になります。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.2 Amazon EBS</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":10,"topic":"大容量アップロード","level":2,"body":["海外の拠点から、<b>1ファイルあたり20 GB</b>の測定データをS3（東京リージョン）へ毎日アップロードしています。アップロードの失敗が多く、完了までの時間も長いという問題があります。適切な対処はどれですか。<b>2つ選択してください。</b>"],"options":[{"l":"A","html":"ストレージクラスをS3 Standard-IAに変更する"},{"l":"B","html":"アップロード先のバケットでバージョニングを有効化する"},{"l":"C","html":"マルチパートアップロードを使い、分割して並列にアップロードする"},{"l":"D","html":"S3 Transfer Accelerationを有効化し、最寄りのエッジロケーション経由で転送する"},{"l":"E","html":"ファイルをGlacier Deep Archiveへ直接アップロードする"}],"answer":["C","D"],"multi":true,"req":"","key":"<b>単一PUTの上限は5 GB</b>であり、20 GBのファイルは<b>マルチパートアップロードが必須</b>です（分割・並列・再試行が可能になり、失敗にも強くなります）。加えて<b>遠距離からの転送はTransfer Acceleration</b>で改善します。","kw":"","reasons":[{"l":"A","html":"ストレージクラスは保管コストの話で、アップロードの速度や成功率には影響しません。"},{"l":"B","html":"バージョニングは誤削除・上書き対策で、転送の問題には関係しません。"},{"l":"E","html":"アーカイブクラスへ直接置いても転送は速くならず、取り出しにも時間がかかるようになります。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"}]},{"id":"exam-set-09","file":"set-09.md","num":"問題セット09","title":"頻出③：ID・運用・サーバーレス連携","questions":[{"n":1,"topic":"認証の主体","level":3,"body":["3つのID管理の要件があります。それぞれに最も適したサービスの組み合わせはどれですか。","1. モバイルアプリの<b>エンドユーザー数百万人</b>のサインアップ・サインインを実装したい","2. 社員が<b>50個のAWSアカウント</b>へ、既存のIdP（Okta）のIDでログインできるようにしたい","3. AWS上のWindows Serverを、<b>オンプレミスのActive Directory</b>のユーザーで認証させたい（AWS側にディレクトリを置かない）"],"options":[{"l":"A","html":"1: IAM Identity Center ／ 2: Amazon Cognito ／ 3: AWS Managed Microsoft AD"},{"l":"B","html":"1: Amazon Cognito ／ 2: IAM Identity Center ／ 3: AD Connector"},{"l":"C","html":"1: Amazon Cognito ／ 2: IAMユーザーとグループ ／ 3: Simple AD"},{"l":"D","html":"1: AWS Directory Service ／ 2: IAM Identity Center ／ 3: Amazon Cognito"}],"answer":["B"],"multi":false,"req":"","key":"<b>アプリの利用者＝Cognito／AWSを操作する社員＝IAM Identity Center／Windowsのドメイン認証＝Directory Service</b>。さらにDirectory Serviceの中では「<b>AWS側にディレクトリを置かず、オンプレADへ転送する＝AD Connector</b>」です。","kw":"","reasons":[{"l":"A","html":"1と2が逆です。Identity Centerは社内の管理者・開発者向けで、一般消費者のサインアップには使いません。"},{"l":"C","html":"50アカウントに個別のIAMユーザーを作る運用は破綻します。Simple ADはオンプレADとの信頼関係を張れず、要件3を満たしません（Simple ADは2026年6月30日に新規受付を終了しています）。"},{"l":"D","html":"Directory Serviceは消費者向けのサインアップ基盤ではなく、Cognitoはドメイン参加の認証を提供しません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.2 IAM Identity Center</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.3 AWS Directory Service</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.4 Amazon Cognito</a>"},{"n":2,"topic":"ポリシー評価","level":3,"body":["あるIAMロールには<code>AmazonS3FullAccess</code>が付与されています。しかし、そのアカウントが所属するOUに適用されたSCPで、<code>s3:DeleteObject</code>が明示的に拒否されています。さらに対象バケットのバケットポリシーでは、当該ロールに対して<code>s3:*</code>が明示的に許可されています。このロールは対象バケットのオブジェクトを削除できますか。"],"options":[{"l":"A","html":"できる。SCPはルートユーザーにのみ適用されるため"},{"l":"B","html":"できる。バケットポリシーでの明示的な許可が、SCPの拒否を上書きするため"},{"l":"C","html":"できる。IAMポリシーとバケットポリシーの両方で許可されているため"},{"l":"D","html":"できない。SCPによる明示的な拒否は、他のどの許可よりも優先されるため"}],"answer":["D"],"multi":false,"req":"","key":"<b>明示的な拒否（Deny）はすべての許可に優先</b>します。SCP・IAMポリシー・リソースポリシーのどこか1つでも拒否があれば、その操作は実行できません。","kw":"","reasons":[{"l":"A","html":"SCPはメンバーアカウント内のすべてのプリンシパル（ルートユーザーを含む）に適用されます。管理アカウントには効かない、という点との混同に注意します。"},{"l":"B","html":"リソースポリシーの許可がSCPの拒否を上書きすることはありません。評価順の理解を問う典型的な誤答です。"},{"l":"C","html":"「複数箇所で許可されている＝実行できる」ではありません。拒否の有無が先に効きます。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":3,"topic":"資格情報の管理","level":2,"body":["アプリケーションの設定値と資格情報をAWSで管理します。要件は (1) RDSのマスターパスワードを<b>30日ごとに自動でローテーション</b>する、(2) アプリの機能フラグなど<b>数百件の設定値を無料で</b>保管する、の2つです。適切な組み合わせはどれですか。"],"options":[{"l":"A","html":"1: AWS KMS ／ 2: Amazon S3"},{"l":"B","html":"1: AWS Systems Manager Parameter Store ／ 2: AWS Secrets Manager"},{"l":"C","html":"1: AWS Secrets Manager ／ 2: AWS Systems Manager Parameter Store"},{"l":"D","html":"1: AWS Secrets Manager ／ 2: AWS Secrets Manager"}],"answer":["C"],"multi":false,"req":"","key":"<b>自動ローテーションが要件にあるか</b>で決まります。あればSecrets Manager（RDS等と統合済み・有料）、なければParameter Store（標準パラメータは無料、SecureStringでKMS暗号化）。","kw":"","reasons":[{"l":"A","html":"KMSは鍵の管理サービスで、資格情報そのものの保管・ローテーションは行いません。S3に平文で置くのは論外です。"},{"l":"B","html":"Parameter Storeの標準機能には、RDSと統合した自動ローテーションはありません。"},{"l":"D","html":"Secrets Managerはシークレット1件あたりの月額課金があるため、数百件の一般的な設定値には割高です。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.10 Secrets Manager vs Parameter Store</a>"},{"n":4,"topic":"監視","level":2,"body":["EC2インスタンスの<b>メモリ使用率</b>と<b>ディスクの空き容量</b>が、CloudWatchのメトリクス一覧に表示されず、しきい値アラームを設定できません。適切な対処はどれですか。"],"options":[{"l":"A","html":"CloudWatchエージェントを導入し、カスタムメトリクスとして送る"},{"l":"B","html":"EC2の詳細モニタリングを有効化し、すべてのメトリクスの取得間隔を1分にする"},{"l":"C","html":"インスタンスにIAMロールを付与すれば、メモリとディスクも標準メトリクスとして自動的に収集される"},{"l":"D","html":"VPCフローログを有効化する"}],"answer":["A"],"multi":false,"req":"","key":"CloudWatchの標準メトリクスは<b>ハイパーバイザー視点</b>で取得されるため、<b>OSの内部情報であるメモリ使用率やディスク空き容量は含まれません</b>。エージェントの導入が必要です（試験の頻出ポイント）。","kw":"","reasons":[{"l":"B","html":"詳細モニタリングは取得<b>間隔</b>を5分から1分にするもので、取得できる<b>種類</b>は増えません。"},{"l":"C","html":"IAMロールはエージェントがメトリクスを送信するために必要ですが、ロールだけでは収集されません。"},{"l":"D","html":"フローログはネットワーク通信の記録で、OSのリソース使用率とは無関係です。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.1 Amazon CloudWatch</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.2 コンピューティングとパフォーマンス</a>"},{"n":5,"topic":"監視と統制","level":3,"body":["セキュリティ監査の指摘に対応します。要件は (1) <b>ルートユーザーによるログインが発生したら即座に通知</b>する、(2) <b>S3バケットが公開設定になっていないかを継続的に評価し、違反を自動修復</b>する、の2つです。適切な組み合わせはどれですか。"],"options":[{"l":"A","html":"1: AWS Config ルール ／ 2: CloudTrail のデータイベント"},{"l":"B","html":"1: CloudTrail → CloudWatch Logs のメトリクスフィルタ＋アラーム → SNS ／ 2: AWS Config ルール＋修復アクション"},{"l":"C","html":"1: Amazon GuardDuty ／ 2: Amazon Macie"},{"l":"D","html":"1: AWS Trusted Advisor ／ 2: Amazon Inspector"}],"answer":["B"],"multi":false,"req":"","key":"<b>「特定のAPI操作をリアルタイムに検知」＝CloudTrail＋メトリクスフィルタ＋アラーム</b>、<b>「設定が基準に沿っているかを継続評価し直す」＝Config ルール＋修復アクション（SSM Automation）</b>。","kw":"","reasons":[{"l":"A","html":"Configは設定状態の評価であり、ログイン操作そのものの通知には向きません。データイベントはS3オブジェクト操作等の記録で、公開設定の評価はしません。"},{"l":"C","html":"GuardDutyは脅威検知、Macieは機密データの発見で、いずれも設定の準拠評価や自動修復の仕組みではありません。"},{"l":"D","html":"Trusted Advisorは定期的な点検、Inspectorは脆弱性診断で、要件の即時通知・自動修復には対応しません。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.2 AWS CloudTrail</a> ／ <a href=\"#management\" data-go=\"management\">第8章 8.7 AWS Config</a>"},{"n":6,"topic":"イベント駆動","level":2,"body":["次の2つの自動化を実装します。それぞれに適したサービスはどれですか。","1. <b>毎日深夜2時</b>に、未使用リソースを棚卸しするLambda関数を実行する","2. <b>RDSインスタンスの障害イベントが発生したら</b>、運用チームのSlackへ通知する"],"options":[{"l":"A","html":"1: EventBridgeのスケジュール ／ 2: EventBridgeのイベントパターン"},{"l":"B","html":"1: Amazon SQSの遅延キュー ／ 2: Amazon SNS"},{"l":"C","html":"1: AWS Lambdaのタイマー機能 ／ 2: AWS CloudTrail"},{"l":"D","html":"1: Amazon EventBridge（スケジュール式） ／ 2: Amazon SQS"}],"answer":["A"],"multi":false,"req":"","key":"<b>EventBridgeは「cron/rate式による定期実行」と「AWSサービスの状態変化をルールで振り分ける」の両方を担います</b>。どちらも試験の定番パターンです。","kw":"","reasons":[{"l":"B","html":"SQSの遅延キューは配信を最大15分遅らせる機能で、毎日のスケジュール実行はできません。"},{"l":"C","html":"Lambda自体にスケジュール実行の機能はなく（EventBridgeが起動します）、CloudTrailは記録であって通知の振り分けは行いません。"},{"l":"D","html":"SQSはキューであり、イベントの内容に応じた振り分けや通知の役割は担いません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.3 Amazon EventBridge</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.4 イベント駆動型アーキテクチャ</a>"},{"n":7,"topic":"ワークフロー","level":3,"body":["保険金請求の処理を自動化します。処理は「書類のOCR → 内容の検証 → <b>金額が100万円を超える場合は管理者の承認を待つ</b> → 支払い」という流れで、各ステップの失敗時には再試行と補償処理が必要です。承認待ちは数日に及ぶことがあります。適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS Step Functions（標準ワークフロー）"},{"l":"B","html":"単一のAWS Lambda関数にすべての処理を実装する"},{"l":"C","html":"Amazon SQS FIFOキューで各ステップをつなぐ"},{"l":"D","html":"Amazon EventBridgeのイベントバスで各Lambdaを連鎖させる"}],"answer":["A"],"multi":false,"req":"","key":"<b>分岐・再試行・補償処理・長時間の待機</b>を宣言的に管理できるのがStep Functionsです。標準ワークフローは<b>最大1年</b>実行でき、タスクトークンによるコールバックで人の承認を待てます。","kw":"","reasons":[{"l":"B","html":"Lambdaの実行時間は<b>最大15分</b>で、数日の承認待ちは不可能です。エラー処理も自前実装になります。"},{"l":"C","html":"キューは処理の受け渡しはできますが、条件分岐・状態管理・補償処理の枠組みは提供しません。"},{"l":"D","html":"EventBridgeでの連鎖は、全体の状態把握と再試行・巻き戻しが困難で、長時間の待機状態を管理できません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.4 AWS Step Functions</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.2 疎結合アーキテクチャ</a>"},{"n":8,"topic":"コンテナの権限","level":3,"body":["Amazon ECS on Fargateで動くアプリケーションが、S3バケットへのアクセスで<code>AccessDenied</code>になります。一方、<b>ECRからのイメージ取得とCloudWatch Logsへのログ出力は正常</b>に動作しています。修正すべき対象はどれですか。"],"options":[{"l":"A","html":"サービスにアタッチされたセキュリティグループでHTTPSのアウトバウンドを許可する"},{"l":"B","html":"タスク実行ロール（task execution role）にS3へのアクセス許可を追加する"},{"l":"C","html":"EC2インスタンスプロファイルにS3へのアクセス許可を追加する"},{"l":"D","html":"タスクロール（task role）にS3へのアクセス許可を追加する"}],"answer":["D"],"multi":false,"req":"","key":"<b>タスクロール＝コンテナ内のアプリが他のAWSサービスを呼ぶための権限</b>、<b>タスク実行ロール＝ECSエージェントがイメージ取得とログ出力を行うための権限</b>。イメージ取得とログが正常なので、実行ロールは正しく機能しています。","kw":"","reasons":[{"l":"A","html":"通信が遮断されていればタイムアウトになります。<code>AccessDenied</code>は<b>到達したうえで認可が拒否された</b>ことを示します。"},{"l":"B","html":"実行ロールはアプリケーションのAPI呼び出しには使われません（症状からも正常に機能していると分かります）。"},{"l":"C","html":"Fargateではインスタンスプロファイルは存在しません（EC2起動タイプの概念です）。"}],"refs":"<a href=\"#container\" data-go=\"container\">第9章 9.1 Amazon ECS</a> ／ <a href=\"#foundations\" data-go=\"foundations\">第0章 0.4 通信経路と認可の区別</a>"},{"n":9,"topic":"Lambdaの同時実行","level":3,"body":["同一アカウント内に複数のLambda関数があります。次の2つの問題が発生しました。<b>それぞれに対する適切な対処を2つ選択してください。</b>","1. 大量に起動されるバッチ用の関数が同時実行数を占有し、<b>決済APIの関数がスロットリング</b>された","2. 決済APIの関数で、<b>コールドスタートによる初回応答の遅延</b>が問題になっている"],"options":[{"l":"A","html":"決済APIの関数のタイムアウト値を15分に延長する"},{"l":"B","html":"バッチ用の関数に予約済み同時実行数を設定し、使用できる上限を制限する"},{"l":"C","html":"決済APIの関数にプロビジョニング済み同時実行数を設定する"},{"l":"D","html":"バッチ用の関数のメモリ割り当てを減らす"},{"l":"E","html":"決済APIの関数をVPC内に配置する"}],"answer":["B","C"],"multi":true,"req":"","key":"<b>予約済み同時実行＝その関数の上限を固定し、他の関数への影響を隔離する</b>（スロットリング対策）。<b>プロビジョニング済み同時実行＝あらかじめ実行環境を温めておく</b>（コールドスタート対策）。名前が似ているため役割の取り違えが頻出します。","kw":"予約済み同時実行数／プロビジョニング済み同時実行数","reasons":[{"l":"A","html":"タイムアウトは1回の実行時間の上限で、同時実行数の枯渇にも初回遅延にも効きません。"},{"l":"D","html":"メモリを減らすとCPUも比例して下がり処理が遅くなるため、占有時間はむしろ延びます。"},{"l":"E","html":"VPC配置はネットワーク到達性のための設定で、コールドスタートはむしろ不利になる場合があります。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.6 AWS Lambda</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.2 コンピューティングとパフォーマンス</a>"},{"n":10,"topic":"運用の自動化","level":2,"body":["数百台のEC2インスタンスに対し、OSのセキュリティパッチを<b>定期的に適用し、適用状況をレポート</b>したいと考えています。インスタンスへのSSH接続は禁止されています。適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS Config"},{"l":"B","html":"Amazon Inspector"},{"l":"C","html":"AWS Systems Manager Patch Manager（メンテナンスウィンドウで実行）"},{"l":"D","html":"Amazon EventBridge＋Lambdaで各インスタンスへSSH接続してパッチを適用する"}],"answer":["C"],"multi":false,"req":"","key":"<b>パッチ適用の自動化と準拠レポート＝Patch Manager</b>。SSMエージェント経由で動作するためSSHは不要で、メンテナンスウィンドウで実行時間帯も制御できます。","kw":"","reasons":[{"l":"A","html":"Configは設定の記録と準拠評価で、OSのパッチ適用の実行者ではありません。"},{"l":"B","html":"Inspectorは脆弱性を<b>検出</b>するサービスで、パッチの適用は行いません（検出→Patch Managerで適用、という組み合わせになります）。"},{"l":"D","html":"SSH接続が禁止されている前提に反し、自前実装の保守負担も大きくなります。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.4 AWS Systems Manager</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.12 Amazon Inspector</a>"}]},{"id":"exam-set-10","file":"set-10.md","num":"問題セット10","title":"頻出④：コンピューティングとアプリ連携の細目","questions":[{"n":1,"topic":"スケーリングポリシー","level":2,"body":["ECサイトのアクセスは、毎日<b>朝9時と夜20時に大きく増える</b>という明確な周期があります。現在はターゲット追跡スケーリングのみを設定していますが、増加の立ち上がりでインスタンスの起動が追いつかず、数分間レスポンスが悪化します。適切な対処はどれですか。"],"options":[{"l":"A","html":"クールダウン期間を0秒に設定する"},{"l":"B","html":"ステップスケーリングに変更し、しきい値を細かく刻んで早めに増やす"},{"l":"C","html":"予測スケーリングを有効にして事前に台数を増やす"},{"l":"D","html":"スケールイン保護をすべてのインスタンスに設定する"}],"answer":["C"],"multi":false,"req":"","key":"<b>周期的な負荷パターンがあり、事後の反応では間に合わない</b>場合は予測スケーリングです。機械学習で需要を予測し、<b>負荷が来る前に</b>容量を用意します（時刻が固定で読めるならスケジュールされたスケーリングでも可）。","kw":"","reasons":[{"l":"A","html":"クールダウンを詰めても、しきい値を超えてから起動する点は変わらず、立ち上がりの遅れは解消しません。"},{"l":"B","html":"ステップスケーリングも実測値に反応する方式のため、起動時間そのものは埋められません。"},{"l":"D","html":"スケールイン保護は縮小を止める設定で、増加への追随とは無関係です。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.2 EC2 Auto Scaling</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a>"},{"n":2,"topic":"ライフサイクルフック","level":3,"body":["Auto Scalingグループのスケールインでインスタンスが終了する際、<b>ローカルに残っているアプリケーションログをS3へ退避</b>してから終了させたいと考えています。退避には最大3分かかります。適切な方法はどれですか。"],"options":[{"l":"A","html":"終了ポリシーを「最も古いインスタンス」に変更する"},{"l":"B","html":"終了時のライフサイクルフックを設定する"},{"l":"C","html":"ターゲットグループの登録解除の遅延を180秒に設定する"},{"l":"D","html":"インスタンスのシャットダウンスクリプトに、ログをS3へ退避する処理を書く"}],"answer":["B"],"multi":false,"req":"","key":"<b>終了・起動の途中で処理を差し込みたいときはライフサイクルフック</b>です。インスタンスを待機状態（Terminating:Wait）で止め、処理完了を通知するまで終了を保留できます。","kw":"","reasons":[{"l":"A","html":"終了ポリシーは「どのインスタンスを選ぶか」の設定で、終了処理の内容には関与しません。"},{"l":"C","html":"登録解除の遅延は<b>処理中のリクエストを完了させる</b>ための待機で、任意の後処理の完了を保証するものではありません。"},{"l":"D","html":"シャットダウンスクリプトは確実な完了を保証できず（強制終了され得る）、失敗時の検知もできません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.2 EC2 Auto Scaling</a>"},{"n":3,"topic":"Elastic Beanstalk","level":3,"body":["Elastic Beanstalkで運用するアプリケーションのデプロイ要件は、(1) <b>ダウンタイムを発生させない</b>、(2) 既存インスタンスの容量を落とさない、(3) 新バージョンに問題があれば<b>即座に切り戻せる</b>、の3つです。追加インスタンスのコストは許容できます。適切なデプロイポリシーはどれですか。"],"options":[{"l":"A","html":"All at once"},{"l":"B","html":"Rolling"},{"l":"C","html":"Rolling with additional batch"},{"l":"D","html":"Immutable"}],"answer":["D"],"multi":false,"req":"","key":"Immutableは<b>新しいインスタンス群を別に立ち上げてから入れ替える</b>方式です。既存環境には触れないため容量が落ちず、失敗時は新しい群を破棄するだけで<b>即座に元に戻せます</b>。","kw":"","reasons":[{"l":"A","html":"全インスタンスを同時に入れ替えるためダウンタイムが発生します。"},{"l":"B","html":"入れ替え中は稼働インスタンスが減り、要件(2)に反します。切り戻しにも再デプロイが必要です。"},{"l":"C","html":"容量は維持できますが、既存インスタンスを段階的に更新するため、切り戻しには再デプロイを要し要件(3)を満たしにくくなります。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.3 AWS Elastic Beanstalk</a>"},{"n":4,"topic":"AMIの管理","level":2,"body":["セキュリティ部門から「<b>毎月、最新のOSパッチとセキュリティエージェントを適用したゴールデンAMIを作成し、各アカウントへ配布する</b>」よう求められました。手作業を避けたいと考えています。適切なサービスはどれですか。"],"options":[{"l":"A","html":"EC2 Image Builder"},{"l":"B","html":"AWS Systems Manager Patch Manager"},{"l":"C","html":"Amazon Inspector"},{"l":"D","html":"AWS Backup"}],"answer":["A"],"multi":false,"req":"","key":"<b>AMIの作成・テスト・配布をパイプラインとして自動化</b>するのがEC2 Image Builderです。スケジュール実行と他アカウントへの共有まで扱えます。","kw":"","reasons":[{"l":"B","html":"Patch Managerは<b>稼働中のインスタンス</b>へパッチを適用する仕組みで、AMIの生成・配布は行いません（併用はします）。"},{"l":"C","html":"Inspectorは脆弱性の検出であり、イメージの作成はしません。"},{"l":"D","html":"AWS Backupはバックアップの管理で、ゴールデンイメージの継続的な生成には使いません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.7 その他のコンピューティングサービス</a> ／ <a href=\"#management\" data-go=\"management\">第8章 8.4 AWS Systems Manager</a>"},{"n":5,"topic":"EC2の停止と再開","level":3,"body":["科学計算アプリケーションは、起動時に<b>メモリ上へ大きなデータセットを読み込むのに15分</b>かかります。日中しか使わないため夜間は停止したいのですが、翌朝の起動に毎回15分待たされるのは避けたいと考えています。適切な方法はどれですか。"],"options":[{"l":"A","html":"インスタンスを停止せず、夜間はインスタンスタイプを小さく変更する"},{"l":"B","html":"EC2 Hibernate（休止）で停止し、翌朝に再開する"},{"l":"C","html":"夜間にAMIを作成し、翌朝そのAMIから新しいインスタンスを起動する"},{"l":"D","html":"インスタンスストアにデータセットを保存しておく"}],"answer":["B"],"multi":false,"req":"","key":"<b>Hibernateはメモリの内容をEBSルートボリュームに保存</b>し、再開時に復元します。長い初期化処理をやり直さずに済みます（対応インスタンスタイプ・暗号化されたルートボリュームなどの条件があります）。","kw":"","reasons":[{"l":"A","html":"タイプ変更にも停止が必要なうえ、稼働し続ける分の課金が残ります。"},{"l":"C","html":"AMIから起動しても<b>メモリの状態は復元されない</b>ため、15分の読み込みは再度発生します。"},{"l":"D","html":"インスタンスストアは<b>停止で内容が失われます</b>。加えてディスクからの読み込み自体は発生します。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":6,"topic":"Lambdaの起動時間","level":3,"body":["Java製のLambda関数で、<b>初回呼び出しの遅延（コールドスタート）が1秒を超える</b>ことが問題になっています。呼び出しは断続的で、常時ウォームな状態を維持するとコストが見合いません。適切な対処はどれですか。"],"options":[{"l":"A","html":"共通ライブラリをLambdaレイヤーへ移動する"},{"l":"B","html":"プロビジョニング済み同時実行数を常時100に設定する"},{"l":"C","html":"関数のタイムアウト値を延長する"},{"l":"D","html":"Lambda SnapStartを有効化する"}],"answer":["D"],"multi":false,"req":"","key":"<b>SnapStartは初期化済みの実行環境のスナップショットから復元</b>するため、追加コストなしでコールドスタートを短縮できます（Javaで顕著に効きます）。","kw":"","reasons":[{"l":"A","html":"レイヤーはデプロイパッケージの共通化・管理のための機能で、初期化時間の短縮を保証するものではありません。"},{"l":"B","html":"効果はありますが、常時ウォームな環境を確保する分の料金がかかり「コストが見合わない」という前提に反します。"},{"l":"C","html":"タイムアウトは処理の上限時間で、起動の遅延とは無関係です。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.6 AWS Lambda</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.2 コンピューティングとパフォーマンス</a>"},{"n":7,"topic":"API Gatewayの種別","level":2,"body":["モバイルアプリ向けのシンプルなプロキシAPI（Lambda統合のみ）を新規に公開します。要件は<b>可能な限り低コスト・低レイテンシ</b>で、APIキーや使用量プラン、リクエスト検証、レスポンスキャッシュは不要です。適切な選択はどれですか。"],"options":[{"l":"A","html":"HTTP APIを作成する"},{"l":"B","html":"REST APIを作成し、キャッシュを無効化する"},{"l":"C","html":"WebSocket APIを作成する"},{"l":"D","html":"Application Load BalancerにLambdaを直接登録する"}],"answer":["A"],"multi":false,"req":"","key":"<b>HTTP APIはREST APIより安価で低レイテンシ</b>な代わりに機能が絞られています。設問は「絞られた機能が不要」と明示しているため、HTTP APIが最適です。","kw":"","reasons":[{"l":"B","html":"REST APIは高機能ですが、使わない機能の分だけ単価が高くなります。"},{"l":"C","html":"WebSocketは双方向通信用で、リクエスト・レスポンス型のAPIには適しません。"},{"l":"D","html":"ALBは時間課金が常時発生し、APIとしての認証・スロットリングなどの機能も別途必要になります。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.1 Amazon API Gateway</a>"},{"n":8,"topic":"メッセージング基盤","level":2,"body":["オンプレミスで稼働する社内システム群が、<b>Apache ActiveMQ（JMS／AMQP）</b>を介して連携しています。この仕組みをAWSへ移行しますが、<b>アプリケーションのコードは変更できません</b>。適切なサービスはどれですか。"],"options":[{"l":"A","html":"Amazon MQ"},{"l":"B","html":"Amazon SNS"},{"l":"C","html":"Amazon SQS"},{"l":"D","html":"Amazon Kinesis Data Streams"}],"answer":["A"],"multi":false,"req":"","key":"<b>既存のJMS／AMQPなど標準プロトコルのアプリをコード変更なしで移行するならAmazon MQ</b>（ActiveMQ／RabbitMQのマネージド版）です。新規開発ならSQS/SNSを選びます。","kw":"","reasons":[{"l":"B","html":"SNSもAWS独自のPub/Subで、プロトコル互換性がありません。"},{"l":"C","html":"SQSはAWS独自のAPIで、JMSクライアントからそのまま利用することはできません（コード変更が必要）。"},{"l":"D","html":"Kinesisはストリーミングデータの取り込み基盤で、メッセージブローカーの置き換えではありません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.5 Amazon MQ</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A アプリケーション統合</a>"},{"n":9,"topic":"通知の振り分け","level":3,"body":["1つのSNSトピックに、注文イベント（<code>type=order</code>）と在庫イベント（<code>type=stock</code>）の両方が発行されています。在庫管理チームのキューには<b>在庫イベントだけ</b>を届けたいと考えています。アプリケーションの発行側は変更できません。適切な方法はどれですか。"],"options":[{"l":"A","html":"トピックを用途ごとに分割し、発行側で宛先を送り分ける"},{"l":"B","html":"在庫チームのキュー側で、不要なメッセージを受信後にLambdaで判定して破棄する"},{"l":"C","html":"サブスクリプションにフィルターポリシーを設定する"},{"l":"D","html":"SQSの可視性タイムアウトを調整する"}],"answer":["C"],"multi":false,"req":"","key":"<b>SNSのフィルターポリシーは、サブスクリプションごとにメッセージ属性で配信を絞り込みます</b>。発行側に手を入れずに、必要な通知だけを届けられます。","kw":"","reasons":[{"l":"A","html":"発行側の変更が必要で、「発行側は変更できない」という前提に反します。"},{"l":"B","html":"不要なメッセージも配信・受信されるため、リクエスト料金と処理の無駄が残ります。"},{"l":"D","html":"可視性タイムアウトは処理中の再配信を防ぐ設定で、配信内容の絞り込みとは無関係です。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.2 Amazon SNS</a>"},{"n":10,"topic":"起動の遅いワークロード","level":3,"body":["Auto Scalingグループで使うAMIは、アプリケーションの初期化に<b>約5分</b>かかります。トラフィックの増加は毎朝ほぼ同じ時間帯に起こりますが、スケールアウトが間に合わず、その間エラー率が上がります。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"ウォームプールを構成し、初期化済みのインスタンスを待機状態で確保しておく"},{"l":"B","html":"ヘルスチェックの猶予期間（グレースピリオド）を0秒に短縮する"},{"l":"C","html":"予測スケーリングを有効にし、需要の増加前に容量を追加する"},{"l":"D","html":"Auto Scalingグループの最大容量を2倍に引き上げる"},{"l":"E","html":"スケールイン時のクールダウンを延長する"}],"answer":["A","C"],"multi":true,"req":"","key":"<b>起動に時間がかかる</b>ことが原因なので、対処は「<b>あらかじめ用意しておく（ウォームプール）</b>」か「<b>早めに増やし始める（予測スケーリング）</b>」のどちらかです。","kw":"","reasons":[{"l":"B","html":"グレースピリオドを短くすると、初期化中のインスタンスが異常と判定されて置き換えられ、状況が悪化します。"},{"l":"D","html":"最大容量は上限値であり、起動の遅さ（立ち上がりの時間）は変わりません。"},{"l":"E","html":"スケールインのクールダウンは縮小の頻度を抑える設定で、スケールアウトの遅れには効きません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.2 EC2 Auto Scaling</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a>"}]},{"id":"exam-set-11","file":"set-11.md","num":"問題セット11","title":"頻出⑤：データベースと分析の細目","questions":[{"n":1,"topic":"Aurora","level":3,"body":["Aurora MySQLで、開発者が誤って本番テーブルの大量の行を削除してしまいました。<b>5分前の状態に、できるだけ短時間で戻す</b>必要があります。スナップショットからの復元では新しいクラスターの作成に時間がかかりすぎます。適切な方法はどれですか。"],"options":[{"l":"A","html":"バイナリログから手動でリカバリする"},{"l":"B","html":"ポイントインタイムリカバリで削除直前の時刻を指定し、新しいクラスターへ復元する"},{"l":"C","html":"リードレプリカを昇格させる"},{"l":"D","html":"Auroraバックトラックで巻き戻す"}],"answer":["D"],"multi":false,"req":"","key":"<b>バックトラックは「復元」ではなく「巻き戻し」</b>です。新しいクラスターを作らずに、同じクラスターを指定時刻の状態へ短時間で戻せます（Aurora MySQL互換の機能で、事前に有効化と保持期間の設定が必要です）。","kw":"","reasons":[{"l":"A","html":"手動リカバリは時間も難度も高く、運用手段として適切ではありません。"},{"l":"B","html":"PITRは新しいクラスターを作成するため時間がかかり、「短時間で」という要件に合いません。"},{"l":"C","html":"リードレプリカは削除操作も複製済みのため、昇格しても失われた行は戻りません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.2 Amazon Aurora</a>"},{"n":2,"topic":"Aurora","level":2,"body":["本番のAuroraクラスター（データ量2 TB）と同じデータで、性能試験を行う検証環境を用意します。要件は (1) <b>短時間で用意</b>できること、(2) ストレージコストを抑えること、(3) 本番に影響を与えないこと、の3つです。適切な方法はどれですか。"],"options":[{"l":"A","html":"Auroraの高速データベースクローンを作成する"},{"l":"B","html":"スナップショットを取得し、新しいクラスターへ復元する"},{"l":"C","html":"リードレプリカを追加し、検証用に使う"},{"l":"D","html":"mysqldumpでエクスポートし、別クラスターへインポートする"}],"answer":["A"],"multi":false,"req":"","key":"<b>高速クローンはコピーオンライト方式</b>で、データを複製せずに即座に別クラスターを作れます。<b>変更された分だけストレージが増える</b>ためコストも抑えられます。","kw":"","reasons":[{"l":"B","html":"2 TBの復元には時間がかかり、ストレージも丸ごと複製されます。"},{"l":"C","html":"レプリカは本番クラスターの一部であり、性能試験の負荷が本番へ影響します（要件3に反する）。"},{"l":"D","html":"エクスポート・インポートは最も時間がかかり、本番への負荷もかかります。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.2 Amazon Aurora</a>"},{"n":3,"topic":"RDSの運用","level":3,"body":["Amazon RDS for PostgreSQLの<b>メジャーバージョンアップ</b>を実施します。要件は (1) 本番と同じ構成で事前に検証する、(2) 切り替えのダウンタイムを<b>数分以内</b>に抑える、(3) 問題があれば元に戻せる、の3つです。適切な方法はどれですか。"],"options":[{"l":"A","html":"スナップショットから新バージョンのインスタンスを復元し、アプリの接続先を変更する"},{"l":"B","html":"メンテナンスウィンドウでインプレースアップグレードを実行する"},{"l":"C","html":"RDS Blue/Greenデプロイを使い、緑環境で検証してから切り替える"},{"l":"D","html":"リードレプリカを新バージョンで作成し、昇格させる"}],"answer":["C"],"multi":false,"req":"","key":"<b>Blue/Greenデプロイは本番の複製（緑）を作り、継続的に同期しながら検証</b>でき、切り替えは通常1分程度です。切り戻しも容易で、3要件すべてに合致します。","kw":"","reasons":[{"l":"A","html":"復元時点以降の差分が失われ、ダウンタイムも長くなります。"},{"l":"B","html":"インプレースはダウンタイムが長く、事前検証も切り戻しも困難です。"},{"l":"D","html":"クロスバージョンのレプリカ構成は制約が多く、検証と切り戻しの枠組みも自前で用意する必要があります。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a>"},{"n":4,"topic":"DBの性能分析","level":2,"body":["RDSインスタンスで、特定の時間帯にだけ応答が遅くなります。<b>どのSQLがどの待機イベントで時間を消費しているか</b>を特定したいと考えています。適切な機能はどれですか。"],"options":[{"l":"A","html":"CloudWatchの標準メトリクス（CPUUtilization、DatabaseConnections）"},{"l":"B","html":"Performance Insights"},{"l":"C","html":"拡張モニタリング（Enhanced Monitoring）"},{"l":"D","html":"VPCフローログ"}],"answer":["B"],"multi":false,"req":"","key":"<b>Performance Insightsはデータベースの負荷（DBロード）を待機イベントと上位SQL単位で可視化</b>します。「どのクエリが原因か」を突き止める機能です。","kw":"","reasons":[{"l":"A","html":"標準メトリクスは「遅い」という事実までは分かっても、原因のSQLは特定できません。"},{"l":"C","html":"拡張モニタリングはOSレベルの指標（プロセスごとのCPU・メモリなど）で、SQL単位の分析はできません。"},{"l":"D","html":"フローログはネットワーク通信の記録で、DB内部の待機とは無関係です。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":5,"topic":"キャパシティ計算","level":3,"body":["DynamoDBテーブルで、<b>1項目あたり6 KB</b>の項目を<b>毎秒80回、結果整合性のある読み取り</b>で取得します。プロビジョニングすべき読み取りキャパシティユニット（RCU）はいくつですか。"],"options":[{"l":"A","html":"40 RCU"},{"l":"B","html":"80 RCU"},{"l":"C","html":"160 RCU"},{"l":"D","html":"240 RCU"}],"answer":["B"],"multi":false,"req":"","key":"手順は3段階です。<b>①項目サイズを4 KB単位に切り上げる</b>（6 KB → 2 単位）。<b>②強い整合性なら 2 RCU／回</b>。<b>③結果整合性はその半分</b>なので 1 RCU／回。これを毎秒80回なので <b>80 RCU</b> です。","kw":"","reasons":[{"l":"A","html":"さらに半分にした値です。結果整合性の割引を二重に適用しています。"},{"l":"C","html":"強い整合性で計算した場合の値（2 × 80）です。設問は結果整合性です。"},{"l":"D","html":"項目サイズの切り上げを誤り、3単位（6 KB ÷ 4 KB を3と数える）として計算した場合の値です。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a> ／ <a href=\"#kw\" data-go=\"kw\">付録B 主要な数値クォータ</a>"},{"n":6,"topic":"インメモリDB","level":3,"body":["リアルタイム入札システムで、<b>マイクロ秒台の読み書き</b>が必要です。加えて、扱うデータは<b>障害時に失われてはならず</b>、このデータストア自体がプライマリのデータベースとして機能する必要があります。適切なサービスはどれですか。"],"options":[{"l":"A","html":"Amazon MemoryDB"},{"l":"B","html":"Amazon ElastiCache for Redis（クラスターモード有効）"},{"l":"C","html":"Amazon DynamoDB Accelerator（DAX）"},{"l":"D","html":"Amazon ElastiCache for Memcached"}],"answer":["A"],"multi":false,"req":"","key":"<b>MemoryDBはRedis互換でありながら、マルチAZのトランザクションログにより耐久性を持つ</b>ため、キャッシュではなく<b>プライマリDBとして</b>使えます。","kw":"","reasons":[{"l":"B","html":"ElastiCacheは基本的にキャッシュ層で、永続化の仕組みはあるものの、プライマリDBとしての耐久性保証は目的が異なります。"},{"l":"C","html":"DAXはDynamoDBの前段に置くキャッシュで、単体のデータベースではありません。"},{"l":"D","html":"Memcachedは永続化もレプリケーションもなく、要件から最も遠い選択肢です。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.4 Amazon ElastiCache</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A データベース</a>"},{"n":7,"topic":"データウェアハウス","level":2,"body":["Amazon Redshiftで運用中のデータウェアハウスに加え、<b>S3に蓄積された過去5年分の生ログ</b>も分析対象にしたいという要望が出ました。ログをRedshiftへロードするとストレージが逼迫します。適切な方法はどれですか。"],"options":[{"l":"A","html":"ログをDynamoDBへ移し、Redshiftから外部テーブルとして参照して集計する"},{"l":"B","html":"すべてのログをCOPYコマンドでRedshiftへロードする"},{"l":"C","html":"Redshift Spectrumで直接クエリする"},{"l":"D","html":"Redshiftクラスターのノード数を増やす"}],"answer":["C"],"multi":false,"req":"","key":"<b>Redshift SpectrumはS3のデータをロードせずに直接クエリ</b>できます。Redshift内のテーブルとの結合も可能で、ストレージを増やさずに分析範囲を広げられます。","kw":"","reasons":[{"l":"A","html":"DynamoDBは大規模な分析クエリには向かず、構成も複雑になります。"},{"l":"B","html":"ストレージの逼迫という前提に反し、コストも増えます。"},{"l":"D","html":"ノード追加はコスト増であり、S3のデータを扱えるようにする解決にはなりません。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.4 Amazon Redshift</a>"},{"n":8,"topic":"データウェアハウス","level":2,"body":["Redshiftクラスターは日中は安定していますが、<b>毎朝9時にレポートクエリが集中</b>し、待ち行列が発生して結果が返るまで数十分かかります。それ以外の時間帯は余裕があります。適切な対処はどれですか。"],"options":[{"l":"A","html":"クラスターを常時2倍のノード数へリサイズし、朝の集中に備える"},{"l":"B","html":"同時実行スケーリングを有効にする"},{"l":"C","html":"すべてのレポートを夜間バッチへ移す"},{"l":"D","html":"クエリのタイムアウト値を延長する"}],"answer":["B"],"multi":false,"req":"","key":"<b>同時実行スケーリングは、混雑時だけ追加のクラスター容量を自動的に割り当てます</b>。ピークの短時間だけ能力を足せるため、常時増強よりコスト効率に優れます。","kw":"","reasons":[{"l":"A","html":"ピーク以外の時間帯も課金され続け、コスト効率が悪化します。"},{"l":"C","html":"業務要件（朝のレポート）を変更する提案であり、技術的な解決になっていません。"},{"l":"D","html":"待ち時間が長くなるだけで、遅延そのものは解消しません。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.4 Amazon Redshift</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.4 データベースのコスト最適化</a>"},{"n":9,"topic":"特化型データベース","level":3,"body":["3つの要件それぞれに最も適したデータベースの組み合わせはどれですか。","1. SNSの友人関係をたどり、「友人の友人」を数ホップ先まで高速に検索したい","2. 工場のセンサーが送る<b>時系列データ</b>を保存し、期間を指定した集計を高速に行いたい","3. 金融取引の履歴を、<b>変更不可能かつ暗号学的に検証可能</b>な形で記録したい"],"options":[{"l":"A","html":"1: Amazon Neptune ／ 2: Amazon Timestream ／ 3: Amazon QLDB"},{"l":"B","html":"1: Amazon DocumentDB ／ 2: Amazon Neptune ／ 3: Amazon Managed Blockchain"},{"l":"C","html":"1: Amazon Neptune ／ 2: Amazon DynamoDB ／ 3: Amazon DocumentDB"},{"l":"D","html":"1: Amazon Keyspaces ／ 2: Amazon Timestream ／ 3: Amazon QLDB"}],"answer":["A"],"multi":false,"req":"","key":"<b>関係をたどる＝Neptune（グラフ）／時系列＝Timestream／改ざん不可能な台帳＝QLDB</b>。用途特化型DBは、キーワードとサービスが1対1で対応します。※QLDBは2025年7月31日にサポートを終了し、Timestream for LiveAnalyticsも2025年6月20日に新規顧客の受付を終了しました。古い設問では今もこの対応で出るため、知識として押さえておきます。","kw":"","reasons":[{"l":"B","html":"DocumentDBはMongoDB互換のドキュメントDB、Managed Blockchainは<b>複数組織が対等に検証する</b>分散台帳で、単一所有者の台帳にはQLDBが適します。"},{"l":"C","html":"DynamoDBでも時系列データは扱えますが、期間集計に最適化されたTimestreamが要件に合致します。DocumentDBに改ざん検証の仕組みはありません。"},{"l":"D","html":"KeyspacesはCassandra互換で、グラフ探索の用途ではありません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.6 その他の特化型データベースサービス</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A データベース</a>"},{"n":10,"topic":"DBの可用性","level":3,"body":["Amazon RDS for MySQLで、フェイルオーバー発生時に<b>アプリケーションが数分間エラーを返し続ける</b>ことが分かりました。原因は、アプリが古いエンドポイントのIPをキャッシュし続け、再接続の嵐でDBの接続数も枯渇するためです。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"マルチAZ配置を有効にする"},{"l":"B","html":"RDS Proxyを導入する"},{"l":"C","html":"リードレプリカを追加する"},{"l":"D","html":"DNSのTTLを尊重し、再接続とリトライを実装する"},{"l":"E","html":"インスタンスクラスを大きくする"}],"answer":["B","D"],"multi":true,"req":"","key":"<b>RDS Proxyは接続をプールし、フェイルオーバー時の切り替えをアプリに代わって吸収</b>します（接続の枯渇も防ぎます）。あわせて、<b>クライアント側のDNSキャッシュとリトライ設計</b>を直すのが定石です。","kw":"","reasons":[{"l":"A","html":"マルチAZはフェイルオーバーを<b>起こせるようにする</b>前提条件で、設問はすでにフェイルオーバーが発生している状況です。切り替え後の接続問題は解決しません。"},{"l":"C","html":"リードレプリカは読み取りのスケール手段で、フェイルオーバー時の再接続には関係しません。"},{"l":"E","html":"インスタンスを大きくしても、DNSキャッシュや再接続の嵐という原因は残ります。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"}]},{"id":"exam-set-12","file":"set-12.md","num":"問題セット12","title":"頻出⑥：セキュリティ運用・IaC・エッジ・AI","questions":[{"n":1,"topic":"証明書","level":2,"body":["CloudFrontディストリビューションに独自ドメインのHTTPS証明書を設定しようとしたところ、<b>ACMで発行済みの証明書が選択肢に表示されません</b>。証明書は東京リージョン（ap-northeast-1）で発行しています。適切な対処はどれですか。"],"options":[{"l":"A","html":"AWS Private CAで証明書を再発行する"},{"l":"B","html":"CloudFrontのディストリビューションを東京リージョンで作り直す"},{"l":"C","html":"証明書をALBに関連付けてから、CloudFrontのオリジンをALBに変更する"},{"l":"D","html":"証明書をus-east-1で発行し直す"}],"answer":["D"],"multi":false,"req":"","key":"<b>CloudFrontで使うACM証明書は、バージニア北部（us-east-1）である必要があります</b>（CloudFrontがグローバルサービスのため）。ALB用は、そのALBと同じリージョンで発行します。","kw":"","reasons":[{"l":"A","html":"Private CAは社内向けのプライベート証明書用で、一般の利用者が検証できる公開証明書にはなりません。"},{"l":"B","html":"CloudFrontはグローバルサービスで、リージョンを指定して作成するものではありません。"},{"l":"C","html":"ALBに証明書を付けても、CloudFrontのビューア向け証明書の要件（us-east-1）は変わりません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.7 AWS Certificate Manager</a> ／ <a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFrontとGlobal Accelerator</a>"},{"n":2,"topic":"DDoS対策","level":3,"body":["大規模なキャンペーンを控え、DDoS攻撃への備えを強化します。要件は (1) 攻撃中に<b>AWSの専門チームの支援</b>を受けられる、(2) 攻撃に起因して急増したスケーリング費用の<b>補償</b>を受けられる、(3) L7の攻撃にも対応する、の3つです。適切な選択はどれですか。"],"options":[{"l":"A","html":"AWS Shield Advanced を契約する"},{"l":"B","html":"AWS Shield Standard を有効化する"},{"l":"C","html":"AWS WAFのレートベースルールのみを設定する"},{"l":"D","html":"Network Firewallを導入する"}],"answer":["A"],"multi":false,"req":"","key":"<b>SRT（Shield Response Team）の支援と、DDoSに起因するスケーリング費用の補償はShield Advancedの機能</b>です。要件(1)(2)が出たら即決できます。","kw":"","reasons":[{"l":"B","html":"StandardはすべてのAWS利用者に自動適用される基本的なL3/L4防御で、専門チームの支援や費用補償はありません。"},{"l":"C","html":"WAFは有効な対策ですが、単体では支援体制や費用補償は付きません。"},{"l":"D","html":"Network FirewallはVPCのトラフィック検査用で、大規模DDoSの緩和を担う製品ではありません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.6 AWS Shield</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.3 多層防御</a>"},{"n":3,"topic":"検出から対応まで","level":3,"body":["GuardDutyが「EC2インスタンスが既知のマルウェア配布元と通信している」という検出結果を出したとき、<b>人手を介さずに自動で当該インスタンスを隔離</b>したいと考えています。適切な構成はどれですか。"],"options":[{"l":"A","html":"GuardDutyの検出結果をCloudTrailに記録し、定期的に確認する"},{"l":"B","html":"検出結果をEventBridgeで受け、Lambdaで隔離する"},{"l":"C","html":"AWS Configルールで、GuardDutyの検出結果を評価して修復する"},{"l":"D","html":"Security Hubで検出結果を集約し、重大度の高いものを担当者へメールで通知する"}],"answer":["B"],"multi":false,"req":"","key":"<b>検出（GuardDuty）→ 振り分け（EventBridge）→ 対応（Lambda／SSM Automation）</b>が自動対応の定型パターンです。","kw":"","reasons":[{"l":"A","html":"CloudTrailはAPI操作の記録であり、検出結果の保存先でも自動対応の仕組みでもありません。"},{"l":"C","html":"Configが評価するのは<b>リソースの設定</b>で、GuardDutyの検出結果を入力とする仕組みではありません。"},{"l":"D","html":"集約と通知までで、<b>自動で隔離する</b>という要件を満たしません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.11 Amazon GuardDuty</a> ／ <a href=\"#integration\" data-go=\"integration\">第6章 6.3 Amazon EventBridge</a>"},{"n":4,"topic":"IaC","level":3,"body":["CloudFormationで構築した検証環境を削除する際、<b>RDSインスタンスのデータだけは残したい</b>（またはスナップショットとして保全したい）と考えています。適切な方法はどれですか。"],"options":[{"l":"A","html":"スタックを削除する前に、RDSに削除保護を設定する"},{"l":"B","html":"RDSリソースに <code>DeletionPolicy: Snapshot</code> を指定する"},{"l":"C","html":"スタックポリシーで、RDSリソースの更新を拒否する"},{"l":"D","html":"スタックを削除せず、手動でリソースを1つずつ削除する"}],"answer":["B"],"multi":false,"req":"","key":"<b>DeletionPolicy はスタック削除時のリソースの扱いを指定</b>します。<code>Snapshot</code> はスナップショットを残して削除、<code>Retain</code> はリソースを残します。データ消失事故を防ぐ定番の設定です。","kw":"","reasons":[{"l":"A","html":"削除保護が有効だとスタックの削除自体が失敗し、中途半端な状態になります（データ保全の仕組みではありません）。"},{"l":"C","html":"スタックポリシーは<b>更新時</b>の保護で、削除時の挙動は制御しません。"},{"l":"D","html":"手動削除はスタックとの整合性が崩れ、再現性も失われます。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.3 AWS CloudFormation</a>"},{"n":5,"topic":"障害情報","level":2,"body":["あるリージョンで自社システムに断続的な障害が出ています。<b>AWS側のサービス障害やメンテナンスが、自分のアカウントのリソースに影響していないか</b>を確認したいと考えています。適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS Health Dashboard"},{"l":"B","html":"Amazon CloudWatch の標準メトリクス"},{"l":"C","html":"AWS Trusted Advisor"},{"l":"D","html":"AWS CloudTrail"}],"answer":["A"],"multi":false,"req":"","key":"<b>AWS側の障害・メンテナンス・自分のリソースへの影響を知らせるのがHealth Dashboard</b>です。EventBridgeと連携して自動通知もできます。","kw":"","reasons":[{"l":"B","html":"CloudWatchは自分のリソースの状態を示すもので、AWS基盤側の障害情報は扱いません。"},{"l":"C","html":"Trusted Advisorはベストプラクティスの点検で、障害情報の通知はしません。"},{"l":"D","html":"CloudTrailは自分のアカウントでのAPI操作の記録です。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.8 その他の管理、監視、ガバナンスサービス</a>"},{"n":6,"topic":"AIサービス","level":2,"body":["3つの要件に最も適したサービスの組み合わせはどれですか。","1. スキャンした<b>請求書PDFから、表とフォームの項目を構造化データとして</b>抽出したい","2. コールセンターの<b>通話音声を文字起こし</b>したい","3. 文字起こしした内容から<b>苦情かどうかの感情</b>を判定したい"],"options":[{"l":"A","html":"1: Amazon Comprehend ／ 2: Amazon Transcribe ／ 3: Amazon Textract"},{"l":"B","html":"1: Amazon Rekognition ／ 2: Amazon Polly ／ 3: Amazon Translate"},{"l":"C","html":"1: Amazon Textract ／ 2: Amazon Transcribe ／ 3: Amazon Comprehend"},{"l":"D","html":"1: Amazon Textract ／ 2: Amazon Polly ／ 3: Amazon Comprehend"}],"answer":["C"],"multi":false,"req":"","key":"<b>入力の種類で一意に決まります</b>。文書＝Textract（単なるOCRではなく表・フォームの構造化）、音声→テキスト＝Transcribe、テキストの意味・感情＝Comprehend。","kw":"","reasons":[{"l":"A","html":"ComprehendとTextractの役割が入れ替わっています。"},{"l":"B","html":"Rekognitionは画像・動画、Pollyは<b>テキスト→音声</b>（向きが逆）、Translateは翻訳です。"},{"l":"D","html":"Pollyは読み上げであり、音声の文字起こしはできません。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.3〜10.8 機械学習・AIサービス</a>"},{"n":7,"topic":"メール送信","level":2,"body":["ECサイトから、<b>注文確認メールを1日あたり10万通</b>送信します。HTMLメールのテンプレート管理と、バウンス率・苦情率の把握が必要です。適切なサービスはどれですか。"],"options":[{"l":"A","html":"Amazon SES"},{"l":"B","html":"Amazon SNSのEメールサブスクリプション"},{"l":"C","html":"Amazon Pinpoint のプッシュ通知"},{"l":"D","html":"Amazon WorkMail"}],"answer":["A"],"multi":false,"req":"","key":"<b>大量のトランザクションメール送信はSES</b>です。テンプレート、配信統計（バウンス・苦情）、専用IPなどの機能を備えます。","kw":"","reasons":[{"l":"B","html":"SNSのEメールは運用通知向けで、<b>購読者による購読確認が必要</b>なうえHTMLテンプレートも使えません。顧客向けの大量送信には適しません。"},{"l":"C","html":"Pinpointはキャンペーン配信やセグメント配信の基盤で、プッシュ通知は今回の要件と異なります（メール送信自体はSESの仕組みを使います）。なおPinpointは2026年10月30日にサポート終了予定です。"},{"l":"D","html":"WorkMailは社内向けのメールボックスサービスです（2026年4月30日に新規顧客の受付を終了）。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.2 フロントエンド・モバイル向けサービス</a>"},{"n":8,"topic":"エッジロケーション","level":3,"body":["3つの要件に最も適したサービスの組み合わせはどれですか。","1. 法規制により、<b>データを自社データセンターの外に出せない</b>が、AWSのAPIで運用したい","2. 都市部の利用者へ、<b>一桁ミリ秒</b>のレイテンシで動画編集アプリを提供したい","3. <b>5G回線のモバイル端末</b>に対し、超低遅延で推論結果を返したい"],"options":[{"l":"A","html":"1: AWS Outposts ／ 2: Amazon CloudFront ／ 3: AWS Local Zones"},{"l":"B","html":"1: AWS Local Zones ／ 2: AWS Outposts ／ 3: Amazon CloudFront"},{"l":"C","html":"1: AWS Outposts ／ 2: AWS Local Zones ／ 3: AWS Wavelength"},{"l":"D","html":"1: AWS Snowball Edge ／ 2: AWS Wavelength ／ 3: AWS Local Zones"}],"answer":["C"],"multi":false,"req":"","key":"<b>自社DC内＝Outposts／大都市圏の一桁ミリ秒＝Local Zones／5Gキャリア網＝Wavelength</b>。3つは設置場所で区別します。","kw":"","reasons":[{"l":"A","html":"CloudFrontはコンテンツ配信のキャッシュで、アプリケーションの実行環境ではありません。"},{"l":"B","html":"1と2が逆です。Local Zonesは自社データセンターではなくAWSが運営する小規模拠点です。"},{"l":"D","html":"Snowball Edgeは一時的な現場処理やデータ移送用で、常設の低遅延基盤ではありません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.4 AWS Outposts</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A ネットワーク</a>"},{"n":9,"topic":"サーバー移行","level":2,"body":["オンプレミスで稼働する<b>200台の仮想サーバー</b>をAWSへ移行します。要件は (1) アプリケーションを書き換えずそのまま移す、(2) 切り替え時のダウンタイムを<b>数分</b>に抑える、(3) 移行前に各サーバーの依存関係と使用状況を把握する、の3つです。適切な組み合わせはどれですか。"],"options":[{"l":"A","html":"各サーバーのAMIを手動で作成し、順次起動する"},{"l":"B","html":"AWS DataSync で仮想ディスクをコピーし、EC2で起動する"},{"l":"C","html":"AWS Database Migration Service（DMS）で、サーバーごとにデータを継続的に複製して移行する"},{"l":"D","html":"Application Discovery Serviceで調査し、Application Migration Service（MGN）で移行する"}],"answer":["D"],"multi":false,"req":"","key":"<b>リフト＆シフト＝MGN</b>（ブロックレベルの継続的複製でダウンタイムを最小化）、<b>移行前の資産調査＝Application Discovery Service</b>。移行の定型セットです。※Application Discovery Serviceは2025年11月7日に新規顧客の受付を終了し、後継はAWS Transformです。試験では今もこの組み合わせで出るため、対応関係として押さえます。","kw":"","reasons":[{"l":"A","html":"200台を手作業で扱うのは非現実的で、ダウンタイムも長くなります。"},{"l":"B","html":"DataSyncはファイル転送サービスで、稼働中サーバーの継続的複製やカットオーバーの仕組みはありません。"},{"l":"C","html":"DMSはデータベースの移行ツールで、サーバー全体の移行には使いません。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.15 その他の移行サービス</a>"},{"n":10,"topic":"コストの監視","level":2,"body":["先月、設定ミスにより特定サービスの利用料が通常の10倍に膨らみ、月末の請求で初めて気づきました。<b>早期に気づける仕組み</b>を用意します。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"AWS Cost and Usage Report をS3へ出力する設定を有効にする"},{"l":"B","html":"すべてのリソースにコスト配分タグを付与する"},{"l":"C","html":"AWS Cost Anomaly Detection を設定し、異常な支出パターンを検知したら通知する"},{"l":"D","html":"Cost Explorer で毎月末にレポートを確認する運用を定める"},{"l":"E","html":"AWS Budgets で予算と予測超過のしきい値を設定し、アラートを受け取る"}],"answer":["C","E"],"multi":true,"req":"","key":"<b>気づく仕組み＝能動的に通知が飛ぶもの</b>です。Cost Anomaly Detectionは機械学習で異常を検知し、Budgetsはしきい値（実績・予測）超過で通知します。","kw":"予測値に基づく予算アラート","reasons":[{"l":"A","html":"CURは詳細データの出力であり、それ自体は通知しません（分析の材料です）。"},{"l":"B","html":"タグは可視化・配賦の前提として有用ですが、単体では異常を知らせません。"},{"l":"D","html":"月末の確認では「請求で初めて気づく」という現状と大差ありません。"}],"refs":"<a href=\"#d4\" data-go=\"d4\">第14章 14.1 コスト管理ツールの使い分け</a> ／ <a href=\"#others\" data-go=\"others\">第10章 10.9〜10.11 コスト管理サービス</a>"}]},{"id":"exam-set-13","file":"set-13.md","num":"問題セット13","title":"第1分野 2周目：セキュアなアーキテクチャの設計","questions":[{"n":1,"topic":"IAMロール","level":3,"body":["別アカウントの開発者が<code>sts:AssumeRole</code>を実行したところ、<code>AccessDenied</code>が返りました。ロールにはS3への必要な権限がアタッチされており、開発者側のIAMユーザーにも<code>sts:AssumeRole</code>が許可されています。次に確認すべき設定はどれですか。"],"options":[{"l":"A","html":"S3バケットのバケットポリシーで、ロールからのアクセスが許可されているか"},{"l":"B","html":"ロールにアタッチされた権限ポリシーで、S3バケットへの読み取りが許可されているか"},{"l":"C","html":"ロールの信頼ポリシーで、相手アカウントからの引き受けが許可されているか"},{"l":"D","html":"ロールの最大セッション時間が、要求した時間より短く設定されていないか"}],"answer":["C"],"multi":false,"req":"","key":"IAMロールには2種類のポリシーがあります。<b>信頼ポリシー（誰が引き受けられるか）</b>と<b>権限ポリシー（引き受けた後に何ができるか）</b>。<code>AssumeRole</code>自体が拒否されている＝<b>引き受けの段階</b>なので、信頼ポリシーを確認します。","kw":"信頼ポリシー","reasons":[{"l":"A","html":"バケットポリシーはS3操作時の認可で、<code>AssumeRole</code>の失敗とは別の層です。"},{"l":"B","html":"権限ポリシーは引き受けた<b>後</b>に効くもので、引き受けの可否には影響しません。"},{"l":"D","html":"セッション時間は有効期限の設定で、引き受けの可否を左右しません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":2,"topic":"条件キー","level":3,"body":["S3バケットへのアクセスを、<b>特定のVPCエンドポイント経由のリクエストだけ</b>に限定したいと考えています。インターネット経由や他のVPCからのアクセスは、たとえ正しいIAM権限を持っていても拒否する必要があります。適切な方法はどれですか。"],"options":[{"l":"A","html":"IAMポリシーに <code>aws:SourceIp</code> 条件を追加し、VPCのCIDR以外からのアクセスを拒否する"},{"l":"B","html":"セキュリティグループのアウトバウンドで、S3のIPレンジ以外への通信を拒否する"},{"l":"C","html":"バケットポリシーで、<code>aws:SourceVpce</code> 以外をDenyする"},{"l":"D","html":"バケットのブロックパブリックアクセスを有効化する"}],"answer":["C"],"multi":false,"req":"","key":"<b>リソース側（バケットポリシー）の条件キーで経路を縛る</b>のが定石です。<code>aws:SourceVpce</code>（エンドポイントID）や<code>aws:SourceVpc</code>（VPC ID）を使い、条件に合わない場合は明示的に拒否します。","kw":"","reasons":[{"l":"A","html":"<code>aws:SourceIp</code>はVPCエンドポイント経由のリクエストには一致しません（プライベート経路のため）。"},{"l":"B","html":"セキュリティグループはENI単位の制御で、S3側で「どの経路から来たか」を判定するものではありません。"},{"l":"D","html":"ブロックパブリックアクセスは公開設定を防ぐ機能で、経路の限定はできません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":3,"topic":"権限の委譲","level":3,"body":["各開発チームのリーダーに、自チーム用のIAMロール作成を任せることになりました。ただし、**リーダーが自分やチームに管理者権限（<code>*:*</code>）を与えられてはなりません**。適切な仕組みはどれですか。"],"options":[{"l":"A","html":"リーダーのIAMユーザーに管理者ポリシーをアタッチし、付与できる権限は運用ルールで制限する"},{"l":"B","html":"CloudTrailでロール作成を監視し、事後にレビューする"},{"l":"C","html":"AWS Configルールで、作成された管理者権限のロールを検出し、自動修復で削除する"},{"l":"D","html":"作成するロールにアクセス許可境界の付与を必須とする条件付きポリシーをリーダーに与える"}],"answer":["D"],"multi":false,"req":"","key":"<b>アクセス許可境界は「そのIAMエンティティが持てる権限の上限」</b>を定めます。委譲する相手のポリシーに「境界を付けたエンティティしか作れない」という条件を入れるのが、権限委譲の標準パターンです。","kw":"アクセス許可境界（Permissions Boundary）","reasons":[{"l":"A","html":"技術的な制限がなく、運用ルールだけでは防げません。"},{"l":"B","html":"CloudTrailは記録であり、予防にはなりません。"},{"l":"C","html":"Configは<b>事後の検出と修復</b>で、作成そのものを防げません（設問は予防を求めています）。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":4,"topic":"公開状態の検出","level":2,"body":["監査に備え、<b>アカウント内のS3バケット・IAMロール・KMSキーなどが、組織外の第三者と共有されていないか</b>を継続的に洗い出したいと考えています。適切なサービスはどれですか。"],"options":[{"l":"A","html":"Amazon Macie"},{"l":"B","html":"IAM Access Analyzer"},{"l":"C","html":"Amazon Inspector"},{"l":"D","html":"AWS Trusted Advisor"}],"answer":["B"],"multi":false,"req":"","key":"<b>IAM Access Analyzerは、リソースポリシーを解析して「外部エンティティからアクセス可能なリソース」を検出</b>します。信頼ゾーン（アカウントまたは組織）の外部への共有を洗い出す専用の仕組みです。","kw":"","reasons":[{"l":"A","html":"MacieはS3内の<b>データの中身</b>（個人情報など）を検出するサービスで、共有設定の解析はしません。"},{"l":"C","html":"Inspectorは脆弱性診断で、ポリシーの解析は行いません。"},{"l":"D","html":"Trusted Advisorにも公開バケットの点検項目はありますが、IAMロールやKMSキーまで含めたポリシー解析の網羅性ではAccess Analyzerが適切です。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.13 その他のセキュリティ・ガバナンスサービス</a>"},{"n":5,"topic":"KMSのクロスアカウント","level":3,"body":["アカウントAのKMSカスタマー管理キーで暗号化したS3オブジェクトを、アカウントBのIAMロールから読み取らせます。バケットポリシーではアカウントBに<code>s3:GetObject</code>を許可済みですが、取得時に<code>AccessDenied</code>になります。追加で必要な設定はどれですか。"],"options":[{"l":"A","html":"アカウントAのKMSキーポリシーでアカウントBに<code>kms:Decrypt</code>を許可し、アカウントB側のIAMポリシーでも同じ操作を許可する"},{"l":"B","html":"S3バケットのブロックパブリックアクセスを無効化する"},{"l":"C","html":"アカウントBでKMSキーを新規作成する"},{"l":"D","html":"オブジェクトの暗号化方式をSSE-S3に変更する"}],"answer":["A"],"multi":false,"req":"","key":"<b>KMSはキーポリシーが必須</b>です。クロスアカウントでは「<b>キー所有側のキーポリシーでの許可</b>」と「<b>利用側アカウントのIAMポリシーでの許可</b>」の<b>両方</b>が揃って初めて復号できます。","kw":"KMSキーポリシー","reasons":[{"l":"B","html":"公開設定とは無関係で、セキュリティを損なうだけです。"},{"l":"C","html":"別のキーを作っても、既存オブジェクトは元のキーで暗号化されているため復号できません。"},{"l":"D","html":"暗号化方式を変えるにはオブジェクトの再暗号化が必要で、監査要件がある場合はSSE-KMSを外せません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.8 AWS KMS</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":6,"topic":"S3のデータ保護","level":3,"body":["S3バケットのデータ保護について、2つの要件があります。それぞれに適した機能はどれですか。","1. 運用担当者による<b>バージョンの完全削除</b>を防ぎたい（削除時にMFAを要求する）","2. 規制対応として、<b>指定期間は誰も上書き・削除できない</b>状態にしたい"],"options":[{"l":"A","html":"1: オブジェクトロック（ガバナンスモード） ／ 2: MFA削除"},{"l":"B","html":"1: MFA削除 ／ 2: オブジェクトロック（コンプライアンスモード）"},{"l":"C","html":"1: バージョニング ／ 2: ライフサイクルポリシー（保存期間後に失効）"},{"l":"D","html":"1: バケットポリシーのDeny ／ 2: レプリケーション"}],"answer":["B"],"multi":false,"req":"","key":"<b>MFA削除＝削除操作に追加認証を要求する運用上の歯止め</b>、<b>オブジェクトロックのコンプライアンスモード＝期間中は誰も（ルートユーザーでも）変更・削除できないWORM</b>。規制対応はオブジェクトロックです。","kw":"","reasons":[{"l":"A","html":"役割が逆です。ガバナンスモードは特別な権限を持つ利用者が解除できるため、厳格な規制要件には足りません。"},{"l":"C","html":"バージョニングは上書き・削除からの復旧手段、ライフサイクルは移行と失効の自動化で、保護の強制力はありません。"},{"l":"D","html":"バケットポリシーは権限があれば変更でき、レプリケーションは複製であって保護ではありません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":7,"topic":"アプリの認証","level":3,"body":["モバイルアプリの利用者が、S3バケット内の<b>自分専用のフォルダ（プレフィックス）だけ</b>に読み書きできるようにします。利用者数は数十万人規模で、1人ずつIAMユーザーを作ることはできません。適切な構成はどれですか。"],"options":[{"l":"A","html":"事前署名URLを、利用者のアクセスのたびに手動で発行する"},{"l":"B","html":"すべての利用者で共有する1つのIAMユーザーのアクセスキーをアプリに埋め込み、プレフィックスはアプリ側で分ける"},{"l":"C","html":"利用者ごとにS3バケットを作成し、それぞれのバケットポリシーで利用者を限定する"},{"l":"D","html":"Cognito IDプールの一時認証情報を、ポリシー変数で利用者ごとに絞る"}],"answer":["D"],"multi":false,"req":"","key":"<b>Cognito IDプールは認証済み利用者に一時認証情報を渡す</b>仕組みで、<b>ポリシー変数</b>を使えば「自分のIDに対応するプレフィックスのみ」という制御が1つのポリシーで実現できます。","kw":"","reasons":[{"l":"A","html":"手動発行は運用が破綻します（バックエンドで自動発行する設計はあり得ますが、選択肢は「手動」です）。"},{"l":"B","html":"全利用者が同じ権限を持ち、キーの漏洩リスクも高く、利用者ごとの分離ができません。"},{"l":"C","html":"バケット数には上限があり、数十万人分の運用は現実的ではありません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.4 Amazon Cognito</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":8,"topic":"通信の制御","level":3,"body":["VPC内のEC2インスタンスからの外部通信を、<b>許可されたドメイン名（FQDN）宛てだけに制限</b>したいと考えています。宛先IPアドレスは頻繁に変わるため、IPベースの制御では運用できません。適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS Network Firewall"},{"l":"B","html":"ネットワークACL（アウトバウンドの拒否ルール）"},{"l":"C","html":"セキュリティグループ"},{"l":"D","html":"AWS WAF"}],"answer":["A"],"multi":false,"req":"","key":"<b>ドメイン名（FQDN）単位のフィルタリングができるのはNetwork Firewall</b>です。SGとNACLはIPアドレスとポートでしか制御できません。","kw":"","reasons":[{"l":"B","html":"NACLはIP／ポート／プロトコルによる制御で、ドメイン名は扱えません。"},{"l":"C","html":"セキュリティグループも同様で、宛先はIPかプレフィックスリスト（またはSG）で指定します。"},{"l":"D","html":"WAFは<b>受信するHTTPリクエスト</b>の検査で、EC2からの送信先の制御には使いません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.1 VPCの基礎</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.3 多層防御</a>"},{"n":9,"topic":"組織全体の統制","level":3,"body":["Organizationsで管理する40アカウントすべてに対し、<b>同一のAWS WAFルールを適用</b>し、<b>新しく作成されたアカウントにも自動的に適用</b>されるようにしたいと考えています。適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS Firewall Manager"},{"l":"B","html":"各アカウントでCloudFormation StackSetsを手動実行する"},{"l":"C","html":"AWS Config のコンフォーマンスパック"},{"l":"D","html":"Service Control Policy（SCP）"}],"answer":["A"],"multi":false,"req":"","key":"<b>Firewall Managerは、WAF・Shield Advanced・セキュリティグループ・Network Firewallのポリシーを組織全体へ一元適用</b>します。新規アカウントにも自動で適用される点が要件に合致します。","kw":"","reasons":[{"l":"B","html":"StackSets自体は自動展開も可能ですが、WAFルールの準拠状態を継続的に強制・是正する仕組みは別途必要です。「手動実行」という選択肢の記述も要件に反します。"},{"l":"C","html":"Configは準拠状況の評価で、WAFルールそのものを配布・適用するサービスではありません。"},{"l":"D","html":"SCPは操作の許可範囲を制限するもので、リソース（WAFルール）を作成・配布することはできません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.13 その他のセキュリティ・ガバナンスサービス</a> ／ <a href=\"#management\" data-go=\"management\">第8章 8.5 AWS Organizations</a>"},{"n":10,"topic":"認証情報の保護","level":2,"body":["アプリケーションがRDSへ接続する際の認証について、<b>パスワードそのものを保持せず、IAMの権限で接続</b>したいと考えています。適切な方法はどれですか。"],"options":[{"l":"A","html":"EC2のユーザーデータにパスワードを記述する"},{"l":"B","html":"データベースのパスワードをAMIに埋め込む"},{"l":"C","html":"RDSのIAMデータベース認証で接続する"},{"l":"D","html":"データベースのパスワードをS3バケットに保存し、インスタンスの起動時に取得する"}],"answer":["C"],"multi":false,"req":"","key":"<b>IAMデータベース認証は、IAMの権限に基づく短命なトークン（15分）で接続</b>する仕組みです。長期のパスワードをアプリ側に持たせずに済みます（ローテーションが必要なパスワード運用ならSecrets Managerを使います）。","kw":"","reasons":[{"l":"A","html":"ユーザーデータはインスタンスメタデータから参照でき、平文での保持は危険です。"},{"l":"B","html":"AMIに機密情報を埋め込むと、AMIの共有やコピーを通じて漏洩します。"},{"l":"D","html":"S3に置いただけでは、取得のための認証・認可とローテーションの問題が残ります。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.10 Secrets Manager vs Parameter Store</a>"},{"n":11,"topic":"脆弱性と設定の監査","level":2,"body":["監査で2つの指摘を受けました。それぞれに適したサービスはどれですか。","1. EC2インスタンスとコンテナイメージに、<b>既知の脆弱性（CVE）</b>が残っていないか継続的に確認すること","2. すべてのEBSボリュームが<b>暗号化されているか</b>を継続的に評価し、違反を記録すること"],"options":[{"l":"A","html":"1: AWS Config ／ 2: Amazon Inspector"},{"l":"B","html":"1: Amazon Inspector ／ 2: AWS Config"},{"l":"C","html":"1: Amazon GuardDuty ／ 2: AWS Trusted Advisor"},{"l":"D","html":"1: Amazon Macie ／ 2: AWS CloudTrail"}],"answer":["B"],"multi":false,"req":"","key":"<b>脆弱性（CVE）＝Inspector／リソース設定の準拠評価＝Config</b>。「ソフトウェアの欠陥」か「設定の状態」かで切り分けます。","kw":"","reasons":[{"l":"A","html":"2つの役割が入れ替わっています。"},{"l":"C","html":"GuardDutyは振る舞いの検知、Trusted Advisorは広く浅い点検で、継続的な準拠評価の仕組みではありません。"},{"l":"D","html":"MacieはS3の機密データ検出、CloudTrailはAPI操作の記録です。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.12 Amazon Inspector</a> ／ <a href=\"#management\" data-go=\"management\">第8章 8.7 AWS Config</a>"},{"n":12,"topic":"多層防御","level":3,"body":["公開Webアプリケーションのセキュリティを強化します。<b>構成として適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"CloudFrontにWeb ACLを関連付け、SQLインジェクションとレート超過を遮断する"},{"l":"B","html":"すべてのEC2インスタンスにパブリックIPを割り当て、SSHを社内IPに限定する"},{"l":"C","html":"アプリケーションサーバーをプライベートサブネットに配置し、ALB経由でのみ到達可能にする"},{"l":"D","html":"ネットワークACLですべてのアウトバウンドを拒否する"},{"l":"E","html":"ALBのセキュリティグループで、インバウンドを0.0.0.0/0の全ポートに開放する"}],"answer":["A","C"],"multi":true,"req":"","key":"多層防御は<b>エッジ（WAF）→ ネットワーク境界（サブネット分離）→ ホスト → データ</b>と層を重ねます。AとBはそれぞれ別の層を担い、両立します。","kw":"","reasons":[{"l":"B","html":"パブリックIPの付与は攻撃面を広げます。運用接続はSession Managerで代替すべきです。"},{"l":"D","html":"アウトバウンドを全拒否するとパッチ取得やAPI呼び出しが不能になり、アプリケーションが動作しません。"},{"l":"E","html":"全ポート開放は必要最小限の原則に反します。開放するのは443（と必要なら80）だけです。"}],"refs":"<a href=\"#d1\" data-go=\"d1\">第11章 11.3 多層防御</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.5 AWS WAF</a>"}]},{"id":"exam-set-14","file":"set-14.md","num":"問題セット14","title":"第2分野 2周目：弾力性に優れたアーキテクチャの設計","questions":[{"n":1,"topic":"メッセージの順序","level":3,"body":["在庫更新の処理で、<b>同じ商品IDに対する更新は送信順に処理</b>される必要があります。一方、異なる商品IDどうしは並行に処理して構いません。スループットは毎秒200メッセージ程度です。適切な構成はどれですか。"],"options":[{"l":"A","html":"SQS FIFOキューを使い、すべてのメッセージに同じメッセージグループIDを設定する"},{"l":"B","html":"SQS標準キューを使い、受信側でタイムスタンプ順に並べ替える"},{"l":"C","html":"SQS FIFOキューを使い、商品IDをメッセージグループIDに設定する"},{"l":"D","html":"SNSトピックにFIFOで発行し、Lambdaで処理する"}],"answer":["C"],"multi":false,"req":"","key":"<b>FIFOキューの順序保証はメッセージグループID単位</b>です。商品IDをグループIDにすると、同一商品内では順序が守られ、異なる商品は並行に処理できます。","kw":"メッセージグループID","reasons":[{"l":"A","html":"全メッセージを1グループにすると<b>並行処理ができなくなり</b>、スループットが大きく落ちます。"},{"l":"B","html":"標準キューは順序を保証しないため、受信側での並べ替えには到着待ちのバッファが必要になり、設計が複雑かつ不確実です。"},{"l":"D","html":"SNS FIFOトピックのサブスクライバーはSQS FIFOキューに限られ、Lambdaを直接サブスクライブさせることはできません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a>"},{"n":2,"topic":"ストリームの再処理","level":3,"body":["EventBridgeで各種イベントをLambdaへ配信しています。下流のバグにより、<b>過去3日分のイベントが正しく処理されていなかった</b>ことが判明しました。修正後、その期間のイベントを再実行したいと考えています。適切な方法はどれですか。"],"options":[{"l":"A","html":"Lambdaの非同期呼び出しの再試行回数を増やす"},{"l":"B","html":"CloudTrailのログからイベントを再構成して手動で再送する"},{"l":"C","html":"EventBridgeのアーカイブとリプレイ"},{"l":"D","html":"デッドレターキューの内容を再送する"}],"answer":["C"],"multi":false,"req":"","key":"<b>EventBridgeのアーカイブとリプレイは、保存したイベントを後から再投入する機能</b>です。「過去のイベントをやり直す」要件はこれで満たせます（事前にアーカイブの設定が必要）。","kw":"","reasons":[{"l":"A","html":"再試行は<b>失敗した</b>呼び出しへの対処です。設問は処理自体は成功し、結果が誤っていた状況です。"},{"l":"B","html":"CloudTrailはAPI操作の記録で、カスタムイベントの完全な再現には適しません。"},{"l":"D","html":"DLQには失敗したイベントしか入りません。成功扱いだったイベントは残っていません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.3 Amazon EventBridge</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.4 イベント駆動型アーキテクチャ</a>"},{"n":3,"topic":"ワークフローの選択","level":2,"body":["IoTデバイスから届くイベントごとに、<b>5つの短い処理を順に実行</b>するワークフローを構築します。イベントは<b>毎秒数千件</b>発生し、1件あたりの処理は数百ミリ秒で完了します。コストを抑えたいと考えています。適切な選択はどれですか。"],"options":[{"l":"A","html":"Step Functions の Expressワークフロー"},{"l":"B","html":"Step Functions の 標準ワークフロー"},{"l":"C","html":"Amazon SQS FIFOキューで各処理をつなぎ、Lambdaで順に処理する"},{"l":"D","html":"単一のLambda関数にすべての処理を実装する"}],"answer":["A"],"multi":false,"req":"","key":"<b>Expressワークフローは大量・高頻度・短時間（最大5分）の処理向け</b>で、実行単価が安く抑えられます。標準ワークフローは状態遷移ごとの課金で、長時間・監査重視の用途向けです。","kw":"","reasons":[{"l":"B","html":"標準は最大1年の実行と正確に1回の実行保証が特徴ですが、毎秒数千件では課金が大きくなります。"},{"l":"C","html":"キューの連結では分岐・エラー処理・全体の可視化を自前で作ることになります。"},{"l":"D","html":"単一関数に詰め込むと、途中失敗時の再実行単位が粗くなり、処理の可視化もできません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.4 AWS Step Functions</a>"},{"n":4,"topic":"ロードバランサー","level":3,"body":["新しいEC2インスタンスがターゲットグループに登録された直後、<b>キャッシュが温まっていないため応答が遅く、エラー率が上がります</b>。数分経てば安定します。適切な設定はどれですか。"],"options":[{"l":"A","html":"スロースタート期間を設定する"},{"l":"B","html":"ヘルスチェックの間隔を短くし、正常になり次第すぐに振り分ける"},{"l":"C","html":"登録解除の遅延を延長する"},{"l":"D","html":"クロスゾーン負荷分散を無効化する"}],"answer":["A"],"multi":false,"req":"","key":"<b>スロースタートは、新しく登録されたターゲットへのトラフィックを設定時間かけて徐々に増やす</b>機能です。ウォームアップが必要なアプリケーションに使います。","kw":"","reasons":[{"l":"B","html":"ヘルスチェックを頻繁にしても、ターゲットが温まる時間は短縮されません。"},{"l":"C","html":"登録解除の遅延は<b>取り外すとき</b>の設定で、追加時の挙動には関係しません。"},{"l":"D","html":"クロスゾーン負荷分散はAZ間の分散設定で、新規ターゲットの立ち上がりとは無関係です。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.5 負荷分散（ELB）</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a>"},{"n":5,"topic":"ヘルスチェック","level":3,"body":["プライベートサブネット内のアプリケーションの健全性に応じて、Route 53のDNSフェイルオーバーを行いたいと考えています。対象はインターネットから到達できないため、Route 53の通常のエンドポイントヘルスチェックでは監視できません。適切な方法はどれですか。"],"options":[{"l":"A","html":"Route 53のヘルスチェックを無効にし、TTLを短くする"},{"l":"B","html":"ヘルスチェックの対象を、パブリックに到達できるALBのDNS名に変更する"},{"l":"C","html":"アプリのサブネットをパブリックサブネットに変更し、ヘルスチェックを直接届かせる"},{"l":"D","html":"アプリのメトリクスのCloudWatchアラームを参照するヘルスチェックを設定する"}],"answer":["D"],"multi":false,"req":"","key":"Route 53のヘルスチェックには3種類（<b>エンドポイント／他のヘルスチェックの計算（親子）／CloudWatchアラーム</b>）があります。<b>インターネットから到達できない対象はCloudWatchアラーム経由</b>で監視します。","kw":"CloudWatchアラームを参照するヘルスチェック","reasons":[{"l":"A","html":"ヘルスチェックを無効にすると、異常時に切り替えが起きなくなります。"},{"l":"B","html":"ALBが内部向け（internal）であれば同じ問題が残り、そもそもアプリ固有の健全性を表すとは限りません。"},{"l":"C","html":"セキュリティ要件を壊す変更であり、可用性の問題を解く手段としても不適切です。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.4 名前解決：Route 53 と Resolver</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":6,"topic":"RDSの可用性","level":3,"body":["RDSのマルチAZ構成について、要件は (1) フェイルオーバーを<b>できるだけ短時間</b>で完了させる、(2) <b>スタンバイも読み取りに活用</b>したい、の2つです。適切な構成はどれですか。"],"options":[{"l":"A","html":"マルチAZ DBインスタンス（単一のスタンバイ）＋ リードレプリカ1台"},{"l":"B","html":"マルチAZ DBクラスター（2つの読み取り可能なスタンバイを持つ構成）"},{"l":"C","html":"シングルAZ構成＋ 別AZのリードレプリカ"},{"l":"D","html":"マルチAZ DBインスタンスを2セット用意する"}],"answer":["B"],"multi":false,"req":"","key":"<b>マルチAZ DBクラスターは、読み取り可能なスタンバイを2つ持ち、フェイルオーバーも通常のマルチAZインスタンスより短時間</b>です。2つの要件を同時に満たします。","kw":"マルチAZ DBクラスター","reasons":[{"l":"A","html":"要件は満たせますが、フェイルオーバー時間はDBクラスター構成より長く、構成要素も増えます。"},{"l":"C","html":"シングルAZでは自動フェイルオーバーがなく、レプリカの昇格は手動です。"},{"l":"D","html":"2セットは同期されておらず、可用性構成として成立しません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":7,"topic":"レプリケーション","level":3,"body":["コンプライアンス要件で、S3オブジェクトを別リージョンへ複製し、<b>複製が15分以内に完了することをSLAで保証</b>する必要があります。また、複製の進捗を監視したいと考えています。適切な設定はどれですか。"],"options":[{"l":"A","html":"ライフサイクルポリシーで別リージョンへ移行する"},{"l":"B","html":"レプリケーションルールでS3 RTCを有効にする"},{"l":"C","html":"クロスリージョンレプリケーションを有効にするだけで、SLAは自動的に適用される"},{"l":"D","html":"AWS DataSyncで15分ごとに同期する"}],"answer":["B"],"multi":false,"req":"","key":"<b>RTC（Replication Time Control）は99.99%のオブジェクトを15分以内に複製するSLA</b>と、レプリケーションメトリクス・イベント通知を提供します。通常のレプリケーションにSLAはありません。","kw":"S3 Replication Time Control（RTC）","reasons":[{"l":"A","html":"ライフサイクルはストレージクラスの移行や失効の仕組みで、別リージョンへのコピー機能ではありません。"},{"l":"C","html":"標準のレプリケーションは<b>ベストエフォート</b>で、完了時間の保証はありません。"},{"l":"D","html":"DataSyncはスケジュール転送で、15分以内という保証はなく、S3イベント連携も別途必要です。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":8,"topic":"コンテナの安全なデプロイ","level":2,"body":["Amazon ECSサービスの新しいタスク定義をデプロイした際、<b>アプリの不具合でタスクが起動に失敗し続け</b>、サービスが不安定になりました。今後は<b>失敗を検知したら自動的に前のバージョンへ戻したい</b>と考えています。適切な設定はどれですか。"],"options":[{"l":"A","html":"Fargate Spotに切り替える"},{"l":"B","html":"タスクの必要数（desired count）を増やす"},{"l":"C","html":"ターゲットグループのヘルスチェック間隔を延ばす"},{"l":"D","html":"ECSのデプロイサーキットブレーカーを有効にする"}],"answer":["D"],"multi":false,"req":"","key":"<b>デプロイサーキットブレーカーは、デプロイの失敗を検知して自動的に直前の安定版へロールバック</b>します。段階的なデプロイの安全装置です。","kw":"","reasons":[{"l":"A","html":"Fargate Spotはコスト最適化の選択で、デプロイの安全性とは無関係です（中断のリスクはむしろ増えます）。"},{"l":"B","html":"起動に失敗するタスクを増やしても状況は改善しません。"},{"l":"C","html":"ヘルスチェックを緩めると、異常なタスクが正常と扱われる時間が延びるだけです。"}],"refs":"<a href=\"#container\" data-go=\"container\">第9章 9.1 Amazon ECS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":9,"topic":"ストリーム処理","level":3,"body":["Kinesis Data Streamsを使う分析基盤で、<b>新たに3つ目のコンシューマーアプリケーション</b>を追加したところ、既存のコンシューマーの読み取りが遅延し、<code>ReadProvisionedThroughputExceeded</code>が発生するようになりました。シャード数は変えたくありません。適切な対処はどれですか。"],"options":[{"l":"A","html":"拡張ファンアウトを使う"},{"l":"B","html":"シャードのパーティションキーを変更する"},{"l":"C","html":"データ保持期間を24時間から7日へ延長し、読み遅れを後から取り戻す"},{"l":"D","html":"コンシューマーのポーリング間隔を短くする"}],"answer":["A"],"multi":false,"req":"","key":"標準のコンシューマーは<b>1シャードあたり2 MB/秒の読み取り帯域を共有</b>します。<b>拡張ファンアウトはコンシューマーごとに専用の2 MB/秒</b>を割り当てるため、シャードを増やさずに読み取りの競合を解消できます。","kw":"","reasons":[{"l":"B","html":"パーティションキーは書き込みの分散に関する設定で、読み取り帯域の共有とは無関係です。"},{"l":"C","html":"保持期間は再処理できる時間の長さで、スループットは変わりません。"},{"l":"D","html":"ポーリングを増やすと共有帯域の奪い合いが激化し、悪化します。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.1 Amazon Kinesis</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":10,"topic":"自動復旧","level":3,"body":["単一のEC2インスタンスで動く社内システムについて、<b>インスタンス障害からの復旧を自動化</b>したいと考えています。アプリケーションは冗長化に対応しておらず、当面は1台構成のままです。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"インスタンスストアにデータを保存し、再起動を速くする"},{"l":"B","html":"Auto Scalingグループ（台数1）で置き換える"},{"l":"C","html":"インスタンスタイプを大きくして、障害に強くする"},{"l":"D","html":"EC2の自動復旧を設定する"},{"l":"E","html":"終了保護を有効にし、インスタンスが消えないようにする"}],"answer":["B","D"],"multi":true,"req":"","key":"<b>1台構成でも「壊れたら作り直す」仕組みは作れます</b>。ASG（最小1台）は置き換えによる復旧、CloudWatchの復旧アクションはシステムステータスチェック失敗時に<b>同じインスタンスIDのまま別ハードウェアで起動</b>します。","kw":"","reasons":[{"l":"A","html":"インスタンスストアは停止・終了でデータが消えるため、復旧の妨げになります。"},{"l":"C","html":"サイズを上げても障害は起こり、復旧は自動化されません。"},{"l":"E","html":"終了保護は誤操作による削除を防ぐ設定で、障害からの復旧手段ではありません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"}]},{"id":"exam-set-15","file":"set-15.md","num":"問題セット15","title":"第3分野 2周目：高パフォーマンスなアーキテクチャの設計","questions":[{"n":1,"topic":"ストレージ性能","level":3,"body":["データベース用のEC2インスタンスで、EBSボリュームのIOPSを20,000までプロビジョニングしましたが、実測値は8,000前後で頭打ちになります。ボリュームのバーストクレジットは枯渇していません。最も可能性が高い原因はどれですか。"],"options":[{"l":"A","html":"ファイルシステムがXFSではなく、ext4で作られているため"},{"l":"B","html":"ボリュームタイプをgp3にしておらず、IOPSが容量に比例して制限されているため"},{"l":"C","html":"ボリュームのサイズが小さすぎ、IOPSが伸びないため"},{"l":"D","html":"インスタンスタイプのEBS帯域の上限に達している"}],"answer":["D"],"multi":false,"req":"","key":"EBSの性能は<b>ボリューム側の設定とインスタンス側のEBS帯域の両方</b>に制限されます。ボリュームでIOPSを上げても、<b>インスタンスタイプごとの上限</b>を超えることはできません。より大きい（またはEBS最適化性能の高い）インスタンスタイプへの変更が対処です。","kw":"","reasons":[{"l":"A","html":"ファイルシステムの種類でプロビジョニングしたIOPSの上限が半分になることはありません。"},{"l":"B","html":"gp3でもio2でも、インスタンス側の上限は同じように効きます。"},{"l":"C","html":"gp3やio2はIOPSを容量と独立に指定できるため、サイズが直接の原因とは限りません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.2 Amazon EBS</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":2,"topic":"共有ストレージ性能","level":2,"body":["複数のEC2インスタンスがEFSを共有しています。平常時は問題ありませんが、月次バッチの時間帯だけ<b>スループットが急激に低下</b>します。CloudWatchで確認すると、バーストクレジットの残高がゼロになっていました。適切な対処はどれですか。"],"options":[{"l":"A","html":"パフォーマンスモードを「最大I/O」に変更する"},{"l":"B","html":"スループットモードをElasticに変更する"},{"l":"C","html":"ライフサイクル管理でIAへ移行する"},{"l":"D","html":"EFSをOne Zoneストレージクラスに変更し、同じAZのインスタンスから接続する"}],"answer":["B"],"multi":false,"req":"","key":"<b>バーストスループットはファイルシステムのサイズに応じたクレジット制</b>です。クレジットが尽きてベースラインまで落ちる問題は、<b>Elasticまたはプロビジョンドスループット</b>への変更で解消します。","kw":"","reasons":[{"l":"A","html":"最大I/Oは多数クライアントの並列性を上げるモードで、レイテンシは悪化します。スループットのクレジット枯渇とは別の話です。"},{"l":"C","html":"IAへの移行は保管コストの削減で、スループットは改善しません（むしろ取り出し料金が発生します）。"},{"l":"D","html":"One Zoneはコスト最適化の選択肢で、可用性が下がるだけでスループットは変わりません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.3 Amazon EFS</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":3,"topic":"キャッシュ効率","level":3,"body":["CloudFrontを導入しましたが、<b>キャッシュヒット率が20%程度</b>と低く、オリジンの負荷が下がりません。調査すると、アプリケーションが計測用のクエリ文字列（<code>?utm_source=...</code>など）を付与しており、それらがキャッシュキーに含まれていました。適切な対処はどれですか。"],"options":[{"l":"A","html":"TTLを0に設定する"},{"l":"B","html":"キャッシュキーのクエリ文字列を絞る"},{"l":"C","html":"すべてのリクエストをオリジンへ転送し、オリジン側でキャッシュする"},{"l":"D","html":"価格クラスをAllに変更し、すべてのエッジで配信する"}],"answer":["B"],"multi":false,"req":"","key":"<b>キャッシュキーに不要な要素（クエリ文字列・ヘッダー・Cookie）が入ると、同じ内容が別物として扱われヒット率が落ちます</b>。キャッシュポリシーで必要な要素だけに絞るのが定石です。","kw":"","reasons":[{"l":"A","html":"TTLを0にするとキャッシュされなくなり、状況は悪化します。"},{"l":"C","html":"オリジンへの転送を増やすのは目的と正反対です。"},{"l":"D","html":"価格クラスは配信するエッジの範囲の設定で、ヒット率とは無関係です。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFrontとGlobal Accelerator</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.4 ネットワークパフォーマンスの最適化</a>"},{"n":4,"topic":"キャッシュ層のスケール","level":3,"body":["ElastiCache for Redisを使っていますが、<b>データ量が単一ノードのメモリ上限に近づき、書き込みのスループットも不足</b>してきました。アプリケーションの改修は許容されます。適切な対処はどれですか。"],"options":[{"l":"A","html":"ノードタイプを変更せず、TTLを短くしてメモリを空ける"},{"l":"B","html":"リードレプリカを追加する"},{"l":"C","html":"Memcachedへ移行する"},{"l":"D","html":"クラスターモードを有効にしてシャードを増やす"}],"answer":["D"],"multi":false,"req":"","key":"<b>クラスターモード（シャーディング）は、データとスループットを複数ノードへ水平分割</b>します。メモリ上限と書き込み性能の両方に効く唯一の選択肢です。","kw":"","reasons":[{"l":"A","html":"TTL短縮は一時しのぎで、根本的な容量・スループット不足は解決しません。"},{"l":"B","html":"レプリカは<b>読み取り</b>のスケールと可用性向上のためで、書き込みとメモリ容量は変わりません。"},{"l":"C","html":"Memcachedも水平分割はできますが、永続化・レプリケーション・高度なデータ型を失います。要件は改修可否のみで、機能の放棄は求められていません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.4 Amazon ElastiCache</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":5,"topic":"Auroraの読み取り分散","level":3,"body":["Auroraクラスターに15台のリーダーがあります。<b>重い分析クエリ専用に3台</b>を割り当て、通常のアプリケーションからの読み取りは残りのリーダーへ分散させたいと考えています。適切な方法はどれですか。"],"options":[{"l":"A","html":"カスタムエンドポイントを作成し、分析用の3台だけを含める"},{"l":"B","html":"リーダーエンドポイントへ接続し、アプリ側で接続先を選ぶ"},{"l":"C","html":"クラスターエンドポイントへ分析クエリを送る"},{"l":"D","html":"分析用に別のAuroraクラスターを作成し、手動で同期する"}],"answer":["A"],"multi":false,"req":"","key":"Auroraのエンドポイントは3種類。<b>クラスター（書き込み）／リーダー（全リーダーへ自動分散）／カスタム（指定したインスタンス群）</b>。用途別に分けるならカスタムエンドポイントです。","kw":"","reasons":[{"l":"B","html":"リーダーエンドポイントは接続先を自動で分散するため、特定の3台に固定できません。"},{"l":"C","html":"クラスターエンドポイントはライター宛てで、分析クエリを送ると本番の書き込みに影響します。"},{"l":"D","html":"手動同期は運用負荷が高く、データの鮮度も落ちます。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.2 Amazon Aurora</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":6,"topic":"DynamoDBのクエリ","level":3,"body":["DynamoDBテーブル（数億項目）から、<b>特定の顧客IDに紐づく注文だけ</b>を取得する処理が、極端に遅くキャパシティも大量に消費しています。実装では<code>Scan</code>にフィルター式を付けて顧客IDを絞り込んでいます。適切な対処はどれですか。"],"options":[{"l":"A","html":"顧客IDをキーに持つGSIを作り、<code>Query</code>で取得する"},{"l":"B","html":"並列スキャン（Parallel Scan）に変更する"},{"l":"C","html":"読み取りを強い整合性に変更する"},{"l":"D","html":"プロビジョニングされた読み取りキャパシティを10倍にする"}],"answer":["A"],"multi":false,"req":"","key":"<b><code>Scan</code>は全項目を読んでからフィルターする</b>ため、対象が少なくてもテーブル全体分のキャパシティを消費します。<b>キーで直接引ける<code>Query</code></b>（必要ならGSIを作る）に変えるのが根本対処です。","kw":"","reasons":[{"l":"B","html":"並列スキャンは速くなりますが、読み取り量（＝コスト）はむしろ増えます。"},{"l":"C","html":"整合性モデルを強くすると消費キャパシティは2倍になり、悪化します。"},{"l":"D","html":"キャパシティを増やしても全件読み取りという非効率は変わらず、コストだけが上がります。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":7,"topic":"グローバル配信","level":3,"body":["TCPベースのオンラインゲームでGlobal Acceleratorを利用しています。<b>同じプレイヤーのセッションが、常に同じエンドポイントへ接続される</b>ようにしたいと考えています。適切な設定はどれですか。"],"options":[{"l":"A","html":"エンドポイントの重みをすべて同じ値にして、均等に振り分ける"},{"l":"B","html":"トラフィックダイヤルを50%に設定し、残りを別のリージョンへ流す"},{"l":"C","html":"クライアントアフィニティを「送信元IP」にする"},{"l":"D","html":"ヘルスチェックの間隔を延ばす"}],"answer":["C"],"multi":false,"req":"","key":"<b>クライアントアフィニティを「送信元IP」にすると、同じクライアントからの接続が同じエンドポイントへ維持</b>されます（既定は「なし」でフローごとに分散）。","kw":"","reasons":[{"l":"A","html":"重みは分散比率の設定で、粘着性は生まれません。"},{"l":"B","html":"トラフィックダイヤルはエンドポイントグループへ流す割合の調整で、個々のクライアントの固定には使えません。"},{"l":"D","html":"ヘルスチェック間隔は障害検知の速さの設定です。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFrontとGlobal Accelerator</a>"},{"n":8,"topic":"ネットワーク性能","level":2,"body":["同一VPC内のEC2インスタンス間で、<b>大きなデータを高スループットで転送</b>したいと考えています。インスタンスは拡張ネットワーキング対応です。追加で有効な設定はどれですか。"],"options":[{"l":"A","html":"NAT Gateway経由で通信させ、帯域を確保する"},{"l":"B","html":"インスタンスにパブリックIPを割り当て、直接通信させる"},{"l":"C","html":"ジャンボフレーム（MTU 9001）を使う"},{"l":"D","html":"VPCピアリングを設定する"}],"answer":["C"],"multi":false,"req":"","key":"<b>VPC内の通信ではMTU 9001（ジャンボフレーム）が利用でき、パケットあたりのペイロードが増えてスループットが向上</b>します（インターネットや一部のゲートウェイ越えでは1500に制限されます）。","kw":"","reasons":[{"l":"A","html":"NAT Gatewayは外向き通信のための仕組みで、VPC内通信に挟む意味はありません。"},{"l":"B","html":"同一VPC内の通信にパブリックIPは不要で、経路がインターネット向けになると性能はむしろ落ちます。"},{"l":"D","html":"ピアリングは<b>別のVPC</b>と接続する機能で、同一VPC内では不要です。"}],"refs":"<a href=\"#d3\" data-go=\"d3\">第13章 13.4 ネットワークパフォーマンスの最適化</a> ／ <a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a>"},{"n":9,"topic":"分析性能","level":3,"body":["Athenaで、S3上の<b>日付パーティション（年/月/日）を持つ大量のデータ</b>をクエリしています。パーティション数が数十万に達し、<b>クエリの計画段階（パーティションの読み込み）に時間がかかる</b>ようになりました。適切な対処はどれですか。"],"options":[{"l":"A","html":"パーティション射影を有効にする"},{"l":"B","html":"すべてのパーティションを削除し、単一のフォルダに統合する"},{"l":"C","html":"Glueクローラーの実行頻度を1時間ごとに増やす"},{"l":"D","html":"データ形式をCSVに戻す"}],"answer":["A"],"multi":false,"req":"","key":"<b>パーティション射影は、パーティションの一覧をカタログから読まずに命名規則から計算</b>します。パーティション数が非常に多いテーブルで、クエリ計画のオーバーヘッドを大きく削減できます。","kw":"","reasons":[{"l":"B","html":"パーティションをなくすと、スキャン量が激増してコストと時間が悪化します。"},{"l":"C","html":"クローラーの頻度を上げてもパーティション数は減らず、カタログ更新の負荷が増えるだけです。"},{"l":"D","html":"CSVは列指向ではないため、スキャン量が増えて遅くなります。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.3 Amazon Athena</a> ／ <a href=\"#analytics\" data-go=\"analytics\">第7章 7.2 AWS Glue</a>"},{"n":10,"topic":"性能改善の打ち手","level":3,"body":["Webアプリケーションの応答が遅く、調査の結果、(1) 同一の商品マスタへの参照クエリがDBへ繰り返し発行されている、(2) 静的な画像・CSS・JSがすべてオリジンのEC2から配信されている、という2点が判明しました。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"EC2のインスタンスタイプをメモリ最適化に変更する"},{"l":"B","html":"ALBのアイドルタイムアウトを延長する"},{"l":"C","html":"商品マスタの参照結果をElastiCacheにキャッシュし、TTLを設定する"},{"l":"D","html":"RDSのストレージをio2に変更する"},{"l":"E","html":"静的アセットをS3に置き、CloudFrontから配信する"}],"answer":["C","E"],"multi":true,"req":"","key":"<b>症状ごとに層を分けて対処</b>します。繰り返しの参照＝<b>キャッシュ層（ElastiCache）</b>、静的配信＝<b>CDN（CloudFront＋S3）</b>。どちらもオリジンの負荷を根本から減らします。","kw":"","reasons":[{"l":"A","html":"ボトルネックはDBへの繰り返しアクセスと静的配信であり、アプリサーバーのメモリではありません。"},{"l":"B","html":"アイドルタイムアウトは接続維持時間の設定で、応答速度には影響しません。"},{"l":"D","html":"ストレージ性能の問題とは特定されていません。まずキャッシュでDBへの到達回数を減らすのが先です。"}],"refs":"<a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.4 ネットワークパフォーマンスの最適化</a>"}]},{"id":"exam-set-16","file":"set-16.md","num":"問題セット16","title":"第4分野 2周目：コストを最適化したアーキテクチャの設計","questions":[{"n":1,"topic":"割引プランの選択","level":3,"body":["今後3年間、EC2に加えて<b>FargateとLambdaも併用</b>する計画です。利用するインスタンスファミリーやリージョンは、事業の状況に応じて変わる可能性があります。最も柔軟に割引を受けられる選択はどれですか。"],"options":[{"l":"A","html":"スタンダードリザーブドインスタンス（3年）"},{"l":"B","html":"EC2 Instance Savings Plans"},{"l":"C","html":"Compute Savings Plans"},{"l":"D","html":"オンデマンドキャパシティ予約"}],"answer":["C"],"multi":false,"req":"","key":"<b>Compute Savings Plansは、EC2・Fargate・Lambdaを横断して適用</b>され、インスタンスファミリー・サイズ・AZ・<b>リージョンの変更にも追随</b>します。柔軟性が要件のときはこれです。","kw":"","reasons":[{"l":"A","html":"スタンダードRIはEC2のみが対象で、インスタンスファミリーの変更もできません（Convertible RIなら交換可）。"},{"l":"B","html":"EC2 Instance SPは割引率が高い代わりに、<b>特定リージョンの特定ファミリーに固定</b>され、FargateやLambdaには適用されません。"},{"l":"D","html":"キャパシティ予約は容量の確保が目的で、それ自体に割引はありません。"}],"refs":"<a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a> ／ <a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a>"},{"n":2,"topic":"リザーブドインスタンス","level":2,"body":["3年前に購入したスタンダードRIが、<b>アプリケーションの刷新で使われなくなりました</b>。残り1年の期間が無駄になっています。将来同じ事態を避けるための購入方法はどれですか。"],"options":[{"l":"A","html":"コンバーティブル（Convertible）RIを選ぶ"},{"l":"B","html":"全額前払いを選ぶ"},{"l":"C","html":"ゾーンRIを選ぶ"},{"l":"D","html":"1年ではなく3年契約のスタンダードRIを選び、割引率を最大にする"}],"answer":["A"],"multi":false,"req":"","key":"<b>コンバーティブルRIは、期間中にインスタンスファミリー・OS・テナンシーなどを交換できます</b>。構成変更の可能性がある場合は、割引率が少し下がってもこちらが適します（スタンダードRIはマーケットプレイスでの売却は可能ですが、交換はできません）。","kw":"","reasons":[{"l":"B","html":"支払い方法の選択で、柔軟性は上がりません（むしろ前払い額が無駄になります）。"},{"l":"C","html":"ゾーンRIは特定AZのキャパシティ予約が付く形態で、柔軟性はさらに下がります。"},{"l":"D","html":"期間を延ばすと、使われなくなったときの損失が大きくなります。"}],"refs":"<a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":3,"topic":"アーカイブ","level":3,"body":["EBSスナップショットを法令対応で<b>7年間保管</b>します。復元の必要が生じるのは数年に一度で、<b>復元までに1〜2日かかっても構いません</b>。保管コストを最小化する方法はどれですか。"],"options":[{"l":"A","html":"スナップショットをS3 Glacier Deep Archiveへコピーする"},{"l":"B","html":"スナップショットを標準層のまま保持する"},{"l":"C","html":"EBSスナップショットアーカイブ層へ移動する"},{"l":"D","html":"スナップショットからAMIを作成し、AMIとして長期保管する"}],"answer":["C"],"multi":false,"req":"","key":"<b>EBSスナップショットアーカイブは、めったに復元しないスナップショットの保管コストを大幅に下げる階層</b>です。復元には最大24〜72時間かかるため、「1〜2日待てる」という条件が決め手になります。","kw":"","reasons":[{"l":"A","html":"EBSスナップショットを直接Glacierへコピーする機能はありません（アーカイブ層が正規の手段です）。"},{"l":"B","html":"標準層のままでは7年分の保管コストが高くつきます。"},{"l":"D","html":"AMIはスナップショットを参照するため、保管コストの削減になりません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.2 Amazon EBS</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":4,"topic":"ストレージ階層","level":3,"body":["S3 Intelligent-Tieringを使っているバケットで、<b>1年以上アクセスされていないオブジェクトが大量に存在</b>することが分かりました。これらの保管コストをさらに下げたいと考えています。取り出しには数時間かかっても構いません。適切な設定はどれですか。"],"options":[{"l":"A","html":"ライフサイクルポリシーで、90日後にStandard-IA、180日後にGlacierへ移行する"},{"l":"B","html":"Intelligent-Tieringのアーカイブ階層を有効にする"},{"l":"C","html":"バケットのバージョニングを無効化する"},{"l":"D","html":"オブジェクトをすべてOne Zone-IAへコピーし、保管単価を下げる"}],"answer":["B"],"multi":false,"req":"","key":"Intelligent-Tieringの<b>アーカイブ階層はオプトイン（既定では無効）</b>です。有効化すると、一定期間アクセスのないオブジェクトが自動的により安い階層へ移動します（取り出しに時間がかかる点が許容条件）。","kw":"アーカイブアクセス階層／ディープアーカイブアクセス階層","reasons":[{"l":"A","html":"Intelligent-Tieringはすでにアクセス頻度に応じて階層移動しており、Standard-IAへの移行は二重管理になります。"},{"l":"C","html":"バージョニングの無効化は誤削除対策を失うだけで、保管コストの本質的な削減にはなりません（不要な旧バージョンの失効はライフサイクルで行います）。"},{"l":"D","html":"コピーすると二重に保管されることになり、コストは増えます。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":5,"topic":"組織でのコスト最適化","level":2,"body":["Organizationsで20アカウントを運用しています。ある子アカウントでRIを購入しましたが、そのアカウントでの利用が少なく、<b>割引が余っています</b>。他のアカウントのEC2利用にもこの割引を適用したいと考えています。適切な方法はどれですか。"],"options":[{"l":"A","html":"すべてのEC2を1つのアカウントへ移設する"},{"l":"B","html":"RIを購入し直し、使用量に合わせて各アカウントに分散する"},{"l":"C","html":"各アカウントを個別の請求に切り替え、使用量を分けて管理する"},{"l":"D","html":"RI/Savings Plansの割引共有を有効にする"}],"answer":["D"],"multi":false,"req":"","key":"<b>一括請求では、RIやSavings Plansの割引が組織内の他アカウントの利用にも適用</b>されます（管理アカウント側で共有の有効／無効を設定できます）。","kw":"","reasons":[{"l":"A","html":"アカウント分離の設計意図（障害・権限の分離）を壊す大掛かりな変更です。"},{"l":"B","html":"買い直しは費用の無駄で、余剰の解消にもなりません。"},{"l":"C","html":"個別請求にすると一括請求のボリュームディスカウントと割引共有の両方を失います。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.5 AWS Organizations</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.1 コスト管理ツールの使い分け</a>"},{"n":6,"topic":"配信コスト","level":2,"body":["CloudFrontで配信しているサービスの利用者は、<b>日本と北米のみ</b>です。ヨーロッパやアジア他地域のエッジロケーションからの配信は不要で、配信コストを抑えたいと考えています。適切な設定はどれですか。"],"options":[{"l":"A","html":"価格クラスを下位のクラスに変更する"},{"l":"B","html":"オリジンシールドを無効にする"},{"l":"C","html":"TTLを最小値に設定する"},{"l":"D","html":"地理的制限で日本と北米以外を拒否する"}],"answer":["A"],"multi":false,"req":"","key":"<b>価格クラスは「どの範囲のエッジロケーションを使うか」の設定</b>で、範囲を絞ると単価の高い地域を除外できます。利用者の所在が限られる場合の定番のコスト削減策です。","kw":"","reasons":[{"l":"B","html":"オリジンシールドはオリジンへのリクエストを集約してオリジン負荷と転送量を減らす機能で、無効化するとむしろ不利になり得ます。"},{"l":"C","html":"TTLを短くするとキャッシュヒット率が下がり、オリジンへの転送が増えてコストが上がります。"},{"l":"D","html":"地理的制限はアクセスの可否の制御であり、配信の単価やエッジの範囲を変えるものではありません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFrontとGlobal Accelerator</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":7,"topic":"コンテナのコスト","level":3,"body":["ECS on Fargateで、<b>CI/CDのビルドジョブ</b>（1回15分程度、失敗しても再実行すればよい）を大量に実行しています。コストを削減する方法はどれですか。"],"options":[{"l":"A","html":"タスクのCPUとメモリを最大値に設定する"},{"l":"B","html":"Fargate Spotで実行する"},{"l":"C","html":"EC2起動タイプに変更し、オンデマンドインスタンスで実行する"},{"l":"D","html":"タスク数を固定し、常時起動しておく"}],"answer":["B"],"multi":false,"req":"","key":"<b>中断されても再実行すればよいワークロードはSpot</b>です。Fargate Spotは大幅に安く、CI/CDのビルドは中断耐性がある典型例です。","kw":"","reasons":[{"l":"A","html":"リソースを増やすと単価が上がります（処理時間の短縮と相殺されるとは限りません）。"},{"l":"C","html":"オンデマンドのEC2に変えても割引はなく、インスタンス管理の手間が増えます。"},{"l":"D","html":"常時起動はアイドル時間に課金され、ジョブ実行型のワークロードには最も不向きです。"}],"refs":"<a href=\"#container\" data-go=\"container\">第9章 9.3 AWS Fargate</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":8,"topic":"データ転送コスト","level":3,"body":["3層構成のアプリケーションで、<b>アベイラビリティゾーンをまたぐデータ転送料</b>が想定以上に発生していました。可用性要件（マルチAZ構成）は維持したままコストを下げたいと考えています。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"リードレプリカを各AZに置き、同一AZ内で読み取りを完結させる"},{"l":"B","html":"すべての通信をパブリックIP経由に変更する"},{"l":"C","html":"マルチAZ構成をやめ、単一AZに集約する"},{"l":"D","html":"ゲートウェイ型VPCエンドポイントでNATを経由させない"},{"l":"E","html":"ALBのクロスゾーン負荷分散を無効化し、可用性を下げてでも転送量を減らす"}],"answer":["A","D"],"multi":true,"req":"","key":"<b>可用性を維持したまま</b>転送量を減らすには、「<b>同一AZ内で完結させる</b>」「<b>そもそも課金される経路を通らない</b>」の2方向です。","kw":"","reasons":[{"l":"B","html":"パブリック経路はデータ転送料がさらに高く、セキュリティも低下します。"},{"l":"C","html":"可用性要件（マルチAZ）を放棄しており、前提に反します。"},{"l":"E","html":"ALBのクロスゾーン負荷分散はALBでは既定で有効かつ無効化できず、「可用性を下げてでも」という方針も要件に反します。"}],"refs":"<a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a> ／ <a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続</a>"}]},{"id":"exam-set-17","file":"set-17.md","num":"問題セット17","title":"複合問題 2周目（分野をまたぐ設計判断）","questions":[{"n":1,"topic":"セキュリティ × パフォーマンス × コスト","level":3,"body":["世界中の利用者がスマートフォンアプリから数百MBの動画をアップロードします。要件は (1) <b>認証済みの利用者だけ</b>が、自分に割り当てられたキーにのみアップロードできる、(2) 海外の利用者のアップロードも<b>遠距離による遅延の影響を減らして</b>速くする、(3) アップロードのためにアプリケーションサーバーを増強しない。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"アプリに書き込み権限を持つIAMユーザーのアクセスキーを埋め込み、S3へ直接アップロードする"},{"l":"B","html":"世界各リージョンにEC2とALBを配置し、アプリサーバーが受け取った動画をS3へ転送する"},{"l":"C","html":"バケットのパブリック書き込みを許可し、アップロード後にLambdaで不正なオブジェクトを削除する"},{"l":"D","html":"署名付きURL（PUT）を発行し、Transfer Accelerationで直接アップロードする"}],"answer":["D"],"multi":false,"req":"①利用者ごと・キーごとの一時的な書き込み許可（第1分野）／②遠距離アップロードの高速化（第3分野）／③アプリサーバーを経由させない＝余計なコンピューティングを持たない（第4分野）","key":"<b>署名付きURL</b>は発行者の権限で、特定のキー・特定の操作だけを期限付きで許可します。アプリはS3へ直接送るのでサーバーを経由せず、<b>Transfer Acceleration</b>がエッジロケーション経由の最適化された経路で遠距離の転送を速めます。数百MBの動画ではマルチパートアップロードと組み合わせるのが定番です。","kw":"署名付きURL／S3 Transfer Acceleration","reasons":[{"l":"A","html":"長期のアクセスキーをアプリに埋め込むと、抽出されたときに全利用者の領域へ書き込めてしまいます。利用者ごとに範囲を絞れず、要件①を満たしません。"},{"l":"B","html":"要件②は満たせますが、動画がすべてアプリサーバーを通るため要件③に正面から反し、各リージョンに常駐するサーバーの費用もかかります。"},{"l":"C","html":"パブリック書き込みは要件①を満たしません。事後に削除する設計では、不正な書き込み自体を防げません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":2,"topic":"弾力性 × コスト","level":3,"body":["毎晩、数百件の画像解析ジョブを実行します。1件の処理は<b>最大4時間</b>かかり、処理の途中経過は<b>S3へチェックポイントとして保存</b>できます。要件は (1) 翌朝までにすべてのジョブを終える、(2) 途中でインスタンスが失われても、そのジョブが再実行されて完了する、(3) サーバー管理の手間とコストを最小にする。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"AWS Batchでスポットのマネージド型コンピューティング環境を使い、再試行を設定する"},{"l":"B","html":"必要な台数のEC2を3年のリザーブドインスタンスで購入し、cronでジョブを順に投入する"},{"l":"C","html":"Lambda関数で1件ずつ処理し、SQSで並列度を制御する"},{"l":"D","html":"単一のインスタンスタイプを指定したスポットインスタンス1台でジョブを順番に処理する"}],"answer":["A"],"multi":false,"req":"①時間内に大量のジョブを完了＝並列実行（第3分野）／②中断されても完了する＝再試行と再開（第2分野）／③管理とコストの最小化（第4分野）","key":"<b>チェックポイントを保存でき、再実行に耐えるバッチ処理はスポットの典型的な適用先</b>です。AWS Batchはジョブのキューイング、コンピューティング環境の増減、失敗時の再試行を引き受けるので、中断を前提にしたスポットを安全に使えます。","kw":"AWS Batch／スポットインスタンス","reasons":[{"l":"B","html":"毎晩数時間しか使わない台数を3年間確保するため、日中は遊休になり要件③に反します。常時稼働するワークロード向けの割引です。"},{"l":"C","html":"Lambdaの実行時間は<b>最大15分</b>で、4時間かかるジョブは実行できません。"},{"l":"D","html":"1台で順番に処理すると翌朝までに終わらず、スポットの容量不足や中断が起きると全体が止まります。スポットは複数のインスタンスタイプに分散させて使うのが原則です。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.5 AWS Batch</a> ／ <a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":3,"topic":"セキュリティ × 弾力性","level":3,"body":["Lambda関数からRDS for MySQLへ接続するAPIがあります。アクセスが急増すると<b>DBの接続数が上限に達してエラー</b>になり、またDBのパスワードは<b>Lambdaの環境変数に平文で</b>設定されています。要件は (1) 認証情報を<b>定期的に自動でローテーション</b>する、(2) 同時実行数が増えても接続数が枯渇しない、(3) コードの変更は最小限にする。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"認証情報をSecrets Managerに保管して自動ローテーションを有効にし、RDS Proxy経由で接続させる"},{"l":"B","html":"パスワードをSystems Manager Parameter StoreのSecureStringに移し、DBインスタンスのクラスを大きくして最大接続数を増やす"},{"l":"C","html":"パスワードをKMSで暗号化した環境変数に置き、Lambdaの予約済み同時実行数を1に制限する"},{"l":"D","html":"リードレプリカを追加し、Lambdaからはレプリカのエンドポイントへのみ接続させる"}],"answer":["A"],"multi":false,"req":"①認証情報の自動ローテーション（第1分野）／②接続の枯渇を防ぐ（第2・第3分野）／③コード変更を最小限に","key":"<b>RDS Proxy</b>が接続をプールして、多数のLambda実行環境からの接続をまとめます。RDS ProxyはSecrets Managerの認証情報を使ってDBへ接続するため、ローテーションはSecrets Managerに任せられ、アプリは接続先をプロキシのエンドポイントに変えるだけで済みます。","kw":"RDS Proxy／Secrets Manager","reasons":[{"l":"B","html":"Parameter Storeには<b>組み込みの自動ローテーション機能がありません</b>。また、接続数の上限を上げても、同時実行が増えればいずれ枯渇します。"},{"l":"C","html":"同時実行数を1に制限すると接続数は抑えられますが、APIが処理を捌けなくなります。暗号化した環境変数もローテーションは自動化されません。"},{"l":"D","html":"リードレプリカは読み取り負荷の分散であり、書き込みを含むAPIの接続枯渇は解決しません。認証情報の要件にも応えていません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.10 AWS Secrets Manager vs AWS Systems Manager Parameter Store</a> ／ <a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.3 サーバーレステクノロジーの活用</a>"},{"n":4,"topic":"弾力性 × パフォーマンス","level":3,"body":["北米・欧州・アジアの利用者を持つSNSアプリで、利用者のプロフィールと投稿を保存します。要件は (1) <b>どのリージョンでも読み取りと書き込みを低遅延で受け付ける</b>、(2) 1つのリージョンが停止しても、他のリージョンで<b>書き込みを継続</b>できる、(3) データベースのサーバー管理はしない。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"Auroraグローバルデータベースを構成し、各リージョンのアプリはそれぞれのセカンダリクラスターへ書き込む"},{"l":"B","html":"DynamoDBグローバルテーブルで3リージョンに置き、レイテンシーベースルーティングで振り分ける"},{"l":"C","html":"ElastiCacheのグローバルデータストアを主データベースとして使う"},{"l":"D","html":"1つのリージョンにDynamoDBテーブルを置き、各リージョンのアプリからリージョンをまたいでアクセスする"}],"answer":["B"],"multi":false,"req":"①全リージョンで低遅延の読み書き＝<b>マルチアクティブ</b>（第3分野）／②リージョン停止時も書き込み継続（第2分野）／③サーバー管理なし","key":"<b>DynamoDBグローバルテーブル</b>は、すべてのレプリカが読み書きを受け付けるマルチアクティブ構成です。各リージョンでローカルに書き込み、変更は他のリージョンへ非同期で複製されます。リージョンが停止しても残りのレプリカで書き込みを続けられます。","kw":"DynamoDBグローバルテーブル","reasons":[{"l":"A","html":"Auroraグローバルデータベースで書き込みを受け付けるのは<b>プライマリリージョンだけ</b>です。セカンダリへの書き込み転送を使っても、書き込み自体はプライマリで処理されるため、遠いリージョンの書き込みは低遅延になりません。"},{"l":"C","html":"グローバルデータストアで書き込めるのはプライマリクラスターだけで、しかもキャッシュ用途のサービスです。主データベースとしての永続性の要件にも合いません。"},{"l":"D","html":"単一リージョンのテーブルでは、遠いリージョンの利用者の遅延が大きく、そのリージョンが停止すると全体が止まります。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a> ／ <a href=\"#database\" data-go=\"database\">第4章 4.2 Amazon Aurora</a> ／ <a href=\"#network\" data-go=\"network\">第3章 3.4 名前解決：Route 53 と Resolver</a>"},{"n":5,"topic":"セキュリティ × コスト","level":3,"body":["AWS Organizationsで40アカウントを管理しています。要件は (1) メンバーアカウントの管理者であっても、<b>許可された小さなインスタンスタイプ以外は起動できない</b>ようにする、(2) 同じく<b>CloudTrailの停止や削除をできない</b>ようにする、(3) 部門ごとの費用を<b>請求データで集計</b>できるようにする。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"部門タグをタグポリシーで標準化し、管理アカウントでコスト配分タグとして有効化する"},{"l":"B","html":"AWS Budgetsで部門ごとの予算を設定し、超過時にメールで通知する"},{"l":"C","html":"各アカウントのIAMグループに、大きなインスタンスタイプを拒否するポリシーをアタッチする"},{"l":"D","html":"AWS Configルールで大きなインスタンスタイプを検出し、管理者へ通知する"},{"l":"E","html":"<code>ec2:InstanceType</code> 条件で許可リスト外のRunInstancesを拒否し、<code>cloudtrail:StopLogging</code> と <code>cloudtrail:DeleteTrail</code> を拒否するSCPを組織単位に適用する"}],"answer":["A","E"],"multi":true,"req":"①②アカウント管理者にも効く<b>予防的な制限</b>（第1分野）／③部門別の費用の集計（第4分野）","key":"アカウントの管理者（ルートユーザーを含む）にも効く上限は<b>SCP</b>でしか掛けられません。費用の集計は、タグの付け方をそろえ（タグポリシー）、請求データで使えるように<b>コスト配分タグを有効化</b>するのが基本の流れです。","kw":"SCP／タグポリシー／コスト配分タグ","reasons":[{"l":"B","html":"予算の通知は事後の気づきであり、起動そのものは止められません。また部門別の集計には、タグを請求データへ反映させる設定が前提になります。"},{"l":"C","html":"メンバーアカウントの管理者は、自分でそのポリシーを外せます。アカウント内のIAMでは、管理者自身を縛る予防策になりません。"},{"l":"D","html":"Configルールは<b>検出</b>の仕組みで、起動を防ぐ予防策ではありません。要件①は「起動できない」ことを求めています。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.5 AWS Organizations</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.1 コスト管理ツールの使い分け</a>"},{"n":6,"topic":"弾力性 × パフォーマンス × コスト","level":3,"body":["ECサイトのWeb層はAuto Scalingグループで動いています。負荷は<b>常に最低6台分</b>あり、夕方には最大30台まで増えます。アプリはステートレスで、1台が突然終了しても処理に影響しません。要件は (1) 夕方のピークでも性能を落とさない、(2) 最低限の台数は<b>確実に確保</b>する、(3) 全体のコストを最小にする。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"30台すべてをオンデマンドで起動し、3年のリザーブドインスタンスで30台分を購入する"},{"l":"B","html":"すべてをスポットインスタンスにし、単一のインスタンスタイプを指定する"},{"l":"C","html":"Auto Scalingグループの混合インスタンスポリシーで、ベース6台をオンデマンド（Savings Plansで割引）、それを超える分を複数のインスタンスタイプのスポットにし、容量の再調整を有効にする"},{"l":"D","html":"夕方の最大台数に合わせて、常時30台のオンデマンドを稼働させる"}],"answer":["C"],"multi":false,"req":"①ピーク時の性能＝スケールアウト（第3分野）／②最低台数は中断されない購入方法で確保（第2分野）／③変動部分は最安の購入方法で（第4分野）","key":"<b>常に必要な部分と変動する部分で購入方法を分ける</b>のが定石です。ベースはオンデマンドにSavings Plansを適用して確実に安く確保し、ステートレスで中断に耐える変動部分はスポットで賄います。スポットは複数のインスタンスタイプに分散させ、<b>容量の再調整</b>で中断の兆候が出たインスタンスを先回りして置き換えます。","kw":"混合インスタンスポリシー／スポットインスタンス（複数のインスタンスタイプ）","reasons":[{"l":"A","html":"夕方の数時間しか使わない24台分まで3年間確保するため、要件③に反します。"},{"l":"B","html":"すべてがスポットでは、容量不足や一斉の中断で最低台数を確保できず要件②を満たしません。単一のインスタンスタイプはその危険をさらに高めます。"},{"l":"D","html":"性能は満たしますが、ピーク以外の時間も最大台数の費用を払い続けるため、要件③に反します。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.2 Amazon EC2 Auto Scaling</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a>"},{"n":7,"topic":"セキュリティ × 弾力性","level":3,"body":["S3バケットに請求書のPDFがアップロードされるたびに、内容を読み取って会計システムへ登録します。要件は (1) 処理の待ち行列に入っているデータも<b>KMSで暗号化</b>する、(2) 処理に<b>何度か失敗したファイルは失われず</b>、後から調べて再処理できる、(3) アップロードが集中しても処理側が過負荷にならない。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"S3イベント通知でLambdaを直接（非同期で）呼び出し、Lambdaの同時実行数を大きくする"},{"l":"B","html":"処理用のEC2が1分ごとにバケットの一覧を取得し、未処理のファイルを探して処理する"},{"l":"C","html":"S3イベント通知をSNSトピックへ送り、Eメールで担当者に通知して手動で登録する"},{"l":"D","html":"S3イベント通知をカスタマー管理のKMSキーでSSEを有効にしたSQSキューへ送り（キーポリシーでS3に使用を許可）、Lambdaがキューから取り出して処理する。キューにはリドライブポリシーでデッドレターキューを設定する"}],"answer":["D"],"multi":false,"req":"①待ち行列のデータも暗号化（第1分野）／②失敗したメッセージを保持して再処理（第2分野）／③集中時の負荷を平準化＝バッファ（第2分野）","key":"<b>SQSを挟むとバッファになり</b>、Lambdaは取り出せる分だけ処理するので集中しても過負荷になりません。規定回数失敗したメッセージは<b>デッドレターキュー</b>へ移り、失われずに後から調べられます。S3からの通知を暗号化キューへ送るには、S3がキーを使えるよう<b>カスタマー管理キーのキーポリシー</b>で許可する必要があります（AWS管理キーはキーポリシーを変更できません）。","kw":"カスタマー管理のKMSキー／SQSのSSE／リドライブポリシー／デッドレターキュー","reasons":[{"l":"A","html":"非同期呼び出しは失敗時に再試行されますが、宛先やDLQを設定しなければ最終的に失敗したイベントは破棄されます。同時実行数を増やすと、集中時にそのまま会計システムへ負荷が流れ込み、要件③にも反します。"},{"l":"B","html":"一覧取得によるポーリングはファイル数が増えるほど遅く高くなり、失敗の記録や再処理の仕組みも自前で作る必要があります。"},{"l":"C","html":"通知と手作業の登録では自動処理の要件を満たさず、暗号化・再処理のどちらにも応えていません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.8 AWS Key Management Service (KMS)</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.2 疎結合アーキテクチャ（Decoupling）</a>"},{"n":8,"topic":"弾力性 × コスト","level":2,"body":["本社のデータセンターとAWSのVPCを接続します。要件は (1) 日常の通信は<b>帯域と遅延が安定した専用線</b>を使う、(2) 専用線が切れても<b>通信を継続できる</b>、(3) 2本目の専用線を引くほどの費用はかけられず、<b>切り替え後は帯域が下がってもよい</b>。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"Direct Connectを1本だけ契約し、障害時は復旧を待つ"},{"l":"B","html":"Direct Connectを主経路、VPNを予備にする"},{"l":"C","html":"Site-to-Site VPNを2本（2つのトンネル）張って冗長化し、専用線は使わない"},{"l":"D","html":"異なるロケーションに2本のDirect Connectを契約する"}],"answer":["B"],"multi":false,"req":"①安定した帯域と遅延＝Direct Connect（第3分野）／②専用線の障害に備える（第2分野）／③2本目の専用線は不要、切り替え後の帯域低下は許容（第4分野）","key":"<b>Direct Connect＋VPNのバックアップ</b>は、費用を抑えて専用線の単一障害点をなくす定番です。BGPで専用線の経路を優先させ、専用線が切れたときだけインターネット経由のVPNへ切り替わります。","kw":"Direct Connect／Site-to-Site VPN（バックアップ経路）","reasons":[{"l":"A","html":"専用線1本は単一障害点で、要件②を満たしません。"},{"l":"C","html":"VPNはインターネットを経由するため、帯域と遅延が安定せず要件①を満たしません。"},{"l":"D","html":"最も可用性は高い構成ですが、要件③が明示的に「2本目の専用線の費用はかけない」としています。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続：エンドポイント・PrivateLink・ピアリング・Transit Gateway・Direct Connect</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性（HA）と耐障害性（Fault Tolerance）</a>"},{"n":9,"topic":"パフォーマンス（データ取り込み） × コスト","level":3,"body":["Webサイトのクリックストリーム（JSON）をS3に集め、Athenaで分析しています。現在はアプリが<b>1イベントごとに小さなJSONファイルをS3へ書き込んで</b>おり、クエリが遅く、スキャン料金も高くなっています。要件は (1) 数分程度の遅れで分析できればよい、(2) クエリの速度と料金を改善する、(3) 取り込みのためのサーバーは管理しない。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"Kinesis Data Streamsで受け、EC2上のコンシューマーがJSONのまま1イベントずつS3へ書き込む"},{"l":"B","html":"1イベントずつ書き込む方式はそのままにし、Athenaのクエリで<code>LIMIT</code>句を使う"},{"l":"C","html":"Data Firehoseでまとめ、Parquetに変換してS3へ配信する"},{"l":"D","html":"RDS for PostgreSQLに1イベントずつINSERTし、分析もRDSで行う"}],"answer":["C"],"multi":false,"req":"①数分の遅れは許容＝ニアリアルタイムで十分（第3分野 3.5）／②スキャン量とファイル数を減らす（第3・第4分野）／③サーバーレスで取り込む","key":"Firehoseは受け取ったレコードを<b>バッファリングして大きなファイルにまとめ</b>、Glueデータカタログのスキーマを使って<b>列指向のParquetへ変換</b>し、パーティション分割して配信できます。小さなファイルが大量にある状態と、行指向のJSONを全列スキャンする状態の両方が解消され、Athenaの速度と料金が同時に改善します。","kw":"Amazon Data Firehose／バッファリング／Parquet形式への変換／パーティション分割","reasons":[{"l":"A","html":"EC2のコンシューマーを管理する必要があり要件③に反します。1イベントずつJSONで書き込むので、小さなファイルと全列スキャンの問題も残ります。"},{"l":"B","html":"<code>LIMIT</code>は返す行数を減らすだけで、Athenaがスキャンするデータ量はほとんど減りません。"},{"l":"D","html":"大量のクリックストリームを1件ずつRDSへ書き込むと書き込み負荷が高く、分析にはデータウェアハウスやAthenaが適しています。サーバーの管理も必要です。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.1 Amazon Kinesis</a> ／ <a href=\"#analytics\" data-go=\"analytics\">第7章 7.3 Amazon Athena</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":10,"topic":"全分野","level":3,"body":["オンプレミスの1台のサーバーで動くWebアプリケーションを、ALBとAuto Scalingグループの構成へ移行します。現在のアプリは (1) ログイン状態を<b>サーバーのメモリ</b>に持ち、(2) 利用者がアップロードした画像を<b>サーバーのローカルディスク</b>に保存しています。要件は、どのインスタンスに振り分けられても同じように動作し、スケールインやAZ障害でデータが失われないことです。コストと管理の手間も抑えます。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"ALBでスティッキーセッションを有効にし、同じ利用者を常に同じインスタンスへ振り分ける"},{"l":"B","html":"セッション情報をDynamoDBまたはElastiCacheへ外部化する"},{"l":"C","html":"各インスタンスのインスタンスストアに画像を保存し、定期的にほかのインスタンスへコピーする"},{"l":"D","html":"アップロードされた画像をS3へ保存し、アプリからはS3のキーを参照する"},{"l":"E","html":"EBSのマルチアタッチで1つのボリュームを全インスタンスから共有する"}],"answer":["B","D"],"multi":true,"req":"①どのインスタンスでも同じ動作＝<b>状態をインスタンスの外へ</b>（第2分野）／②スケールインやAZ障害でもデータを失わない＝耐久性のある共有ストレージ（第1・第2分野）／③コストと管理の手間（第4分野）","key":"水平スケールする構成では、<b>インスタンスを使い捨てにできる</b>ことが前提です。セッションはDynamoDBやElastiCacheへ、ファイルは複数のAZにまたがって保存される<b>S3</b>へ移すと、どのインスタンスが終了しても利用者への影響がなくなります。","kw":"セッションの外部化（DynamoDB／ElastiCache）／S3","reasons":[{"l":"A","html":"振り分け先を固定するだけで、そのインスタンスが終了すればログイン状態は失われます。負荷も偏ります。"},{"l":"C","html":"インスタンスストアはインスタンスの停止や終了で消える一時ストレージです。自前のコピー処理は管理の手間が増え、コピー前に終了すれば画像が失われます。"},{"l":"E","html":"EBSのマルチアタッチはio1/io2に限られ、<b>同じAZのインスタンス</b>からしか接続できません。AZ障害に耐えられず、複数から書き込むにはクラスター対応のファイルシステムも必要です。"}],"refs":"<a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a> ／ <a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#storage\" data-go=\"storage\">第2章 2.2 Amazon EBS</a> ／ <a href=\"#database\" data-go=\"database\">第4章 4.4 Amazon ElastiCache</a>"}]},{"id":"exam-set-18","file":"set-18.md","num":"問題セット18","title":"実戦演習①（本番の分野比率・15問）","questions":[{"n":1,"topic":"配信とデータ保護","level":3,"body":["S3バケットの静的コンテンツをCloudFrontで配信しています。現在はオリジンアクセスアイデンティティ（OAI）でバケットへの直接アクセスを防いでいます。コンプライアンス対応のため、バケットの既定の暗号化を<b>SSE-KMS（カスタマー管理キー）</b>に変更したところ、CloudFront経由の取得がエラーになりました。<b>バケットを公開せずに</b>配信を再開する方法はどれですか。"],"options":[{"l":"A","html":"バケットポリシーでOAIに <code>kms:Decrypt</code> を許可する"},{"l":"B","html":"OAIをOACに置き換え、KMSキーポリシーでCloudFrontに <code>kms:Decrypt</code> を許可する"},{"l":"C","html":"バケットのブロックパブリックアクセスを無効にし、CloudFrontが付けるRefererヘッダーで取得元を制限する"},{"l":"D","html":"暗号化方式をSSE-KMSのまま、CloudFrontの署名付きURLを発行する"}],"answer":["B"],"multi":false,"req":"","key":"<b>OAIはSSE-KMSで暗号化されたオブジェクトに対応していません</b>。OACは署名付きリクエスト（SigV4）でS3へアクセスするため、KMSキーポリシーでCloudFrontのサービスプリンシパル（<code>cloudfront.amazonaws.com</code>、条件で対象ディストリビューションに限定）に復号を許可すれば、非公開のまま配信できます。OACがOAIの後継として推奨される理由の1つです。","kw":"オリジンアクセスコントロール（OAC）／KMSキーポリシー","reasons":[{"l":"A","html":"<code>kms:Decrypt</code> はバケットポリシーではなく<b>KMSキーポリシー</b>（またはIAM）で許可する操作です。そもそもOAIではSSE-KMSのオブジェクトを取得できません。"},{"l":"C","html":"バケットを公開する時点で要件に反します。Refererヘッダーは偽装できるため、アクセス制御になりません。"},{"l":"D","html":"署名付きURLは閲覧者側のアクセス制御で、CloudFrontからS3へのアクセスでKMSの復号ができない問題は解決しません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#network\" data-go=\"network\">第3章 3.6 コンテンツ配信と高速化</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.8 AWS KMS</a>"},{"n":2,"topic":"特権アクセス","level":2,"body":["開発者は開発アカウントのIAMユーザーでサインインし、本番アカウントのロールを引き受けて作業しています。セキュリティ部門から「本番のロールを引き受けるときは、<b>必ずMFAで認証済みであること</b>」を求められました。最も適切な設定はどれですか。"],"options":[{"l":"A","html":"本番アカウントのIAMパスワードポリシーでMFAを必須にする"},{"l":"B","html":"本番アカウントに開発者ごとのIAMユーザーを作成し、MFAデバイスを登録させてから作業させる"},{"l":"C","html":"本番ロールの信頼ポリシーでMFAを条件にする"},{"l":"D","html":"開発アカウントのSCPで、MFAなしのすべての操作を拒否する"}],"answer":["C"],"multi":false,"req":"","key":"ロールを<b>誰が・どんな条件で引き受けられるか</b>を決めるのは信頼ポリシーです。<code>aws:MultiFactorAuthPresent</code> を条件にすれば、MFAで認証したセッションからの <code>sts:AssumeRole</code> だけが通ります。","kw":"信頼ポリシー／aws:MultiFactorAuthPresent","reasons":[{"l":"A","html":"パスワードポリシーは文字数や有効期限などを定めるもので、MFAの使用を強制する設定ではありません。"},{"l":"B","html":"アカウントごとにIAMユーザーを作る運用は管理が分散し、クロスアカウントロールの利点を失います。"},{"l":"D","html":"開発アカウントのすべての操作を止めてしまい、影響範囲が広すぎます。本番ロールの引き受けだけに条件を付けるのが最小限の対策です。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":3,"topic":"Web攻撃の防御","level":2,"body":["CloudFrontとALBで公開しているWebサイトのログイン画面（<code>/login</code>）に、世界中の多数のIPアドレスから総当たりのログイン試行が続いています。送信元IPは頻繁に変わります。正規の利用者への影響を抑えつつ、攻撃を自動的に抑える方法はどれですか。"],"options":[{"l":"A","html":"攻撃元のIPアドレスをネットワークACLで拒否する"},{"l":"B","html":"ALBのセキュリティグループで、ログイン試行の多い攻撃元のIPアドレスを拒否する"},{"l":"C","html":"AWS Shield Standardを有効にする"},{"l":"D","html":"WAFで <code>/login</code> にレートベースルールを設定する"}],"answer":["D"],"multi":false,"req":"","key":"<b>送信元が変わり続ける攻撃</b>は、IPを1件ずつ登録する方式では追いつきません。レートベースルールは一定時間あたりのリクエスト数が上限を超えたIPを自動で遮断し、スコープダウン文で <code>/login</code> だけに適用できます。CloudFrontに関連付ければエッジで止められます。","kw":"レートベースルール","reasons":[{"l":"A","html":"IPが頻繁に変わるため、手動の拒否リストでは追いつきません。CloudFront経由の通信では、ALBのサブネットに届く送信元はCloudFrontのIPになる点でも不適です。"},{"l":"B","html":"セキュリティグループには<b>拒否ルールがありません</b>。"},{"l":"C","html":"Shield StandardはL3/L4のDDoS攻撃を自動で緩和するもので、アプリケーション層の総当たりログインは防げません（しかも既定で有効です）。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.5 AWS WAF</a> ／ <a href=\"#network\" data-go=\"network\">第3章 3.2 通信制御</a>"},{"n":4,"topic":"監査ログの一元化","level":2,"body":["AWS Organizationsで30アカウントを管理しています。全アカウント・全リージョンのCloudTrailログを監査用アカウントのS3バケットに集約し、<b>メンバーアカウントの管理者がログ記録を止めたり設定を変えたりできない</b>ようにしたいと考えています。運用負荷が最も小さい方法はどれですか。"],"options":[{"l":"A","html":"管理アカウントで組織の証跡（組織トレイル）を作成する"},{"l":"B","html":"各アカウントに証跡を作成し、EventBridgeで停止を検知したらLambdaで再開する"},{"l":"C","html":"CloudFormation StackSetsで各アカウントに証跡を配布する"},{"l":"D","html":"各アカウントのCloudTrailイベント履歴を毎日エクスポートする"}],"answer":["A"],"multi":false,"req":"","key":"組織の証跡は管理アカウント（または委任管理者）で1つ作るだけで、<b>全メンバーアカウントに自動適用</b>され、新しいアカウントにも広がります。メンバーアカウント側からは組織の証跡を停止・変更・削除できません。","kw":"組織の証跡（組織トレイル）","reasons":[{"l":"B","html":"停止されてから再開するまでの間はログが欠けます。アカウントごとの仕組みを保守する負荷もかかります。"},{"l":"C","html":"配布はできますが、各アカウントの証跡はそのアカウントの管理者が変更・削除できます（別途SCPが必要）。"},{"l":"D","html":"イベント履歴は直近90日の管理イベントだけで、全リージョン・データイベントを網羅できません。手作業の運用にもなります。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.2 AWS CloudTrail</a> ／ <a href=\"#management\" data-go=\"management\">第8章 8.5 AWS Organizations</a>"},{"n":5,"topic":"保管時と転送時の暗号化","level":2,"body":["ALBとAuto ScalingグループのEC2で構成されたWebアプリケーションについて、監査で「<b>EC2のディスクに保存されるデータ</b>と、<b>利用者とシステムの間の通信</b>がどちらも暗号化されていること」を求められました。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"EBSの既定の暗号化を有効にする"},{"l":"B","html":"Amazon Macieを有効にして、機密データを検出する"},{"l":"C","html":"ACMの証明書をALBのHTTPSリスナーに設定し、HTTPへのアクセスはHTTPSへリダイレクトする"},{"l":"D","html":"Amazon Inspectorで、EC2の脆弱性を継続的に評価する"},{"l":"E","html":"S3バケットの既定の暗号化をSSE-KMSにする"}],"answer":["A","C"],"multi":true,"req":"","key":"保管時は<b>EBSの暗号化</b>（既定の暗号化を有効にすれば、以後作られるボリュームはすべて暗号化されます）、転送時は<b>ALBでのTLS終端</b>（ACMの証明書とHTTPSリスナー、HTTPからのリダイレクト）が、それぞれの要件に直接対応します。","kw":"EBSの既定の暗号化／HTTPSリスナー","reasons":[{"l":"B","html":"MacieはS3内の機密データを検出するサービスで、暗号化は行いません。"},{"l":"D","html":"Inspectorは脆弱性の評価で、暗号化の要件とは別です。"},{"l":"E","html":"対象はEC2のディスクであり、S3の暗号化は要件に関係しません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.2 Amazon EBS</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.7 AWS Certificate Manager</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":6,"topic":"スケールアウトの失敗","level":2,"body":["Auto ScalingグループのEC2は、起動後にアプリケーションの初期化に<b>約5分</b>かかります。スケールアウトのたびに、新しいインスタンスが初期化中にELBヘルスチェックで異常と判定され、終了と起動を繰り返しています。最も適切な対処はどれですか。"],"options":[{"l":"A","html":"ヘルスチェックのタイプをEC2に戻し、OSの状態だけで判定する"},{"l":"B","html":"スケールアウトのクールダウン期間を短くし、置き換えを速める"},{"l":"C","html":"インスタンスタイプを大きくする"},{"l":"D","html":"ヘルスチェックの猶予期間を初期化時間より長くする"}],"answer":["D"],"multi":false,"req":"","key":"ヘルスチェックの猶予期間は、起動直後のインスタンスをヘルスチェックの判定から外しておく時間です。初期化にかかる時間より長く設定すれば、準備中のインスタンスが異常と判定されて置き換えられることはなくなります。","kw":"ヘルスチェックの猶予期間","reasons":[{"l":"A","html":"EC2ヘルスチェックに戻すと、アプリケーションが応答しない障害を検知できなくなります（ELBヘルスチェックに切り替えた意味を失います）。"},{"l":"B","html":"クールダウンはスケーリングの間隔を調整するもので、起動直後の誤判定は防げません。むしろ起動と終了の繰り返しを速めます。"},{"l":"C","html":"初期化が多少速くなる可能性はありますが、根本原因（判定のタイミング）は変わらず、コストも増えます。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.2 Amazon EC2 Auto Scaling</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a>"},{"n":7,"topic":"単一インスタンスの冗長化","level":3,"body":["社内向けのレガシーWebアプリケーションが、1つのAZの<b>1台のEC2</b>で動いています。アプリはローカルのEBSにあるディレクトリへファイルを書き込み、同時に複数台で動かすことはできません。<b>AZ障害が起きても自動で復旧</b>でき、アプリのコード変更は最小限にしたいと考えています。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"EBSのマルチアタッチで、別のAZで起動したインスタンスからも同じボリュームを接続できるようにする"},{"l":"B","html":"書き込み先をEFSに移し、2つのAZにまたがるAuto Scalingグループ（1台固定）で動かす"},{"l":"C","html":"1時間ごとにEBSスナップショットを取得し、障害時に手動で別のAZに復元する"},{"l":"D","html":"インスタンスタイプを大きくし、EC2の自動復旧を設定する"}],"answer":["B"],"multi":false,"req":"","key":"データを<b>AZをまたいで保存されるEFS</b>に置けば、どのAZで起動し直しても同じファイルを使えます。台数を1に固定したAuto Scalingグループを2つのAZにまたがらせると、AZ障害時には別のAZで自動的に起動し直されます。同時に1台しか動かない前提も守れます。","kw":"Amazon EFS／マルチAZのAuto Scalingグループ","reasons":[{"l":"A","html":"EBSのマルチアタッチは<b>同じAZ内</b>のインスタンスに限られ、AZ障害に耐えられません。"},{"l":"C","html":"復旧が手動で、自動復旧の要件を満たしません。"},{"l":"D","html":"EC2の自動復旧は同じAZ内のハードウェア障害への対策で、AZ全体の障害には効きません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.3 Amazon EFS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":8,"topic":"キュー処理の流量制御","level":3,"body":["SQSキューのメッセージをLambda関数で処理し、結果をRDSに書き込んでいます。メッセージが急増するとLambdaの同時実行数が一気に増え、<b>RDSの接続数が上限に達して</b>エラーが多発します。メッセージの取りこぼしを起こさずに、RDSへの同時アクセスを抑えたいと考えています。最も適切な対処はどれですか。"],"options":[{"l":"A","html":"SQSのイベントソースマッピングに最大同時実行数を設定する"},{"l":"B","html":"SQSキューをFIFOキューに変更する"},{"l":"C","html":"可視性タイムアウトを12時間に延長する"},{"l":"D","html":"Lambda関数のタイムアウトを最大の15分にして、処理を確実に終わらせる"}],"answer":["A"],"multi":false,"req":"","key":"SQSのイベントソースマッピングには、そのキューのために起動するLambdaの<b>同時実行数の上限</b>を設定できます。上限を超える分のメッセージはキューに残って順に処理されるため、取りこぼしなくRDSへの同時接続を抑えられます（RDS Proxyを併用すると接続の効率がさらに上がります）。","kw":"イベントソースマッピングの最大同時実行数","reasons":[{"l":"B","html":"FIFOは順序を保証する仕組みで、同時実行数の制御が目的ではありません。スループットも下がります。"},{"l":"C","html":"失敗したメッセージが再び見えるまでの時間が延びるだけで、同時実行数は変わりません。"},{"l":"D","html":"タイムアウトを延ばしても同時実行数は減らず、接続がつながったままになる時間が長くなるだけです。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a> ／ <a href=\"#compute\" data-go=\"compute\">第1章 1.6 AWS Lambda</a> ／ <a href=\"#database\" data-go=\"database\">第4章 4.5 データベースの性能問題を原因別に切り分ける</a>"},{"n":9,"topic":"障害時の案内ページ","level":2,"body":["ALBで公開しているWebアプリケーションが停止したときに、利用者へ「メンテナンス中」の静的ページを自動で表示したいと考えています。追加のサーバーは用意したくありません。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"ALBのリスナールールで、ターゲットが異常なときに固定レスポンスを返す"},{"l":"B","html":"Route 53の複数値回答ルーティングで、ALBとS3のIPアドレスを返す"},{"l":"C","html":"Route 53の加重ルーティングで、ALBとS3へ半分ずつ振り分ける"},{"l":"D","html":"Route 53のフェイルオーバールーティングで、プライマリにALB（ヘルスチェック付き）、セカンダリに静的ページを置いたS3の静的ウェブサイトを指定する"}],"answer":["D"],"multi":false,"req":"","key":"<b>プライマリが異常なときだけ別の宛先へ切り替える</b>のがフェイルオーバールーティングです。セカンダリに静的ウェブサイトのS3バケット（エイリアスレコード）を置けば、サーバーを増やさずに案内ページを出せます。","kw":"フェイルオーバールーティング／S3の静的ウェブサイト","reasons":[{"l":"A","html":"ALBのリスナールールはターゲットの正常性で分岐させることができません。ALB自体が停止した場合にも対応できません。"},{"l":"B","html":"複数値回答ルーティングはIPアドレスを返す仕組みで、ALBやS3のようにエイリアスで指定する宛先とは組み合わせられません。案内ページへの切り替えという目的にも合いません。"},{"l":"C","html":"正常時にも半分の利用者がメンテナンスページに振り分けられてしまいます。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.4 名前解決：Route 53 と Resolver</a> ／ <a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a>"},{"n":10,"topic":"ストリームの書き込み性能","level":3,"body":["Kinesis Data Streams（プロビジョンドモード、10シャード）にIoT機器のデータを書き込んでいます。全体の書き込み量はシャード合計の上限を大きく下回っているのに、<code>ProvisionedThroughputExceededException</code> が頻発しています。調べると、パーティションキーに<b>機器の設置拠点ID</b>（全部で3種類）を使っていました。最も効果的な対処はどれですか。"],"options":[{"l":"A","html":"パーティションキーを機器IDに変更する"},{"l":"B","html":"データ保持期間を7日に延長し、書き込みを平準化する"},{"l":"C","html":"コンシューマーに拡張ファンアウトを設定し、処理の遅れをなくす"},{"l":"D","html":"シャード数を20に増やす"}],"answer":["A"],"multi":false,"req":"","key":"パーティションキーの値が3種類しかないため、データが<b>最大でも3つのシャードに集中</b>しています（ホットシャード）。値の種類が多いキー（機器IDなど）に変えれば、書き込みが全シャードに分散します。","kw":"パーティションキーのカーディナリティ","reasons":[{"l":"B","html":"保持期間は読み直せる期間を決める設定で、書き込みの上限とは関係ありません。"},{"l":"C","html":"拡張ファンアウトは<b>読み取り</b>側の帯域を増やす機能で、書き込みのスロットリングは解消しません。"},{"l":"D","html":"キーが3種類のままでは、シャードを増やしても使われるのは3つのままです。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.1 Amazon Kinesis</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":11,"topic":"ストリームのリアルタイム集計","level":2,"body":["ECサイトのクリックストリームをKinesis Data Streamsで受けています。<b>直近5分間の商品別閲覧数を1分ごとに更新する</b>ダッシュボードを作りたいと考えています。サーバーの管理はしたくありません。最も適切なサービスはどれですか。"],"options":[{"l":"A","html":"Amazon Managed Service for Apache Flinkで、ウィンドウ集計を行う"},{"l":"B","html":"Amazon Data Firehoseで S3 に配信し、Athenaで毎分クエリする"},{"l":"C","html":"AWS Glueの定期ETLジョブで、1時間ごとに集計する"},{"l":"D","html":"EC2上にストリーム処理用のアプリケーションを構築する"}],"answer":["A"],"multi":false,"req":"","key":"<b>ストリームに対する時間窓（ウィンドウ）集計を継続的に行う</b>のが Managed Service for Apache Flink の役割です。Flink SQL などで「直近5分間を1分ごとにずらして集計」を書け、サーバーの管理も不要です。","kw":"Amazon Managed Service for Apache Flink","reasons":[{"l":"B","html":"S3に書き出してから毎分クエリする方式は、配信のバッファ時間とクエリ時間が加わり、毎分の更新に向きません。毎分のスキャン料金もかかります。"},{"l":"C","html":"1時間ごとのバッチでは、1分ごとの更新という要件を満たせません。"},{"l":"D","html":"要件は満たせますが、サーバーの管理が必要になり、要件に反します。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.1 Amazon Kinesis</a>"},{"n":12,"topic":"機械学習の推論基盤","level":2,"body":["学習済みの自然言語処理モデルを使った推論APIを、EC2で大量に動かしています。現在は汎用のGPUインスタンスを使っていますが、<b>推論の単価を下げつつスループットを上げたい</b>と考えています。モデルの学習は別の環境で行います。最も適切なインスタンスはどれですか。"],"options":[{"l":"A","html":"メモリ最適化インスタンス（R系）"},{"l":"B","html":"AWS Trainium を搭載したインスタンス（Trn1、機械学習向け）"},{"l":"C","html":"AWS Inferentia を搭載したインスタンス（Inf2）"},{"l":"D","html":"バースト可能なインスタンス（T系）"}],"answer":["C"],"multi":false,"req":"","key":"<b>Inferentiaは推論専用</b>に設計されたAWSの機械学習チップで、推論1回あたりのコストを下げつつ高いスループットを出すことを目的としています。「推論」と「コスト」が並んだら Inferentia です。","kw":"","reasons":[{"l":"A","html":"メモリ最適化インスタンスはインメモリ処理向けで、推論の演算性能を高めるものではありません。"},{"l":"B","html":"Trainiumは<b>学習（トレーニング）</b>向けのチップです。学習は別環境で行うという条件と合いません。"},{"l":"D","html":"T系はCPUクレジットで一時的に性能を上げる汎用インスタンスで、大量の推論を継続的に処理する用途に向きません。"}],"refs":"<a href=\"#d3\" data-go=\"d3\">第13章 13.2 コンピューティングとパフォーマンス</a>"},{"n":13,"topic":"ログの保管コスト","level":2,"body":["アプリケーションのログファイルをS3に保存しています。<b>作成後30日は頻繁に</b>参照し、<b>30〜90日は障害調査でまれに即時参照</b>します。<b>90日を過ぎると監査対応でのみ参照し、取り出しに12時間以上かかってもかまいません</b>。作成から1年で削除します。最もコストの低いライフサイクル設定はどれですか。"],"options":[{"l":"A","html":"30日後にS3 One Zone-IA、90日後にS3 Glacier Instant Retrieval、365日後に削除"},{"l":"B","html":"作成時からS3 Intelligent-Tieringに置き、365日後に削除"},{"l":"C","html":"30日後にS3 Standard-IA、90日後にS3 Glacier Deep Archive、365日後に削除"},{"l":"D","html":"30日後にS3 Standard-IA、90日後にS3 Glacier Flexible Retrieval、365日後に削除"}],"answer":["C"],"multi":false,"req":"","key":"アクセス頻度が段階的に下がり、それぞれの時期に<b>許容できる取り出し時間が明示</b>されているので、ライフサイクルで順に移すのが最安です。30〜90日は即時取り出しが必要なのでStandard-IA、90日以降は12時間以上待てるので最安のDeep Archiveを選びます。Deep Archiveにいる期間は275日で、最低保存期間（180日）も満たします。","kw":"S3 Standard-IA／S3 Glacier Deep Archive","reasons":[{"l":"A","html":"One Zone-IAは単一AZに保存されるため、AZ障害でログを失う可能性があります。90日以降も即時取り出しは不要なので、Glacier Instant Retrievalは割高です。"},{"l":"B","html":"アクセスパターンが既知なので、監視料金のかかるIntelligent-Tieringより、ライフサイクルで明示的に移すほうが安くなります（アーカイブ階層もオプトインが必要です）。"},{"l":"D","html":"要件は満たしますが、12時間以上待てるならDeep Archiveのほうが安くなります。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":14,"topic":"開発用データベースのコスト","level":2,"body":["開発チームがAurora MySQLを使っています。利用は<b>平日の日中だけ</b>で、夜間と週末は接続がまったくありません。日中の負荷も日によって大きく変わります。管理の手間をかけずにコストを下げたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"リードレプリカを追加し、プライマリのインスタンスクラスを小さくして分散する"},{"l":"B","html":"Aurora Serverless v2（最小0 ACU）に移行する"},{"l":"C","html":"3年のリザーブドインスタンスを購入する"},{"l":"D","html":"毎晩スナップショットを取得してクラスターを削除し、朝に復元する"}],"answer":["B"],"multi":false,"req":"","key":"Aurora Serverless v2は負荷に合わせて容量（ACU）を細かく自動調整し、<b>最小容量を0 ACUにすると、接続がない間は自動で一時停止</b>してコンピューティング料金がかからなくなります。日中の変動にも夜間の停止にも、管理の手間なく対応できます。","kw":"Aurora Serverless v2（自動一時停止）","reasons":[{"l":"A","html":"インスタンスが増えるうえ、夜間も料金がかかり続けます。"},{"l":"C","html":"夜間と週末は使わないため、3年間の常時稼働を前提にした割引は無駄が大きくなります。"},{"l":"D","html":"毎日の削除と復元は手間がかかり、復元にも時間がかかります。自動化するにしても、Serverless v2のほうがはるかに簡単です。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.2 Amazon Aurora</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.4 データベースのコスト最適化</a>"},{"n":15,"topic":"常時稼働するフリートの割引","level":3,"body":["1つのリージョンで、M系のEC2インスタンス40台が24時間365日稼働しています。今後1年以内に、一部を<b>Graviton（Arm）インスタンスやFargateへ移行する</b>計画があります。移行の自由度を保ちながらコストを下げたいと考えています。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"M系インスタンスの3年スタンダードリザーブドインスタンスを購入する"},{"l":"B","html":"Compute Savings Plansを購入する"},{"l":"C","html":"すべてのインスタンスをスポットインスタンスに置き換える"},{"l":"D","html":"AWS Compute Optimizerの推奨に基づいて、過剰なインスタンスサイズを見直す"},{"l":"E","html":"Dedicated Hostsへ移行する"}],"answer":["B","D"],"multi":true,"req":"","key":"Compute Savings Plansは、<b>インスタンスファミリー・サイズ・OS・リージョン</b>が変わっても割引が続き、<b>FargateやLambdaにも適用</b>されます。移行計画があるなら最も柔軟な選択肢です。さらに、コミットの前にCompute Optimizerでサイズを適正化しておくと、無駄なコミットを避けられます。","kw":"Compute Savings Plans／AWS Compute Optimizer","reasons":[{"l":"A","html":"スタンダードRIはインスタンスファミリーを変更できず、Gravitonへの移行やFargateには割引が適用されません。"},{"l":"C","html":"常時稼働のフリートをすべてスポットにすると、中断によってサービスが止まる危険があります。"},{"l":"E","html":"Dedicated Hostsはライセンスやコンプライアンスのための選択肢で、コストは上がります。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a> ／ <a href=\"#management\" data-go=\"management\">第8章 8.6 AWS Trusted Advisor</a>"}]},{"id":"exam-set-19","file":"set-19.md","num":"問題セット19","title":"実戦演習②（本番の分野比率・15問）","questions":[{"n":1,"topic":"社内専用API","level":2,"body":["社内システム向けのREST APIをAPI Gatewayで提供しています。このAPIは<b>VPC内のアプリケーションからだけ</b>呼び出せるようにし、インターネットからは到達できないようにしたいと考えています。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"リージョンAPIのまま、AWS WAFで社内のIPアドレス範囲以外を拒否する"},{"l":"B","html":"APIキーを必須にし、キーをVPC内のアプリケーションにだけ配布する"},{"l":"C","html":"エッジ最適化APIにし、CloudFrontの地理的制限で日本以外を拒否する"},{"l":"D","html":"プライベートAPIにし、<code>execute-api</code> のインターフェース型VPCエンドポイント経由でのみ呼び出させる"}],"answer":["D"],"multi":false,"req":"","key":"プライベートAPIは<b>インターフェース型VPCエンドポイント経由でしか到達できない</b>API Gatewayのエンドポイント種別です。リソースポリシーで <code>aws:SourceVpce</code> などを条件にすれば、呼び出し元をさらに特定のエンドポイントやVPCに絞れます。","kw":"プライベートAPI／インターフェース型VPCエンドポイント","reasons":[{"l":"A","html":"APIはインターネットに公開されたままです。IPアドレスによる制限だけでは「インターネットから到達できない」状態になりません。"},{"l":"B","html":"APIキーは利用量の管理のためのもので、認証や到達範囲の制御には使えません。キーが漏れれば外部からも呼び出せます。"},{"l":"C","html":"国単位の制限は到達範囲をVPCに絞る仕組みではありません。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.1 Amazon API Gateway</a> ／ <a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続</a>"},{"n":2,"topic":"シークレットのDR","level":2,"body":["東京リージョンのアプリケーションがSecrets ManagerからDBの認証情報を取得しています。災害対策として大阪リージョンにも同じ構成を用意しますが、<b>フェイルオーバー時に同じ認証情報をすぐ取得できる</b>必要があり、ローテーション後の値も両リージョンでそろえたいと考えています。最も運用負荷が小さい方法はどれですか。"],"options":[{"l":"A","html":"シークレットを大阪リージョンへレプリケートする"},{"l":"B","html":"大阪リージョンにも同じ名前のシークレットを手動で作成し、ローテーションのたびに担当者が値を更新する"},{"l":"C","html":"認証情報をS3に保存し、クロスリージョンレプリケーションで複製する"},{"l":"D","html":"認証情報をアプリケーションのAMIに埋め込み、AMIを大阪へコピーする"}],"answer":["A"],"multi":false,"req":"","key":"Secrets Managerには<b>シークレットを別リージョンへ複製する機能</b>があり、プライマリの値が更新・ローテーションされるとレプリカにも反映されます。DRリージョンのアプリは、自リージョンのレプリカから同じ値を取得できます。","kw":"Secrets Managerのレプリケーション","reasons":[{"l":"B","html":"手作業の同期は漏れや遅れが起きやすく、フェイルオーバー時に値がずれる危険があります。"},{"l":"C","html":"S3に認証情報を置くと管理が煩雑になり、ローテーションとも連動しません。"},{"l":"D","html":"認証情報をイメージに埋め込むのはアンチパターンで、ローテーションにも追従できません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.10 AWS Secrets Manager vs Parameter Store</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":3,"topic":"コンテナへの機密情報の受け渡し","level":2,"body":["ECS on Fargateのタスク定義で、DBのパスワードを<b>環境変数に平文で</b>書いています。タスク定義を閲覧できる人なら誰でもパスワードを読めてしまう状態です。コードの変更を最小限にして改善したいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"パスワードをBase64でエンコードしてから環境変数に設定する"},{"l":"B","html":"パスワードをコンテナイメージに埋め込み、ECRのリポジトリを非公開にしてイメージの取得をIAMで制限する"},{"l":"C","html":"Secrets Managerに保存してタスク定義の<code>secrets</code>で参照し、実行ロールに取得権限を付ける"},{"l":"D","html":"パスワードをS3に保存し、コンテナの起動スクリプトでダウンロードする"}],"answer":["C"],"multi":false,"req":"","key":"タスク定義の <code>secrets</code> にSecrets Manager（またはParameter Store）のARNを指定すると、<b>タスクの起動時に値が取得され、環境変数としてコンテナへ渡されます</b>。アプリは従来どおり環境変数を読むだけなので、コードの変更は不要です。値を取得するのはECSエージェント側なので、権限は<b>タスク実行ロール</b>に付けます。","kw":"タスク定義のsecrets／タスク実行ロール","reasons":[{"l":"A","html":"Base64は暗号化ではなく、誰でも元に戻せます。"},{"l":"B","html":"イメージを取得できる人なら誰でもパスワードを読めます。変更のたびにイメージを作り直す必要もあります。"},{"l":"D","html":"起動スクリプトの変更が必要になり、S3の権限管理も増えます。"}],"refs":"<a href=\"#container\" data-go=\"container\">第9章 9.1 Amazon ECS</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.10 AWS Secrets Manager vs Parameter Store</a>"},{"n":4,"topic":"最小権限への絞り込み","level":2,"body":["バッチ処理用のIAMロールに、開発初期に <code>AdministratorAccess</code> を付与したままになっています。実際に使っている操作だけを許可するポリシーに置き換えたいのですが、どの操作を使っているか誰も把握していません。最も効率的な方法はどれですか。"],"options":[{"l":"A","html":"<code>AdministratorAccess</code> を外し、エラーが出た操作を1つずつ追加する"},{"l":"B","html":"IAM Access AnalyzerでCloudTrailの記録からポリシーを生成する"},{"l":"C","html":"IAM認証情報レポートをダウンロードして確認する"},{"l":"D","html":"AWS Configで、ロールの設定変更履歴を確認する"}],"answer":["B"],"multi":false,"req":"","key":"IAM Access Analyzerは、指定した期間の<b>CloudTrailのログからロールが実際に呼び出した操作を洗い出し、ポリシーのひな形を生成</b>できます。これを確認・調整して置き換えるのが、最小権限へ絞り込む最短の手順です。","kw":"IAM Access Analyzerのポリシー生成","reasons":[{"l":"A","html":"本番のバッチが失敗するたびに権限を足す運用になり、業務への影響が大きくなります。"},{"l":"C","html":"認証情報レポートはIAMユーザーのパスワードやアクセスキー、MFAの状況を一覧にするもので、ロールが使った操作はわかりません。"},{"l":"D","html":"Configで追えるのはロール自体の設定の変更履歴で、ロールがどの操作を呼んだかはわかりません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":5,"topic":"不正なドメインへの通信の遮断","level":3,"body":["AWS Organizationsで管理する全アカウントのVPCについて、<b>既知のマルウェア配布ドメインやボットネットのドメイン</b>へ名前解決や通信ができないようにしたいと考えています。新しいアカウントやVPCにも自動で適用したいと考えています。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"各VPCのセキュリティグループで、対象ドメインへのアウトバウンドを拒否する"},{"l":"B","html":"ネットワークACLで、対象ドメインのIPアドレス範囲を拒否する"},{"l":"C","html":"Route 53 ResolverのDNS Firewallでブロックする"},{"l":"D","html":"AWS WAFのWeb ACLを各VPCに関連付ける"},{"l":"E","html":"Firewall Managerで組織全体のVPCへ一括適用する"}],"answer":["C","E"],"multi":true,"req":"","key":"<b>ドメイン名で止める</b>にはDNS Firewallが適しています。VPCからの名前解決の段階でブロックでき、AWSが管理する脅威ドメインのリストも使えます。<b>組織全体への一括適用と、新しいアカウント・VPCへの自動適用</b>はFirewall Managerの役割です。","kw":"Route 53 ResolverのDNS Firewall／AWS Firewall Manager","reasons":[{"l":"A","html":"セキュリティグループには拒否ルールがなく、ドメイン名も指定できません。"},{"l":"B","html":"ネットワークACLはIPアドレスでしか指定できず、変わり続ける攻撃者のIPアドレスを追いかけるのは現実的ではありません。"},{"l":"D","html":"WAFはCloudFrontやALBなどに届くHTTPリクエストを検査するもので、VPCからの外向きの名前解決や通信は対象外です。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.4 名前解決：Route 53 と Resolver</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.13 その他のセキュリティ・ガバナンスサービス</a>"},{"n":6,"topic":"アカウントをまたぐイベント連携","level":2,"body":["20個のワークロードアカウントで発生する特定のイベント（EC2の状態変化やGuardDutyの検出結果）を、<b>セキュリティアカウントで一元的に処理</b>したいと考えています。処理はセキュリティアカウントのLambda関数で行います。最も運用負荷が小さい構成はどれですか。"],"options":[{"l":"A","html":"各アカウントのEventBridgeルールで、セキュリティアカウントのイベントバスへ転送する"},{"l":"B","html":"各アカウントにLambda関数を配置し、処理結果をセキュリティアカウントのS3バケットに書き込む"},{"l":"C","html":"各アカウントのCloudTrailログをセキュリティアカウントに集約し、1時間ごとにLambdaで解析する"},{"l":"D","html":"各アカウントからSNSトピックへ発行し、セキュリティアカウントの担当者がメールで確認する"}],"answer":["A"],"multi":false,"req":"","key":"EventBridgeは<b>別アカウントのイベントバスを直接ターゲットにできます</b>。各アカウントのルールで対象イベントを転送し、セキュリティアカウントのイベントバスで受けて、そこのルールからLambdaを起動します。処理のロジックを1か所にまとめられ、イベント駆動でほぼリアルタイムに動きます。","kw":"EventBridgeのクロスアカウントのイベントバス","reasons":[{"l":"B","html":"処理のロジックが20アカウントに分散し、更新や監視の負荷が大きくなります。"},{"l":"C","html":"1時間ごとのバッチ処理では即応できず、ログ解析の実装も必要になります。"},{"l":"D","html":"人手の確認は自動処理の要件を満たしません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.3 Amazon EventBridge</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.4 イベント駆動型アーキテクチャ</a>"},{"n":7,"topic":"ワークフローのエラー処理","level":2,"body":["Step Functionsで、外部の決済APIを呼び出すLambda関数を含むワークフローを動かしています。決済APIは<b>一時的にタイムアウトする</b>ことがあり、そのたびにワークフロー全体が失敗しています。一時的な失敗は自動でやり直し、それでも失敗した場合は担当者への通知処理に進めたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"Lambda関数の中でループを書き、APIが成功するまで何度も呼び出す"},{"l":"B","html":"該当ステートにRetryとCatchを定義し、失敗時は通知へ進める"},{"l":"C","html":"ワークフロー全体を毎回最初から手動で再実行する"},{"l":"D","html":"Lambda関数のタイムアウトを15分に延長する"}],"answer":["B"],"multi":false,"req":"","key":"Step Functionsは、ステートごとに<b>Retry（エラーの種類・回数・間隔と倍率）</b>と<b>Catch（最終的に失敗したときの遷移先）</b>を宣言的に書けます。再試行と失敗時の分岐を関数のコードではなくワークフローの定義で管理でき、実行履歴にも残ります。","kw":"Retry／Catch","reasons":[{"l":"A","html":"実行時間と料金が膨らみ、Lambdaの最大実行時間に達する危険もあります。再試行の状況も見えにくくなります。"},{"l":"C","html":"手作業の再実行は自動化の要件に反し、途中まで進んだ処理を二重に実行する危険もあります。"},{"l":"D","html":"タイムアウトを延ばしても、APIの一時的な失敗は解消しません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.4 AWS Step Functions</a>"},{"n":8,"topic":"オンプレミスサーバーの災害対策","level":2,"body":["オンプレミスの30台の業務サーバー（物理・仮想の混在）について、AWSを災害対策サイトにしたいと考えています。要件は<b>RPOが数秒、RTOが数分</b>で、平常時のAWS側のコストは最小限に抑えたいと考えています。最も適切なサービスはどれですか。"],"options":[{"l":"A","html":"Elastic Disaster Recoveryで継続的に複製する"},{"l":"B","html":"AWS DataSyncで、サーバーのファイルを1時間ごとにS3へ同期し、災害時にEC2へ書き戻して起動する"},{"l":"C","html":"AWS Backupで、オンプレミスのサーバーを毎日バックアップする"},{"l":"D","html":"AWS Snowball Edgeで、毎月データを輸送する"}],"answer":["A"],"multi":false,"req":"","key":"Elastic Disaster Recoveryは、サーバーのディスクを<b>ブロックレベルで継続的にAWSへ複製</b>し（RPOは秒単位）、災害時には数分でEC2として起動できます（RTOは分単位）。平常時は低コストのステージング領域に複製を保つだけなので、本番相当のサーバーを常時動かす必要がありません。","kw":"AWS Elastic Disaster Recovery","reasons":[{"l":"B","html":"ファイルの同期であり、サーバー全体（OSやアプリケーション）を起動し直せる形にはなりません。RPOも1時間です。"},{"l":"C","html":"日次のバックアップではRPOが最大1日になり、復元にも時間がかかります。"},{"l":"D","html":"物理輸送では秒単位のRPOは実現できません。"}],"refs":"<a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a> ／ <a href=\"#others\" data-go=\"others\">第10章 10.15 その他の移行サービス</a>"},{"n":9,"topic":"テーブルの誤操作への備え","level":2,"body":["DynamoDBのテーブルで、運用担当者の誤ったスクリプトにより<b>大量の項目が上書き</b>される事故が起きました。今後は、<b>誤操作の直前の状態に戻せる</b>ようにし、<b>テーブルそのものの誤削除</b>も防ぎたいと考えています。最も適切な組み合わせはどれですか。"],"options":[{"l":"A","html":"グローバルテーブルで別リージョンにレプリカを作成する"},{"l":"B","html":"PITRと削除保護を有効にする"},{"l":"C","html":"DAXを導入し、読み取りをキャッシュ経由にする"},{"l":"D","html":"オンデマンドキャパシティモードに変更する"}],"answer":["B"],"multi":false,"req":"","key":"PITRを有効にすると、<b>過去35日間の任意の時点</b>へ秒単位でテーブルを復元できます。削除保護を有効にすれば、設定を解除しない限りテーブルを削除できません。誤更新と誤削除の両方に対応する組み合わせです。","kw":"ポイントインタイムリカバリ（PITR）／削除保護","reasons":[{"l":"A","html":"グローバルテーブルは変更を即座に複製するため、誤った上書きもレプリカへそのまま反映されます（レプリケーションはバックアップではありません）。"},{"l":"C","html":"DAXは読み取りの高速化で、データ保護には関係しません。"},{"l":"D","html":"キャパシティモードは課金とスループットの方式で、誤操作への備えにはなりません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a> ／ <a href=\"#foundations\" data-go=\"foundations\">第0章 0.2 可用性と耐久性、冗長化・レプリケーション・バックアップの区別</a>"},{"n":10,"topic":"キャッシュの読み取り負荷","level":2,"body":["ElastiCache for Redis（クラスターモード無効、ノード1台）をセッションとランキングのキャッシュに使っています。データ量はノードのメモリに十分収まっていますが、<b>読み取り</b>が急増してCPU使用率が高止まりしています。書き込みは少量です。最も適切な対処はどれですか。"],"options":[{"l":"A","html":"リードレプリカを追加し、読み取りをリーダーエンドポイントに向ける"},{"l":"B","html":"クラスターモードを有効にし、データを複数のシャードに分散して負荷を分ける"},{"l":"C","html":"Memcachedへ移行する"},{"l":"D","html":"キャッシュのTTLを短くする"}],"answer":["A"],"multi":false,"req":"","key":"データ量ではなく<b>読み取りの集中</b>が問題なので、同じデータを持つレプリカを増やして読み取りを分散します。リーダーエンドポイントを使えば、アプリは接続先を1つ指定するだけで複数のレプリカに分散できます。レプリカはマルチAZの自動フェイルオーバーにも使えます。","kw":"リードレプリカ／リーダーエンドポイント","reasons":[{"l":"B","html":"シャーディングは<b>メモリ容量や書き込み</b>の限界を広げる手段です。データがメモリに収まっていて書き込みも少ない状況では、構成の変更に見合いません。"},{"l":"C","html":"Memcachedにはレプリケーションや永続化がなく、ランキング（ソート済みセット）などRedisのデータ構造も使えません。"},{"l":"D","html":"TTLを短くするとキャッシュのミスが増え、バックエンドの負荷がかえって上がります。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.4 Amazon ElastiCache</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":11,"topic":"ストリーミング基盤の移行","level":1,"body":["オンプレミスでApache Kafkaを運用しており、多数のプロデューサーとコンシューマーがKafkaのクライアントライブラリで接続しています。AWSへ移行するにあたり、<b>アプリケーションのコードを変えずに</b>、ブローカーの運用負荷をなくしたいと考えています。最も適切なサービスはどれですか。"],"options":[{"l":"A","html":"Amazon Kinesis Data Streams"},{"l":"B","html":"Amazon SQS"},{"l":"C","html":"Amazon MSK"},{"l":"D","html":"Amazon MQ"}],"answer":["C"],"multi":false,"req":"","key":"Amazon MSKは<b>Apache Kafkaそのもの</b>をマネージドで提供するため、既存のKafkaクライアントをそのまま接続できます。「既存のKafka」「コードを変えずに」がそろえばMSKです。","kw":"Amazon MSK","reasons":[{"l":"A","html":"Kinesisは独自のAPIを使うため、プロデューサーとコンシューマーの書き換えが必要です。"},{"l":"B","html":"SQSはキューで、Kafkaのプロトコルやトピック・パーティションの考え方とは異なります。"},{"l":"D","html":"Amazon MQはActiveMQとRabbitMQのマネージドサービスで、Kafkaには対応していません。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.9 その他のアナリティクスサービス</a> ／ <a href=\"#integration\" data-go=\"integration\">第6章 6.5 Amazon MQ</a>"},{"n":12,"topic":"夜間のデータ変換","level":2,"body":["毎晩、S3に置かれた数百GBのCSVファイルを結合・変換し、Parquet形式で別のバケットに書き出しています。現在は常時起動のEMRクラスターで処理していますが、<b>日中はクラスターが遊んでいる</b>うえ、クラスターの運用にも手間がかかっています。Sparkのコードは流用したいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"Athenaのクエリで毎晩変換する"},{"l":"B","html":"Lambda関数で1ファイルずつ変換する"},{"l":"C","html":"EMRクラスターのインスタンスタイプを大きくし、夜間の処理時間を短くする"},{"l":"D","html":"AWS GlueのETLジョブ（Spark）に移す"}],"answer":["D"],"multi":false,"req":"","key":"Glue ETLは<b>サーバーレスのSpark実行環境</b>で、ジョブが動いている間だけ課金されます。既存のSparkのコードを流用でき、クラスターの管理も不要です。スケジュールやジョブブックマーク（処理済みデータの管理）も備えています。","kw":"AWS GlueのETLジョブ","reasons":[{"l":"A","html":"AthenaのCTASでも変換はできますが、Sparkのコードを流用できず、複雑な結合・変換ロジックの移植が必要になります。"},{"l":"B","html":"数百GBを結合する処理は、Lambdaの実行時間（最大15分）やメモリの制約に合いません。Sparkのコードも流用できません。"},{"l":"C","html":"常時起動のクラスターである限り、日中の遊休コストと運用の手間は残ります。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.2 AWS Glue</a> ／ <a href=\"#analytics\" data-go=\"analytics\">第7章 7.8 Amazon EMR</a>"},{"n":13,"topic":"サーバーレス関数のコスト","level":2,"body":["数百のLambda関数（Python、x86_64）が毎月大量に実行され、Lambdaの料金が増え続けています。関数の多くは<b>メモリを3GBに設定したまま</b>ですが、実際の使用量は500MB程度です。ネイティブの依存ライブラリはありません。コードの変更を最小限にしてコストを下げたいと考えています。最も効果的な対策はどれですか。"],"options":[{"l":"A","html":"プロビジョニング済み同時実行数を設定する"},{"l":"B","html":"関数のタイムアウトを短くし、長い処理を打ち切る"},{"l":"C","html":"すべての関数をEC2上のcronジョブに移行する"},{"l":"D","html":"関数をarm64に切り替え、メモリを見直す"}],"answer":["D"],"multi":false,"req":"","key":"Lambdaの料金は<b>メモリ量×実行時間</b>で決まるため、過大なメモリ設定を実測に合わせて下げるのが最も直接的です（Compute Optimizerがメモリの推奨を出します）。さらに<b>arm64はx86_64より単価が安く</b>、ネイティブの依存ライブラリがないPythonならコードを変えずに切り替えられます。","kw":"arm64（Graviton）","reasons":[{"l":"A","html":"プロビジョニング済み同時実行数はコールドスタート対策で、待機中の料金が追加でかかります。"},{"l":"B","html":"正常に終わる処理の料金は変わりません。途中で打ち切られる処理が出れば、再実行でかえってコストが増えます。"},{"l":"C","html":"サーバーの管理が必要になり、処理の量に合わせた伸縮もできなくなります。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.6 AWS Lambda</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":14,"topic":"I/Oの多いデータベース","level":2,"body":["Aurora PostgreSQLの請求を分析したところ、<b>I/Oリクエストの料金がAuroraの費用全体の約半分</b>を占めており、月ごとの変動も大きいことがわかりました。アプリケーションやインスタンス構成は変えたくありません。最も適切な対策はどれですか。"],"options":[{"l":"A","html":"Aurora Serverless v2に移行する"},{"l":"B","html":"リードレプリカを追加して読み取りを分散する"},{"l":"C","html":"Aurora I/O-Optimizedに変更する"},{"l":"D","html":"自動バックアップの保持期間を短くする"}],"answer":["C"],"multi":false,"req":"","key":"Aurora I/O-Optimizedは、<b>I/Oリクエストの料金がかからない</b>代わりにインスタンスとストレージの単価が上がる構成です。I/O料金が費用の大きな割合（目安として25%超）を占めるワークロードでは、総額が下がり、請求も予測しやすくなります。構成の切り替えだけで済み、アプリの変更は不要です。","kw":"Aurora I/O-Optimized","reasons":[{"l":"A","html":"Serverless v2は容量の伸縮による節約策で、I/O料金の課金方式は変わりません。"},{"l":"B","html":"レプリカを増やしてもI/Oの量は減らず、インスタンス料金が増えます。"},{"l":"D","html":"バックアップの保持期間はI/O料金とは関係ありません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.2 Amazon Aurora</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.4 データベースのコスト最適化</a>"},{"n":15,"topic":"費用の見張り","level":2,"body":["経営層から、「<b>月末の請求が予算を超えそうなら早めに知りたい</b>」「<b>普段と違う急な費用の増加はすぐに検知したい</b>」という2つの要望がありました。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"AWS Budgetsの予算アラートを設定する"},{"l":"B","html":"AWS Trusted Advisorのコスト最適化チェックを毎月確認する"},{"l":"C","html":"Cost and Usage ReportをS3に出力する"},{"l":"D","html":"AWS Cost Anomaly Detectionで、機械学習による異常な支出の検知と通知を設定する"},{"l":"E","html":"AWS Configで、高額なインスタンスタイプの起動を記録する"}],"answer":["A","D"],"multi":true,"req":"","key":"「予算を<b>超えそう</b>」はBudgetsの<b>予測値に基づくアラート</b>、「<b>普段と違う</b>急増」はCost Anomaly Detectionの役割です。前者は計画との比較、後者は過去のパターンとの比較で、見張る観点が違います。","kw":"AWS Budgets（予測値のアラート）／AWS Cost Anomaly Detection","reasons":[{"l":"B","html":"Trusted Advisorは削減の余地を示す点検で、予算の超過見込みや急増を通知する仕組みではありません。"},{"l":"C","html":"CURは詳細な分析用のデータで、自分で集計や通知を作り込まない限り、要望には応えられません。"},{"l":"E","html":"Configは構成の記録で、費用の監視や通知の仕組みではありません。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.9〜10.11 コスト管理サービス</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.1 コスト管理ツールの使い分け</a>"}]},{"id":"exam-set-20","file":"set-20.md","num":"問題セット20","title":"実戦演習③（本番の分野比率・15問）","questions":[{"n":1,"topic":"通信の暗号化の強制","level":1,"body":["セキュリティ基準で「S3バケットへのアクセスは<b>必ずHTTPSで行う</b>こと」と定められました。HTTPでのリクエストは拒否したいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"バケットの既定の暗号化をSSE-KMSにし、すべてのオブジェクトをKMSキーで暗号化する"},{"l":"B","html":"バケットのブロックパブリックアクセスを4つとも有効にし、インターネットからの匿名アクセスを止める"},{"l":"C","html":"バケットポリシーで <code>aws:SecureTransport</code> が <code>false</code> の要求をDenyする"},{"l":"D","html":"S3 Transfer Accelerationを有効にする"}],"answer":["C"],"multi":false,"req":"","key":"<code>aws:SecureTransport</code> はリクエストがTLSで送られたかを示す条件キーです。<code>false</code> のときに明示的に拒否すれば、HTTPでのアクセスは誰が行っても失敗します。<b>転送時の暗号化の強制＝SecureTransportのDeny</b>は定番の組み合わせです。","kw":"aws:SecureTransport","reasons":[{"l":"A","html":"既定の暗号化は<b>保管時</b>の暗号化で、通信の暗号化とは別です。"},{"l":"B","html":"ブロックパブリックアクセスは公開の防止で、HTTPの通信は拒否しません。"},{"l":"D","html":"Transfer Accelerationはアップロードの高速化の機能で、HTTPを禁止するものではありません。"}],"refs":"<a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a> ／ <a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a>"},{"n":2,"topic":"メタデータ経由の認証情報の窃取","level":2,"body":["脆弱性診断で、EC2上のWebアプリケーションに<b>SSRF（サーバーサイドリクエストフォージェリ）</b>の危険があると指摘されました。攻撃者にインスタンスメタデータ経由でIAMロールの一時認証情報を盗まれることを防ぎたいと考えています。アプリケーションはIAMロールを使い続けます。最も適切な対策はどれですか。"],"options":[{"l":"A","html":"IMDSv2を必須にする"},{"l":"B","html":"インスタンスメタデータサービスを無効にする"},{"l":"C","html":"セキュリティグループで、<code>169.254.169.254</code> への通信を拒否する"},{"l":"D","html":"IAMロールを外し、アクセスキーを環境変数に設定する"}],"answer":["A"],"multi":false,"req":"","key":"IMDSv2は、PUTリクエストで取得した<b>セッショントークンがないとメタデータを返しません</b>。SSRFでは攻撃者が任意のヘッダー付きPUTを送らせることが難しいため、認証情報の窃取を大幅に防げます。ロールの一時認証情報は引き続き利用できます。","kw":"IMDSv2","reasons":[{"l":"B","html":"メタデータを無効にすると、アプリケーションがIAMロールの認証情報を取得できなくなります。"},{"l":"C","html":"セキュリティグループには拒否ルールがなく、メタデータへの通信はそもそもセキュリティグループで制御できません。"},{"l":"D","html":"長期のアクセスキーを置くのはより危険で、ベストプラクティスに反します。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":3,"topic":"データベース接続の暗号化","level":2,"body":["RDS for PostgreSQLのデータベースについて、監査で「<b>クライアントからの接続がすべてSSL/TLSで暗号化されている</b>ことを保証すること」を求められました。暗号化されていない接続は拒否したいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"DBインスタンスのストレージ暗号化を有効にする"},{"l":"B","html":"DBパラメータグループで <code>rds.force_ssl</code> を有効にする"},{"l":"C","html":"セキュリティグループで、PostgreSQLのポート以外を拒否する"},{"l":"D","html":"DBインスタンスをプライベートサブネットに移す"}],"answer":["B"],"multi":false,"req":"","key":"<code>rds.force_ssl</code> を有効にすると、RDS for PostgreSQLは<b>SSL/TLSを使わない接続を拒否</b>します（MySQLでは <code>require_secure_transport</code> が同じ役割です）。サーバー側で強制できるため、クライアントの設定漏れがあっても平文の接続は成立しません。","kw":"rds.force_ssl","reasons":[{"l":"A","html":"ストレージ暗号化は<b>保管時</b>の暗号化で、通信の暗号化とは別です。"},{"l":"C","html":"ポートを絞っても、そのポートでの平文の接続は拒否されません。"},{"l":"D","html":"到達できる範囲は狭まりますが、通信の暗号化は保証されません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":4,"topic":"利用リージョンの制限","level":2,"body":["データ所在地の規制に対応するため、組織内の全アカウントで、<b>東京と大阪以外のリージョンではリソースを作成できない</b>ようにしたいと考えています。ただし、IAMやCloudFrontなどのグローバルサービスは使えるようにしておく必要があります。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"各アカウントのIAMユーザーとグループに、東京と大阪以外のリージョンでの操作を拒否するポリシーをアタッチする"},{"l":"B","html":"AWS Configルールで東京と大阪以外に作られたリソースを検出し、SNSで管理者に通知する"},{"l":"C","html":"各アカウントで、使わないリージョンを手動で無効にする"},{"l":"D","html":"<code>aws:RequestedRegion</code> で東京・大阪以外を拒否するSCPを組織に適用する"}],"answer":["D"],"multi":false,"req":"","key":"SCPは組織内の<b>全アカウントの全プリンシパル（ルートユーザーを含む）</b>に上限をかけられます。<code>aws:RequestedRegion</code> で許可するリージョン以外を拒否し、us-east-1などで処理されるグローバルサービスは <code>NotAction</code> で除外するのが定番の書き方です。","kw":"SCP／aws:RequestedRegion","reasons":[{"l":"A","html":"アカウントの管理者はポリシーを外せるうえ、ロールや新しいユーザーには適用されません。"},{"l":"B","html":"検出は事後の対応で、作成そのものを防げません。"},{"l":"C","html":"既定で有効なリージョンの多くは無効にできず、アカウントの追加のたびに手作業も発生します。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.5 AWS Organizations</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a>"},{"n":5,"topic":"機密データの可視化","level":2,"body":["100個以上のS3バケットに、部署ごとのデータが保存されています。セキュリティ部門は、<b>個人情報を含むオブジェクトがどのバケットにあるか</b>を継続的に把握し、ほかのセキュリティサービスの検出結果と<b>一緒に1つの画面で</b>管理したいと考えています。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"Amazon Inspectorを有効にする"},{"l":"B","html":"Amazon Macieの自動機密データ検出を有効にする"},{"l":"C","html":"Amazon Detectiveで、S3へのアクセスを調査する"},{"l":"D","html":"AWS Configで、S3バケットの設定変更を記録する"},{"l":"E","html":"AWS Security Hubで、Macieを含む各サービスの検出結果を集約する"}],"answer":["B","E"],"multi":true,"req":"","key":"S3の中身から<b>個人情報を見つける</b>のはMacie、GuardDutyやInspectorなどと並べて<b>検出結果を一元管理する</b>のはSecurity Hubの役割です。Macieの検出結果はSecurity Hubに送れるため、組み合わせて使うのが定番です。","kw":"Amazon Macie／AWS Security Hub","reasons":[{"l":"A","html":"InspectorはEC2・ECR・Lambdaの脆弱性を評価するサービスで、S3の中身は検査しません。"},{"l":"C","html":"Detectiveはインシデントの原因調査のためのサービスで、機密データの検出はしません。"},{"l":"D","html":"Configはバケットの<b>設定</b>の記録で、オブジェクトの中身に個人情報があるかはわかりません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.9 Amazon Macie</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.13 その他のセキュリティ・ガバナンスサービス</a>"},{"n":6,"topic":"順序付きキューの処理能力","level":3,"body":["SQS FIFOキューで注文を処理しています。注文の順序は<b>顧客ごと</b>に守れればよいのですが、現在は全メッセージに同じメッセージグループIDを付けており、ピーク時に処理が追いつきません。順序の要件を守ったまま処理能力を上げたいと考えています。最も適切な対処はどれですか。"],"options":[{"l":"A","html":"メッセージグループIDを顧客IDに変え、高スループットモードを有効にする"},{"l":"B","html":"標準キューに変更する"},{"l":"C","html":"可視性タイムアウトを短くする"},{"l":"D","html":"コンシューマーの台数を増やして並列に受信する（メッセージグループIDは変えない）"}],"answer":["A"],"multi":false,"req":"","key":"FIFOキューで順序が保証され、同時に1つずつしか処理されないのは<b>同じメッセージグループIDの中だけ</b>です。グループIDを顧客IDにすれば、顧客ごとの順序を守りつつ、異なる顧客の注文を並行して処理できます。高スループットモードはメッセージグループ単位でスループットを伸ばす設定です。","kw":"メッセージグループID／高スループットモード","reasons":[{"l":"B","html":"標準キューでは順序が保証されず、重複配信もあるため、要件を満たしません。"},{"l":"C","html":"可視性タイムアウトを短くしても処理は速くならず、処理中のメッセージが再配信されて二重処理が起きる危険があります。"},{"l":"D","html":"グループIDが1つのままでは、同時に処理できるのは1件ずつです。コンシューマーを増やしても待たされるだけです。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a>"},{"n":7,"topic":"配信元の自動切り替え","level":2,"body":["CloudFrontで、東京リージョンのS3バケットから画像を配信しています。バケットは大阪リージョンへクロスリージョンレプリケーションしています。<b>東京のバケットがエラーを返したときに、自動で大阪のバケットから配信を続けたい</b>と考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"Route 53のフェイルオーバールーティングで、2つのバケットのエンドポイントを切り替える"},{"l":"B","html":"CloudFrontのディストリビューションを2つ作り、障害時に手動でDNSを切り替える"},{"l":"C","html":"CloudFrontのオリジングループで、東京をプライマリ、大阪をセカンダリにする"},{"l":"D","html":"S3 Transfer Accelerationを有効にする"}],"answer":["C"],"multi":false,"req":"","key":"オリジングループは、<b>プライマリのオリジンが指定したエラー（5xxや403・404など）を返したときに、同じリクエストをセカンダリへ送り直す</b>CloudFrontの機能です。DNSの切り替えを待たず、リクエスト単位で自動的にフェイルオーバーします。","kw":"オリジングループ","reasons":[{"l":"A","html":"CloudFrontのオリジンはディストリビューションの設定で決まるため、Route 53でバケットを切り替えても配信元は変わりません。DNSのキャッシュによる遅れもあります。"},{"l":"B","html":"手動の切り替えは自動化の要件を満たしません。"},{"l":"D","html":"Transfer Accelerationはアップロードの高速化で、配信元の切り替えとは関係ありません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 コンテンツ配信と高速化</a> ／ <a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a>"},{"n":8,"topic":"重い処理の切り離し","level":2,"body":["API Gateway＋Lambdaで、アップロードされた動画のサムネイルを生成するAPIを提供しています。処理に<b>最大で40秒</b>かかることがあり、クライアントのタイムアウトや、急増時のLambdaの同時実行数の上限到達が問題になっています。利用者には「受け付けた」ことだけすぐに返せばよいと考えています。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"SQSを挟んで非同期処理にする"},{"l":"B","html":"API Gatewayの統合タイムアウトの上限を引き上げ、処理が終わるまで同期のまま待たせる"},{"l":"C","html":"Lambda関数のメモリを最大にして処理を速くする"},{"l":"D","html":"API Gatewayのキャッシュを有効にする"}],"answer":["A"],"multi":false,"req":"","key":"<b>時間のかかる処理を同期の要求から切り離す</b>のが定石です。受付と処理の間にSQSを挟めば、APIはすぐに応答でき、急増した要求はキューで待たせて処理側のペースで消化できます。処理の結果は、完了通知や状態確認用のAPIで返します。","kw":"SQSによる非同期化","reasons":[{"l":"B","html":"クライアントを長く待たせる設計のままで、急増時の同時実行数の問題も解決しません。"},{"l":"C","html":"多少速くなっても、同期処理である限りタイムアウトと同時実行数の問題は残ります。"},{"l":"D","html":"アップロードごとに内容が違う処理はキャッシュできません。"}],"refs":"<a href=\"#d2\" data-go=\"d2\">第12章 12.2 疎結合アーキテクチャ</a> ／ <a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a>"},{"n":9,"topic":"AZ障害時の処理能力","level":3,"body":["Webアプリケーションは、ピーク時に<b>6台</b>のEC2で処理能力が足ります。可用性の要件は「<b>1つのAZが停止しても、スケールアウトを待たずにピーク時の処理能力を維持する</b>」ことです。3つのAZを使うAuto Scalingグループで、最もコストの低い構成はどれですか。"],"options":[{"l":"A","html":"3つのAZに2台ずつ、合計6台"},{"l":"B","html":"3つのAZに3台ずつ、合計9台"},{"l":"C","html":"3つのAZに4台ずつ、合計12台"},{"l":"D","html":"1つのAZに6台を配置し、障害時は別のAZで起動し直す"}],"answer":["B"],"multi":false,"req":"","key":"1つのAZを失っても、<b>残り2つのAZだけで6台</b>が必要です。したがって1AZあたり3台、合計9台が最小です。障害が起きてから増やすのではなく、あらかじめ余力を持たせておく考え方（静的安定性）です。","kw":"静的安定性","reasons":[{"l":"A","html":"1つのAZが止まると4台になり、スケールアウトが終わるまで処理能力が足りません。"},{"l":"C","html":"要件は満たしますが、1つのAZが止まっても8台が残り、必要以上の余力にコストを払うことになります。"},{"l":"D","html":"単一AZに集中しているため、AZ障害でサービス全体が止まります。"}],"refs":"<a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a> ／ <a href=\"#compute\" data-go=\"compute\">第1章 1.2 Amazon EC2 Auto Scaling</a>"},{"n":10,"topic":"インデックスによる書き込みの詰まり","level":3,"body":["プロビジョンドモードのDynamoDBテーブルで、テーブル本体の書き込みキャパシティには十分な余裕があるのに、<b>書き込みがスロットリング</b>されています。このテーブルには、書き込みのたびに更新されるグローバルセカンダリインデックス（GSI）が1つあり、その書き込みキャパシティは小さく設定されています。最も適切な対処はどれですか。"],"options":[{"l":"A","html":"テーブル本体の書き込みキャパシティをさらに増やす"},{"l":"B","html":"GSIの書き込みキャパシティを増やす"},{"l":"C","html":"DAXを導入する"},{"l":"D","html":"読み込みを強い整合性に変更する"}],"answer":["B"],"multi":false,"req":"","key":"GSIはテーブルとは<b>別に書き込みキャパシティ</b>を持ちます。GSIの書き込みが追いつかないと、その影響で<b>テーブル本体への書き込みもスロットリング</b>されます。テーブル側に余裕があるのにスロットリングされるときは、GSIのキャパシティを疑います。","kw":"GSIの書き込みキャパシティ","reasons":[{"l":"A","html":"ボトルネックはGSI側なので、テーブル本体を増やしても解消しません。"},{"l":"C","html":"DAXは読み取りのキャッシュで、書き込みのスロットリングには効きません。"},{"l":"D","html":"読み込みの設定は書き込みのスロットリングと関係ありません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":11,"topic":"業務データのほぼリアルタイム分析","level":2,"body":["Aurora MySQLの業務データを、Redshiftで<b>数秒〜数分の遅れで</b>分析したいと考えています。現在は夜間のバッチでエクスポートしてロードしており、<b>ETLパイプラインの構築と保守</b>が負担になっています。最も運用負荷の小さい方法はどれですか。"],"options":[{"l":"A","html":"DMSでCDCのタスクを作成し、Redshiftへ継続的に複製する"},{"l":"B","html":"GlueのETLジョブを5分ごとに実行する"},{"l":"C","html":"Auroraのスナップショットを毎時S3にエクスポートし、Redshiftにロードする"},{"l":"D","html":"AuroraとRedshiftのzero-ETL統合を設定する"}],"answer":["D"],"multi":false,"req":"","key":"zero-ETL統合は、Auroraへの書き込みを<b>AWSが管理する仕組みで数秒程度の遅れでRedshiftへ複製</b>します。パイプラインを自分で作る必要がなく、「ETLの保守をなくしたい」「ほぼリアルタイム」という要件に直接応えます。","kw":"zero-ETL統合","reasons":[{"l":"A","html":"実現はできますが、レプリケーションインスタンスやタスクの管理が残り、運用負荷はzero-ETLより大きくなります。"},{"l":"B","html":"ETLジョブの構築と保守という、なくしたい負担そのものが残ります。遅れも5分以上になります。"},{"l":"C","html":"毎時のバッチでは数秒〜数分の遅れという要件を満たせません。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.4 Amazon Redshift</a> ／ <a href=\"#database\" data-go=\"database\">第4章 4.2 Amazon Aurora</a>"},{"n":12,"topic":"商品の全文検索","level":2,"body":["商品データをDynamoDBに保存しています。利用者から「商品名や説明文の<b>一部の語句で検索</b>したい」「<b>表記ゆれ</b>も拾ってほしい」という要望がありました。DynamoDBのデータを正本として使い続けたいと考えています。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"DynamoDBの <code>Scan</code> にフィルター式の <code>contains</code> を付け、商品名に語句を含む項目を探す"},{"l":"B","html":"商品名をソートキーにしたGSIを作成し、<code>begins_with</code> で商品名を検索する"},{"l":"C","html":"OpenSearch Serviceへ同期して検索する"},{"l":"D","html":"DAXを導入してテーブルの前にキャッシュを置き、<code>Scan</code> による検索を高速化する"}],"answer":["C"],"multi":false,"req":"","key":"部分一致・表記ゆれ・関連度順の並べ替えといった<b>全文検索は検索エンジンの役割</b>です。正本はDynamoDBに置いたまま、変更をOpenSearch Serviceへ同期して検索用のインデックスを持たせるのが定番の構成です。","kw":"Amazon OpenSearch Service","reasons":[{"l":"A","html":"<code>Scan</code> はテーブル全体を読むため、遅く高コストです。表記ゆれにも対応できません。"},{"l":"B","html":"ソートキーでできるのは前方一致までで、文中の語句の検索や表記ゆれには対応できません。"},{"l":"D","html":"DAXは項目の読み取りをキャッシュするもので、全文検索の機能は持ちません。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.6 Amazon OpenSearch Service</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":13,"topic":"常時稼働するコンテナのコスト","level":2,"body":["ECS on Fargateで、24時間ほぼ一定の負荷のサービスを動かしています。サーバー管理をしなくてよい現在の運用は維持したいまま、コストを下げたいと考えています。中断は許されません。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"EC2起動タイプに移行し、EC2 Instance Savings Plansを購入する"},{"l":"B","html":"すべてのタスクをFargate Spotで実行する"},{"l":"C","html":"タスクのCPUとメモリを最大にして、タスク数を減らす"},{"l":"D","html":"Compute Savings Plansを購入する"}],"answer":["D"],"multi":false,"req":"","key":"Compute Savings Plansは<b>EC2だけでなくFargateとLambdaにも適用</b>されます。Fargateのままでも、1年または3年のコミットで割引を受けられ、サーバー管理なしの運用も維持できます。","kw":"Compute Savings Plans","reasons":[{"l":"A","html":"EC2起動タイプではインスタンスの管理が必要になり、「サーバー管理をしない運用を維持する」要件に反します。EC2 Instance Savings PlansはFargateには適用されません。"},{"l":"B","html":"Fargate Spotは中断される可能性があり、中断が許されないという要件を満たしません。"},{"l":"C","html":"リソースの過剰な割り当てはかえってコストを増やします。"}],"refs":"<a href=\"#container\" data-go=\"container\">第9章 9.3 AWS Fargate</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":14,"topic":"開発環境のデータベース","level":1,"body":["開発環境のRDS for MySQLが、本番と同じ<b>マルチAZ配置</b>で作られています。開発環境には可用性の要件はなく、障害時は作り直しても問題ありません。最も簡単にコストを下げる方法はどれですか。"],"options":[{"l":"A","html":"リードレプリカを追加する"},{"l":"B","html":"シングルAZ配置に変更する"},{"l":"C","html":"自動バックアップの保持期間を35日にする"},{"l":"D","html":"ストレージをプロビジョンドIOPSに変更する"}],"answer":["B"],"multi":false,"req":"","key":"マルチAZ配置はスタンバイ分のインスタンス料金がかかります。<b>可用性の要件がない環境ではシングルAZで十分</b>で、料金がほぼ半分になります。要件を満たす範囲で最も安い構成を選ぶ、の典型です。","kw":"シングルAZ配置","reasons":[{"l":"A","html":"インスタンスが増え、コストが上がります。"},{"l":"C","html":"保持期間を延ばすとバックアップの保存料金が増える可能性があり、コストは下がりません。"},{"l":"D","html":"プロビジョンドIOPSは性能を上げるための選択肢で、コストは上がります。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.4 データベースのコスト最適化</a>"},{"n":15,"topic":"配信のデータ転送コスト","level":2,"body":["EC2上のWebサーバーが、画像やJavaScriptなどの<b>静的ファイル</b>も直接配信しており、インターネットへのデータ転送料金とEC2の負荷が高くなっています。利用者は世界中にいます。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"静的ファイルをS3に置き、CloudFront（OAC）経由で配信する"},{"l":"B","html":"EC2のインスタンスタイプを大きくする"},{"l":"C","html":"EC2に割り当てるElastic IPアドレスを増やす"},{"l":"D","html":"Global Acceleratorを導入する"},{"l":"E","html":"CloudFrontの圧縮を有効にする"}],"answer":["A","E"],"multi":true,"req":"","key":"静的ファイルをS3＋CloudFrontへ移すと、<b>エッジのキャッシュから配信される分だけEC2の負荷とオリジンからの転送が減ります</b>（S3からCloudFrontへの転送は無料です）。さらにCloudFrontで圧縮を有効にすれば、利用者へ送るバイト数そのものが減ります。","kw":"CloudFront（OAC）／CloudFrontの圧縮","reasons":[{"l":"B","html":"負荷には対応できても、転送料金は減らず、インスタンスの料金は上がります。"},{"l":"C","html":"IPアドレスを増やしても転送量や負荷は変わりません。パブリックIPv4アドレスには料金もかかります。"},{"l":"D","html":"Global Acceleratorはキャッシュを持たず、経路の最適化に追加料金がかかります。転送量は減りません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 コンテンツ配信と高速化</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"}]},{"id":"exam-set-21","file":"set-21.md","num":"問題セット21","title":"実戦演習④（本番の分野比率・15問）","questions":[{"n":1,"topic":"他アカウントからのアップロード","level":2,"body":["取引先の複数のAWSアカウントから、自社のS3バケットへファイルがアップロードされます。アップロードされたオブジェクトの所有者がアップロード元のアカウントになるため、<b>自社のアカウントから一部のオブジェクトを読めない・管理できない</b>問題が起きています。最も適切な対処はどれですか。"],"options":[{"l":"A","html":"取引先に、アップロードのたびに <code>bucket-owner-full-control</code> のACLを付けてもらうよう依頼する"},{"l":"B","html":"取引先ごとに別のバケットを用意し、それぞれに権限を付ける"},{"l":"C","html":"オブジェクト所有権を「バケット所有者の強制」にする"},{"l":"D","html":"バケットのバージョニングを有効にする"}],"answer":["C"],"multi":false,"req":"","key":"「バケット所有者の強制」を設定すると<b>ACLが無効になり、バケット内のすべてのオブジェクトの所有者がバケット所有者になります</b>。誰がアップロードしても自社のアカウントで管理でき、アクセス制御はバケットポリシーとIAMに一本化されます。現在のAWSが推奨する設定です。","kw":"オブジェクト所有権（バケット所有者の強制）","reasons":[{"l":"A","html":"取引先の設定漏れがあれば同じ問題が起きます。相手任せの運用で、ACLの管理も残ります。"},{"l":"B","html":"バケットが増えるだけで、所有者の問題は解決しません。"},{"l":"D","html":"バージョニングはオブジェクトの世代管理で、所有者とは関係ありません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":2,"topic":"持ち出しの防止","level":3,"body":["プライベートサブネットのEC2は、S3用のゲートウェイ型VPCエンドポイント経由でS3にアクセスしています。セキュリティ部門は、侵害されたインスタンスが<b>自社の組織外のS3バケットへデータを書き出す</b>ことを防ぎたいと考えています。最も適切な対策はどれですか。"],"options":[{"l":"A","html":"セキュリティグループのアウトバウンドで、S3のプレフィックスリストを許可する"},{"l":"B","html":"自社のバケットのバケットポリシーで、<code>aws:SourceVpce</code> が自社のエンドポイント以外からのアクセスを拒否する"},{"l":"C","html":"NAT Gatewayを削除する"},{"l":"D","html":"VPCエンドポイントポリシーで、<code>aws:ResourceOrgID</code> が自社の組織のリソースだけを許可する"}],"answer":["D"],"multi":false,"req":"","key":"守りたいのは「<b>VPCから外へ</b>」の方向です。エンドポイントポリシーは、そのエンドポイントを通るリクエストが<b>どのリソースに届いてよいか</b>を制限できます。<code>aws:ResourceOrgID</code> を条件にすれば、自社の組織が所有するバケット以外への読み書きはエンドポイントで止まります。","kw":"VPCエンドポイントポリシー／aws:ResourceOrgID","reasons":[{"l":"A","html":"プレフィックスリストはS3全体のIPアドレス範囲なので、組織外のバケットへの通信も許可されてしまいます。"},{"l":"B","html":"自社のバケットへの入り口を絞る対策で、<b>他社のバケット</b>への書き出しは防げません。"},{"l":"C","html":"エンドポイント経由の通信には影響しません（S3への経路はエンドポイントのまま残ります）。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.5 設計ケーススタディ：機密データへの安全な内部アクセス</a>"},{"n":3,"topic":"ロールの受け渡しの制限","level":2,"body":["開発者は、自分のアプリケーション用のEC2インスタンスを起動する権限を持っています。しかし、起動時に<b>管理者権限を持つIAMロール</b>をインスタンスに付ければ、そのインスタンス経由で管理者の操作ができてしまうことがわかりました。開発者が付けられるロールを、アプリ用の特定のロールに限定したいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"EC2の起動権限を開発者から取り上げる"},{"l":"B","html":"管理者ロールの信頼ポリシーから、EC2サービスをプリンシパルとして削除する"},{"l":"C","html":"開発者の <code>iam:PassRole</code> をアプリ用ロールのARNだけに限定する"},{"l":"D","html":"開発者のIAMユーザーにMFAを必須にする"}],"answer":["C"],"multi":false,"req":"","key":"サービスにロールを渡す操作には <code>iam:PassRole</code> の権限が必要です。これを<b>許可するロールのARNで絞る</b>（必要なら <code>iam:PassedToService</code> でEC2に限定する）ことで、開発者は許可されたロールしかインスタンスに付けられなくなります。権限昇格を防ぐ定番の対策です。","kw":"iam:PassRole","reasons":[{"l":"A","html":"業務に必要な権限まで奪ってしまいます。"},{"l":"B","html":"管理者ロールをEC2で使う正当な用途まで止めてしまいます。ほかにも権限の強いロールがあれば、同じ問題が残ります。"},{"l":"D","html":"MFAは本人確認の強化で、渡せるロールの範囲は変わりません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":4,"topic":"利用者アカウントの乗っ取り対策","level":2,"body":["Cognitoユーザープールで会員サイトのログインを提供しています。ほかのサイトから漏えいしたパスワードを使った<b>不正ログイン</b>が疑われています。すべての利用者に毎回MFAを求めるのは避け、<b>リスクが高いと判断されたログインだけ追加の確認を求めたい</b>と考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"パスワードの最小文字数を20文字にし、記号を必須にする"},{"l":"B","html":"Cognitoの脅威保護（適応型認証）を有効にする"},{"l":"C","html":"AWS WAFをAPIの前段に置き、ログインAPIへのリクエストをすべて拒否する"},{"l":"D","html":"利用者ごとにIAMユーザーを発行する"}],"answer":["B"],"multi":false,"req":"","key":"Cognitoの脅威保護は、<b>漏えいが知られている認証情報の使用を検出</b>し、ログインのたびにリスクを評価して、<b>リスクが高いときだけMFAを求める・ブロックする</b>（適応型認証）ことができます。利用者の負担を増やさずに乗っ取りを防ぐ要件に直接対応します（脅威保護は旧称「高度なセキュリティ機能」）。","kw":"Cognitoの脅威保護（旧・高度なセキュリティ機能）","reasons":[{"l":"A","html":"既存の利用者には効かず、漏えいしたパスワードの使い回しも防げません。"},{"l":"C","html":"正規の利用者もログインできなくなります（レート制限なら補助にはなりますが、要件の「リスクに応じた追加確認」は実現できません）。"},{"l":"D","html":"一般の利用者をIAMで管理するのは用途が違い、現実的ではありません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.4 Amazon Cognito</a>"},{"n":5,"topic":"ランサムウェアへの備え","level":3,"body":["重要な業務データをS3に保存しています。<b>管理者の認証情報が盗まれた場合でも</b>、一定期間はデータを削除・上書きできず、別の場所からも復旧できるようにしたいと考えています。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"ライフサイクルルールでS3 Glacier Deep Archiveへ移行する"},{"l":"B","html":"SSE-KMSで暗号化する"},{"l":"C","html":"S3のバージョニングを有効にし、オブジェクトロックをコンプライアンスモードで設定する"},{"l":"D","html":"アクセス権限を厳しく分けた別のAWSアカウントのバケットへレプリケーションする"},{"l":"E","html":"S3 Intelligent-Tieringを使う"}],"answer":["C","D"],"multi":true,"req":"","key":"コンプライアンスモードのオブジェクトロックは、<b>ルートユーザーを含む誰であっても</b>保持期間中の削除や上書きができません。さらに、権限を分離した<b>別アカウント</b>へ複製しておけば、元のアカウントが丸ごと乗っ取られても復旧元が残ります。","kw":"オブジェクトロック（コンプライアンスモード）／別アカウントへのレプリケーション","reasons":[{"l":"A","html":"保存場所が変わるだけで、削除は防げません。"},{"l":"B","html":"暗号化は盗み見への対策で、権限を持つ者による削除や上書きは防げません。"},{"l":"E","html":"ストレージクラスの自動最適化で、データ保護の機能ではありません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":6,"topic":"定期実行","level":1,"body":["<b>5分ごと</b>に外部APIから為替レートを取得してDynamoDBへ保存する処理を作ります。サーバーの管理はしたくありません。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"EC2でcronを設定して処理を実行する"},{"l":"B","html":"EventBridge Schedulerで5分ごとにLambda関数を起動する"},{"l":"C","html":"SQSの遅延キューに5分遅延のメッセージを送り続ける"},{"l":"D","html":"Step FunctionsのWaitステートで5分待ち、処理を呼び出す流れを無限に繰り返す"}],"answer":["B"],"multi":false,"req":"","key":"<b>定期実行はEventBridgeのスケジュール</b>で起動するのがサーバーレスの定番です。rate式やcron式で間隔を指定し、Lambdaを直接起動できます。","kw":"EventBridge Scheduler","reasons":[{"l":"A","html":"サーバーの管理が必要で、要件に反します。"},{"l":"C","html":"仕組みが複雑で、メッセージの送り忘れがあると処理が止まります。"},{"l":"D","html":"実行が長く続くほどステートの遷移が積み上がり、実行時間の上限にも達します。定期実行の用途に合いません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.3 Amazon EventBridge</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.4 イベント駆動型アーキテクチャ</a>"},{"n":7,"topic":"大きなメッセージの受け渡し","level":2,"body":["画像処理パイプラインで、SQSを使って処理の依頼を受け渡しています。依頼には<b>最大50MBの画像データ</b>を含める必要がありますが、SQSのメッセージサイズの上限を超えてしまいます。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"画像はS3に置き、メッセージにはオブジェクトキーだけを入れる"},{"l":"B","html":"画像を256KB以下に分割し、複数のメッセージに分けて送る"},{"l":"C","html":"Kinesis Data Streamsに切り替え、画像をレコードとして送る"},{"l":"D","html":"SNSトピックに切り替える"}],"answer":["A"],"multi":false,"req":"","key":"大きなデータは<b>S3に置き、メッセージには参照だけを入れる</b>のが定石です（クレームチェックパターン）。SQS拡張クライアントライブラリを使えば、上限を超える本文を自動でS3に保存し、受信時に取り出せます。","kw":"SQS拡張クライアントライブラリ（クレームチェック）","reasons":[{"l":"B","html":"分割したメッセージは順序どおり・同じコンシューマーに届く保証がなく、組み立ての処理も複雑になります。"},{"l":"C","html":"Kinesisのレコードにもサイズの上限があり、キューとしての受け渡しの仕組みも異なります。"},{"l":"D","html":"SNSのメッセージにもサイズの上限があり、問題は解決しません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a> ／ <a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a>"},{"n":8,"topic":"計画的なリージョン切り替え","level":2,"body":["Auroraグローバルデータベースを、東京をプライマリ、大阪をセカンダリとして運用しています。災害対策の訓練として、<b>データを失わずに</b>プライマリを大阪へ切り替え、訓練後に元へ戻したいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"大阪のクラスターをグローバルデータベースから切り離し、独立したクラスターとして昇格させる"},{"l":"B","html":"東京のクラスターを削除する"},{"l":"C","html":"大阪にリードレプリカを追加する"},{"l":"D","html":"グローバルデータベースのスイッチオーバー（計画的な切り替え）を実行する"}],"answer":["D"],"multi":false,"req":"","key":"スイッチオーバーは<b>プライマリとセカンダリの同期を待ってから役割を入れ替える</b>ため、データを失いません（RPOはゼロ）。グローバルデータベースの構成もそのまま保たれるので、訓練後に同じ操作で元に戻せます。障害時に使うフェイルオーバーとの違いが問われます。","kw":"スイッチオーバー","reasons":[{"l":"A","html":"切り離しは非常時の手段で、未反映のデータを失う可能性があり、グローバルデータベースの構成も崩れます。元に戻すには作り直しが必要です。"},{"l":"B","html":"本番のデータを失います。"},{"l":"C","html":"レプリカを追加しても、プライマリは切り替わりません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.2 Amazon Aurora</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":9,"topic":"複数リージョンの振り分けと障害時の除外","level":2,"body":["東京とバージニア北部の2つのリージョンで、同じWebアプリケーションをアクティブ・アクティブで動かしています。利用者を<b>遅延の小さいほうのリージョンへ振り分け</b>、一方のリージョンが停止したときは<b>自動的にもう一方だけへ振り分けたい</b>と考えています。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"Route 53の加重ルーティングで50%ずつ振り分ける"},{"l":"B","html":"Route 53のレイテンシーベースルーティングにヘルスチェックを組み合わせる"},{"l":"C","html":"Route 53のシンプルルーティングで、両方のALBを1つのレコードに登録する"},{"l":"D","html":"Route 53の位置情報ルーティングで、日本からは東京、それ以外はバージニア北部へ振り分ける"}],"answer":["B"],"multi":false,"req":"","key":"レイテンシーベースルーティングは利用者から<b>遅延の小さいリージョン</b>を返し、ヘルスチェックで異常と判定されたレコードは回答から外されます。遅延による振り分けと障害時の自動切り替えを1つの仕組みで満たせます。","kw":"レイテンシーベースルーティング／ヘルスチェック","reasons":[{"l":"A","html":"遅延の大小に関係なく振り分けるため、1つ目の要件を満たしません。"},{"l":"C","html":"シンプルルーティングはヘルスチェックに対応しておらず、障害時の除外ができません。"},{"l":"D","html":"地域で固定的に振り分けるだけで、遅延の大小に基づく振り分けにはなりません。ヘルスチェックの記述もありません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.4 名前解決：Route 53 と Resolver</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":10,"topic":"関数で使う大きなファイル","level":2,"body":["Lambda関数で、<b>数GBの機械学習モデルファイル</b>を読み込んで推論しています。モデルは<b>週に数回更新</b>され、そのたびに関数を作り直したり再デプロイしたりするのは避けたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"モデルをEFSに置いてマウントする"},{"l":"B","html":"モデルを関数の環境変数に格納する"},{"l":"C","html":"モデルをデプロイパッケージ（ZIP）に含め、更新時に再デプロイする"},{"l":"D","html":"モデルを <code>/tmp</code> に保存したまま関数を使い続ける"}],"answer":["A"],"multi":false,"req":"","key":"LambdaはVPC経由でEFSを<b>ファイルシステムとしてマウント</b>できます。大きなファイルを関数の外に置き、EFS上のファイルを差し替えるだけで次の実行から新しいモデルが使えるため、関数の再デプロイが不要です。","kw":"LambdaのEFSマウント","reasons":[{"l":"B","html":"環境変数の容量はごく小さく、ファイルを格納する場所ではありません。"},{"l":"C","html":"ZIPのデプロイパッケージは展開後250MBが上限で、数GBのモデルは入りません。更新のたびに再デプロイも必要です。"},{"l":"D","html":"<code>/tmp</code> は実行環境ごとの一時領域で、新しい実行環境では空になります。更新の配布手段にもなりません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.6 AWS Lambda</a> ／ <a href=\"#storage\" data-go=\"storage\">第2章 2.3 Amazon EFS</a>"},{"n":11,"topic":"顧客へのサービス提供","level":3,"body":["SaaS事業者として、自社のVPCで動くAPIを<b>数百の顧客のVPC</b>へ非公開で提供したいと考えています。顧客のVPCのCIDRは自社と<b>重複しているもの</b>が多く、顧客に自社のネットワーク全体を見せることも避けたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"APIをPrivateLinkで公開し、顧客はインターフェースVPCエンドポイントで接続する"},{"l":"B","html":"Transit Gatewayを作成し、全顧客のVPCをアタッチして相互にルーティングする"},{"l":"C","html":"APIをインターネットに公開し、セキュリティグループとWAFで顧客のIPアドレスだけを許可する"},{"l":"D","html":"各顧客のVPCとVPCピアリングを結ぶ"}],"answer":["A"],"multi":false,"req":"","key":"PrivateLinkでは、顧客は<b>自分のVPC内のエンドポイント（自分のCIDRのIPアドレス）</b>に接続するだけなので、<b>CIDRが重複していても</b>問題ありません。公開されるのは特定のサービスだけで、自社のVPC全体は見えません。数百の顧客にも同じ方法で提供できます。サービス側はAPIを<b>NLBの背後</b>に置き、VPCエンドポイントサービスとして公開します。","kw":"AWS PrivateLink（VPCエンドポイントサービス）","reasons":[{"l":"B","html":"CIDRの重複はルーティングで衝突します。顧客同士のネットワークを分離する設計も複雑になります。"},{"l":"C","html":"非公開で提供するという要件に反します。"},{"l":"D","html":"CIDRが重複しているVPC同士はピアリングできず、数百の接続の管理も現実的ではありません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続</a>"},{"n":12,"topic":"届いたファイルをすぐに分析","level":1,"body":["取引先から毎日、S3にCSVファイルが届きます。列の構成はときどき変わります。アナリストは、届いたデータに<b>すぐSQLでクエリしたい</b>と考えています。サーバーは管理したくありません。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"EC2にデータベースをインストールし、CSVを取り込む"},{"l":"B","html":"Redshiftクラスターを構築し、毎日CSVを手作業で <code>COPY</code> してロードする"},{"l":"C","html":"Glueクローラー＋Athenaでクエリする"},{"l":"D","html":"CSVをDynamoDBに取り込み、Scanで検索する"}],"answer":["C"],"multi":false,"req":"","key":"Glueクローラーは<b>スキーマを自動で推定し、列の変化も検出して</b>データカタログを更新します。Athenaはそのカタログを使ってS3上のデータに直接SQLを実行できます。どちらもサーバーレスです。","kw":"Glueクローラー／Amazon Athena","reasons":[{"l":"A","html":"サーバーの管理が必要です。"},{"l":"B","html":"クラスターの管理と手作業のロードが必要で、要件に反します。"},{"l":"D","html":"DynamoDBはアドホックなSQL分析に向かず、Scanは高コストです。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.2 AWS Glue</a> ／ <a href=\"#analytics\" data-go=\"analytics\">第7章 7.3 Amazon Athena</a>"},{"n":13,"topic":"アーカイブの取り出しコスト","level":2,"body":["S3 Glacier Flexible Retrievalに保存している<b>過去5年分・数百TB</b>のデータを、新しい分析基盤へ移すために取り出します。移行の期限は<b>2週間後</b>で、急ぎではありません。取り出しのコストを最小にしたいと考えています。最も適切な取り出しオプションはどれですか。"],"options":[{"l":"A","html":"大容量（Bulk）取り出し"},{"l":"B","html":"標準（Standard）取り出し"},{"l":"C","html":"迅速（Expedited）取り出し"},{"l":"D","html":"プロビジョニングされた取り出し容量を購入して迅速取り出しを行う"}],"answer":["A"],"multi":false,"req":"","key":"大容量取り出しは<b>数時間（目安5〜12時間）かかる代わりに最も安価</b>なオプションで、大量のデータを急がずに取り出す用途向けです。期限まで2週間あるなら十分に間に合います。","kw":"大容量（Bulk）取り出し","reasons":[{"l":"B","html":"大容量取り出しより高くなります。急ぎでないなら大容量で十分です。"},{"l":"C","html":"数分で取り出せる代わりに最も高価です。急ぎでない大量の取り出しには向きません。"},{"l":"D","html":"迅速取り出しの容量を確保するための追加料金で、コストはさらに上がります。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":14,"topic":"ときどき使うデータウェアハウス","level":2,"body":["社内のBIダッシュボード用に、Redshiftのプロビジョンドクラスターを24時間稼働させています。実際にクエリが実行されるのは<b>平日の日中の数時間だけ</b>で、利用量も日によって大きく変わります。管理の手間を増やさずにコストを下げたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"3年のリザーブドノードを購入する"},{"l":"B","html":"データをすべてDynamoDBに移す"},{"l":"C","html":"ノード数を2倍にしてクエリを速く終わらせ、稼働時間を短くする"},{"l":"D","html":"Redshift Serverlessに移行する"}],"answer":["D"],"multi":false,"req":"","key":"Redshift Serverlessは<b>クエリを実行している間の処理量（RPU）に対して課金</b>され、使わない時間のコンピューティング料金はかかりません。容量も負荷に合わせて自動で調整されるため、利用が断続的で変動も大きいワークロードに向いています。","kw":"Redshift Serverless","reasons":[{"l":"A","html":"24時間の稼働を前提にした割引で、実際に使うのは一部の時間だけなので無駄が大きくなります。"},{"l":"B","html":"DynamoDBは分析用のデータウェアハウスではなく、BIの集計には向きません。"},{"l":"C","html":"ノードを増やせば常時の料金が増えます。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.4 Amazon Redshift</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.4 データベースのコスト最適化</a>"},{"n":15,"topic":"ログのコスト","level":2,"body":["CloudWatch Logsの料金が増えています。調べると、(1) すべてのロググループの保持期間が<b>無期限</b>のまま、(2) 監査のためだけに保存し、<b>ほとんど検索しない大量のログ</b>がある、ことがわかりました。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"EC2の詳細モニタリングを有効にし、ログの量を把握する"},{"l":"B","html":"各ロググループに、要件に合わせた保持期間を設定する"},{"l":"C","html":"ほとんど参照しないログは、低頻度アクセスログクラスに送る"},{"l":"D","html":"カスタムメトリクスを高解像度（1秒）にし、ログを減らす"},{"l":"E","html":"すべてのログにメトリクスフィルタを追加する"}],"answer":["B","C"],"multi":true,"req":"","key":"(1) には<b>保持期間の設定</b>（不要になったログを自動で削除）、(2) には<b>低頻度アクセスログクラス</b>（取り込み料金が安い代わりに、メトリクスフィルタなど一部の機能が使えない）が対応します。長期保管が必要なものはS3へエクスポートする方法もあります。","kw":"ロググループの保持期間／低頻度アクセス（Infrequent Access）ログクラス","reasons":[{"l":"A","html":"詳細モニタリングはメトリクスの頻度を上げる追加料金の機能で、ログの料金は減りません。"},{"l":"D","html":"高解像度メトリクスは料金が増えます。"},{"l":"E","html":"メトリクスフィルタはログから数値を作る機能で、ログの料金は減りません。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.1 Amazon CloudWatch</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"}]},{"id":"exam-set-22","file":"set-22.md","num":"問題セット22","title":"総合 2周目（本番の分野比率に合わせた混合セット）","questions":[{"n":1,"topic":"暗号鍵とDR","level":2,"body":["アプリケーションが、東京リージョンのKMSキーを使って<b>クライアント側でデータを暗号化</b>し、暗号化したデータを大阪リージョンにも複製しています。東京リージョンが停止したときでも、<b>大阪リージョンだけで復号</b>できるようにしたいと考えています。暗号化したデータを作り直すことは避けたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"大阪リージョンで新しいKMSキーを作成し、障害時にそのキーで復号する"},{"l":"B","html":"KMSキーのキーポリシーで、大阪リージョンのロールに <code>kms:Decrypt</code> を許可する"},{"l":"C","html":"マルチリージョンキーを使い、大阪リージョンにレプリカキーを作成する"},{"l":"D","html":"データキーを平文のままS3に保存しておく"}],"answer":["C"],"multi":false,"req":"","key":"KMSキーは<b>リージョンごとのリソース</b>で、別のリージョンのキーでは復号できません。マルチリージョンキーは<b>同じキーIDと鍵素材</b>を複数のリージョンに持てるため、東京で暗号化したデータを大阪のレプリカキーだけで復号できます。","kw":"マルチリージョンキー","reasons":[{"l":"A","html":"別の鍵素材を持つ新しいキーでは、既存のデータを復号できません。"},{"l":"B","html":"権限を与えても、東京のキーを使うには東京のKMSを呼び出す必要があり、東京が停止すると復号できません。"},{"l":"D","html":"データキーを平文で保存すると、暗号化の意味がなくなります。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.8 AWS KMS</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":2,"topic":"監査ログの完全性","level":2,"body":["監査法人から、「CloudTrailのログファイルが、<b>配信された後に改ざんや削除をされていないことを証明</b>できること」を求められました。最も適切な対策はどれですか。"],"options":[{"l":"A","html":"ログを保存するS3バケットでSSE-KMSを有効にする"},{"l":"B","html":"ログファイルの整合性検証を有効にする"},{"l":"C","html":"CloudTrailのログをCloudWatch Logsにも送る"},{"l":"D","html":"S3バケットのバージョニングを有効にする"}],"answer":["B"],"multi":false,"req":"","key":"ログファイルの整合性検証を有効にすると、CloudTrailは各ログファイルのハッシュを記録し、署名付きの<b>ダイジェストファイル</b>を1時間ごとに配信します。これを使えば、ログが変更・削除・追加されていないことを後から検証できます。「改ざんされていないことの<b>証明</b>」が決め手です。","kw":"ログファイルの整合性検証","reasons":[{"l":"A","html":"暗号化は内容の秘匿で、改ざんの有無は証明できません。"},{"l":"C","html":"別の場所に送っても、元のログファイルが改ざんされていないことの証明にはなりません。"},{"l":"D","html":"変更前のバージョンは残りますが、改ざんがなかったことを証明する仕組みではありません（削除や改ざんの防止にはオブジェクトロックを組み合わせます）。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.2 AWS CloudTrail</a>"},{"n":3,"topic":"イベント通知の権限","level":2,"body":["S3バケットにオブジェクトが作成されたら、SQSキューへイベント通知を送る設定を追加しようとしましたが、「送信先を検証できない」というエラーで保存できません。キューはSSEを使わない標準キューです。最も適切な対処はどれですか。"],"options":[{"l":"A","html":"S3バケットのバケットポリシーで、SQSに <code>s3:GetObject</code> を許可する"},{"l":"B","html":"S3バケットにIAMロールを割り当て、そのロールに <code>sqs:SendMessage</code> を許可する"},{"l":"C","html":"SQSキューをFIFOキューに変更する"},{"l":"D","html":"SQSのアクセスポリシーで、S3に <code>sqs:SendMessage</code> を許可する"}],"answer":["D"],"multi":false,"req":"","key":"S3がキューへメッセージを送るには、<b>送信先のキュー側（リソースベースポリシー）でS3サービスからの送信を許可</b>する必要があります。<code>aws:SourceArn</code>（と <code>aws:SourceAccount</code>）で対象のバケットに限定するのが定石です。SNSトピックやLambda関数を送信先にするときも、同じく送信先側のポリシーで許可します。","kw":"SQSのアクセスポリシー（リソースベースポリシー）","reasons":[{"l":"A","html":"バケットポリシーはバケットへのアクセスを制御するもので、S3からキューへの送信の許可にはなりません。"},{"l":"B","html":"S3のイベント通知は、バケットにIAMロールを割り当てて送る仕組みではありません。"},{"l":"C","html":"S3のイベント通知の送信先には標準キューを使います。FIFOにしても権限の問題は解決しません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a> ／ <a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a>"},{"n":4,"topic":"バックグラウンド処理の分離","level":2,"body":["Elastic Beanstalkで動かしているWebアプリケーションが、リクエストの処理中に<b>PDFのレポート生成</b>（数十秒かかる）を行っており、応答が遅くなっています。Beanstalkの運用の仕組みはそのまま使いたいと考えています。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"Webサーバー環境はキューへ依頼を送るだけにし、ワーカー環境で生成する"},{"l":"B","html":"レポート生成を同じインスタンス上の別スレッドで行い、応答を先に返す"},{"l":"C","html":"レポート生成をLambda関数に移し、Webサーバーから同期で呼び出す"},{"l":"D","html":"Webサーバー環境のインスタンス数を2倍にし、負荷を分散させる"}],"answer":["A"],"multi":false,"req":"","key":"Beanstalkの<b>ワーカー環境</b>は、SQSキューのメッセージを自動で取り出してアプリケーションに渡す仕組みを備えています。Webサーバー環境は依頼をキューに入れてすぐに応答し、重い処理はワーカー環境が別にスケールしながら処理します。Beanstalkの運用のまま、受付と処理を切り離せます。","kw":"Elastic Beanstalkのワーカー環境","reasons":[{"l":"B","html":"同じインスタンスの資源を奪い合い、インスタンスが入れ替わると処理中の生成が失われます。"},{"l":"C","html":"同期で呼び出す限り、応答の遅さは変わりません。"},{"l":"D","html":"1件ごとの応答の遅さは変わらず、コストだけが増えます。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.3 AWS Elastic Beanstalk</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.2 疎結合アーキテクチャ</a>"},{"n":5,"topic":"S3のイベントを複数の処理へ","level":3,"body":["S3バケットの <code>uploads/</code> に置かれたファイルについて、(1) 画像ならサムネイル生成、(2) すべてのファイルでウイルススキャン、(3) CSVなら取り込み処理、の3つを起動したいと考えています。S3のイベント通知で設定しようとしたところ、<b>同じイベントタイプでプレフィックスが重なる</b>ため設定できませんでした。処理を追加しやすい構成にしたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"バケットを3つに分け、アップロード先を処理ごとに変えてもらう"},{"l":"B","html":"EventBridge通知を有効にし、ルールで各処理を振り分ける"},{"l":"C","html":"1つのLambda関数でイベントを受け、関数の中で3つの処理を順番に実行する"},{"l":"D","html":"3つの処理を5分ごとのバッチにし、新しいファイルを探して処理する"}],"answer":["B"],"multi":false,"req":"","key":"S3のイベント通知は、同じイベントタイプで<b>プレフィックスやサフィックスが重なる複数の送信先</b>を設定できません。EventBridge通知を有効にすれば、すべてのイベントがEventBridgeへ送られ、<b>ルールごとにキーの接頭辞・接尾辞などで絞り込んで</b>それぞれの処理を起動できます。処理の追加もルールを足すだけです。","kw":"S3のEventBridge通知","reasons":[{"l":"A","html":"利用者の運用を変える必要があり、すべてのファイルに行うウイルススキャンとも両立しません。"},{"l":"C","html":"処理同士が結合し、1つの失敗や遅れがほかに波及します。処理を足すたびに関数の改修も必要です。"},{"l":"D","html":"即時の処理ではなくなり、新しいファイルを探す仕組みも自前で作ることになります。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.3 Amazon EventBridge</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.4 イベント駆動型アーキテクチャ</a>"},{"n":6,"topic":"予測できないストリーム","level":2,"body":["新サービスのイベントをKinesis Data Streamsで受けます。リリース直後のトラフィックは<b>まったく予測できず</b>、日によって10倍以上変動する見込みです。シャード数の見積もりや調整の運用はしたくありません。最も適切な設定はどれですか。"],"options":[{"l":"A","html":"プロビジョンドモードで、想定の最大値に合わせたシャード数を用意する"},{"l":"B","html":"プロビジョンドモードで、CloudWatchアラームを見て手動でシャードを分割する"},{"l":"C","html":"Kinesis Data Streamsの代わりにSQSを使う"},{"l":"D","html":"オンデマンドモードを使う"}],"answer":["D"],"multi":false,"req":"","key":"オンデマンドモードは、<b>書き込み量に合わせて容量が自動で調整</b>され、シャード数を管理する必要がありません。料金は実際の流量に応じて決まるため、予測できないトラフィックに向いています。","kw":"Kinesis Data Streamsのオンデマンドモード","reasons":[{"l":"A","html":"最大値に合わせると、普段は大半のシャードが遊んでコストが無駄になります。見積もりを外すと不足します。"},{"l":"B","html":"シャードの調整を手作業で行う運用になり、要件に反します。"},{"l":"C","html":"SQSはストリームの再読み込みや複数のコンシューマーによる並行読み取りができず、Kinesisを選んだ要件が失われます。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.1 Amazon Kinesis</a>"},{"n":7,"topic":"データベースのストレージ","level":2,"body":["EC2上に自社で運用しているデータベースは、<b>常に一定で非常に低いレイテンシ</b>と<b>高いIOPS</b>を必要とし、ストレージの<b>耐久性も最高水準</b>が求められています。どのEBSボリュームタイプが最も適していますか。"],"options":[{"l":"A","html":"io2 Block Express"},{"l":"B","html":"gp3"},{"l":"C","html":"st1"},{"l":"D","html":"sc1"}],"answer":["A"],"multi":false,"req":"","key":"io2 Block Expressは<b>1ミリ秒未満のレイテンシ</b>と非常に高いIOPS・スループットを提供し、耐久性も99.999%と、EBSで最も高い水準です。性能と耐久性の両方が最重要の基幹データベース向けです。","kw":"io2 Block Express","reasons":[{"l":"B","html":"gp3は汎用のSSDで、多くのワークロードには十分ですが、一定の極めて低いレイテンシと最高水準の耐久性を求める要件では io2 に劣ります。"},{"l":"C","html":"st1はスループット重視のHDDで、ランダムI/O中心のデータベースには向きません。"},{"l":"D","html":"sc1はアクセスの少ないデータ向けの最も安いHDDで、性能要件を満たしません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.2 Amazon EBS</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":8,"topic":"大きなオブジェクトのダウンロード","level":2,"body":["EC2上の解析アプリケーションが、同じリージョンのS3から<b>1つあたり数十GBのオブジェクト</b>を1つずつダウンロードしており、取得に時間がかかっています。インスタンスのネットワーク帯域にはまだ余裕があります。最も効果的な改善策はどれですか。"],"options":[{"l":"A","html":"Rangeヘッダーでバイト範囲を分けて並列にGETする"},{"l":"B","html":"オブジェクトをS3 Glacier Instant Retrievalに移す"},{"l":"C","html":"CloudFrontを経由してダウンロードする"},{"l":"D","html":"S3 Transfer Accelerationを有効にする"}],"answer":["A"],"multi":false,"req":"","key":"1つの接続で順に取得するのではなく、<b>バイト範囲を指定した複数のGETを並列に実行</b>すると、帯域を使い切って取得時間を短くできます。アップロードのマルチパートに対応する、ダウンロード側の定石です。","kw":"バイト範囲指定のGET（Range）","reasons":[{"l":"B","html":"ストレージクラスを変えても取得速度は上がらず、取り出し料金がかかります。"},{"l":"C","html":"同じリージョンの1台が一度ずつ読む用途では、キャッシュの効果がなく、経路が増えるだけです。"},{"l":"D","html":"Transfer Accelerationは遠距離からの転送を速める機能で、同じリージョン内の取得には効果がなく、追加料金がかかります。"}],"refs":"<a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a> ／ <a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a>"},{"n":9,"topic":"ほとんど読まれないテーブル","level":2,"body":["DynamoDBに、<b>数年分の注文履歴</b>を保存したテーブルがあります。データ量は数TBあり、費用の大部分は<b>ストレージ料金</b>です。読み書きはごくまれですが、必要なときはすぐに参照できなければなりません。アプリケーションは変えたくありません。最も適切な対策はどれですか。"],"options":[{"l":"A","html":"DAXを導入する"},{"l":"B","html":"オンデマンドモードからプロビジョンドモードに変更する"},{"l":"C","html":"テーブルクラスをStandard-IAに変更する"},{"l":"D","html":"テーブルをグローバルテーブルに変更し、複数リージョンに分散する"}],"answer":["C"],"multi":false,"req":"","key":"Standard-IAテーブルクラスは、<b>ストレージ料金が大幅に安い代わりに読み書きの料金が高い</b>クラスです。ストレージが費用の大部分を占め、アクセスがまれなテーブルに向いています。テーブルクラスの変更だけで済み、アプリケーションやアクセス方法は変わりません。","kw":"DynamoDB Standard-IAテーブルクラス","reasons":[{"l":"A","html":"DAXはキャッシュの追加で、コストが増えます。"},{"l":"B","html":"キャパシティモードは読み書きの課金方式で、ストレージ料金は下がりません。"},{"l":"D","html":"レプリカの分だけストレージ料金が増えます。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.4 データベースのコスト最適化</a>"},{"n":10,"topic":"ビッグデータ処理のコスト","level":2,"body":["毎晩、EMRクラスターでSparkのバッチ処理を実行しています。処理を急ぐときは計算ノードを増やしますが、コストが問題になっています。<b>HDFSのデータが失われると処理をやり直す必要がある</b>ため、データの保持は安定させたいと考えています。最もコスト効率の良い構成はどれですか。"],"options":[{"l":"A","html":"すべてのノードをスポットインスタンスにする"},{"l":"B","html":"プライマリとコアはオンデマンド、タスクノードだけをスポットにする"},{"l":"C","html":"すべてのノードをオンデマンドにし、ノード数を固定して安定させる"},{"l":"D","html":"タスクノードをオンデマンド、コアノードをスポットインスタンスにする"}],"answer":["B"],"multi":false,"req":"","key":"EMRでは、<b>HDFSのデータを持つのはコアノード</b>、タスクノードは<b>計算だけ</b>を担います。データを持つノードは中断されないオンデマンドで安定させ、中断されても再計算で済むタスクノードをスポットにして増減させるのが定石です。","kw":"EMRのタスクノード／スポットインスタンス","reasons":[{"l":"A","html":"コアノードやプライマリノードが中断されると、HDFSのデータやクラスター自体が失われます。"},{"l":"C","html":"安定はしますが、処理を急ぐときに増やす分までオンデマンドになり、コストが高くなります。"},{"l":"D","html":"データを持つコアノードがスポットで中断されると、データを失い処理のやり直しになります。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.8 Amazon EMR</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"}]},{"id":"exam-set-23","file":"set-23.md","num":"問題セット23","title":"頻出① 2周目：ネットワークと名前解決","questions":[{"n":1,"topic":"ネットワークACLの評価順","level":2,"body":["サブネットのネットワークACLに、特定の攻撃元IPアドレスを拒否するルールを追加しましたが、攻撃元からの通信が止まりません。インバウンドルールは次のとおりです。<b>ルール100：すべての送信元からTCP 443を許可</b>、<b>ルール200：攻撃元IP（/32）からのすべての通信を拒否</b>、<b>＊：すべて拒否</b>。最も適切な対処はどれですか。"],"options":[{"l":"A","html":"ルール200の対象を攻撃元のIPアドレスを含む /16 に広げる"},{"l":"B","html":"拒否ルールをアウトバウンドにも追加する"},{"l":"C","html":"セキュリティグループにも、攻撃元のIPアドレスを拒否するルールを追加する"},{"l":"D","html":"拒否ルールを、ルール100より小さい番号に付け直す"}],"answer":["D"],"multi":false,"req":"","key":"ネットワークACLは<b>ルール番号の小さい順に評価され、最初に一致したルールで決まります</b>。攻撃元からのTCP 443はルール100の許可に先に一致するため、ルール200の拒否まで評価されません。拒否ルールを許可ルールより小さい番号にすれば止まります。","kw":"ネットワークACLのルール番号（評価順）","reasons":[{"l":"A","html":"範囲を広げても評価順は変わらず、ルール100に先に一致します。無関係な利用者まで巻き込みます。"},{"l":"B","html":"インバウンドがルール100で許可されている限り、通信は入ってきます。評価順の問題は解決しません。"},{"l":"C","html":"セキュリティグループには拒否ルールがありません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.2 通信制御：セキュリティグループとネットワークACL</a>"},{"n":2,"topic":"オリジンへの直接アクセスの防止","level":3,"body":["CloudFrontのオリジンとしてALBを使っています。攻撃者がCloudFrontを経由せずに<b>ALBへ直接アクセス</b>し、WAFの保護をすり抜けていることがわかりました。ALBへの通信をCloudFront経由に限定したいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"ALBのセキュリティグループで、CloudFrontのオリジン向けのAWSマネージドプレフィックスリストからの通信だけを許可し、さらにCloudFrontが付けるカスタムヘッダーをALBのリスナールールで確認する"},{"l":"B","html":"ALBのセキュリティグループのインバウンドで、CloudFrontのエッジのIPアドレス範囲を1つずつ手動で登録する"},{"l":"C","html":"ALBを内部向け（internal）に変更する"},{"l":"D","html":"ALBのネットワークACLで、CloudFront以外のIPアドレスを拒否する"}],"answer":["A"],"multi":false,"req":"","key":"AWSが管理する<b>CloudFrontのオリジン向けプレフィックスリスト</b>をセキュリティグループで参照すれば、CloudFrontから来る通信だけを許可でき、IPアドレスの変更もAWSが追従します。ほかの利用者のCloudFrontディストリビューション経由のアクセスまでは区別できないため、<b>自社だけが知るカスタムヘッダー</b>をALBで確認する二重の対策が定石です。","kw":"CloudFrontのオリジン向けマネージドプレフィックスリスト","reasons":[{"l":"B","html":"CloudFrontのIPアドレス範囲は変わるため、手動での登録は追従できず、運用負荷も大きくなります。"},{"l":"C","html":"内部向けALBにはCloudFrontから直接接続できません（VPCオリジンという別の構成が必要です）。"},{"l":"D","html":"ネットワークACLにはルール数の上限があり、変わり続ける範囲を管理するのに向きません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.2 通信制御</a> ／ <a href=\"#network\" data-go=\"network\">第3章 3.6 コンテンツ配信と高速化</a>"},{"n":3,"topic":"新環境への段階的な移行","level":2,"body":["Webアプリケーションを新しい環境へ移行します。まず<b>利用者の5%だけ</b>を新環境へ向けて様子を見て、問題がなければ段階的に割合を増やし、問題があればすぐに元へ戻したいと考えています。DNSで実現する場合、最も適切なルーティングポリシーはどれですか。"],"options":[{"l":"A","html":"フェイルオーバールーティング"},{"l":"B","html":"位置情報ルーティング"},{"l":"C","html":"加重ルーティング"},{"l":"D","html":"複数値回答ルーティング"}],"answer":["C"],"multi":false,"req":"","key":"加重ルーティングは、レコードごとの<b>重みの比率でトラフィックを配分</b>します。重みを 95:5 から徐々に変えれば段階的に移行でき、問題があれば新環境の重みを0にするだけで戻せます。TTLを短くしておくと、変更が早く反映されます。","kw":"加重ルーティング","reasons":[{"l":"A","html":"プライマリが異常なときだけ切り替える仕組みで、一部の利用者だけを新環境へ向けることはできません。"},{"l":"B","html":"利用者の地域で振り分けるため、割合を指定した移行にはなりません。"},{"l":"D","html":"正常なレコードをランダムに返す仕組みで、割合を制御できません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.4 名前解決：Route 53 と Resolver</a>"},{"n":4,"topic":"地域の割り当ての調整","level":3,"body":["東京とシンガポールの2リージョンでアプリケーションを運用しています。Route 53で<b>利用者から地理的に近いリージョン</b>へ振り分けていますが、東京リージョンの処理能力に余裕があるため、<b>東京が受け持つ地域を広げ</b>、シンガポールの負荷を減らしたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"位置情報ルーティングで、国ごとに振り分け先を列挙し直す"},{"l":"B","html":"地理的近接性ルーティングで、東京のバイアスを大きくする"},{"l":"C","html":"レイテンシーベースルーティングで、東京のレコードの重みを大きくする"},{"l":"D","html":"シンプルルーティングで、東京のIPアドレスを2つ登録する"}],"answer":["B"],"multi":false,"req":"","key":"地理的近接性ルーティングは、利用者とリソースの<b>物理的な距離</b>で振り分け、<b>バイアス</b>で各リソースが受け持つ地域を広げたり狭めたりできます。「受け持つ範囲を広げる・狭める」が決め手です。","kw":"地理的近接性ルーティング（バイアス）","reasons":[{"l":"A","html":"国単位で固定的に列挙することになり、距離に基づいて範囲を少しずつ調整することはできません。"},{"l":"C","html":"レイテンシーベースルーティングに重みの設定はありません（重みは加重ルーティングの機能です）。"},{"l":"D","html":"シンプルルーティングでは振り分けの比率も地域も制御できません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.4 名前解決：Route 53 と Resolver</a>"},{"n":5,"topic":"社内ドメインを複数のVPCで","level":3,"body":["共有サービス用アカウントのVPCに、<code>corp.internal</code> のプライベートホストゾーンを作成しました。<b>別のアカウントにある複数のVPC</b>からも、この名前を解決できるようにしたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"各VPCに同じ名前のプライベートホストゾーンを作り、レコードを手動で同期する"},{"l":"B","html":"<code>corp.internal</code> をパブリックホストゾーンに変更する"},{"l":"C","html":"各VPCのDHCPオプションセットで、共有サービス用VPCのDNSサーバーのIPアドレスを指定する"},{"l":"D","html":"各アカウントのVPCを、プライベートホストゾーンに関連付ける（関連付けの承認を使う）"}],"answer":["D"],"multi":false,"req":"","key":"プライベートホストゾーンは<b>複数のVPCに関連付けられ</b>、<b>別アカウントのVPC</b>も、ホストゾーン側で関連付けを承認すれば関連付けられます。関連付けたVPCでは、VPCのDNS（Route 53 Resolver）で名前が解決されます。VPCのDNS解決とDNSホスト名の属性が有効であることが前提です。","kw":"プライベートホストゾーンのVPC関連付け","reasons":[{"l":"A","html":"レコードの二重管理になり、同期漏れが起きます。"},{"l":"B","html":"社内の名前をインターネットに公開することになり、要件に反します。"},{"l":"C","html":"VPCのDNSはAmazon提供のResolverが担うため、別のVPCのIPアドレスを指定しても共有の仕組みにはなりません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.4 名前解決：Route 53 と Resolver</a>"},{"n":6,"topic":"IPアドレスの枯渇","level":2,"body":["VPC（10.0.0.0/24）で稼働するEKSクラスターのPodが増え、<b>サブネットのIPアドレスが足りなくなりました</b>。既存のリソースを作り直さずに、使えるIPアドレスを増やしたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"VPCにセカンダリCIDRを追加し、新しいサブネットを作る"},{"l":"B","html":"既存のVPCのプライマリCIDRを /16 に変更して、範囲を広げる"},{"l":"C","html":"新しいVPCを大きなCIDRで作成し、すべてのリソースを移行する"},{"l":"D","html":"NAT Gatewayを追加する"}],"answer":["A"],"multi":false,"req":"","key":"VPCの<b>プライマリCIDRは後から変更できません</b>が、<b>セカンダリCIDRブロックを追加</b>して、その範囲に新しいサブネットを作れます。既存のリソースはそのままで、使えるアドレスを増やせます。","kw":"セカンダリCIDRブロック","reasons":[{"l":"B","html":"作成済みのVPCのプライマリCIDRは変更できません。"},{"l":"C","html":"移行の手間が大きく、既存のリソースを作り直さないという要件に反します。"},{"l":"D","html":"NAT Gatewayはアウトバウンドの経路を提供するもので、VPC内のIPアドレスは増えません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.1 VPCの基礎：所属範囲とルーティング</a>"},{"n":7,"topic":"ハブ型接続での分離","level":3,"body":["Transit Gatewayで、本番VPC群・開発VPC群・共有サービスVPCを接続しています。要件は、<b>本番と開発は互いに通信できない</b>、<b>どちらも共有サービスVPCとは通信できる</b>、の2つです。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"すべてのVPCを1つのTransit Gatewayルートテーブルに関連付け、セキュリティグループで本番と開発の通信を拒否する"},{"l":"B","html":"本番用と開発用に別々のTransit Gatewayを用意し、共有サービスVPCを両方に接続する"},{"l":"C","html":"Transit Gatewayに本番用・開発用・共有用のルートテーブルを作り、本番用と開発用には共有サービスVPCへの経路だけを、共有用には両方への経路を伝播させる"},{"l":"D","html":"本番と開発のVPCのネットワークACLで、互いのCIDRを拒否する"}],"answer":["C"],"multi":false,"req":"","key":"Transit Gatewayは<b>複数のルートテーブル</b>を持ち、アタッチメントごとに<b>どのテーブルを使うか（関連付け）</b>と<b>どのテーブルへ経路を載せるか（伝播）</b>を設定できます。本番用と開発用のテーブルに共有サービスへの経路だけを載せれば、本番と開発の間には経路がなくなり、ネットワークの設計として分離できます。","kw":"Transit Gatewayのルートテーブル（関連付け・伝播）","reasons":[{"l":"A","html":"セキュリティグループには拒否ルールがありません。経路が残る設計は分離として不十分です。"},{"l":"B","html":"実現はできますが、Transit Gatewayが増えて管理とコストが二重になります。"},{"l":"D","html":"個々のACLで拒否する方式は、VPCが増えるたびに設定漏れが起きやすく、経路の分離にもなりません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続</a>"},{"n":8,"topic":"エンドポイントとアプリの設定","level":2,"body":["プライベートサブネットのアプリケーションがSQSを呼び出すため、SQS用の<b>インターフェース型VPCエンドポイント</b>を作成しました。アプリケーションは<b>AWS SDKの既定のエンドポイント</b>（<code>sqs.ap-northeast-1.amazonaws.com</code>）を使っており、コードや設定を変えたくありません。最も適切な設定はどれですか。"],"options":[{"l":"A","html":"アプリケーションの接続先を、エンドポイント固有のDNS名に書き換える"},{"l":"B","html":"エンドポイントのプライベートDNSを有効にする"},{"l":"C","html":"ルートテーブルに、SQSのプレフィックスリスト宛ての経路を追加する"},{"l":"D","html":"NAT Gatewayを追加する"}],"answer":["B"],"multi":false,"req":"","key":"インターフェース型エンドポイントでプライベートDNSを有効にすると、<b>サービスの標準のDNS名がエンドポイントのプライベートIPアドレスに解決</b>されます。SDKは既定の名前のまま、自動的にエンドポイント経由で通信します。VPCのDNS属性が有効であることが前提です。","kw":"プライベートDNS","reasons":[{"l":"A","html":"コードや設定の変更が必要になり、要件に反します。"},{"l":"C","html":"ルートテーブルに経路を追加するのはゲートウェイ型（S3とDynamoDB）の仕組みで、インターフェース型では使いません。"},{"l":"D","html":"インターネット経由の通信になり、エンドポイントを作った意味がなくなります。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続</a>"},{"n":9,"topic":"1つのALBで複数のドメイン","level":2,"body":["3つのサービス（<code>shop.example.com</code>、<code>api.example.net</code>、<code>admin.example.org</code>）を、<b>1つのALB</b>で公開したいと考えています。それぞれHTTPSで配信し、ドメインごとに別のターゲットグループへ振り分けます。<b>適切な設定を2つ選択してください。</b>"],"options":[{"l":"A","html":"HTTPSリスナーに、3つのドメインの証明書を追加する（SNIで使い分けられる）"},{"l":"B","html":"ドメインごとにNLBを追加する"},{"l":"C","html":"リスナールールで、ホストヘッダーの条件ごとに転送先のターゲットグループを分ける"},{"l":"D","html":"<code>*.example.com</code> のワイルドカード証明書を1枚だけ設定する"},{"l":"E","html":"Route 53の加重ルーティングで、ドメインごとにターゲットグループを選ぶ"}],"answer":["A","C"],"multi":true,"req":"","key":"ALBのHTTPSリスナーは<b>複数の証明書を持ち、SNIでクライアントが要求したドメインに合う証明書を選びます</b>。振り分けは<b>ホストヘッダーを条件にしたリスナールール</b>で行います。1つのALBで複数のドメインを扱う定番の組み合わせです。","kw":"SNI／ホストヘッダーによるルーティング","reasons":[{"l":"B","html":"ロードバランサーが増え、1つのALBで公開するという要件に反します。"},{"l":"D","html":"<code>*.example.com</code> は <code>example.net</code> や <code>example.org</code> のドメインには使えません。"},{"l":"E","html":"DNSは宛先のIPアドレスを返すだけで、ALBの中でどのターゲットグループへ送るかは決められません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.5 負荷分散：Elastic Load Balancing</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.7 AWS Certificate Manager</a>"},{"n":10,"topic":"VPNの帯域不足","level":3,"body":["オンプレミスとAWSを、仮想プライベートゲートウェイに接続した<b>Site-to-Site VPN</b>でつないでいます。データの転送量が増え、<b>1本のトンネルの帯域の上限</b>に達しています。専用線を引く予算はありません。最も適切な対処はどれですか。"],"options":[{"l":"A","html":"VPNをTransit Gatewayに付け替え、ECMPで複数のVPN接続を束ねる"},{"l":"B","html":"仮想プライベートゲートウェイに、同じオンプレミスからのVPN接続をもう1本追加する"},{"l":"C","html":"VPNの暗号化方式をAES-128など軽いものに変えて、処理を速くする"},{"l":"D","html":"VPC内のEC2インスタンスを大きくする"}],"answer":["A"],"multi":false,"req":"","key":"VPNの1本のトンネルの帯域には上限があります。<b>Transit GatewayはECMPに対応</b>しており、複数のVPN接続（トンネル）に通信を分散して、合計の帯域を広げられます。仮想プライベートゲートウェイはECMPに対応していません。","kw":"Transit Gateway／ECMP","reasons":[{"l":"B","html":"仮想プライベートゲートウェイは複数のトンネルに通信を分散しないため、帯域の合計は増えません。"},{"l":"C","html":"暗号化方式を変えても、トンネルの帯域の上限は変わりません。セキュリティも下がります。"},{"l":"D","html":"ボトルネックはVPNの経路で、インスタンスの性能ではありません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.4 ネットワークパフォーマンスの最適化</a>"}]},{"id":"exam-set-24","file":"set-24.md","num":"問題セット24","title":"頻出② 2周目：ストレージの選択と移行","questions":[{"n":1,"topic":"共有ファイルシステムの入り口","level":2,"body":["1つのEFSファイルシステムを、3つのアプリケーションで共有しています。要件は、(1) 各アプリケーションは<b>自分用のディレクトリ</b>だけを見られること、(2) アプリケーションごとに<b>決まったPOSIXユーザー・グループ</b>として読み書きすること、です。最も管理しやすい方法はどれですか。"],"options":[{"l":"A","html":"アプリケーションごとに別のEFSファイルシステムを作成する"},{"l":"B","html":"セキュリティグループでアプリケーションごとにNFSの通信を分ける"},{"l":"C","html":"各インスタンスでマウント後に <code>chmod</code> を実行してディレクトリの権限を調整する"},{"l":"D","html":"アプリケーションごとにEFSアクセスポイントを作成する"}],"answer":["D"],"multi":false,"req":"","key":"EFSアクセスポイントは、接続したクライアントに<b>特定のディレクトリをルートとして見せ</b>、<b>POSIXのユーザーとグループを強制</b>できます。IAMポリシーでアプリごとに使えるアクセスポイントを限定することもでき、1つのファイルシステムを安全に共有できます。","kw":"EFSアクセスポイント","reasons":[{"l":"A","html":"ファイルシステムが増えて管理が分散し、共有の利点を失います。"},{"l":"B","html":"セキュリティグループはネットワークの到達を制御するもので、ディレクトリ単位の制御はできません。"},{"l":"C","html":"各インスタンスの設定に依存し、設定漏れや、ほかのディレクトリへのアクセスを防げません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.3 Amazon EFS</a>"},{"n":2,"topic":"LinuxとWindowsで同じデータ","level":2,"body":["オンプレミスのNetApp製ストレージで、<b>同じデータをLinuxからはNFS、WindowsからはSMB</b>で共有しています。スナップショットや重複排除の機能も使っており、運用手順をできるだけ変えずにAWSへ移したいと考えています。最も適切なサービスはどれですか。"],"options":[{"l":"A","html":"Amazon FSx for NetApp ONTAP"},{"l":"B","html":"Amazon FSx for Windows File Server"},{"l":"C","html":"Amazon FSx for Lustre"},{"l":"D","html":"Amazon EFS"}],"answer":["A"],"multi":false,"req":"","key":"FSx for NetApp ONTAPは、<b>NFS・SMB・iSCSIを同じデータに対して同時に提供</b>でき、スナップショットや重複排除などONTAPの機能もそのまま使えます。「NetApp」「マルチプロトコル」がそろえば ONTAP です。","kw":"Amazon FSx for NetApp ONTAP","reasons":[{"l":"B","html":"FSx for Windows File ServerはSMB向けで、LinuxからのNFSでは共有できません。"},{"l":"C","html":"FSx for LustreはHPC向けの高速ファイルシステムで、SMBには対応していません。"},{"l":"D","html":"EFSはNFSだけで、WindowsのSMBには対応していません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.4 Amazon FSx</a>"},{"n":3,"topic":"ブロックストレージの拡張","level":2,"body":["工場の生産管理システムは、<b>オンプレミスのiSCSIボリューム</b>を使っています。すべてのデータを<b>ローカルで低遅延に</b>読み書きしたまま、クラウドにバックアップを取り、災害時にはAWS上で復元できるようにしたいと考えています。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"Volume Gatewayのキャッシュ型ボリュームを使う"},{"l":"B","html":"Volume Gatewayの保管型ボリュームを使う"},{"l":"C","html":"S3 File Gatewayを使う"},{"l":"D","html":"Tape Gatewayを使う"}],"answer":["B"],"multi":false,"req":"","key":"保管型ボリュームは<b>全データをオンプレミスに置き</b>、その特定時点のスナップショットを非同期でAWSへ保存します（EBSスナップショットとして復元可能）。全データを低遅延で扱いながら、クラウドへのバックアップとDRを実現できます。","kw":"Volume Gatewayの保管型ボリューム","reasons":[{"l":"A","html":"キャッシュ型は<b>全データをAWS側に置き</b>、よく使うデータだけをローカルにキャッシュします。すべてのデータを低遅延で扱うという要件を満たしません。"},{"l":"C","html":"S3 File GatewayはNFS/SMBのファイル共有で、iSCSIのブロックストレージではありません。"},{"l":"D","html":"Tape Gatewayはバックアップソフト向けの仮想テープで、業務システムが直接読み書きするボリュームではありません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.6 AWS Storage Gateway</a>"},{"n":4,"topic":"大量オブジェクトの一括処理","level":2,"body":["S3バケットに保存された<b>約5億個のオブジェクト</b>すべてに、部署名のタグを付け直す必要があります。自前のスクリプトで1つずつ処理すると、何週間もかかり、失敗したオブジェクトの管理も大変です。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"EC2インスタンスを多数起動し、オブジェクトの一覧を分担して並列でタグを付け直す"},{"l":"B","html":"S3 Batch Operationsで、既存オブジェクトのタグを一括で置き換える"},{"l":"C","html":"S3のイベント通知でLambda関数を起動し、オブジェクトごとに新しいタグを付け直す"},{"l":"D","html":"ライフサイクルルールでタグを付ける"}],"answer":["B"],"multi":false,"req":"","key":"S3 Batch Operationsは、<b>大量の既存オブジェクト</b>に対してタグの付け替え・コピー・復元・Lambdaの実行などを<b>1つのジョブ</b>で行えます。対象はインベントリなどのマニフェストで指定し、進捗や失敗したオブジェクトのレポートも自動で出力されます。","kw":"S3 Batch Operations","reasons":[{"l":"A","html":"並列化や再試行、失敗の管理を自前で作る必要があり、運用負荷が大きくなります。"},{"l":"C","html":"イベント通知は<b>新しく作成・変更された</b>オブジェクトで動く仕組みで、既存のオブジェクトには働きません。"},{"l":"D","html":"ライフサイクルルールはストレージクラスの移行や削除を行うもので、タグは付けられません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a>"},{"n":5,"topic":"復元直後の性能","level":2,"body":["障害訓練で、EBSスナップショットから大量のボリュームを作成してデータベースを起動しました。しかし、<b>起動直後のしばらくはディスクの読み取りが非常に遅く</b>、性能要件を満たせませんでした。本番の復旧時は、<b>ボリュームの作成直後から本来の性能</b>を出したいと考えています。最も適切な対策はどれですか。"],"options":[{"l":"A","html":"復元先のAZで、高速スナップショット復元（FSR）を有効にする"},{"l":"B","html":"ボリュームタイプをsc1にする"},{"l":"C","html":"スナップショットの取得頻度を上げ、最新の状態から復元できるようにする"},{"l":"D","html":"スナップショットをEBSスナップショットアーカイブに移し、保管コストを下げる"}],"answer":["A"],"multi":false,"req":"","key":"通常、スナップショットから作ったボリュームは、データが<b>最初にアクセスされたときにS3から読み込まれる</b>ため、初回の読み取りが遅くなります。FSRを有効にしたスナップショットから作ったボリュームは、<b>作成時点で完全に初期化</b>されており、すぐに本来の性能を出せます（AZごとに有効化し、料金がかかります）。","kw":"高速スナップショット復元（FSR）","reasons":[{"l":"B","html":"sc1はさらに性能の低いHDDです。"},{"l":"C","html":"取得頻度はRPOに関係する設定で、復元直後の性能は変わりません。"},{"l":"D","html":"アーカイブ層からの復元はさらに時間がかかります。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.2 Amazon EBS</a>"},{"n":6,"topic":"無停止でのボリュームの変更","level":2,"body":["本番のEC2インスタンスで使っているgp3ボリュームの<b>容量とIOPSが不足</b>してきました。アプリケーションを止めずに、容量とIOPSを増やしたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"スナップショットを取得し、大きなボリュームを作成して付け替える"},{"l":"B","html":"インスタンスを停止してから、ボリュームを変更する"},{"l":"C","html":"Elastic Volumesで、接続したまま容量とIOPSを変更する"},{"l":"D","html":"インスタンスストアを追加し、データを移す"}],"answer":["C"],"multi":false,"req":"","key":"Elastic Volumesを使えば、EBSボリュームの<b>容量・タイプ・IOPS・スループットを、接続したまま変更</b>できます。容量を増やした場合は、OS側でパーティションとファイルシステムを拡張すれば使えるようになります。","kw":"Elastic Volumes","reasons":[{"l":"A","html":"付け替えには停止や切り替えの作業が必要で、手間もかかります。"},{"l":"B","html":"停止は不要です。停止すれば要件に反します。"},{"l":"D","html":"インスタンスストアは停止や終了で消える一時領域で、本番データの置き場所に向きません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.2 Amazon EBS</a>"},{"n":7,"topic":"共有データレイクの権限","level":2,"body":["1つのS3バケットに全社のデータレイクを置き、<b>数十のチーム</b>がそれぞれ異なるプレフィックスと権限でアクセスしています。1つのバケットポリシーにすべてのルールを書いた結果、<b>ポリシーが巨大で変更しにくく</b>なっています。最も適切な改善策はどれですか。"],"options":[{"l":"A","html":"チームごとにS3アクセスポイントを作成する"},{"l":"B","html":"チームごとにバケットを分け、データを複製する"},{"l":"C","html":"バケットのACLでチームごとに権限を付ける"},{"l":"D","html":"すべてのチームに同じIAMロールを使わせる"}],"answer":["A"],"multi":false,"req":"","key":"S3アクセスポイントは、1つのバケットに対して<b>用途ごとの入り口と専用のポリシー</b>を作れる機能です。チームごとに権限を分けて管理でき、特定のVPCからだけ使えるアクセスポイントも作れます。巨大なバケットポリシーを分割する定番の方法です。","kw":"S3アクセスポイント","reasons":[{"l":"B","html":"データが重複し、同期の管理とコストが増えます。"},{"l":"C","html":"ACLは細かな条件を表現できず、現在は無効にすることが推奨されています。"},{"l":"D","html":"チームごとに権限を分けるという要件に反します。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a>"},{"n":8,"topic":"同じエンジンへのDB移行","level":2,"body":["オンプレミスのMySQL（1 TB）を<b>Aurora MySQL</b>へ移行します。移行作業中も業務は止められず、<b>切り替え時の停止は数分以内</b>にしたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"AWS SCTでスキーマを変換してから、DMSでデータを移して切り替える"},{"l":"B","html":"mysqldumpでエクスポートし、Auroraへインポートしてから切り替える"},{"l":"C","html":"AWS DMSで全ロードとCDCを行い、追いついた時点で切り替える"},{"l":"D","html":"Snowball Edgeでデータを輸送する"}],"answer":["C"],"multi":false,"req":"","key":"DMSは初期の全体ロードの後、<b>変更データキャプチャ（CDC）で移行中の更新を継続的に反映</b>できます。移行元を止めずに同期を続け、差分がなくなった時点で接続先を切り替えれば、停止は切り替えの数分だけで済みます。同じMySQL系のエンジン同士なので、スキーマの変換は不要です。","kw":"AWS DMS（全体ロード＋CDC）","reasons":[{"l":"A","html":"SCTはエンジンが異なる移行（例：OracleからPostgreSQL）で使うものです。同じエンジン同士では不要です。"},{"l":"B","html":"エクスポートからインポートまでの間の更新が反映されず、長い停止が必要になります。"},{"l":"D","html":"輸送の間に発生した更新を反映できず、1 TBであればネットワーク経由で十分に転送できます。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.12 AWS Database Migration Service</a>"},{"n":9,"topic":"一時的な高速処理","level":2,"body":["ゲノム解析のジョブを<b>数日間だけ</b>実行します。入力データはS3にあり、処理中は非常に高いスループットのファイルシステムが必要です。結果はS3に書き戻し、ファイルシステムはジョブ終了後に削除します。<b>コストを最小</b>にしたいと考えています。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"FSx for Windows File Serverを使う"},{"l":"B","html":"FSx for Lustreのパーシステントデプロイタイプを使う"},{"l":"C","html":"EFSのプロビジョンドスループットモードを使う"},{"l":"D","html":"FSx for Lustreのスクラッチを、S3にリンクして使う"}],"answer":["D"],"multi":false,"req":"","key":"スクラッチは<b>データの複製を持たない代わりに安価</b>で、短期間の処理と一時的なデータに向いたデプロイタイプです。S3にリンクすれば、入力を読み込み、結果をS3へ書き戻せます。元データはS3にあるため、ファイルシステムの障害に備える必要もありません。","kw":"FSx for Lustreのスクラッチ","reasons":[{"l":"A","html":"Windows向けのファイルサーバーで、HPCの用途に合いません。"},{"l":"B","html":"パーシステントは長期間の利用とデータ保護のためのタイプで、数日間だけの処理には割高です。"},{"l":"C","html":"EFSは汎用の共有ファイルシステムで、HPC並みのスループットを出すにはFSx for Lustreより高くつきます。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.4 Amazon FSx</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":10,"topic":"バックアップの一元管理","level":3,"body":["EC2、EBS、RDS、EFSのバックアップを、アカウントごと・サービスごとのスクリプトで取得しています。監査から、(1) <b>全リソースのバックアップ方針を一元管理</b>すること、(2) <b>管理者であっても保持期間中のバックアップを削除できない</b>こと、を求められました。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"Amazon Data Lifecycle ManagerでEBSのスナップショットだけを管理する"},{"l":"B","html":"AWS Backupのバックアッププランを作成し、タグで対象のリソースを割り当てる"},{"l":"C","html":"各サービスの手動スナップショットをS3にエクスポートする"},{"l":"D","html":"バックアップボールトにAWS Backup Vault Lock（コンプライアンスモード）を設定する"},{"l":"E","html":"EC2のインスタンスストアにバックアップを保存する"}],"answer":["B","D"],"multi":true,"req":"","key":"AWS Backupは複数のサービスのバックアップを<b>1つのプランで一元管理</b>でき、タグで対象を自動的に割り当てられます。Vault Lockのコンプライアンスモードを設定すると、<b>ルートユーザーを含む誰であっても</b>保持期間中のバックアップを削除したり、保持期間を短くしたりできなくなります。","kw":"AWS Backup／AWS Backup Vault Lock","reasons":[{"l":"A","html":"Data Lifecycle ManagerはEBS（とAMI）が対象で、RDSやEFSは管理できません。"},{"l":"C","html":"手作業の運用が残り、一元管理にも削除防止にもなりません。"},{"l":"E","html":"インスタンスストアはインスタンスの停止や終了で消える一時領域です。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.5 AWS Backup</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"}]},{"id":"exam-set-25","file":"set-25.md","num":"問題セット25","title":"頻出③ 2周目：ID・運用・サービス連携","questions":[{"n":1,"topic":"既存のID基盤との連携","level":2,"body":["社員のアカウントは<b>Microsoft Entra ID</b>で管理しています。AWS Organizationsの40アカウントへのサインインを、Entra IDのアカウントで行えるようにし、<b>入社・退職に伴うユーザーやグループの追加・削除も自動で反映</b>させたいと考えています。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"各アカウントにIAMユーザーを作成し、社員ごとにパスワードを配布する"},{"l":"B","html":"IAM Identity CenterにEntra IDを外部IdPとして接続し、SCIMで同期する"},{"l":"C","html":"Amazon Cognitoのユーザープールで、Entra IDとSAML連携する"},{"l":"D","html":"AWS Managed Microsoft ADを構築し、Entra IDと手動で同期する"}],"answer":["B"],"multi":false,"req":"","key":"IAM Identity Centerは外部IdPとSAMLで連携してシングルサインオンを提供し、<b>SCIM</b>でユーザーとグループを自動的に同期できます。権限は<b>許可セット</b>をアカウントとグループの組み合わせに割り当てて管理します。「多数のAWSアカウント」「社内の既存ID基盤」がそろえば Identity Center です。","kw":"IAM Identity Center／SCIM","reasons":[{"l":"A","html":"アカウントごとのIAMユーザーは管理が分散し、入退社の反映も手作業になります。"},{"l":"C","html":"Cognitoは一般の利用者（顧客）向けのサービスで、社員のAWSアカウントへのアクセス管理には使いません。"},{"l":"D","html":"ディレクトリを二重に持つことになり、手動の同期は漏れが出ます。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.2 AWS IAM Identity Center</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":2,"topic":"SCPが効かないアカウント","level":3,"body":["組織のルートに「S3バケットの削除を拒否する」SCPを適用しました。メンバーアカウントではバケットを削除できなくなりましたが、<b>管理アカウントの管理者は、引き続きバケットを削除できて</b>しまいます。この理由として正しいものはどれですか。"],"options":[{"l":"A","html":"SCPは組織の管理アカウントには適用されないため"},{"l":"B","html":"管理者がルートユーザーでサインインしているため"},{"l":"C","html":"SCPが反映されるまで24時間かかるため"},{"l":"D","html":"管理アカウントのIAMポリシーで明示的に許可されているため"}],"answer":["A"],"multi":false,"req":"","key":"SCPは<b>メンバーアカウント</b>（ルートユーザーを含む）に上限をかける仕組みで、<b>管理アカウントには効きません</b>。そのため、管理アカウントでは業務用のリソースを動かさず、組織の管理だけに使うのがベストプラクティスです。","kw":"SCPと管理アカウント","reasons":[{"l":"B","html":"メンバーアカウントのルートユーザーにもSCPは効きます。ルートユーザーかどうかは理由ではありません。"},{"l":"C","html":"SCPはすぐに反映されます。"},{"l":"D","html":"SCPが適用されるアカウントでは、IAMポリシーで許可していてもSCPの拒否が優先されます。許可があることは理由になりません。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.5 AWS Organizations</a>"},{"n":3,"topic":"環境ごとの設定値","level":2,"body":["アプリケーションは、開発・検証・本番の<b>環境ごとに数十個の設定値</b>（接続先のURL、機能フラグ、一部はAPIキー）を持っています。起動時に<b>その環境の設定値をまとめて取得</b>したいと考えています。値の自動ローテーションは不要で、コストはできるだけ抑えたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"設定値をAMIに埋め込み、環境ごとに専用のAMIを作って起動する"},{"l":"B","html":"すべての値をSecrets Managerに1つずつ保存し、自動ローテーションを設定する"},{"l":"C","html":"Parameter Storeに階層で保存する"},{"l":"D","html":"設定値をLambdaの環境変数にすべて書く"}],"answer":["C"],"multi":false,"req":"","key":"Parameter Storeは<b>階層構造</b>でパラメータを管理でき、パスを指定して<b>配下の値をまとめて取得</b>できます。機密の値はKMSで暗号化されるSecureStringにでき、標準パラメータは無料です。ローテーションが不要ならParameter Storeが最もコスト効率に優れます。","kw":"Parameter Storeの階層","reasons":[{"l":"A","html":"値を変えるたびにAMIを作り直す必要があり、APIキーをイメージに含めるのも危険です。"},{"l":"B","html":"シークレットごとに月額料金がかかり、ローテーションが不要な設定値まで保存するのは割高です。"},{"l":"D","html":"環境変数には容量の上限があり、アプリの実行基盤もLambdaに限られます。機密の値の管理にも向きません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.10 AWS Secrets Manager vs Parameter Store</a> ／ <a href=\"#management\" data-go=\"management\">第8章 8.4 AWS Systems Manager</a>"},{"n":4,"topic":"アラートの出すぎ","level":2,"body":["Webサービスで、CPU使用率・エラー率・レイテンシのアラームを個別に設定しています。一時的にCPUが上がるだけでも通知が飛び、<b>本当に対応が必要な障害の通知が埋もれて</b>しまっています。「<b>エラー率とレイテンシがともに悪化したときだけ</b>」通知したいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"各アラームのしきい値を大きく引き上げ、誤報を減らす"},{"l":"B","html":"各アラームの評価期間を1時間に延ばし、一時的な変動を無視する"},{"l":"C","html":"既存のアラームを組み合わせた複合アラームを作る"},{"l":"D","html":"SNSトピックのサブスクリプションを減らす"}],"answer":["C"],"multi":false,"req":"","key":"CloudWatchの複合アラームは、複数のアラームの状態を<b>AND・OR・NOTで組み合わせ</b>て1つのアラームにできます。通知は複合アラームからだけ行い、個々のアラームは通知しないようにすれば、本当に対応が必要な状況だけを知らせられます。","kw":"複合アラーム","reasons":[{"l":"A","html":"しきい値を上げると、本当の障害の検知まで遅れます。"},{"l":"B","html":"検知が大幅に遅れ、短時間の深刻な障害を見逃します。"},{"l":"D","html":"通知の宛先を減らしても、通知の多さ自体は変わりません。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.1 Amazon CloudWatch</a>"},{"n":5,"topic":"組織全体の準拠状況","level":2,"body":["AWS Organizationsの全アカウント・全リージョンで、AWS Configルールの<b>準拠状況を1か所でまとめて確認</b>したいと考えています。各アカウントにサインインして確認する運用はやめたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"各アカウントのConfigのデータを毎日S3にエクスポートして結合する"},{"l":"B","html":"Trusted Advisorの組織ビューを使う"},{"l":"C","html":"CloudTrailの組織トレイルを作成し、全アカウントの記録を集める"},{"l":"D","html":"監査用アカウントにConfigのアグリゲータを作成する"}],"answer":["D"],"multi":false,"req":"","key":"Configのアグリゲータは、<b>複数のアカウント・リージョン</b>の構成情報とルールの準拠状況を1つのアカウントに集約します。組織を対象にすれば、新しいアカウントも自動的に含まれます。","kw":"Configのアグリゲータ","reasons":[{"l":"A","html":"自前の集計の仕組みが必要で、運用負荷が大きくなります。"},{"l":"B","html":"Trusted Advisorはベストプラクティスの点検で、独自に定義したConfigルールの準拠状況は確認できません。"},{"l":"C","html":"CloudTrailはAPI操作の記録で、ルールへの準拠状況はわかりません。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.7 AWS Config</a>"},{"n":6,"topic":"多数のサーバーへの一斉作業","level":1,"body":["300台のEC2インスタンス（一部はオンプレミスのサーバー）で、<b>同じ診断スクリプトを一斉に実行</b>し、結果を集めたいと考えています。SSHの鍵の配布や踏み台サーバーは使いたくありません。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"踏み台サーバーから並列SSHでスクリプトを実行する"},{"l":"B","html":"Systems Manager Run Commandで、タグで対象を指定して実行する"},{"l":"C","html":"各インスタンスのユーザーデータにスクリプトを書き、再起動する"},{"l":"D","html":"Lambda関数から各インスタンスへ直接接続して実行する"}],"answer":["B"],"multi":false,"req":"","key":"Run Commandは、SSM Agentが動く<b>EC2やオンプレミスのサーバーに、SSHなしでコマンドを一斉に実行</b>できます。タグで対象を選び、同時実行数やエラーの許容数を指定でき、出力はS3やCloudWatch Logsに保存できます。","kw":"Systems Manager Run Command","reasons":[{"l":"A","html":"鍵の配布と踏み台の管理が必要で、要件に反します。"},{"l":"C","html":"ユーザーデータは既定では初回の起動時にしか実行されません。再起動も業務への影響が大きくなります。"},{"l":"D","html":"インスタンスへの接続手段を自前で用意する必要があり、SSHなどの仕組みが結局必要になります。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.4 AWS Systems Manager</a>"},{"n":7,"topic":"大量のファイルの並列処理","level":3,"body":["S3に置かれた<b>数百万個の画像</b>それぞれに、同じ処理（Lambda関数による解析）を実行するワークフローを作ります。処理は<b>大きな並列度</b>で行い、失敗した画像の数が一定を超えたらワークフロー全体を止めたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"1つのLambda関数の中で、全画像をループして順に処理する"},{"l":"B","html":"EC2を1台起動し、スクリプトで順番に処理する"},{"l":"C","html":"各画像のアップロード時にS3のイベント通知でLambdaを起動する"},{"l":"D","html":"Step Functionsの分散マップで、S3のオブジェクト一覧を入力に並列実行する"}],"answer":["D"],"multi":false,"req":"","key":"分散マップは、<b>S3のオブジェクト一覧やCSVなどを入力に、多数の子ワークフローを大きな並列度で実行</b>できるStep Functionsの機能です。失敗の許容数や割合を設定でき、超えたら全体を失敗として止められます。進み具合と結果もまとめて管理できます。","kw":"Step Functionsの分散マップ（Distributed Map）","reasons":[{"l":"A","html":"Lambdaの最大実行時間（15分）で数百万件は処理しきれず、並列度も得られません。"},{"l":"B","html":"並列度が得られず、処理に非常に長い時間がかかります。"},{"l":"C","html":"既に保存されている画像には働きません。失敗の件数で全体を止める制御もできません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.4 AWS Step Functions</a>"},{"n":8,"topic":"修正後の再処理","level":2,"body":["SQSキューのメッセージを処理するワーカーのバグで、<b>数千件のメッセージがデッドレターキュー（DLQ）に移されました</b>。バグを修正してデプロイしたので、DLQのメッセージを元のキューに戻して処理し直したいと考えています。最も手間の少ない方法はどれですか。"],"options":[{"l":"A","html":"DLQのリドライブで元のキューへ戻す"},{"l":"B","html":"DLQのメッセージを1件ずつコンソールで確認し、手作業で元のキューに送り直す"},{"l":"C","html":"DLQをワーカーの入力キューに設定し直す"},{"l":"D","html":"DLQのメッセージ保持期間を延長して、自然に元のキューへ戻るのを待つ"}],"answer":["A"],"multi":false,"req":"","key":"SQSには、DLQのメッセージを<b>元のキュー（または指定したキュー）へまとめて移動するリドライブ</b>の機能があります。移動の速度も指定でき、修正後の再処理を手間なく行えます。","kw":"DLQのリドライブ","reasons":[{"l":"B","html":"数千件を手作業で扱うのは現実的ではなく、誤りも起きます。"},{"l":"C","html":"ワーカーの設定を変える必要があり、DLQと通常のキューの役割が混ざってしまいます。"},{"l":"D","html":"DLQのメッセージが自然に元のキューへ戻ることはありません。保持期間を過ぎると削除されます。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.4 イベント駆動型アーキテクチャ</a>"},{"n":9,"topic":"非公開のデータベースへの接続","level":3,"body":["プライベートサブネットのRDSに、開発者が<b>手元のPCのSQLクライアントから</b>接続して調査する必要があります。セキュリティ部門は、<b>踏み台サーバーへのSSHやインバウンドのポート開放を禁止</b>しています。操作は監査できるようにしたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"Session Managerのポートフォワーディング"},{"l":"B","html":"踏み台サーバーを置き、SSHのポートを社内のIPアドレスに限定して開放する"},{"l":"C","html":"Site-to-Site VPNを開発者ごとに構成する"},{"l":"D","html":"RDSをパブリックアクセス可能にして、開発者のIPアドレスだけを許可する"}],"answer":["A"],"multi":false,"req":"","key":"Session Managerは、シェル接続だけでなく<b>ポートフォワーディング</b>にも対応しており、SSM Agentが動くインスタンスを中継して<b>リモートのホスト（RDS）のポートを手元のPCへ転送</b>できます。インバウンドのポート開放もSSHの鍵も不要で、セッションはIAMで認可され、ログに記録されます。","kw":"Session Managerのポートフォワーディング","reasons":[{"l":"B","html":"SSHのポートを開けることが禁止されています。"},{"l":"C","html":"Site-to-Site VPNは拠点間の接続で、開発者のPCごとに構成する仕組みではありません。"},{"l":"D","html":"データベースをインターネットに公開することになり、危険です。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.4 AWS Systems Manager</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.3 多層防御</a>"},{"n":10,"topic":"新しいアカウントへの初期設定","level":2,"body":["AWS Organizationsの「ワークロード」OUに新しいアカウントが追加されるたびに、(1) 監査用のIAMロールとConfigの設定を<b>自動で展開</b>し、(2) 特定のサービスの利用を<b>自動で禁止</b>したいと考えています。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"IAM Identity Centerの許可セットで、禁止したサービスを除外する"},{"l":"B","html":"新しいアカウントが作られるたびに、管理者がCloudFormationのスタックを手動で作成する"},{"l":"C","html":"CloudFormation StackSets（サービスマネージドの権限）をOUに対して展開し、自動デプロイを有効にする"},{"l":"D","html":"AWS Configルールで、禁止したサービスの利用を検出する"},{"l":"E","html":"禁止するサービスを拒否するSCPをOUにアタッチする"}],"answer":["C","E"],"multi":true,"req":"","key":"サービスマネージドのStackSetsを<b>OUに対して展開し自動デプロイを有効にする</b>と、OUに追加されたアカウントへ自動でスタックが作成されます。SCPは<b>OUにアタッチすれば、配下のすべてのアカウントに自動で適用</b>されます。どちらも「アカウントが増えても人手がいらない」仕組みです。","kw":"CloudFormation StackSets（自動デプロイ）／SCP","reasons":[{"l":"A","html":"許可セットはサインインする人の権限で、アカウント内のロールやルートユーザーの操作は制限できません。"},{"l":"B","html":"手作業は漏れや遅れの原因になり、自動化の要件に反します。"},{"l":"D","html":"Configは検出の仕組みで、利用そのものは禁止できません。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.3 AWS CloudFormation</a> ／ <a href=\"#management\" data-go=\"management\">第8章 8.5 AWS Organizations</a>"}]},{"id":"exam-set-26","file":"set-26.md","num":"問題セット26","title":"頻出④ 2周目：コンピューティングの細目","questions":[{"n":1,"topic":"新しいAMIへの入れ替え","level":2,"body":["Auto Scalingグループ（20台）の起動テンプレートを、セキュリティパッチを当てた<b>新しいAMI</b>に更新しました。しかし、既存のインスタンスは古いAMIのまま動いています。<b>サービスを止めずに、一定の割合ずつ</b>新しいAMIのインスタンスへ入れ替えたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"インスタンスの更新（Instance Refresh）を開始する"},{"l":"B","html":"全インスタンスを一度に終了させ、新しいAMIの起動テンプレートで起動し直させる"},{"l":"C","html":"希望容量を40台に増やしてから20台に戻す"},{"l":"D","html":"各インスタンスにSSHでログインし、パッチを手作業で順番に適用する"}],"answer":["A"],"multi":false,"req":"","key":"インスタンスの更新は、起動テンプレートの新しい設定に合わせて<b>既存のインスタンスを順番に入れ替える</b>機能です。<b>最小正常率</b>を指定すると、その割合の正常なインスタンスを保ちながら置き換え、途中で問題があれば止めたり元に戻したりもできます。","kw":"インスタンスの更新（Instance Refresh）","reasons":[{"l":"B","html":"一斉に終了させるとサービスが止まります。"},{"l":"C","html":"スケールインで新しいインスタンスが先に消える可能性があり、確実な入れ替えになりません。一時的にコストも倍になります。"},{"l":"D","html":"手作業でAMIとの差が生じ、次にスケールアウトしたときに古いAMIの状態に戻ります。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.2 Amazon EC2 Auto Scaling</a>"},{"n":2,"topic":"スケールインで消すインスタンス","level":2,"body":["Auto Scalingグループで、起動テンプレートのバージョンを更新しました。今後のスケールインでは、<b>古い起動テンプレートのインスタンスから優先して終了</b>させたいと考えています。最も適切な設定はどれですか。"],"options":[{"l":"A","html":"スケールイン保護を新しいインスタンスに設定し、古いものから外れるようにする"},{"l":"B","html":"終了ポリシーに <code>NewestInstance</code> を指定して、順番を固定する"},{"l":"C","html":"終了ポリシーに <code>OldestLaunchTemplate</code> を指定する"},{"l":"D","html":"ヘルスチェックの猶予期間を短くし、古いインスタンスを早く入れ替える"}],"answer":["C"],"multi":false,"req":"","key":"終了ポリシーは、スケールインのときに<b>どのインスタンスを先に終了させるか</b>を決めます。<code>OldestLaunchTemplate</code> を指定すると、最も古い起動テンプレート（またはそのバージョン）で起動したインスタンスが優先して終了し、自然に新しい設定へ置き換わっていきます。","kw":"終了ポリシー（OldestLaunchTemplate）","reasons":[{"l":"A","html":"保護を個別に付ける運用は手間がかかり、保護を外し忘れると新しいインスタンスのスケールインまで止まります。"},{"l":"B","html":"<code>NewestInstance</code> は最も新しいインスタンスから終了させるため、逆の結果になります。"},{"l":"D","html":"猶予期間はヘルスチェックの開始を遅らせる設定で、終了させる順番とは関係ありません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.2 Amazon EC2 Auto Scaling</a>"},{"n":3,"topic":"分散システムの配置","level":2,"body":["EC2上にApache Kafkaのクラスター（30台）を構築します。ハードウェアの障害で<b>複数のブローカーが同時に失われる</b>ことを避けたいのですが、スプレッドプレイスメントグループでは台数が足りません。Kafkaには、ブローカーがどの<b>障害単位（ラック）</b>にいるかを伝えて、レプリカを分散させたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"パーティションプレイスメントグループ"},{"l":"B","html":"クラスタープレイスメントグループ"},{"l":"C","html":"Dedicated Hosts"},{"l":"D","html":"プレイスメントグループを使わず、1つのAZに配置する"}],"answer":["A"],"multi":false,"req":"","key":"パーティションプレイスメントグループは、インスタンスを<b>ラック単位の論理的なパーティション</b>に分けて配置し、パーティション同士はハードウェアを共有しません。各インスタンスがどのパーティションにいるかを取得できるため、Kafka・HDFS・Cassandraなどにラックの情報として渡し、レプリカを別のパーティションに置けます。","kw":"パーティションプレイスメントグループ","reasons":[{"l":"B","html":"クラスタープレイスメントグループは同じラックの近くに集める配置で、同時に障害が起きる可能性がかえって高まります。"},{"l":"C","html":"Dedicated Hostsはホストの専有とライセンス管理のためのもので、ラック単位での分散を制御する仕組みではありません。"},{"l":"D","html":"障害の単位が考慮されず、同時障害の危険を減らせません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a>"},{"n":4,"topic":"スポットインスタンスの使い方","level":3,"body":["ステートレスな画像変換ワーカーを、スポットインスタンスのAuto Scalingグループで動かしています。<b>容量不足や中断で処理が止まる</b>ことが多く、改善したいと考えています。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"複数のインスタンスタイプとAZを指定する（price-capacity-optimized）"},{"l":"B","html":"最も安い1種類のインスタンスタイプだけを指定する"},{"l":"C","html":"上限価格をオンデマンド料金の10倍に設定して中断を防ぐ"},{"l":"D","html":"中断通知を受けて、処理中の仕事をキューに戻す"},{"l":"E","html":"ワーカーをデータベースのプライマリと同じインスタンスで動かす"}],"answer":["A","D"],"multi":true,"req":"","key":"スポットは、<b>使えるインスタンスタイプとAZを広げ、空き容量が多く価格も低いプールを選ぶ</b>（price-capacity-optimized）ほど中断されにくくなります。そのうえで、中断の<b>2分前の通知</b>を受けて処理を安全に手放せば、中断されても仕事は失われません。","kw":"price-capacity-optimized／スポットの中断通知","reasons":[{"l":"B","html":"1種類に絞ると、そのプールの容量がなくなったときにすべてが止まります。"},{"l":"C","html":"スポットの中断は主にAWS側の容量の回収で起きるため、上限価格を上げても防げません。"},{"l":"E","html":"中断されるインスタンスに、中断されてはいけないデータベースを載せるのは誤りです。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":5,"topic":"一部の利用者で試すデプロイ","level":2,"body":["Elastic Beanstalkで運用しているWebアプリケーションの新バージョンを、まず<b>全体の10%のトラフィック</b>で一定時間試し、エラーが増えなければ残りを切り替えたいと考えています。問題があれば自動で元に戻したいと考えています。最も適切なデプロイポリシーはどれですか。"],"options":[{"l":"A","html":"一括（All at once）"},{"l":"B","html":"ローリング（Rolling）"},{"l":"C","html":"追加バッチによるローリング（Rolling with additional batch）"},{"l":"D","html":"トラフィック分割（Traffic splitting）"}],"answer":["D"],"multi":false,"req":"","key":"トラフィック分割は、新しいバージョンのインスタンス群を別に起動し、<b>指定した割合のトラフィックだけを一定時間流して正常性を評価</b>します。問題がなければ全体を切り替え、問題があれば新しいインスタンスを捨てて元に戻します。カナリアリリースをBeanstalkで行う方法です。","kw":"トラフィック分割（Traffic splitting）","reasons":[{"l":"A","html":"全インスタンスを一度に更新するため、一部の利用者で試すことはできず、ダウンタイムも発生します。"},{"l":"B","html":"インスタンス単位で順番に入れ替えるだけで、割合を指定した試験や自動の切り戻しはできません。"},{"l":"C","html":"処理能力を保ちながら順に入れ替える方式で、割合を指定した試験にはなりません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.3 AWS Elastic Beanstalk</a>"},{"n":6,"topic":"時間帯で変わるコールドスタート対策","level":3,"body":["Lambda関数で提供するAPIは、<b>平日の9時から18時</b>に利用が集中し、その時間帯はコールドスタートの遅延を避けたいと考えています。夜間と週末は利用がほとんどなく、その時間帯のコストは抑えたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"プロビジョニング済み同時実行数を、ピーク時の台数に合わせて24時間設定しておく"},{"l":"B","html":"予約済み同時実行数を大きく設定する"},{"l":"C","html":"EventBridgeで5分ごとにダミーのリクエストを送り、関数を温めておく"},{"l":"D","html":"平日の日中だけ、プロビジョニング済み同時実行数を増やす"}],"answer":["D"],"multi":false,"req":"","key":"プロビジョニング済み同時実行数は、Application Auto Scalingで<b>スケジュールや使用率に応じて増減</b>できます。利用が集中する時間帯だけ実行環境を事前に用意しておけば、コールドスタートを避けつつ、夜間と週末のコストを抑えられます。","kw":"プロビジョニング済み同時実行数／Application Auto Scalingのスケジュール","reasons":[{"l":"A","html":"使わない時間帯もプロビジョニング済み同時実行数の料金がかかり続けます。"},{"l":"B","html":"予約済み同時実行数は同時実行数の上限を確保する設定で、実行環境を事前に初期化しないため、コールドスタートは防げません。"},{"l":"C","html":"温められる実行環境は一部だけで、同時に多数のリクエストが来ると新しい実行環境でコールドスタートが起きます。確実な方法ではありません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.6 AWS Lambda</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.2 コンピューティングとパフォーマンス</a>"},{"n":7,"topic":"共通ライブラリの共有","level":1,"body":["20個のLambda関数が、同じ社内ライブラリと外部パッケージを使っています。現在は関数ごとにデプロイパッケージへ含めており、ライブラリを更新するたびに20個すべてを作り直しています。最も適切な改善策はどれですか。"],"options":[{"l":"A","html":"20個の関数を1つの関数に統合し、ライブラリを1か所にまとめる"},{"l":"B","html":"ライブラリを環境変数に格納する"},{"l":"C","html":"共通ライブラリをLambdaレイヤーにまとめる"},{"l":"D","html":"関数の実行時に、毎回S3からライブラリをダウンロードする"}],"answer":["C"],"multi":false,"req":"","key":"Lambdaレイヤーは、<b>複数の関数で共通のライブラリやランタイムの依存関係を共有</b>するための仕組みです。ライブラリを1か所で管理でき、各関数のデプロイパッケージも小さくなります。","kw":"Lambdaレイヤー","reasons":[{"l":"A","html":"役割の違う処理が1つにまとまり、変更の影響範囲が広がります。"},{"l":"B","html":"環境変数はコードやライブラリを置く場所ではなく、容量も小さすぎます。"},{"l":"D","html":"実行のたびにダウンロードが発生して遅くなり、コストも増えます。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.6 AWS Lambda</a>"},{"n":8,"topic":"APIの応答のキャッシュ","level":2,"body":["API Gateway（REST API）＋Lambdaで、商品カテゴリの一覧を返すAPIを提供しています。一覧は<b>1日に数回しか変わらない</b>のに、毎回Lambdaとデータベースが呼ばれ、コストと応答時間が問題になっています。コードの変更を最小限にして改善したいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"Lambda関数のメモリを増やして、1回あたりの処理時間を短くする"},{"l":"B","html":"API Gatewayのキャッシュを有効にする"},{"l":"C","html":"HTTP APIに移行する"},{"l":"D","html":"データベースのリードレプリカを追加し、読み取りを分散する"}],"answer":["B"],"multi":false,"req":"","key":"REST APIのステージでキャッシュを有効にすると、<b>同じリクエストへの応答をTTLの間キャッシュから返し</b>、バックエンドの呼び出しを減らせます。メソッドごとにTTLやキャッシュの有無を変えられるため、変化の少ないAPIだけに適用できます。コードの変更も不要です。","kw":"API Gatewayのキャッシュ","reasons":[{"l":"A","html":"多少速くなっても、呼び出しの回数とデータベースへの負荷は減りません。"},{"l":"C","html":"HTTP APIは安価ですが、API Gatewayのキャッシュ機能を持たないため、この問題の解決になりません。"},{"l":"D","html":"データベースの負荷は分散されますが、Lambdaの呼び出しは減らず、コストは増えます。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.1 Amazon API Gateway</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.4 ネットワークパフォーマンスの最適化</a>"},{"n":9,"topic":"コンテナの実行基盤の組み合わせ","level":3,"body":["ECS on Fargateで、キューのメッセージを処理するワーカーを動かしています。<b>最低2つのタスクは確実に動かし</b>、それを超える分はできるだけ安く動かしたいと考えています。ワーカーは中断されても、処理中のメッセージがキューに戻るため問題ありません。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"サービスのキャパシティプロバイダー戦略で、FARGATEにベース2を設定し、それを超える分はFARGATE_SPOTの重みを大きくする"},{"l":"B","html":"すべてのタスクをFargate Spotで実行する"},{"l":"C","html":"すべてのタスクをFargateで実行する"},{"l":"D","html":"EC2起動タイプに変更し、スポットインスタンスで動かす"}],"answer":["A"],"multi":false,"req":"","key":"キャパシティプロバイダー戦略では、<b>ベース</b>（最低限そのプロバイダーで動かすタスク数）と<b>重み</b>（それを超える分の配分比）を指定できます。FARGATEにベース2を置けば最低限の処理は中断されず、超える分をFARGATE_SPOTに多く配分すればコストを抑えられます。","kw":"キャパシティプロバイダー戦略（ベースと重み）","reasons":[{"l":"B","html":"すべてが同時に中断されると、最低2タスクという要件を満たせません。"},{"l":"C","html":"確実ですが、中断を許容できる分までFargateの料金を払うことになります。"},{"l":"D","html":"インスタンスの管理が必要になり、すべてがスポットでは最低2タスクも保証されません。"}],"refs":"<a href=\"#container\" data-go=\"container\">第9章 9.3 AWS Fargate</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":10,"topic":"必要なときに確実に起動","level":2,"body":["年に一度の大型セール（3日間）では、<b>東京リージョンの特定のAZ</b>で、あるインスタンスタイプを100台確実に起動できる必要があります。過去に容量不足で起動できなかったことがあります。長期の契約はしたくありません。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"スポットインスタンスで100台を起動する"},{"l":"B","html":"その期間だけオンデマンドキャパシティ予約を作成する"},{"l":"C","html":"3年のリザーブドインスタンス（リージョン）を購入する"},{"l":"D","html":"Compute Savings Plansを購入する"}],"answer":["B"],"multi":false,"req":"","key":"オンデマンドキャパシティ予約は、<b>特定のAZで特定のインスタンスタイプの容量を、期間の約束なしに確保</b>できます。必要な期間だけ作成し、終われば解除できます（予約中は使わなくてもオンデマンド料金がかかります）。","kw":"オンデマンドキャパシティ予約","reasons":[{"l":"A","html":"スポットは容量が保証されず、中断される可能性もあります。"},{"l":"C","html":"リージョン単位のリザーブドインスタンスは割引であり、容量は予約されません。3年の契約も要件に反します。"},{"l":"D","html":"Savings Plansは料金の割引の約束で、容量は確保されません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a>"}]},{"id":"exam-set-27","file":"set-27.md","num":"問題セット27","title":"頻出⑤ 2周目：データベースと分析の細目","questions":[{"n":1,"topic":"リージョン障害への備え","level":2,"body":["RDS for PostgreSQLで業務システムを運用しています。<b>リージョン全体の障害</b>に備え、別のリージョンで<b>数分程度のデータ損失で</b>データベースを再開できるようにしたいと考えています。コストはできるだけ抑えたいと考えています。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"別リージョンにリードレプリカを作り、障害時に昇格させる"},{"l":"B","html":"マルチAZ DBインスタンス配置に変更し、別のAZにスタンバイを置く"},{"l":"C","html":"自動バックアップの保持期間を35日にする"},{"l":"D","html":"毎日の手動スナップショットを別のリージョンへコピーする"}],"answer":["A"],"multi":false,"req":"","key":"クロスリージョンリードレプリカは、別のリージョンへ<b>非同期で継続的に複製</b>するため、損失は複製の遅れ（通常は秒〜数分）に収まります。リージョン障害時にはレプリカを昇格させて独立したデータベースとして使います（昇格は手動、または自動化の仕組みで行います）。","kw":"クロスリージョンリードレプリカ","reasons":[{"l":"B","html":"マルチAZは同じリージョン内のAZ障害への備えで、リージョン全体の障害には効きません。"},{"l":"C","html":"バックアップは同じリージョン内に保存されるため、リージョン障害時に使えません。"},{"l":"D","html":"日次のコピーでは最大1日分のデータを失い、「数分程度」という要件を満たせません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":2,"topic":"読み取りの増減への追従","level":2,"body":["Aurora MySQLの読み取りは、キャンペーンの時期に数倍に増え、普段は少なくなります。現在はリードレプリカを最大の台数で常に動かしています。<b>負荷に合わせてレプリカの台数を自動で増減</b>させたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"Aurora Auto Scalingで、レプリカの平均CPU使用率を目標にして台数を調整する"},{"l":"B","html":"EC2 Auto Scalingグループでレプリカを管理する"},{"l":"C","html":"プライマリのインスタンスクラスを大きくする"},{"l":"D","html":"クラスターエンドポイントの数を増やす"}],"answer":["A"],"multi":false,"req":"","key":"Aurora Auto Scalingは、<b>レプリカの平均CPU使用率や接続数を目標値にして、Auroraレプリカを自動で追加・削除</b>します。追加されたレプリカはリーダーエンドポイントの振り分け先にも自動で入ります。","kw":"Aurora Auto Scaling","reasons":[{"l":"B","html":"AuroraのレプリカはEC2 Auto Scalingグループでは管理できません。"},{"l":"C","html":"プライマリを大きくしても、読み取りを分散する仕組みにはなりません。常にコストもかかります。"},{"l":"D","html":"エンドポイントは接続先の名前であり、数を増やしても処理能力は増えません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.2 Amazon Aurora</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a>"},{"n":3,"topic":"読めない負荷","level":1,"body":["新しいモバイルアプリのバックエンドにDynamoDBを使います。リリース後の利用者数は<b>まったく予測できず</b>、急に数十倍に増える可能性もあります。キャパシティの見積もりや調整はしたくありません。最も適切な設定はどれですか。"],"options":[{"l":"A","html":"プロビジョンドモードで、想定の最大値に合わせて容量を設定する"},{"l":"B","html":"プロビジョンドモードで、Auto Scalingを設定する"},{"l":"C","html":"DAXを導入して容量の不足を補う"},{"l":"D","html":"オンデマンドモードを使う"}],"answer":["D"],"multi":false,"req":"","key":"オンデマンドモードは<b>リクエスト数に応じた完全な従量課金</b>で、容量の見積もりが不要です。予測できないトラフィックや急な増加に向いています。利用が安定して予測できるようになったら、プロビジョンドモードへの切り替えでコストを下げることを検討します。","kw":"DynamoDBのオンデマンドモード","reasons":[{"l":"A","html":"最大値に合わせると普段は大半が無駄になり、見積もりを外すと不足します。"},{"l":"B","html":"Auto Scalingは容量の調整に時間がかかり、急な数十倍の増加には追いつかない場合があります。見積もりの手間も残ります。"},{"l":"C","html":"DAXは読み取りのキャッシュで、書き込みの容量不足は補えません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a>"},{"n":4,"topic":"期限切れデータの自動削除","level":1,"body":["Webアプリケーションのセッション情報をDynamoDBに保存しています。<b>最終アクセスから24時間たったセッション</b>は不要になりますが、削除用のバッチ処理の運用とコストが負担になっています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"毎時、Lambda関数でScanして期限切れの項目を削除する"},{"l":"B","html":"TTLを有効にする"},{"l":"C","html":"テーブルを毎日作り直す"},{"l":"D","html":"DynamoDB Streamsで古い項目を検出し、Lambda関数で削除する"}],"answer":["B"],"multi":false,"req":"","key":"TTLを有効にすると、指定した属性の<b>時刻を過ぎた項目をDynamoDBが自動で削除</b>します。削除の書き込みキャパシティは消費せず、追加の料金もかかりません（削除は即時ではなく、期限後しばらくしてから行われます）。","kw":"DynamoDBのTTL","reasons":[{"l":"A","html":"Scanは読み取りのキャパシティを大量に消費し、バッチの運用も残ります。"},{"l":"C","html":"有効なセッションまで消えてしまいます。"},{"l":"D","html":"Streamsは変更を受け取る仕組みで、古い項目を検出する機能はありません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a>"},{"n":5,"topic":"複数の項目をまとめて更新","level":2,"body":["ポイント交換の処理で、DynamoDBの<b>利用者のポイント残高を減らす</b>ことと、<b>交換履歴の項目を追加する</b>ことを、<b>両方成功するか、両方失敗するか</b>のどちらかにしたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"<code>TransactWriteItems</code> で2つの操作を1つのトランザクションにする"},{"l":"B","html":"<code>BatchWriteItem</code> で2つの書き込みをまとめて送る"},{"l":"C","html":"2回の <code>PutItem</code> を順番に実行し、2回目が失敗したら1回目を手動で戻す"},{"l":"D","html":"グローバルテーブルを使う"}],"answer":["A"],"multi":false,"req":"","key":"<code>TransactWriteItems</code> は、複数の項目への書き込みを<b>すべて成功するか、すべて失敗するか</b>のどちらかにするトランザクションです。「残高が足りる場合だけ」といった条件チェックも一緒に書けます。","kw":"TransactWriteItems","reasons":[{"l":"B","html":"<code>BatchWriteItem</code> はまとめて送るだけで、一部が失敗しても残りは成功します。原子性はありません。"},{"l":"C","html":"途中で失敗したときの取り消しを自前で実装する必要があり、その取り消しが失敗すると不整合が残ります。"},{"l":"D","html":"グローバルテーブルは複数リージョンへの複製で、項目をまたぐ原子性とは関係ありません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a>"},{"n":6,"topic":"キャッシュの古いデータ","level":2,"body":["ElastiCache for Redisで商品情報を<b>遅延読み込み</b>（キャッシュになければDBから読んでキャッシュする）方式でキャッシュしています。価格を変更しても、<b>しばらく古い価格が表示される</b>という苦情が出ています。読み取りの性能は維持したまま、変更がすぐに反映されるようにしたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"キャッシュを使うのをやめ、すべての読み取りをデータベースから直接行う"},{"l":"B","html":"TTLを数日に延ばし、キャッシュのヒット率を上げる"},{"l":"C","html":"更新時にキャッシュも書き換える書き込みスルーを組み合わせる"},{"l":"D","html":"Memcachedへ移行し、複数ノードで読み取りを分散する"}],"answer":["C"],"multi":false,"req":"","key":"遅延読み込みだけでは、<b>TTLが切れるまで古い値が残ります</b>。更新のときにキャッシュも書き換える<b>書き込みスルー</b>を組み合わせれば、変更がすぐに反映されます。TTLも併用しておくと、更新の取りこぼしがあっても一定時間で解消されます。","kw":"書き込みスルー","reasons":[{"l":"A","html":"読み取りの性能を維持するという要件に反し、DBの負荷も増えます。"},{"l":"B","html":"古い値が残る時間がさらに長くなります。"},{"l":"D","html":"エンジンを変えても、キャッシュの更新方式の問題は解決しません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.4 Amazon ElastiCache</a>"},{"n":7,"topic":"ストレージの枯渇","level":2,"body":["RDS for MySQLで、データが想定以上の速さで増え、<b>ストレージの空き容量が尽きて</b>書き込みが止まりかける事態が起きました。今後は、容量が不足しそうになったら<b>停止せずに自動で拡張</b>されるようにしたいと考えています。最も適切な設定はどれですか。"],"options":[{"l":"A","html":"マルチAZ配置に変更し、スタンバイにも同じ容量を持たせる"},{"l":"B","html":"ストレージの自動スケーリングを有効にする"},{"l":"C","html":"リードレプリカを追加する"},{"l":"D","html":"空き容量のアラームを設定し、通知を受けたら手動で拡張する"}],"answer":["B"],"multi":false,"req":"","key":"RDSのストレージの自動スケーリングは、<b>空き容量が少なくなると自動でストレージを拡張</b>し、停止は発生しません。上限を設定しておけば、予期しない増加でコストが膨らみすぎることも防げます。","kw":"RDSのストレージの自動スケーリング","reasons":[{"l":"A","html":"可用性の対策で、ストレージの容量は増えません。"},{"l":"C","html":"読み取りの分散で、プライマリのストレージの問題は解決しません。"},{"l":"D","html":"夜間や休日の対応が遅れる危険があり、自動化の要件を満たしません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a>"},{"n":8,"topic":"部門をまたぐデータの共有","level":3,"body":["全社のデータウェアハウス（Redshift）のデータを、マーケティング部門が<b>自部門のRedshift</b>からも参照したいと考えています。データを<b>コピーせず</b>、常に<b>最新のデータ</b>を参照でき、マーケティング部門のクエリが全社のクラスターの性能に影響しないようにしたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"毎晩、全社のRedshiftからS3にアンロードし、マーケティング部門のRedshiftにロードする"},{"l":"B","html":"マーケティング部門の担当者に、全社のRedshiftのユーザーを発行する"},{"l":"C","html":"全社のRedshiftにマーケティング部門用のノードを追加する"},{"l":"D","html":"Redshiftのデータ共有で、全社のデータを直接参照する"}],"answer":["D"],"multi":false,"req":"","key":"Redshiftのデータ共有は、<b>データをコピーせずに、別のクラスター（またはServerless）から最新のデータを読める</b>機能です。クエリは参照する側のコンピューティングで実行されるため、全社のクラスターの性能に影響しません（RA3ノードまたはServerlessが前提です）。","kw":"Redshiftのデータ共有","reasons":[{"l":"A","html":"データがコピーされ、最新の状態にもなりません。"},{"l":"B","html":"マーケティング部門のクエリが全社のクラスターで実行され、性能に影響します。"},{"l":"C","html":"全社のクラスターのコストが増え、処理の分離にもなりません。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.4 Amazon Redshift</a>"},{"n":9,"topic":"データレイクの列単位の権限","level":2,"body":["S3のデータレイクを、AthenaとRedshift Spectrumから複数の部署が参照しています。人事部以外は、<b>給与や個人番号などの特定の列を参照できない</b>ようにしたいと考えています。分析エンジンごとに個別に設定するのは避けたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"部署ごとに、該当の列を除いたコピーをS3に作る"},{"l":"B","html":"S3のバケットポリシーで、部署ごとに列単位のアクセスを制御する"},{"l":"C","html":"Lake Formationで、列単位の権限を部署ごとに付ける"},{"l":"D","html":"IAMポリシーの条件で、Athenaのクエリに含まれる列名を制限する"}],"answer":["C"],"multi":false,"req":"","key":"Lake Formationは、データカタログのテーブルに対して<b>列・行・セル単位のきめ細かな権限</b>を定義でき、Athena・Redshift Spectrum・EMRなどの分析エンジンに<b>共通して適用</b>されます。エンジンごとに設定する必要がありません。","kw":"AWS Lake Formation（列単位のアクセス許可）","reasons":[{"l":"A","html":"データが重複し、同期と管理の負担が増えます。"},{"l":"B","html":"S3のポリシーはオブジェクト（ファイル）単位の制御で、ファイルの中の列までは制御できません。"},{"l":"D","html":"クエリの文字列による制限は回避しやすく、エンジンごとの設定にもなります。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.7 AWS Lake Formation</a>"},{"n":10,"topic":"BIダッシュボードの性能と権限","level":2,"body":["QuickSightで全社向けの売上ダッシュボードを公開します。要件は、(1) 表示が遅く、元のデータベースへの負荷も高いので<b>表示を速くし負荷を下げる</b>こと、(2) 各支店の担当者には<b>自分の支店の行だけ</b>を見せること、です。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"支店ごとに別々のダッシュボードを作り、それぞれの支店に共有する"},{"l":"B","html":"データセットをSPICEに取り込み、定期的に更新する"},{"l":"C","html":"ダッシュボードをPDFで毎日配布する"},{"l":"D","html":"元のデータベースのインスタンスクラスを大きくする"},{"l":"E","html":"データセットに行レベルセキュリティ（RLS）を設定する"}],"answer":["B","E"],"multi":true,"req":"","key":"SPICEはQuickSightに内蔵されたインメモリの計算エンジンで、<b>データを取り込んでおけば表示が速くなり、元のデータベースにも毎回問い合わせません</b>。行レベルセキュリティは、利用者やグループの属性に応じて<b>見られる行を自動で絞り込み</b>、1つのダッシュボードで支店ごとの見せ分けを実現します。","kw":"SPICE／行レベルセキュリティ（RLS）","reasons":[{"l":"A","html":"支店の数だけダッシュボードを作ることになり、管理が大変です。"},{"l":"C","html":"対話的に分析できなくなり、支店ごとの見せ分けも手作業になります。"},{"l":"D","html":"表示は速くなるかもしれませんが、元のデータベースへの負荷の問題は残り、コストも増えます。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.5 Amazon QuickSight</a>"}]},{"id":"exam-set-28","file":"set-28.md","num":"問題セット28","title":"頻出⑥ 2周目：セキュリティ運用・IaC・エッジ・AI","questions":[{"n":1,"topic":"証明書の自動更新","level":2,"body":["ACMで発行したパブリック証明書を<b>Eメール検証</b>で取得したところ、更新の時期に担当者がメールを見落とし、証明書の期限切れが起きかけました。今後は<b>人の操作なしで自動更新</b>されるようにしたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"更新のメールを複数の担当者に届くようにする"},{"l":"B","html":"証明書をエクスポートして、自分で更新スクリプトを作る"},{"l":"C","html":"有効期間の長いサードパーティの証明書をインポートする"},{"l":"D","html":"DNS検証で取得し直し、CNAMEレコードを残す"}],"answer":["D"],"multi":false,"req":"","key":"DNS検証で発行した証明書は、<b>検証用のCNAMEレコードが残っている限り、ACMが自動で更新</b>します（Route 53を使っていれば、レコードの作成も自動化できます）。Eメール検証では更新のたびに承認の操作が必要です。","kw":"ACMのDNS検証","reasons":[{"l":"A","html":"人の操作が必要な状態は変わらず、見落としの危険も残ります。"},{"l":"B","html":"更新と再配置を自分で管理することになり、手間が増えます。"},{"l":"C","html":"インポートした証明書はACMが自動更新しないため、期限の管理が必要なままです。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.7 AWS Certificate Manager</a>"},{"n":2,"topic":"ボットによる不正アクセス","level":2,"body":["ECサイトで、<b>スクレイピングや在庫の買い占めを行うボット</b>のアクセスが急増しています。一般的なクローラー（検索エンジンなど）は許可しつつ、悪質なボットを抑えたいと考えています。サイトはCloudFrontとALBで公開しています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"ネットワークACLで、アクセスの多いIPアドレスを拒否する"},{"l":"B","html":"AWS WAFのBot ControlのマネージドルールをWeb ACLに追加する"},{"l":"C","html":"Shield Advancedを有効にする"},{"l":"D","html":"ALBのセキュリティグループで、海外のIPアドレスを拒否する"}],"answer":["B"],"multi":false,"req":"","key":"WAFのBot Controlは、リクエストの特徴から<b>ボットを識別・分類</b>し、検索エンジンなどの<b>検証済みのボットは許可したまま</b>、悪質なボットをブロックしたりCAPTCHAを出したりできます。","kw":"AWS WAF Bot Control","reasons":[{"l":"A","html":"ボットはIPアドレスを変え続けるため追いつかず、CloudFront経由の通信ではALBに届く送信元はCloudFrontのIPアドレスです。"},{"l":"C","html":"Shield AdvancedはDDoS攻撃への対策で、ボットの識別は行いません。"},{"l":"D","html":"セキュリティグループには拒否ルールがなく、国単位の制御もできません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.5 AWS WAF</a>"},{"n":3,"topic":"マルウェアの調査","level":2,"body":["GuardDutyで、あるEC2インスタンスについて「<b>マルウェアに感染している可能性</b>」を示す検出結果が出ました。インスタンスに<b>エージェントを入れずに</b>、接続されたEBSボリュームにマルウェアがあるかを確認したいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"GuardDutyのMalware Protectionを使う"},{"l":"B","html":"Amazon Inspectorで、インスタンスの脆弱性をスキャンする"},{"l":"C","html":"Amazon Macieで、インスタンスのディスクをスキャンする"},{"l":"D","html":"VPCフローログで、通信の内容を確認する"}],"answer":["A"],"multi":false,"req":"","key":"GuardDutyのMalware Protectionは、インスタンスに接続された<b>EBSボリュームのスナップショットを取得してエージェントなしでスキャン</b>し、マルウェアを検出します。GuardDutyの検出結果をきっかけに自動で実行することも、必要なときに実行することもできます。","kw":"GuardDuty Malware Protection","reasons":[{"l":"B","html":"Inspectorはソフトウェアの既知の脆弱性を評価するもので、マルウェアの検出はしません。"},{"l":"C","html":"MacieはS3の中の機密データを検出するサービスで、EBSのスキャンはしません。"},{"l":"D","html":"フローログは通信のメタデータで、ディスクの内容やマルウェアの有無はわかりません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.11 Amazon GuardDuty</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.13 検出系の整理</a>"},{"n":4,"topic":"コンテナと関数の脆弱性","level":2,"body":["ECRに保存しているコンテナイメージと、Lambda関数で使っているライブラリについて、<b>新しい脆弱性（CVE）が公開されたときにすぐ気づけるよう</b>にしたいと考えています。プッシュ時の1回きりのスキャンでは、後から見つかった脆弱性を検知できません。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"GuardDutyを有効にする"},{"l":"B","html":"Amazon Inspectorの継続的スキャンを有効にする"},{"l":"C","html":"AWS Configのルールでイメージのタグを確認する"},{"l":"D","html":"ECRの基本スキャンを、イメージをプッシュするたびに実行する"}],"answer":["B"],"multi":false,"req":"","key":"Amazon Inspectorは、ECRのイメージとLambda関数を<b>継続的に評価</b>し、新しいCVEが公開されると、既存のイメージや関数についても<b>自動で再評価</b>します。プッシュ時だけのスキャンでは見落とす「後から見つかった脆弱性」に対応できます。","kw":"Amazon Inspector","reasons":[{"l":"A","html":"GuardDutyは脅威の検知で、ソフトウェアの脆弱性の評価はしません。"},{"l":"C","html":"Configはリソースの設定の評価で、イメージの中身の脆弱性はわかりません。"},{"l":"D","html":"プッシュ時のスキャンだけでは、その後に公開された脆弱性を検知できません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.12 Amazon Inspector</a> ／ <a href=\"#container\" data-go=\"container\">第9章 9.4 Amazon ECR</a>"},{"n":5,"topic":"手作業の変更の発見","level":2,"body":["CloudFormationで構築した本番環境について、「<b>誰かがコンソールからセキュリティグループのルールを直接変更した</b>のではないか」という疑いがあります。テンプレートの定義と実際の設定の違いを確認したいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"変更セットを作成する"},{"l":"B","html":"スタックを削除して作り直す"},{"l":"C","html":"スタックのドリフト検出を実行する"},{"l":"D","html":"スタックのイベント履歴を確認する"}],"answer":["C"],"multi":false,"req":"","key":"ドリフト検出は、スタックのリソースの<b>実際の設定がテンプレートの定義と違っていないか</b>を調べ、違いがあった項目を表示します。コンソールなどでの手作業の変更を見つけるための機能です（誰が変えたかはCloudTrailで確認します）。","kw":"ドリフト検出","reasons":[{"l":"A","html":"変更セットは、テンプレートを<b>これから更新する</b>ときの影響の確認で、手作業の変更の検出ではありません。"},{"l":"B","html":"本番環境を作り直すことになり、影響が大きすぎます。"},{"l":"D","html":"イベント履歴はCloudFormationが行った操作の記録で、スタックの外で行われた変更は記録されません。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.3 AWS CloudFormation</a>"},{"n":6,"topic":"更新前の影響確認","level":2,"body":["本番のCloudFormationスタックで、RDSのプロパティを変更するテンプレートの更新を行います。変更によっては<b>RDSインスタンスが作り直される（置き換え）</b>可能性があると聞き、実行前に確認したいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"ドリフト検出を実行する"},{"l":"B","html":"テンプレートをそのまま適用し、問題があればロールバックする"},{"l":"C","html":"変更セットを作成し、内容を確認してから実行する"},{"l":"D","html":"スタックポリシーを削除する"}],"answer":["C"],"multi":false,"req":"","key":"変更セットは、テンプレートを更新したときに<b>どのリソースが追加・変更・削除されるか、置き換えが起きるか</b>を実行前に表示します。確認して問題がなければ、その変更セットを実行します。本番のデータベースのように置き換えが致命的なリソースでは必須の手順です（DeletionPolicyやスタックポリシーによる保護も併用します）。","kw":"変更セット","reasons":[{"l":"A","html":"ドリフト検出は、手作業の変更による現在の差分を調べるもので、これから行う更新の影響は示しません。"},{"l":"B","html":"置き換えが起きるとデータが失われる可能性があり、ロールバックでは元に戻らない場合があります。"},{"l":"D","html":"スタックポリシーは意図しない更新を防ぐ保護です。削除すると保護が弱まるだけです。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.3 AWS CloudFormation</a>"},{"n":7,"topic":"投稿画像の審査","level":2,"body":["SNSアプリで、利用者が投稿した画像に<b>暴力的・性的な内容が含まれていないか</b>を、投稿時に自動で判定したいと考えています。機械学習のモデルを自分で学習させる余裕はありません。最も適切なサービスはどれですか。"],"options":[{"l":"A","html":"Amazon Rekognitionのコンテンツモデレーション"},{"l":"B","html":"Amazon Comprehend"},{"l":"C","html":"Amazon SageMakerで独自のモデルを学習させる"},{"l":"D","html":"Amazon Textract"}],"answer":["A"],"multi":false,"req":"","key":"Rekognitionの不適切コンテンツの検出（コンテンツモデレーション）は、<b>学習済みのモデルで画像の不適切な要素を分類</b>し、信頼度とともに返します。投稿時にAPIを呼び出すだけで、独自のモデルは不要です。「画像・動画の解析」は Rekognition です。","kw":"Amazon Rekognition（不適切コンテンツの検出）","reasons":[{"l":"B","html":"Comprehendはテキストの自然言語処理で、画像は扱いません。"},{"l":"C","html":"独自のモデルの学習が必要で、要件に反します。"},{"l":"D","html":"Textractは文書からテキストや表を抽出するサービスで、画像の内容の審査はしません。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.3〜10.8 機械学習・AIサービス</a>"},{"n":8,"topic":"社内文書を踏まえた生成AI","level":2,"body":["社内の規程集やマニュアル（S3に保存）の内容に基づいて質問に答える<b>生成AIのチャットボット</b>を作りたいと考えています。基盤モデルを自分で運用・学習させるのは避け、<b>回答の根拠として社内文書を参照</b>させたいと考えています。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"Amazon BedrockのナレッジベースでRAGを構成する"},{"l":"B","html":"Amazon Lexだけでチャットボットを作り、すべての質問と回答を手作業で登録する"},{"l":"C","html":"SageMakerで大規模言語モデルを一から学習させる"},{"l":"D","html":"Amazon Translateで文書を翻訳して公開する"}],"answer":["A"],"multi":false,"req":"","key":"Bedrockは基盤モデルをAPIで使えるサーバーレスのサービスで、ナレッジベースを使うと<b>S3の文書を取り込んでベクトル化し、質問に関連する箇所を検索して回答の根拠に使う（RAG）</b>仕組みを、マネージドで構築できます。モデルの運用や学習は不要です。","kw":"Amazon Bedrock（ナレッジベース／RAG）","reasons":[{"l":"B","html":"想定される質問と回答をすべて手作業で登録する必要があり、文書の内容に基づく柔軟な回答はできません。"},{"l":"C","html":"膨大なコストと専門知識が必要で、要件に反します。"},{"l":"D","html":"翻訳は質問への回答とは関係ありません。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.3〜10.8 機械学習・AIサービス</a>"},{"n":9,"topic":"国単位の遮断と例外","level":3,"body":["CloudFrontで配信しているサイトについて、契約上、<b>特定の国からのアクセスを遮断</b>する必要があります。ただし、その国にある<b>提携先のオフィス（固定のIPアドレス）</b>からのアクセスだけは許可しなければなりません。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"CloudFrontの地理的制限で対象の国を拒否する"},{"l":"B","html":"Route 53の位置情報ルーティングで、対象の国からの問い合わせにエラーを返す"},{"l":"C","html":"オリジンのALBのセキュリティグループで、対象の国のIPアドレスを拒否する"},{"l":"D","html":"AWS WAFで、提携先のIPセットを許可するルールを、対象の国をブロックする地理的一致ルールより優先度を高く設定する"}],"answer":["D"],"multi":false,"req":"","key":"CloudFrontの地理的制限は<b>国単位の許可・拒否だけ</b>で、特定のIPアドレスを例外にできません。WAFでは、ルールを優先度の順に評価し、<b>先に一致したルールのアクションで決まる</b>ため、提携先のIPセットを許可するルールを上位に置けば、国の遮断に例外を作れます。","kw":"AWS WAF（地理的一致ルールとIPセット、ルールの優先度）","reasons":[{"l":"A","html":"国単位の拒否しかできず、提携先のオフィスまで遮断されます。"},{"l":"B","html":"DNSの回答を変えても、ほかのDNSを使えば回避できます。アクセスの遮断の仕組みとして不確かです。"},{"l":"C","html":"セキュリティグループには拒否ルールがなく、CloudFront経由の通信では送信元もCloudFrontになります。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.5 AWS WAF</a> ／ <a href=\"#network\" data-go=\"network\">第3章 3.2 通信制御</a>"},{"n":10,"topic":"事業単位での費用の把握","level":2,"body":["AWS Organizationsの50アカウントの費用を、<b>事業部（5つ）ごと</b>に集計したいと考えています。事業部とアカウントの対応は決まっていますが、一部のアカウントは複数の事業部で共有しており、その分はリソースのタグで分ける必要があります。<b>適切な対策を2つ選択してください。</b>"],"options":[{"l":"A","html":"事業部を表すタグをコスト配分タグとして有効化する"},{"l":"B","html":"AWS Budgetsのアクションで、予算を超えたアカウントを停止する"},{"l":"C","html":"Compute Optimizerで、インスタンスのサイズを見直す"},{"l":"D","html":"Trusted Advisorで、アイドル状態のリソースを確認する"},{"l":"E","html":"AWS Cost Categoriesで、アカウントとタグの条件から事業部ごとの分類ルールを定義する"}],"answer":["A","E"],"multi":true,"req":"","key":"Cost Categoriesは、<b>アカウント・タグ・サービスなどの条件を組み合わせて、費用を独自の分類（事業部など）にまとめる</b>ルールを定義でき、Cost ExplorerやBudgetsでその分類ごとに集計できます。タグで分ける部分は、そのタグを<b>コスト配分タグとして有効化</b>しておくことが前提です。","kw":"コスト配分タグ／AWS Cost Categories","reasons":[{"l":"B","html":"予算超過時の措置で、事業部ごとの集計にはなりません。"},{"l":"C","html":"サイズの最適化の推奨で、集計の要件とは関係ありません。"},{"l":"D","html":"削減の余地を探す点検で、費用の分類とは関係ありません。"}],"refs":"<a href=\"#d4\" data-go=\"d4\">第14章 14.1 コスト管理ツールの使い分け</a> ／ <a href=\"#others\" data-go=\"others\">第10章 10.9〜10.11 コスト管理サービス</a>"}]},{"id":"exam-set-29","file":"set-29.md","num":"問題セット29","title":"実戦演習⑤（本番の分野比率・15問）","questions":[{"n":1,"topic":"コンテナからのAWS APIの呼び出し","level":2,"body":["ある企業は、Amazon ECS on Fargateでアプリケーションを動かしています。アプリケーションはAmazon S3のバケットへファイルを書き込みますが、現在はIAMユーザーのアクセスキーをコンテナイメージに含めています。セキュリティ監査で長期の認証情報の使用を指摘されました。<b>運用上のオーバーヘッドが最も少なく</b>、この指摘に対応する方法はどれですか。"],"options":[{"l":"A","html":"アクセスキーをSecrets Managerに移し、コンテナの起動時に環境変数として渡す"},{"l":"B","html":"S3への書き込み権限を持つIAMロールを作成し、タスク定義のタスク実行ロールに指定する"},{"l":"C","html":"S3への書き込み権限を持つIAMロールを作成し、タスク定義のタスクロールに指定する"},{"l":"D","html":"アクセスキーを90日ごとに自動でローテーションするLambda関数を作成する"}],"answer":["C"],"multi":false,"req":"","key":"コンテナの中のアプリケーションがAWS APIを呼ぶときの権限は<b>タスクロール</b>で渡します。ECSがロールの一時的な認証情報をコンテナへ自動で配り、期限が来れば更新するため、長期のアクセスキーが不要になります。","kw":"タスクロール（アプリの権限）とタスク実行ロール（ECSエージェントの権限）","reasons":[{"l":"A","html":"保管場所が変わっただけで、長期のアクセスキーを使い続けることになります。"},{"l":"B","html":"タスク実行ロールは、ECSがイメージの取得やログの送信、シークレットの取得を行うためのロールです。アプリケーションの権限には使いません。"},{"l":"D","html":"長期の認証情報を使う状態は変わらず、ローテーションの仕組みを保守する負荷が増えます。"}],"refs":"<a href=\"#container\" data-go=\"container\">第9章 9.1 Amazon ECS</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a>"},{"n":2,"topic":"会員限定の動画配信","level":2,"body":["動画学習サービスは、S3に保存した講座の動画をCloudFrontで配信しています。1つの講座は数百の動画ファイルとプレイリストで構成されます。<b>有料会員だけ</b>が視聴でき、S3のバケットには直接アクセスできないようにする必要があります。既存の動画のURLは変更したくありません。最も適切な組み合わせはどれですか。"],"options":[{"l":"A","html":"OACでバケットを非公開にし、署名付きCookieを会員に発行する"},{"l":"B","html":"OACでバケットを非公開にし、動画ファイルごとに署名付きURLを発行する"},{"l":"C","html":"バケットを公開したまま、CloudFrontの地理的制限で国内からのアクセスだけを許可する"},{"l":"D","html":"S3の事前署名URLを発行し、CloudFrontを経由せずに配信する"}],"answer":["A"],"multi":false,"req":"①会員だけに見せる ②バケットへの直接アクセスを防ぐ ③多数のファイル・URLは変えない","key":"②はOACとバケットポリシーで満たします。①③は、<b>多数のファイルへのアクセスをまとめて許可でき、URLを変えずに済む署名付きCookie</b>が適しています。署名付きURLは1ファイルごとに発行するもので、URLそのものが変わります。","kw":"署名付きCookie（複数ファイル・URLを変えない）／署名付きURL（個別のファイル）","reasons":[{"l":"B","html":"数百のファイルごとにURLを発行し直す必要があり、URLも変わるため要件③に反します。"},{"l":"C","html":"地理的制限は国単位の制御で、会員かどうかは判定できません。バケットを公開したままでは要件②も満たしません。"},{"l":"D","html":"CloudFrontのキャッシュを使わなくなり、配信の性能とコストが悪化します。ファイルごとの発行という問題も残ります。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 コンテンツ配信と高速化</a> ／ <a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a>"},{"n":3,"topic":"SSE-KMSのリクエスト料金","level":2,"body":["ある企業は、S3バケットの既定の暗号化にSSE-KMS（カスタマー管理キー）を使っています。数百万の小さなオブジェクトを頻繁に書き込み・読み込みするようになってから、<b>KMSへのリクエスト料金が急増し、KMSのスロットリングも発生</b>しています。暗号化の要件は変えずに、<b>最もコスト効率よく</b>この問題を解消する方法はどれですか。"],"options":[{"l":"A","html":"暗号化の方式をSSE-S3に変更する"},{"l":"B","html":"KMSのリクエストクォータの引き上げを申請し、料金はそのまま受け入れる"},{"l":"C","html":"クライアント側暗号化に切り替え、アプリケーションで鍵を管理する"},{"l":"D","html":"バケットでS3バケットキーを有効にする"}],"answer":["D"],"multi":false,"req":"","key":"S3バケットキーを有効にすると、S3が<b>バケット単位の短期のキーをKMSから取得して使い回す</b>ため、オブジェクトごとのKMSへのリクエストが大幅に減ります（最大99%）。カスタマー管理キーによるSSE-KMSのまま、料金とスロットリングの両方を抑えられます。","kw":"S3バケットキー（KMSへのリクエストの削減）","reasons":[{"l":"A","html":"カスタマー管理キーでの暗号化という要件を満たさなくなります（キーの管理や利用の監査ができません）。"},{"l":"B","html":"スロットリングは緩和されても、増えた料金はそのままです。コスト効率の要件を満たしません。"},{"l":"C","html":"鍵の管理と暗号化の処理をアプリケーションで作り込む必要があり、運用負荷が大きく増えます。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.8 AWS KMS</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":4,"topic":"データベースの認証情報の自動更新","level":1,"body":["Amazon RDS for MySQLに接続するアプリケーションが、設定ファイルにデータベースのパスワードを平文で保持しています。セキュリティ方針により、<b>パスワードを暗号化して保管し、30日ごとに自動で変更</b>しなければなりません。<b>運用上のオーバーヘッドが最も少ない</b>方法はどれですか。"],"options":[{"l":"A","html":"パスワードをSystems Manager Parameter StoreのSecureStringに保存し、アプリケーションから取得する"},{"l":"B","html":"パスワードをSecrets Managerに保存し、RDSとの統合による自動ローテーションを30日ごとに設定する"},{"l":"C","html":"パスワードをKMSで暗号化してS3に保存し、30日ごとに担当者が変更する"},{"l":"D","html":"パスワードをEC2のユーザーデータに記述し、再起動のたびに読み込む"}],"answer":["B"],"multi":false,"req":"","key":"Secrets Managerは<b>RDSの認証情報の自動ローテーションを標準で備えて</b>おり、スケジュールを指定するだけでデータベース側のパスワードとシークレットの値を同時に変更します。保管時はKMSで暗号化されます。","kw":"自動ローテーション → Secrets Manager","reasons":[{"l":"A","html":"暗号化して保管はできますが、Parameter Storeには組み込みの自動ローテーション機能がありません。"},{"l":"C","html":"手作業の変更は運用負荷が大きく、「自動で」という要件を満たしません。"},{"l":"D","html":"ユーザーデータは暗号化されず、インスタンスから誰でも読めます。自動の変更もできません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.10 Secrets Manager vs Parameter Store</a>"},{"n":5,"topic":"アプリケーション層の攻撃","level":1,"body":["Application Load Balancer（ALB）の背後で動くWebアプリケーションに、<b>SQLインジェクションとクロスサイトスクリプティング（XSS）</b>の攻撃が繰り返し届いています。アプリケーションのコードを改修するまでの間、<b>すぐに</b>攻撃を遮断したいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"ALBのセキュリティグループで、攻撃元のIPアドレスからの通信を拒否する"},{"l":"B","html":"AWS Shield Advancedを契約する"},{"l":"C","html":"AWS WAFのWeb ACLをALBに関連付け、マネージドルールを有効にする"},{"l":"D","html":"Amazon GuardDutyを有効にし、検出結果をSNSで通知する"}],"answer":["C"],"multi":false,"req":"","key":"SQLインジェクションやXSSは<b>HTTPリクエストの中身を検査するL7の防御</b>で止めます。AWS WAFのマネージドルール（SQLデータベース用、コアルールセットなど）をALBに関連付ければ、コードを変えずにすぐ遮断できます。","kw":"SQLインジェクション・XSS → AWS WAF","reasons":[{"l":"A","html":"セキュリティグループには拒否ルールがなく、リクエストの中身も検査できません。"},{"l":"B","html":"Shield AdvancedはDDoS攻撃への対策で、SQLインジェクションなどのアプリケーション層の攻撃は防ぎません。"},{"l":"D","html":"GuardDutyは脅威の検知で、リクエストを遮断する機能はありません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.5 AWS WAF</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.3 多層防御</a>"},{"n":6,"topic":"注文の急増とワーカーの台数","level":2,"body":["ECサイトでは、Webサーバーが受けた注文をAmazon SQSのキューに入れ、Auto Scalingグループのワーカーがキューから取り出して処理しています。セール時にはキューに数万件がたまり、処理が数時間遅れます。ワーカーのCPU使用率でスケーリングしていますが、処理の多くは外部APIの待ち時間のため、<b>CPU使用率はあまり上がりません</b>。処理の遅れを解消する最も適切な方法はどれですか。"],"options":[{"l":"A","html":"ワーカーのインスタンスタイプを大きくする"},{"l":"B","html":"キューの可視性タイムアウトを短くして、メッセージを早く再処理させる"},{"l":"C","html":"CPU使用率のしきい値を5%に下げ、少しの負荷でもスケールアウトさせる"},{"l":"D","html":"インスタンスあたりの滞留数でターゲット追跡する"}],"answer":["D"],"multi":false,"req":"","key":"キューを使う構成では、<b>処理すべき仕事の量（滞留数）</b>でスケーリングするのが定石です。<code>ApproximateNumberOfMessagesVisible</code> をインスタンス数で割った値を目標値にすると、滞留が増えるほど台数が増え、許容できる遅れの範囲に収まります。","kw":"インスタンスあたりのバックログ（滞留数）でスケーリング","reasons":[{"l":"A","html":"処理の多くが待ち時間なので、1台を大きくしても処理件数はほとんど増えません。"},{"l":"B","html":"処理中のメッセージが再び見えるようになり、二重処理が増えるだけです。"},{"l":"C","html":"CPU使用率は仕事の量を表していないため、平常時の不要なスケールアウトと、急増時の遅れの両方が起きます。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a>"},{"n":7,"topic":"データベースの自動フェイルオーバー","level":1,"body":["Amazon RDS for PostgreSQLのシングルAZ構成で本番システムが動いています。AZの障害でデータベースが停止した場合でも、<b>アプリケーションの接続先を変えずに、数分以内に自動で復旧</b>させたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"別のAZにリードレプリカを作成し、障害時に手動で昇格させる"},{"l":"B","html":"マルチAZ配置に変更する"},{"l":"C","html":"自動バックアップの保持期間を延ばし、障害時にポイントインタイムリカバリで復元する"},{"l":"D","html":"毎時スナップショットを取得し、別のAZで復元するLambda関数を用意する"}],"answer":["B"],"multi":false,"req":"","key":"マルチAZ配置は、別のAZのスタンバイへ<b>同期レプリケーション</b>し、障害時には<b>自動でフェイルオーバー</b>します。エンドポイントのDNS名は変わらないため、アプリケーションの接続先を変える必要がありません。","kw":"自動フェイルオーバー・接続先を変えない → マルチAZ","reasons":[{"l":"A","html":"昇格は手動で、昇格したレプリカのエンドポイントは元と異なるため、接続先の変更が必要です。非同期のため、データの欠落も起こり得ます。"},{"l":"C","html":"新しいインスタンスとして復元されるため、時間がかかり、接続先も変わります。"},{"l":"D","html":"最大1時間分のデータを失い、復元の仕組みも自前で保守することになります。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":8,"topic":"コストを抑えた災害対策","level":3,"body":["ある企業は、東京リージョンでAurora MySQLとEC2のアプリケーションを動かしています。大阪リージョンを使った災害対策を検討しており、要件は <b>RPOは数秒、RTOは1時間以内</b>です。平常時の費用はできるだけ抑えたいと考えています。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"大阪にも同じ規模の環境を常時稼働させ、Route 53で両リージョンに振り分ける（マルチサイト）"},{"l":"B","html":"Auroraのスナップショットを毎日大阪へコピーし、災害時にAMIとCloudFormationで環境一式を作る"},{"l":"C","html":"大阪に縮小した規模のアプリケーションを常時稼働させ、災害時にスケールアウトする（ウォームスタンバイ）"},{"l":"D","html":"Auroraグローバルデータベースで大阪へ複製し、アプリケーション層は災害時にIaCで起動する（パイロットライト）"}],"answer":["D"],"multi":false,"req":"①RPO数秒 → データは常に複製しておく ②RTO1時間以内 → 起動の手順が自動化されていればよい ③平常時の費用を抑える","key":"データだけを<b>グローバルデータベースで常時複製</b>し（RPOは通常1秒程度）、アプリケーション層は止めておいて災害時にIaCで起動するのがパイロットライトです。RTOが1時間あれば起動は間に合い、平常時に払うのはデータの複製分だけです。","kw":"RPO秒・RTO数十分〜1時間・費用を抑える → パイロットライト","reasons":[{"l":"A","html":"要件は満たしますが、平常時から2倍の環境を払い続けるため、費用の要件に反します。"},{"l":"B","html":"日次のコピーではRPOが最大1日になり、要件①を満たしません（バックアップと復元）。"},{"l":"C","html":"アプリケーションを常時動かす分、パイロットライトより費用がかかります。RTO1時間という要件には過剰です。"}],"refs":"<a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a> ／ <a href=\"#database\" data-go=\"database\">第4章 4.2 Amazon Aurora</a> ／ <a href=\"#foundations\" data-go=\"foundations\">第0章 0.3 RTOとRPO</a>"},{"n":9,"topic":"Web層の高可用性","level":1,"body":["1台のEC2インスタンスで動いているWebアプリケーションを、<b>1つのAZが停止しても利用を続けられる</b>構成に変えたいと考えています。アプリケーションはステートレスです。どの組み合わせが適切ですか。（<b>2つ選択してください</b>）"],"options":[{"l":"A","html":"複数のAZのサブネットを指定したAuto Scalingグループでインスタンスを起動する"},{"l":"B","html":"インスタンスを大きなタイプに変更し、処理能力に余裕を持たせる"},{"l":"C","html":"複数のAZにまたがるApplication Load Balancerを前段に置く"},{"l":"D","html":"インスタンスをクラスタープレイスメントグループに配置する"},{"l":"E","html":"Elastic IPアドレスを割り当て、障害時にスクリプトで別のインスタンスへ付け替える"}],"answer":["A","C"],"multi":true,"req":"","key":"AZ障害に耐えるには、<b>インスタンスを複数のAZに分散させ（Auto Scalingグループ）</b>、<b>正常なインスタンスにだけ振り分ける（ALB）</b>ことが必要です。Auto Scalingグループは、停止したAZの分を残りのAZで起動し直します。","kw":"マルチAZ ＝ ALB ＋ 複数AZのAuto Scalingグループ","reasons":[{"l":"B","html":"1台のままでは、そのAZが停止すればサービスも止まります。"},{"l":"D","html":"クラスタープレイスメントグループは1つのAZの中に密集させる配置で、AZ障害にはむしろ弱くなります。"},{"l":"E","html":"手作りの切り替えは遅く壊れやすいうえ、Elastic IPは別のリージョンやAZの冗長化の仕組みではありません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.2 EC2 Auto Scaling</a> ／ <a href=\"#network\" data-go=\"network\">第3章 3.5 負荷分散</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":10,"topic":"遠隔地からの大きなファイルのアップロード","level":2,"body":["世界各地の撮影チームが、1本あたり数GBの動画ファイルを東京リージョンのS3バケットへアップロードしています。欧州と南米のチームから、<b>アップロードが遅く、途中で失敗するとやり直しになる</b>という苦情が出ています。最も適切な改善策はどれですか。"],"options":[{"l":"A","html":"各地域のリージョンにバケットを作り、クロスリージョンレプリケーションで東京へ集める"},{"l":"B","html":"Transfer Accelerationとマルチパートアップロードを使う"},{"l":"C","html":"CloudFrontのディストリビューションを作成し、キャッシュのTTLを長くする"},{"l":"D","html":"各拠点とAWSの間にSite-to-Site VPNを構成する"}],"answer":["B"],"multi":false,"req":"","key":"Transfer Accelerationは、利用者に近い<b>エッジロケーションでデータを受け、AWSのネットワークで転送</b>するため、遠距離のアップロードが速くなります。マルチパートアップロードは大きなファイルを分割して並列に送り、失敗した部分だけを再送できます。","kw":"遠距離のアップロード → Transfer Acceleration／大きなファイル・再送 → マルチパート","reasons":[{"l":"A","html":"バケットとレプリケーションの管理が増え、東京に届くまでの時間もかかります。失敗時のやり直しも解決しません。"},{"l":"C","html":"キャッシュのTTLは配信（ダウンロード）の設定で、アップロードの速度には関係ありません。"},{"l":"D","html":"VPNはインターネットを経由するため速くならず、暗号化の処理で遅くなることもあります。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":11,"topic":"同じクエリの繰り返し","level":2,"body":["商品カタログのWebアプリケーションは、Amazon RDS for MySQLから商品情報を読み込んでいます。<b>同じ商品の情報が1秒に数千回読まれ</b>、データベースのCPU使用率が高止まりしています。商品情報の更新は1日に数回です。<b>応答時間を短くし、データベースの負荷を下げる</b>最も適切な方法はどれですか。"],"options":[{"l":"A","html":"ElastiCacheに読み込み結果をキャッシュする"},{"l":"B","html":"データベースのインスタンスクラスを大きくし、ストレージをio2に変更する"},{"l":"C","html":"マルチAZ配置に変更し、スタンバイにも読み込みを分散させる"},{"l":"D","html":"商品情報をS3に保存し、アプリケーションから毎回S3を読み込む"}],"answer":["A"],"multi":false,"req":"","key":"<b>同じデータが繰り返し読まれ、更新が少ない</b>のはキャッシュが最も効く条件です。インメモリのElastiCacheから返せば応答はミリ秒未満になり、データベースに届く読み込みも大きく減ります。更新時の古い値はTTLや書き込み時の更新で抑えます。","kw":"同じ読み込みの繰り返し・更新が少ない → キャッシュ（ElastiCache）","reasons":[{"l":"B","html":"一時的には改善しても、同じ読み込みを毎回データベースで処理する構造は変わらず、コストも上がります。"},{"l":"C","html":"マルチAZ配置のスタンバイは読み込みに使えません（待機専用です）。"},{"l":"D","html":"毎回S3を読むとレイテンシが大きくなり、応答時間の要件に反します。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.4 Amazon ElastiCache</a> ／ <a href=\"#database\" data-go=\"database\">第4章 4.5 データベースの性能問題の切り分け</a>"},{"n":12,"topic":"センサーデータの取り込み","level":2,"body":["数千台のセンサーが、数秒ごとにJSON形式のデータを送信しています。データは<b>数分以内にS3へ保存</b>され、後でAthenaで分析されます。受信側のサーバーやコンシューマーのアプリケーションを<b>管理したくありません</b>。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"Kinesis Data Streamsで受け、EC2上のコンシューマーアプリケーションがS3へ書き込む"},{"l":"B","html":"SQSのキューで受け、EC2のワーカーがまとめてS3へ書き込む"},{"l":"C","html":"Amazon Data Firehoseで受け、バッファリングしてS3へ配信する"},{"l":"D","html":"センサーから直接S3へ、1件ずつPUTリクエストで書き込む"}],"answer":["C"],"multi":false,"req":"","key":"Firehoseは<b>ストリームを受けてS3などへ配信するまでをフルマネージドで</b>行います。バッファの時間やサイズでまとめて書き込むため、小さなファイルが大量にできる問題も避けられ、必要ならParquetへの変換もできます。","kw":"ストリームをS3へ・管理不要・数分の遅れは許容 → Firehose","reasons":[{"l":"A","html":"コンシューマーのアプリケーションとEC2を自分で管理する必要があります。"},{"l":"B","html":"ワーカーの管理が必要です。SQSはストリームデータの取り込みと配信の仕組みとしても向きません。"},{"l":"D","html":"小さなオブジェクトが大量にでき、リクエスト料金とAthenaでの分析効率が悪化します。センサー側に書き込みの権限も必要です。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.1 Amazon Kinesis</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":13,"topic":"ログの保存期間とストレージクラス","level":2,"body":["アプリケーションのログはS3に保存されます。ログは<b>作成から30日間は頻繁に参照</b>され、その後1年間はまれに参照されます（すぐに読める必要があります）。1年を過ぎたログは<b>監査のために7年間保管</b>し、取り出しには<b>12時間まで</b>かけてかまいません。<b>最もコスト効率の高い</b>ライフサイクルの設定はどれですか。"],"options":[{"l":"A","html":"作成時からS3 Glacier Deep Archiveに保存し、7年後に削除する"},{"l":"B","html":"30日後にS3 One Zone-IA、1年後にS3 Glacier Flexible Retrievalへ移行し、8年後に削除する"},{"l":"C","html":"作成時からS3 Intelligent-Tieringに保存し、8年後に削除する"},{"l":"D","html":"30日後にS3 Standard-IA、1年後にS3 Glacier Deep Archiveへ移行し、8年後に削除する"}],"answer":["D"],"multi":false,"req":"","key":"「30日は頻繁 → 1年はまれだがすぐ読む → 以後は取り出しに12時間かけてよい」という<b>アクセスの変化がわかっている</b>ので、ライフサイクルで順に移すのが最も安くなります。すぐ読める低頻度用はStandard-IA、12時間以内の取り出しで足りる長期保管は最も安いDeep Archiveです（標準の取り出しは12時間以内）。","kw":"アクセスの変化が既知 → ライフサイクル／12時間以内でよい長期保管 → Deep Archive","reasons":[{"l":"A","html":"最初の30日の頻繁な参照にもその後の即時の参照にも、Deep Archiveは対応できません。"},{"l":"B","html":"One Zone-IAは1つのAZにしか保存しないため、監査の証跡としての耐障害性が下がります。1年後の保管もDeep Archiveより高くなります。"},{"l":"C","html":"アクセスの変化がわかっている場合は、監視料金のかかるIntelligent-Tieringより、ライフサイクルで明示的に移すほうが安くなります。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":14,"topic":"常時稼働とバッチのコスト","level":2,"body":["ある企業のEC2の利用は次の2種類です。①24時間365日動く業務システム（今後3年は台数がほぼ一定。インスタンスファミリーは今後変える可能性がある） ②夜間に数時間動く集計バッチ（中断されても再実行すれば問題ない）。<b>コストを最も削減できる</b>組み合わせはどれですか。（<b>2つ選択してください</b>）"],"options":[{"l":"A","html":"①に3年のCompute Savings Plansを適用する"},{"l":"B","html":"①にオンデマンドキャパシティ予約を設定する"},{"l":"C","html":"②をスポットインスタンスで実行する"},{"l":"D","html":"②に3年のスタンダードリザーブドインスタンスを購入する"},{"l":"E","html":"①と②をすべてDedicated Hostsへ移行する"}],"answer":["A","C"],"multi":true,"req":"","key":"常に一定量を使う①は<b>コミットによる割引</b>が効きます。ファミリーを変える可能性があるので、変更に追従できるCompute Savings Plansが適しています。中断されても再実行できる②は、<b>最大90%安いスポットインスタンス</b>の典型的な用途です。","kw":"一定の使用量 → Savings Plans／中断を許容 → スポット","reasons":[{"l":"B","html":"キャパシティ予約は容量の確保で、それ自体に割引はありません。"},{"l":"D","html":"1日数時間しか動かないバッチに24時間分のコミットをすると、使わない時間の分が無駄になります。"},{"l":"E","html":"Dedicated Hostsはライセンスやコンプライアンスのための物理サーバー専有で、費用はむしろ上がります。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":15,"topic":"NAT Gatewayの処理料金","level":2,"body":["プライベートサブネットのEC2インスタンスが、Amazon DynamoDBへ毎日数TBの読み書きを行っています。通信はNAT Gateway経由で、<b>NAT Gatewayのデータ処理料金</b>が月額の大きな割合を占めています。<b>最もコスト効率よく</b>料金を下げる方法はどれですか。"],"options":[{"l":"A","html":"DynamoDB用のゲートウェイ型エンドポイントを作成する"},{"l":"B","html":"NAT Gatewayを各AZから1つに集約する"},{"l":"C","html":"DynamoDB用のインターフェース型VPCエンドポイントを作成する"},{"l":"D","html":"NAT GatewayをEC2のNATインスタンスに置き換える"}],"answer":["A"],"multi":false,"req":"","key":"S3とDynamoDBには<b>追加料金のかからないゲートウェイ型エンドポイント</b>があります。ルートテーブルに経路が追加され、DynamoDBへの通信がNAT Gatewayを通らなくなるため、データ処理料金がかからなくなります。","kw":"S3・DynamoDBへの通信とNATの料金 → ゲートウェイ型エンドポイント（無料）","reasons":[{"l":"B","html":"削減されるのは時間料金だけで、支配的なデータ処理料金は変わりません。AZ障害への耐性も下がります。"},{"l":"C","html":"インターフェース型は時間料金とデータ処理料金がかかります。DynamoDBならゲートウェイ型のほうが安くなります。"},{"l":"D","html":"インスタンスの管理と冗長化が必要になり、帯域も限られます。通信がNATを通ることも変わりません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.5 コスト削減の3つの観点</a>"}]},{"id":"exam-set-30","file":"set-30.md","num":"問題セット30","title":"実戦演習⑥（本番の分野比率・15問）","questions":[{"n":1,"topic":"別アカウントからの暗号化オブジェクトの読み込み","level":3,"body":["アカウントAのS3バケットは、アカウントAのKMSカスタマー管理キーによるSSE-KMSで暗号化されています。アカウントBのIAMロールに読み込みを許可するため、バケットポリシーでそのロールに <code>s3:GetObject</code> を許可し、ロール側のIAMポリシーでも <code>s3:GetObject</code> を許可しました。しかし、読み込みは <b>AccessDenied</b> で失敗します。最も適切な対処はどれですか。"],"options":[{"l":"A","html":"バケットのブロックパブリックアクセスを無効にし、オブジェクトを公開する"},{"l":"B","html":"アカウントBにも同じ名前のKMSキーを作成し、オブジェクトを再暗号化する"},{"l":"C","html":"バケットの既定の暗号化をSSE-S3に変更し、既存のオブジェクトはそのままにする"},{"l":"D","html":"キーポリシーとIAMポリシーの両方で <code>kms:Decrypt</code> を許可する"}],"answer":["D"],"multi":false,"req":"","key":"SSE-KMSのオブジェクトを読むには、S3の権限に加えて<b>KMSキーで復号する権限</b>が必要です。別のアカウントから使う場合は、<b>キーポリシー（キー側）でアカウントBを許可し、アカウントBのIAMポリシー（使う側）でも許可する</b>という、両側の許可がそろって初めて復号できます。","kw":"クロスアカウントのSSE-KMS → キーポリシーとIAMポリシーの両方で <code>kms:Decrypt</code>","reasons":[{"l":"A","html":"公開しても、KMSで暗号化されたオブジェクトは復号の権限がなければ読めません。公開すること自体も危険です。"},{"l":"B","html":"KMSキーはアカウントとリージョンに固有で、同じ名前のキーを作っても別のキーです。再暗号化の手間も大きく、目的に合いません。"},{"l":"C","html":"既定の暗号化の変更は新しいオブジェクトにしか効かず、既存のオブジェクトは読めないままです。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.8 AWS KMS</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":2,"topic":"モバイルアプリの会員認証","level":1,"body":["新しいモバイルアプリで会員登録とサインインの機能が必要です。メールアドレスでの登録に加えて、<b>GoogleやAppleのアカウントでのサインイン</b>と、<b>多要素認証（MFA）</b>にも対応したいと考えています。開発と運用の負荷を<b>最も小さく</b>する方法はどれですか。"],"options":[{"l":"A","html":"会員ごとにIAMユーザーを作成し、MFAデバイスを登録させる"},{"l":"B","html":"Amazon Cognitoのユーザープールを使う"},{"l":"C","html":"IAM Identity Centerで会員を管理し、外部IDプロバイダーを設定する"},{"l":"D","html":"EC2上に認証サーバーを構築し、会員情報をRDSに保存する"}],"answer":["B"],"multi":false,"req":"","key":"Cognitoのユーザープールは、<b>アプリの利用者（顧客）向けの会員管理</b>のサービスです。登録・サインイン・パスワードの再設定・MFAを備え、Google・Apple・Facebookなどのソーシャルログインや、SAML／OIDCのIDプロバイダーとも連携できます。","kw":"アプリの利用者の登録・サインイン・ソーシャルログイン → Cognitoユーザープール","reasons":[{"l":"A","html":"IAMユーザーはAWSを操作する人やシステムのためのもので、一般の会員の管理には使いません。上限もあります。"},{"l":"C","html":"Identity Centerは社員などの労働力（ワークフォース）がAWSアカウントや業務アプリにアクセスするためのサービスです。"},{"l":"D","html":"認証の仕組みを自前で作り、運用し続けることになります。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.4 Amazon Cognito</a>"},{"n":3,"topic":"3層構成の通信の制限","level":2,"body":["ALB、アプリケーション層のEC2（Auto Scalingグループ）、RDSの3層構成です。セキュリティ部門は、<b>データベースにはアプリケーション層からだけ</b>接続でき、<b>アプリケーション層にはALBからだけ</b>接続できるようにしたいと考えています。インスタンスは頻繁に入れ替わり、IPアドレスも変わります。最も適切な設定はどれですか。"],"options":[{"l":"A","html":"各層のセキュリティグループで、前の層のセキュリティグループをソースに指定する"},{"l":"B","html":"各層のネットワークACLで、前の層のサブネットのCIDRだけを許可し、それ以外を拒否する"},{"l":"C","html":"インスタンスの起動時にIPアドレスを取得し、データベースのセキュリティグループにLambda関数で登録する"},{"l":"D","html":"RDSをパブリックサブネットに移し、アプリケーション層のElastic IPアドレスだけを許可する"}],"answer":["A"],"multi":false,"req":"","key":"セキュリティグループは、ソースに<b>別のセキュリティグループを指定</b>できます。「アプリ層のSGからのみ許可」と書けば、そのSGが付いたインスタンスであれば入れ替わってIPアドレスが変わっても自動的に許可され、ほかからの接続は届きません。","kw":"セキュリティグループの参照（SGをソースに指定）","reasons":[{"l":"B","html":"サブネット単位の制御になり、同じサブネットにある別のリソースからの接続も通してしまいます。ステートレスなので戻りの通信の許可も必要です。"},{"l":"C","html":"IPアドレスの登録と削除を自前で作ることになり、漏れや遅れが起きます。"},{"l":"D","html":"データベースをインターネットに近づけることになり、危険です。Auto Scalingのインスタンスごとに固定のIPアドレスを管理するのも現実的ではありません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.2 セキュリティグループとネットワークACL</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.3 多層防御</a>"},{"n":4,"topic":"鍵の管理と監査","level":2,"body":["S3に保存する顧客データについて、セキュリティ方針で次のことが求められています。①保管時の暗号化 ②暗号化キーを<b>自社で管理し、利用者を制御</b>できる ③<b>キーの利用を監査</b>できる ④キーを<b>自動でローテーション</b>する。<b>運用上のオーバーヘッドが最も少ない</b>方法はどれですか。"],"options":[{"l":"A","html":"SSE-S3で暗号化する"},{"l":"B","html":"SSE-Cで暗号化し、キーはアプリケーションのサーバーで管理する"},{"l":"C","html":"カスタマー管理キーのSSE-KMSで、自動ローテーションを有効にする"},{"l":"D","html":"クライアント側で暗号化し、キーをオンプレミスのHSMで保管して毎年手動で更新する"}],"answer":["C"],"multi":false,"req":"","key":"KMSのカスタマー管理キーは、<b>キーポリシーで使える人を制御</b>でき、<b>キーの利用がCloudTrailに記録</b>されます。自動ローテーションも設定だけで有効になり、S3との統合で暗号化も自動で行われます。4つの要件をすべて満たし、運用の手間も最小です。","kw":"キーの管理・利用の監査・自動ローテーション → SSE-KMS（カスタマー管理キー）","reasons":[{"l":"A","html":"キーはS3が管理するため、利用者の制御や利用の監査（要件②③）ができません。"},{"l":"B","html":"キーをリクエストのたびに渡す必要があり、キーの保管とローテーションも自前です。"},{"l":"D","html":"要件は満たせても、暗号化とキーの管理をすべて自前で行うことになり、運用負荷が最も大きくなります。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.8 AWS KMS</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":5,"topic":"不審な挙動の検知","level":1,"body":["ある企業は、侵害されたEC2インスタンスが<b>暗号資産のマイニングを行う</b>ことや、<b>既知の悪意のあるIPアドレスと通信する</b>こと、普段と異なる場所からの<b>不審なAPI呼び出し</b>を検知したいと考えています。エージェントの導入や、ログを分析する仕組みの構築は避けたいと考えています。最も適切なサービスはどれですか。"],"options":[{"l":"A","html":"Amazon Inspector"},{"l":"B","html":"Amazon Macie"},{"l":"C","html":"AWS Config"},{"l":"D","html":"Amazon GuardDuty"}],"answer":["D"],"multi":false,"req":"","key":"GuardDutyは、VPCフローログ・DNSのログ・CloudTrailのイベントなどを<b>AWS側で自動的に分析</b>し、マイニングや悪意のあるIPとの通信、不審なAPI呼び出しといった<b>脅威を検知</b>します。有効にするだけで使え、ログの収集や分析の仕組みを作る必要はありません。","kw":"脅威の検知・不審な通信やAPI呼び出し → GuardDuty","reasons":[{"l":"A","html":"InspectorはEC2やコンテナイメージの<b>ソフトウェアの脆弱性</b>を評価するサービスで、実行中の不審な挙動は検知しません。"},{"l":"B","html":"MacieはS3の中の<b>機密データ</b>を検出するサービスです。"},{"l":"C","html":"Configはリソースの<b>設定の記録と準拠状況</b>の評価で、脅威の検知は行いません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.11 Amazon GuardDuty</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.13 検出系の整理</a>"},{"n":6,"topic":"1つのイベントを複数の処理へ","level":2,"body":["注文が確定すると、在庫の引き当て・配送の手配・売上の分析の3つの処理が必要です。現在は注文サービスが3つのサービスのAPIを順番に呼んでいるため、<b>1つのサービスが止まると注文そのものが失敗</b>します。各処理を<b>独立して</b>実行し、止まっていたサービスは復旧後に処理を再開できるようにしたいと考えています。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"注文サービスから1つのSQSキューへ送り、3つのサービスが同じキューからメッセージを取り出す"},{"l":"B","html":"注文サービスがAPIの呼び出しに失敗したら、成功するまで同期で再試行を繰り返す"},{"l":"C","html":"SNSトピックに発行し、サービスごとのSQSキューをサブスクライブさせる"},{"l":"D","html":"注文サービスが3つのサービスのデータベースへ直接書き込む"}],"answer":["C"],"multi":false,"req":"","key":"SNSからサービスごとのSQSキューへ配る<b>ファンアウト</b>にすると、1つのイベントが3つのキューにそれぞれ届きます。各サービスは自分のキューから独立して処理し、止まっていたサービスの分はキューに残るので、復旧後に続きから処理できます。","kw":"1つのイベントを複数の処理へ・独立して再開 → SNS ＋ SQSのファンアウト","reasons":[{"l":"A","html":"SQSのメッセージは1つのコンシューマーが受け取ると処理されて消えるため、3つのサービスすべてには届きません。"},{"l":"B","html":"注文サービスが相手の障害に引きずられる構造は変わらず、利用者への応答も遅れます。"},{"l":"D","html":"サービス同士が強く結合し、相手のデータベースの変更がすべてに波及します。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.2 Amazon SNS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.2 疎結合アーキテクチャ</a>"},{"n":7,"topic":"リージョン障害に備えるデータベース","level":2,"body":["グローバルに展開するアプリケーションがAurora PostgreSQLを使っています。リージョン全体の障害に備えて、<b>RPOは1秒程度、RTOは数分以内</b>で別のリージョンに切り替えたいと考えています。また、別のリージョンの利用者の<b>読み込みを低レイテンシーで</b>処理したいと考えています。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"Auroraグローバルデータベースを構成する"},{"l":"B","html":"Auroraのスナップショットを1時間ごとに別のリージョンへコピーする"},{"l":"C","html":"同じリージョンの3つのAZにAuroraレプリカを配置する"},{"l":"D","html":"AWS DMSで別のリージョンのRDS for PostgreSQLへ継続的に複製する"}],"answer":["A"],"multi":false,"req":"","key":"グローバルデータベースは、ストレージ層で<b>別のリージョンへ通常1秒未満の遅れで複製</b>し、障害時には数分以内にセカンダリのリージョンを昇格できます。セカンダリのクラスターは読み込みにも使えるため、その地域の利用者の読み込みを低レイテンシーで処理できます。","kw":"リージョン障害・RPO1秒・RTO数分・別リージョンの読み込み → Auroraグローバルデータベース","reasons":[{"l":"B","html":"RPOが最大1時間になり、復元にも時間がかかります。読み込みの分散にもなりません。"},{"l":"C","html":"同じリージョンの中の対策で、リージョン全体の障害には効きません。"},{"l":"D","html":"複製の遅れと切り替えの手順が大きく、エンジンの違うデータベースの運用も必要になります。グローバルデータベースより運用負荷が大きくなります。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.2 Amazon Aurora</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":8,"topic":"複数のインスタンスで共有するファイル","level":2,"body":["WebアプリケーションはALBの背後の複数のEC2インスタンス（Auto Scalingグループ、2つのAZ）で動いています。利用者がアップロードした画像を各インスタンスのEBSボリュームに保存しているため、<b>別のインスタンスに振り分けられた利用者が画像を見られない</b>問題が起きています。アプリケーションは画像をファイルとして読み書きしており、<b>コードの変更は最小限</b>にしたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"EBSのマルチアタッチで、1つのボリュームを全インスタンスに接続する"},{"l":"B","html":"Amazon EFSを全インスタンスにマウントし、画像をEFSに保存する"},{"l":"C","html":"ALBのスティッキーセッションを有効にし、同じ利用者を同じインスタンスへ振り分ける"},{"l":"D","html":"各インスタンスのEBSボリュームを1時間ごとに同期するスクリプトを実行する"}],"answer":["B"],"multi":false,"req":"","key":"EFSは<b>複数のインスタンスから同時にマウントできるNFSのファイルシステム</b>で、複数のAZにデータを保存します。保存先のディレクトリをEFSのマウント先に変えるだけで、どのインスタンスからも同じ画像を読み書きでき、コードの変更もほとんど要りません。","kw":"複数のインスタンス・複数のAZで共有するファイル → EFS","reasons":[{"l":"A","html":"マルチアタッチはio1／io2の同じAZのインスタンスに限られ、クラスター対応のファイルシステムも必要です。別のAZのインスタンスからは使えません。"},{"l":"C","html":"その利用者が別の人の画像を見る場合や、インスタンスが入れ替わった場合には画像が見つかりません。"},{"l":"D","html":"同期までの間は画像が見えず、同時の書き込みで不整合も起きます。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.3 Amazon EFS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a>"},{"n":9,"topic":"サーバーレスAPIのマルチリージョン化","level":3,"body":["API Gateway・Lambda・DynamoDBで構成したAPIを、東京とシンガポールの2つのリージョンで動かし、<b>一方のリージョンが停止しても、もう一方で読み書きを続けられる</b>ようにしたいと考えています。どの組み合わせが適切ですか。（<b>2つ選択してください</b>）"],"options":[{"l":"A","html":"DynamoDBのテーブルでポイントインタイムリカバリを有効にする"},{"l":"B","html":"DynamoDBをグローバルテーブルにし、両方のリージョンにレプリカを置く"},{"l":"C","html":"API Gatewayをエッジ最適化エンドポイントにして、世界中のエッジで受け付ける"},{"l":"D","html":"Lambda関数の予約済み同時実行数を大きくし、処理能力を確保する"},{"l":"E","html":"Route 53のフェイルオーバーまたはレイテンシーベースのルーティングで、ヘルスチェックに応じて両リージョンのAPIに振り分ける"}],"answer":["B","E"],"multi":true,"req":"","key":"データ層は、<b>両リージョンで読み書きできるグローバルテーブル</b>で複製します。入口は、<b>ヘルスチェックに基づいて正常なリージョンのAPIへ振り分けるRoute 53</b>で切り替えます。この2つがそろって初めて、片方のリージョンが止まっても読み書きを続けられます。","kw":"マルチリージョンのアクティブ構成 → DynamoDBグローバルテーブル ＋ Route 53のヘルスチェック","reasons":[{"l":"A","html":"PITRは誤操作などからの復元のための機能で、別のリージョンでの読み書きを続ける仕組みではありません。"},{"l":"C","html":"エッジ最適化は受け付けをエッジから行うだけで、APIの本体は1つのリージョンにあります。リージョンが止まれば使えません。"},{"l":"D","html":"同時実行数の確保はリージョンの中の性能の話で、リージョン障害への備えにはなりません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a> ／ <a href=\"#network\" data-go=\"network\">第3章 3.4 Route 53</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":10,"topic":"Windowsのファイルサーバーの移行","level":2,"body":["オンプレミスのWindowsファイルサーバー（SMBの共有フォルダー、Active Directoryのユーザーでアクセス権を管理）をAWSへ移行します。WindowsのEC2インスタンスと社内のPCから、<b>これまでどおりSMBで接続し、ADのアクセス権を使い続け</b>たいと考えています。管理の負荷は<b>最小限</b>にしたいと考えています。最も適切なサービスはどれですか。"],"options":[{"l":"A","html":"Amazon EFS"},{"l":"B","html":"Amazon FSx for Lustre"},{"l":"C","html":"Windows ServerのEC2でファイル共有を構築する"},{"l":"D","html":"Amazon FSx for Windows File Server"}],"answer":["D"],"multi":false,"req":"","key":"FSx for Windows File Serverは、<b>SMBプロトコルとActive Directoryの統合</b>を備えたフルマネージドのWindowsファイルサーバーです。NTFSのアクセス権をそのまま使え、マルチAZの構成やバックアップもマネージドで提供されます。","kw":"SMB・Active Directory・Windows → FSx for Windows File Server","reasons":[{"l":"A","html":"EFSはNFSのファイルシステムで、Linux向けです。SMBには対応していません。"},{"l":"B","html":"FSx for LustreはHPCや機械学習向けの高速なファイルシステムで、Windowsの共有フォルダーの用途ではありません。"},{"l":"C","html":"実現はできますが、OSのパッチ・冗長化・バックアップをすべて自分で管理することになります。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.4 Amazon FSx</a>"},{"n":11,"topic":"UDPのゲームサーバー","level":2,"body":["オンラインゲームのサーバーは、<b>UDP</b>で通信し、東京とバージニア北部のリージョンのNLBの背後で動いています。世界中のプレイヤーの<b>遅延とジッターを減らし</b>、リージョンに障害が起きた場合は<b>数十秒以内に別のリージョンへ切り替え</b>たいと考えています。プレイヤーのクライアントには、接続先として<b>固定のIPアドレス</b>を設定したいと考えています。最も適切なサービスはどれですか。"],"options":[{"l":"A","html":"Amazon CloudFront"},{"l":"B","html":"Route 53のレイテンシーベースルーティング"},{"l":"C","html":"AWS Global Accelerator"},{"l":"D","html":"各リージョンのNLBにElastic IPアドレスを割り当て、クライアントに両方を登録する"}],"answer":["C"],"multi":false,"req":"","key":"Global Acceleratorは、<b>2つの固定のエニーキャストIPアドレス</b>で受け、利用者に近いエッジからAWSのネットワークを通して最適なリージョンへ届けます。<b>TCPとUDPに対応</b>し、ヘルスチェックで異常なリージョンを数十秒以内に外せます。DNSのキャッシュにも左右されません。","kw":"UDP・固定IP・高速なリージョンの切り替え → Global Accelerator","reasons":[{"l":"A","html":"CloudFrontはHTTP／HTTPS（とWebSocket）の配信のためのサービスで、UDPのゲームの通信には使えません。"},{"l":"B","html":"固定のIPアドレスを提供できず、切り替えもクライアントやリゾルバーのDNSキャッシュに左右されます。"},{"l":"D","html":"切り替えをクライアント側で作り込む必要があり、経路の最適化による遅延の改善もありません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFront と Global Accelerator</a>"},{"n":12,"topic":"Athenaのクエリの高速化","level":2,"body":["S3に保存した数年分のアクセスログ（<b>CSV形式</b>、日付ごとに大量の小さなファイル）に対してAthenaでクエリを実行しています。ほとんどのクエリは<b>直近の数日分</b>を対象に、<b>一部の列</b>だけを集計しますが、実行に時間がかかり、スキャン量に応じた料金も高くなっています。どの組み合わせが最も効果的ですか。（<b>2つ選択してください</b>）"],"options":[{"l":"A","html":"データを列指向のParquet形式に変換し、ファイルをまとめて大きくする"},{"l":"B","html":"クエリに <code>LIMIT</code> 句を付けて、返す行数を減らす"},{"l":"C","html":"ログのバケットでS3 Transfer Accelerationを有効にする"},{"l":"D","html":"日付でパーティション分割し、クエリの条件で日付を指定する"},{"l":"E","html":"ログのストレージクラスをS3 Standard-IAに変更する"}],"answer":["A","D"],"multi":true,"req":"","key":"Athenaの速度と料金は<b>スキャンするデータ量</b>で決まります。<b>パーティション分割</b>すれば対象の日付のデータだけを読み、<b>列指向のParquet</b>なら必要な列だけを読めます（圧縮も効きます）。小さなファイルをまとめると、ファイルを開く処理の負担も減ります。","kw":"Athenaのスキャン量の削減 → パーティション分割 ＋ 列指向形式（Parquet）","reasons":[{"l":"B","html":"<code>LIMIT</code> は返す行数を減らすだけで、読み込むデータ量はほとんど減りません。"},{"l":"C","html":"Transfer Accelerationは遠距離からのアップロードを速くする機能で、Athenaのクエリには関係ありません。"},{"l":"E","html":"保管の料金は下がっても、クエリの速度は変わらず、読み込みのたびに取り出し料金がかかります。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.3 Amazon Athena</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":13,"topic":"やり直しのきく夜間処理","level":1,"body":["毎晩3時間ほど動く画像の変換処理があります。処理は小さな単位に分かれており、<b>途中で中断されても、未処理の分を再実行すれば問題ありません</b>。終了時刻にも数時間の余裕があります。<b>最もコスト効率の高い</b>EC2の購入方法はどれですか。"],"options":[{"l":"A","html":"1年のスタンダードリザーブドインスタンス"},{"l":"B","html":"スポットインスタンス"},{"l":"C","html":"オンデマンドインスタンスとオンデマンドキャパシティ予約"},{"l":"D","html":"Dedicated Instances"}],"answer":["B"],"multi":false,"req":"","key":"<b>中断を許容でき、時間にも余裕のある処理</b>は、オンデマンドより最大90%安いスポットインスタンスが最も適しています。複数のインスタンスタイプを指定しておくと、中断されにくく容量も確保しやすくなります。","kw":"中断されても再実行できる → スポットインスタンス","reasons":[{"l":"A","html":"1日3時間の処理に24時間分のコミットをすると、使わない時間の分が無駄になります。"},{"l":"C","html":"キャパシティ予約に割引はなく、オンデマンドの料金を払い続けることになります。"},{"l":"D","html":"ハードウェアを専有するための購入方法で、費用はむしろ上がります。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":14,"topic":"アクセスの傾向がわからないデータ","level":2,"body":["データ分析の基盤に、数百TBのデータセットをS3で保管しています。どのデータがいつ使われるかは<b>分析のテーマ次第で予測できず</b>、長く使われなかったデータが突然まとめて読まれることもあります。読み込むときは<b>すぐに</b>使える必要があります。取り出しの手間や料金を気にせず、保管の費用を<b>自動で</b>下げたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"90日後にS3 Glacier Flexible Retrievalへ移行するライフサイクルルールを設定する"},{"l":"B","html":"すべてのデータをS3 One Zone-IAに移す"},{"l":"C","html":"30日後にS3 Standard-IAへ移行するライフサイクルルールを設定する"},{"l":"D","html":"S3 Intelligent-Tieringに保存する"}],"answer":["D"],"multi":false,"req":"","key":"Intelligent-Tieringは、オブジェクトごとのアクセスを監視して、<b>使われなくなったものを自動で安い階層へ移し、アクセスされれば高頻度の階層へ戻します</b>。取り出し料金がかからず、既定の階層はすぐに読めるため、アクセスの傾向を予測できないデータに最も適しています。","kw":"アクセスの傾向が予測できない → Intelligent-Tiering","reasons":[{"l":"A","html":"Flexible Retrievalはすぐには読めず、取り出しに数分から数時間かかります。取り出し料金もかかります。"},{"l":"B","html":"1つのAZにしか保存されず耐久性の面で劣るうえ、読み込むたびに取り出し料金がかかります。"},{"l":"C","html":"突然まとめて読まれると取り出し料金が大きくなり、Standardには自動で戻りません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":15,"topic":"部署ごとの費用の把握","level":1,"body":["1つのAWSアカウントを複数の部署で使っています。経理部門は、<b>部署ごとの月額の費用</b>をCost Explorerで確認したいと考えています。各リソースには、すでに <code>Department</code> というタグが付いています。最も適切な対応はどれですか。"],"options":[{"l":"A","html":"<code>Department</code> をコスト配分タグとして有効にする"},{"l":"B","html":"部署ごとにAWS Budgetsの予算を作成し、アラートを設定する"},{"l":"C","html":"AWS Configで、タグのないリソースを検出するルールを設定する"},{"l":"D","html":"部署ごとに別のリージョンを使うように、リソースを移動する"}],"answer":["A"],"multi":false,"req":"","key":"リソースに付けたタグは、<b>コスト配分タグとして有効にしてはじめて</b>Cost Explorerや請求のレポートで集計に使えるようになります（有効にした時点以降の費用が対象）。有効にすれば、<code>Department</code> の値ごとに費用を分けて確認できます。","kw":"タグ別の費用の集計 → コスト配分タグの有効化","reasons":[{"l":"B","html":"予算は超過を通知するための機能で、部署ごとの費用の集計にはなりません（タグで絞った予算を作る場合も、コスト配分タグの有効化が前提です）。"},{"l":"C","html":"タグの付け忘れの検出には役立ちますが、費用の集計はできません。"},{"l":"D","html":"リージョンで費用を分けるのは本末転倒で、移動の手間と影響も大きすぎます。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.9〜10.11 コスト管理サービス</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.1 コスト管理ツールの使い分け</a>"}]},{"id":"exam-set-31","file":"set-31.md","num":"問題セット31","title":"実戦演習⑦（本番の分野比率・15問）","questions":[{"n":1,"topic":"監査ログの停止の防止","level":2,"body":["ある企業はAWS Organizationsで数十のアカウントを管理しています。各アカウントでCloudTrailの証跡を有効にしていますが、アカウントの管理者（ルートユーザーを含む）が<b>証跡を停止・削除したり、アカウントを組織から離脱させたりできない</b>ようにしたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"各アカウントのIAMユーザーとロールに、CloudTrailの操作を拒否するポリシーをアタッチする"},{"l":"B","html":"証跡の停止・削除と組織からの離脱を拒否するSCPを、ルートまたはOUに適用する"},{"l":"C","html":"AWS Configで証跡の停止を検出し、SNSで管理者に通知する"},{"l":"D","html":"CloudTrailのログを保存するS3バケットでMFA削除を有効にする"}],"answer":["B"],"multi":false,"req":"","key":"SCPは、メンバーアカウントの<b>すべてのプリンシパル（ルートユーザーを含む）</b>に対して、使える操作の上限を設けます。<code>cloudtrail:StopLogging</code>・<code>cloudtrail:DeleteTrail</code>・<code>organizations:LeaveOrganization</code> を拒否すれば、アカウントの管理者でも実行できません。","kw":"組織全体で、ルートユーザーを含めて禁止する → SCP","reasons":[{"l":"A","html":"アカウントの管理者は自分でポリシーを外せます。ルートユーザーにはIAMポリシーを付けられません。"},{"l":"C","html":"停止されたことを事後に知るだけで、停止そのものは防げません。停止中のログは欠けます。"},{"l":"D","html":"保存済みのログファイルの削除を防ぐ設定で、証跡の停止や組織からの離脱は防げません。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.5 AWS Organizations</a> ／ <a href=\"#management\" data-go=\"management\">第8章 8.2 AWS CloudTrail</a>"},{"n":2,"topic":"SSHを使わないサーバーの操作","level":1,"body":["プライベートサブネットのLinuxのEC2インスタンスを、運用担当者が操作する必要があります。セキュリティ方針により、<b>インバウンドのポートを開けること、踏み台サーバーを置くこと、SSHの鍵を配ること</b>は禁止されています。また、<b>操作の内容を記録</b>しなければなりません。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"EC2 Instance Connectを使い、インスタンスのセキュリティグループでSSHを社内のIPアドレスに限定する"},{"l":"B","html":"パブリックサブネットに踏み台サーバーを置き、SSHのセッションを録画するソフトウェアを導入する"},{"l":"C","html":"Site-to-Site VPNで社内とVPCを接続し、社内から直接SSHで接続する"},{"l":"D","html":"Systems Manager Session Managerを使い、セッションのログをS3に保存する"}],"answer":["D"],"multi":false,"req":"","key":"Session Managerは、インスタンスのSSMエージェントが<b>外向きにSystems Managerへ接続</b>する仕組みのため、インバウンドのポート・踏み台・SSHの鍵が要りません。アクセスはIAMで制御でき、<b>セッションの操作ログをS3やCloudWatch Logsに保存</b>できます。","kw":"ポートを開けない・踏み台なし・鍵なし・操作の記録 → Session Manager","reasons":[{"l":"A","html":"SSHのポートを開ける必要があり、方針に反します。"},{"l":"B","html":"踏み台サーバーの設置もSSHの鍵の配布も禁止されています。"},{"l":"C","html":"SSHの鍵の配布が必要で、操作の記録の仕組みも別に用意しなければなりません。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.4 AWS Systems Manager</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":3,"topic":"通信の暗号化と証明書の更新","level":1,"body":["ALBの背後で動くWebサイトは、現在HTTPだけで公開されています。利用者とALBの間の通信を<b>HTTPSで暗号化</b>し、HTTPでのアクセスはHTTPSへ転送したいと考えています。証明書の<b>更新の作業はなくしたい</b>と考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"認証局から購入した証明書をACMにインポートし、ALBのHTTPSリスナーに設定する"},{"l":"B","html":"各EC2インスタンスに自己署名の証明書を入れ、ALBはTCPのまま通信を転送する"},{"l":"C","html":"ACMの公開証明書をHTTPSリスナーに設定し、HTTPはリダイレクトする"},{"l":"D","html":"CloudHSMで鍵を生成し、証明書をEC2インスタンスで管理する"}],"answer":["C"],"multi":false,"req":"","key":"ACMが発行した公開証明書は<b>無料で、ALBなどの統合サービスで使う限り自動で更新</b>されます。ALBのHTTPSリスナーでTLSを終端し、HTTPのリスナーにはHTTPSへのリダイレクトのルールを設定するのが定番の構成です。","kw":"証明書の自動更新 → ACMで発行した証明書（インポートした証明書は自動更新されない）","reasons":[{"l":"A","html":"インポートした証明書はACMが自動で更新しないため、期限が来るたびに入れ替える作業が残ります。"},{"l":"B","html":"自己署名の証明書はブラウザーに信頼されず、インスタンスごとの管理も必要です。ALBはTCPを扱えません（NLBの機能です）。"},{"l":"D","html":"鍵と証明書の管理をすべて自分で行うことになり、要件に対して過剰です。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.7 AWS Certificate Manager</a> ／ <a href=\"#network\" data-go=\"network\">第3章 3.5 負荷分散</a>"},{"n":4,"topic":"S3の意図しない公開の防止","level":2,"body":["ある企業は、どのアカウントでもS3のバケットやオブジェクトが<b>インターネットに公開されることを防ぎたい</b>と考えています。各アカウントの管理者が、うっかり、または意図的に設定を変えても公開できないようにする必要があります。どの組み合わせが適切ですか。（<b>2つ選択してください</b>）"],"options":[{"l":"A","html":"Amazon Macieを有効にし、公開されたバケットの機密データを検出する"},{"l":"B","html":"各アカウントで、アカウント単位のS3ブロックパブリックアクセスをすべて有効にする"},{"l":"C","html":"毎月、全バケットのACLとバケットポリシーを担当者が確認する"},{"l":"D","html":"アカウント単位のブロックパブリックアクセスの設定変更を拒否するSCPを適用する"},{"l":"E","html":"AWS Configのルールで公開されたバケットを検出し、管理者にメールで通知する"}],"answer":["B","D"],"multi":true,"req":"","key":"アカウント単位のブロックパブリックアクセスは、<b>そのアカウントのすべてのバケット</b>で、ACLやバケットポリシーによる公開を無効にします。さらに、この設定を変える操作（<code>s3:PutAccountPublicAccessBlock</code>）をSCPで拒否すれば、<b>アカウントの管理者でも元に戻せなく</b>なります。「防ぐ」仕組みと「外させない」仕組みの組み合わせです。","kw":"公開を防ぐ → ブロックパブリックアクセス／管理者にも変えさせない → SCP","reasons":[{"l":"A","html":"公開された後に機密データを見つける検出の仕組みで、公開そのものは防げません。"},{"l":"C","html":"月1回の確認では、公開されてから気づくまでの間に漏れます。手作業で漏れも起きます。"},{"l":"E","html":"検出と通知は事後の対応で、公開の瞬間を防げません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#management\" data-go=\"management\">第8章 8.5 AWS Organizations</a>"},{"n":5,"topic":"インターネットに出られないサブネットからのAPI呼び出し","level":2,"body":["プライベートサブネットのEC2インスタンスで動くアプリケーションが、起動時にSecrets Managerからデータベースの認証情報を取得します。このVPCには<b>インターネットゲートウェイもNAT Gatewayもなく</b>、今後も作らない方針です。現在、Secrets Managerへの呼び出しはタイムアウトしています。アプリケーションのコードを変えずに解決する最も適切な方法はどれですか。"],"options":[{"l":"A","html":"Secrets Manager用のゲートウェイ型VPCエンドポイントを作成し、ルートテーブルに関連付ける"},{"l":"B","html":"認証情報をインスタンスのユーザーデータに移し、Secrets Managerを使うのをやめる"},{"l":"C","html":"VPCピアリングで、NAT Gatewayを持つ別のVPCと接続する"},{"l":"D","html":"Secrets Manager用のインターフェース型エンドポイントを作成する"}],"answer":["D"],"multi":false,"req":"","key":"インターフェース型エンドポイント（PrivateLink）は、VPC内に<b>サービスへの入り口となるENI</b>を作ります。プライベートDNSを有効にすれば、Secrets Managerの標準のエンドポイント名がこのENIのIPアドレスに解決されるため、SDKの設定もコードも変えずに、インターネットを経由せず呼び出せます。","kw":"インターネットに出られないサブネットからAWSのAPI → インターフェース型エンドポイント（S3・DynamoDB以外）","reasons":[{"l":"A","html":"ゲートウェイ型エンドポイントがあるのはS3とDynamoDBだけです。"},{"l":"B","html":"ユーザーデータは暗号化されず、インスタンスから誰でも読めます。認証情報の管理として後退します。"},{"l":"C","html":"ピアリングしたVPCのNAT Gatewayを経由してインターネットに出ることはできません（推移的な経路は使えません）。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.5 機密データへの安全な内部アクセス</a>"},{"n":6,"topic":"処理できないメッセージの隔離","level":2,"body":["SQSのキューをイベントソースにしたLambda関数がメッセージを処理しています。形式が壊れたメッセージが届くと、関数は毎回エラーになり、そのメッセージが<b>何度も再配信されて処理を妨げ</b>ています。正常なメッセージの処理を止めずに、失敗を繰り返すメッセージを<b>後から調査できる場所に隔離</b>したいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"Lambda関数の非同期呼び出しの設定で、失敗時の送信先にデッドレターキューを指定する"},{"l":"B","html":"SQSのキューにデッドレターキューを設定し、<code>maxReceiveCount</code> を指定する"},{"l":"C","html":"キューのメッセージ保持期間を1分に短くして、壊れたメッセージを早く消す"},{"l":"D","html":"Lambda関数の中で例外を握りつぶし、エラーにならないようにする"}],"answer":["B"],"multi":false,"req":"","key":"キューの<b>リドライブポリシー</b>でデッドレターキュー（DLQ）と <code>maxReceiveCount</code> を指定すると、指定した回数だけ受信されても削除されないメッセージが<b>自動でDLQへ移されます</b>。正常なメッセージの処理は続き、隔離したメッセージは後から調べてリドライブできます。","kw":"失敗を繰り返すメッセージの隔離 → SQSのDLQ ＋ maxReceiveCount","reasons":[{"l":"A","html":"非同期呼び出しの設定は、S3やSNSなどから非同期に呼ばれた場合のものです。SQSのイベントソースマッピングからの呼び出しには効きません。"},{"l":"C","html":"正常なメッセージまで処理される前に消える危険があり、壊れたメッセージも調査できなくなります。"},{"l":"D","html":"失敗が記録されずにメッセージが削除され、データが黙って失われます。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a> ／ <a href=\"#compute\" data-go=\"compute\">第1章 1.6 AWS Lambda</a>"},{"n":7,"topic":"毎朝の決まったピーク","level":1,"body":["社内向けの業務システムは、<b>毎朝9時の始業と同時にアクセスが急増</b>します。Auto Scalingグループはターゲット追跡スケーリングを使っていますが、インスタンスの起動に数分かかるため、毎朝9時からの数分間は応答が遅くなります。最も適切な対策はどれですか。"],"options":[{"l":"A","html":"8時45分に台数を増やすスケジュールを設定する"},{"l":"B","html":"ターゲット追跡の目標値を下げ、終日多めの台数で待機させる"},{"l":"C","html":"インスタンスタイプを大きくし、台数を減らす"},{"l":"D","html":"ヘルスチェックの猶予期間を短くして、起動したインスタンスを早く使う"}],"answer":["A"],"multi":false,"req":"","key":"<b>時刻が決まっている負荷の増加</b>には、スケジュールされたスケーリングで先回りして台数を増やします。ピークの前にインスタンスの起動を終えておけば、9時の時点で処理能力がそろっています。日中の変動は、これまでどおりターゲット追跡に任せます。","kw":"決まった時刻の負荷の増加 → スケジュールされたスケーリング","reasons":[{"l":"B","html":"終日余分な台数を動かすことになり、コストが増えます。"},{"l":"C","html":"急増に追従できる台数の余裕が減り、起動の遅れの問題も解決しません。"},{"l":"D","html":"初期化が終わる前のインスタンスが異常と判定されるなど、かえって不安定になります。起動にかかる時間は変わりません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.2 EC2 Auto Scaling</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a>"},{"n":8,"topic":"バックアップの一元管理","level":2,"body":["ある企業は、EC2（EBS）・RDS・DynamoDB・EFSのデータを、サービスごとに異なる方法でバックアップしています。<b>バックアップのスケジュールと保持期間を1か所で管理</b>し、災害対策のために<b>別のリージョンにもコピー</b>したいと考えています。<b>運用上のオーバーヘッドが最も少ない</b>方法はどれですか。"],"options":[{"l":"A","html":"Lambda関数とEventBridgeで、スナップショットを自前で取得・コピーする"},{"l":"B","html":"各サービスの自動バックアップ機能を個別に設定し、スプレッドシートで保持期間を管理する"},{"l":"C","html":"AWS Backupのバックアップ計画を作成し、クロスリージョンコピーのルールを設定する"},{"l":"D","html":"データをすべてS3にエクスポートし、クロスリージョンレプリケーションで複製する"}],"answer":["C"],"multi":false,"req":"","key":"AWS Backupは、EBS・RDS・DynamoDB・EFSなど多くのサービスのバックアップを、<b>バックアップ計画（スケジュール・保持期間・コピー先）で一元管理</b>できます。タグで対象を指定すれば新しいリソースも自動で含まれ、別のリージョン（や別のアカウント）へのコピーも計画のルールで設定できます。","kw":"複数サービスのバックアップの一元管理・別リージョンへのコピー → AWS Backup","reasons":[{"l":"A","html":"実現はできますが、サービスごとの処理を自前で作って保守し続けることになります。"},{"l":"B","html":"管理が分散したままで、保持期間の管理も手作業です。別のリージョンへのコピーも個別に設定が必要です。"},{"l":"D","html":"エクスポートと復元の仕組みを自前で作る必要があり、サービスによっては整合性のある復元も難しくなります。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.5 AWS Backup</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":9,"topic":"決済サービスの障害の切り離し","level":2,"body":["注文サービスは、注文を受けるたびに決済サービスのAPIを<b>同期で</b>呼び出しています。決済サービスが一時的に停止すると、注文の受け付けまで失敗します。決済の処理は<b>数分遅れてもかまいません</b>。注文の受け付けを決済サービスの障害から切り離すために、どの組み合わせが適切ですか。（<b>2つ選択してください</b>）"],"options":[{"l":"A","html":"注文サービスと決済サービスの間にSQSのキューを置き、決済サービスはキューから取り出して処理する"},{"l":"B","html":"決済サービスのインスタンスを大きくし、停止しにくくする"},{"l":"C","html":"同じメッセージが2回届いても二重に決済されないよう、決済の処理を冪等にする"},{"l":"D","html":"注文サービスのAPI呼び出しのタイムアウトを長くし、決済サービスの復旧を待つ"},{"l":"E","html":"注文サービスと決済サービスを1つのアプリケーションに統合する"}],"answer":["A","C"],"multi":true,"req":"","key":"キューを挟めば、注文サービスは<b>キューに入れた時点で受け付けを完了</b>でき、決済サービスが止まっていても注文は失敗しません。止まっていた間のメッセージはキューに残り、復旧後に処理されます。SQSの標準キューは<b>少なくとも1回</b>の配信なので、同じメッセージが重複しても安全なように、決済の処理を冪等にしておく必要があります。","kw":"同期呼び出しの切り離し → SQS／少なくとも1回の配信 → 冪等な処理","reasons":[{"l":"B","html":"停止の原因はサイズだけではなく、同期で結合している構造は変わりません。"},{"l":"D","html":"注文の受け付けが決済サービスの復旧を待つことになり、利用者への応答も遅れます。"},{"l":"E","html":"障害の影響範囲が広がり、個別にスケーリングすることもできなくなります。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.2 疎結合アーキテクチャ</a>"},{"n":10,"topic":"ランキングのキャッシュ","level":2,"body":["ゲームのランキング機能で、数百万人のスコアを<b>リアルタイムに順位付け</b>して表示したいと考えています。ランキングのデータは<b>キャッシュのノードが障害で停止しても失われない</b>ようにし、読み込みはレプリカにも分散したいと考えています。最も適切なサービスはどれですか。"],"options":[{"l":"A","html":"ElastiCache for Memcached"},{"l":"B","html":"DynamoDBのテーブルをスキャンし、アプリケーションで並べ替える"},{"l":"C","html":"RDS for MySQLで、スコアの列にインデックスを作り <code>ORDER BY</code> で取得する"},{"l":"D","html":"ElastiCache for Redis OSS（またはValkey）"}],"answer":["D"],"multi":false,"req":"","key":"Redis OSS／Valkeyの<b>ソート済みセット</b>は、スコアの追加と順位の取得を高速に行えるため、ランキングの定番のデータ構造です。<b>レプリケーション（リードレプリカ）と自動フェイルオーバー、データの永続化</b>にも対応しています。","kw":"ランキング（ソート済みセット）・レプリケーション・永続化 → Redis OSS／Valkey","reasons":[{"l":"A","html":"Memcachedは単純なキーと値のキャッシュで、ソート済みセットもレプリケーションも永続化もありません。"},{"l":"B","html":"数百万件のスキャンと並べ替えは遅く高価で、リアルタイムの更新には向きません。"},{"l":"C","html":"スコアの更新が多いと書き込みとインデックスの更新の負荷が大きく、インメモリの処理には速度で及びません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.4 Amazon ElastiCache</a>"},{"n":11,"topic":"ノード間の低レイテンシー","level":2,"body":["流体解析のシミュレーションを、数十台のEC2インスタンスで<b>密に連携させて</b>実行します。ノード同士が頻繁に通信するため、<b>ノード間のネットワークのレイテンシーを最小にし、スループットを最大に</b>したいと考えています。可用性よりも性能を優先します。最も適切な配置はどれですか。"],"options":[{"l":"A","html":"スプレッドプレイスメントグループで、インスタンスを別々のハードウェアに分散させる"},{"l":"B","html":"クラスタープレイスメントグループで、1つのAZにまとめて配置する"},{"l":"C","html":"パーティションプレイスメントグループで、複数のAZに分散させる"},{"l":"D","html":"Auto Scalingグループで、3つのAZに均等に配置する"}],"answer":["B"],"multi":false,"req":"","key":"クラスタープレイスメントグループは、1つのAZの中で<b>インスタンスを物理的に近くに配置</b>し、ノード間の低レイテンシーと高いスループットを実現します。拡張ネットワーキングやEFAに対応したインスタンスタイプと組み合わせるのが、HPCの定番の構成です。","kw":"ノード間の低レイテンシー・HPC → クラスタープレイスメントグループ","reasons":[{"l":"A","html":"スプレッドは障害の影響を分散させるための配置で、ノード間の距離は遠くなります。1つのAZに置ける台数にも上限があります。"},{"l":"C","html":"パーティションはHadoopなどの大規模な分散システムで障害の範囲を分けるための配置です。AZをまたぐと遅延も増えます。"},{"l":"D","html":"AZをまたぐ通信は遅延が大きくなり、AZ間のデータ転送料もかかります。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.2 コンピューティングとパフォーマンス</a>"},{"n":12,"topic":"ファイルサーバーからの継続的な転送","level":2,"body":["オンプレミスのNASに保存された数十TBのファイル（NFSの共有）を、Amazon S3へ移行します。移行期間中もNASのファイルは更新され続けるため、<b>最初の全量転送のあと、毎晩の差分だけを自動で転送</b>し、転送したデータの<b>整合性を検証</b>したいと考えています。拠点のインターネット回線には十分な帯域があります。<b>運用上のオーバーヘッドが最も少ない</b>方法はどれですか。"],"options":[{"l":"A","html":"Snowball Edgeで全量を輸送し、差分は担当者が毎晩コピーする"},{"l":"B","html":"EC2上にrsyncのサーバーを構築し、NASからcronで同期する"},{"l":"C","html":"AWS DataSyncのエージェントを配置し、スケジュールを設定したタスクで転送する"},{"l":"D","html":"S3 File Gatewayを配置し、スクリプトでファイルをコピーする"}],"answer":["C"],"multi":false,"req":"","key":"DataSyncは、NFS／SMBのファイルサーバーからS3・EFS・FSxへの<b>オンライン転送をマネージドで</b>行うサービスです。スケジュールで繰り返し実行すると<b>変更されたファイルだけを転送</b>し、転送後にはデータの整合性も自動で検証します。暗号化と帯域の制御も備えています。","kw":"オンラインで大量のファイルを移行・定期的な差分転送・整合性の検証 → DataSync","reasons":[{"l":"A","html":"回線に余裕がある状況で輸送の手間をかける必要はなく、毎晩の手作業の差分コピーも運用負荷が大きくなります。"},{"l":"B","html":"転送の仕組み・再試行・検証・サーバーの管理をすべて自分で行うことになります。"},{"l":"D","html":"File Gatewayはオンプレミスのアプリケーションが使い続けるファイル共有の仕組みで、移行の転送と検証を担う機能ではありません。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.13 AWS DataSync</a> ／ <a href=\"#storage\" data-go=\"storage\">第2章 2.6 AWS Storage Gateway</a>"},{"n":13,"topic":"過剰なインスタンスの見直し","level":1,"body":["数百台のEC2インスタンスのうち、多くは<b>CPU使用率が常に10%未満</b>です。どのインスタンスをどのタイプに変えれば安くなるかを、<b>使用状況のデータに基づいて</b>知りたいと考えています。最も適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS Budgets"},{"l":"B","html":"AWS Cost and Usage Report"},{"l":"C","html":"AWS Trusted Advisorのセキュリティのチェック"},{"l":"D","html":"AWS Compute Optimizer"}],"answer":["D"],"multi":false,"req":"","key":"Compute Optimizerは、CloudWatchのメトリクスを機械学習で分析し、<b>EC2・Auto Scalingグループ・EBS・Lambdaなどの適切なサイズ（ライトサイジング）を推奨</b>します。推奨のタイプと、変更した場合の性能のリスクや削減額も示されます。メモリの使用率もCloudWatchエージェントで集めると、推奨の精度が上がります。","kw":"使用状況に基づくサイズの推奨 → Compute Optimizer","reasons":[{"l":"A","html":"Budgetsは予算の超過を通知する機能で、サイズの推奨はしません。"},{"l":"B","html":"CURは詳細な請求データで、どのタイプに変えるべきかは自分で分析する必要があります。"},{"l":"C","html":"セキュリティのチェックはセキュリティの設定の点検で、インスタンスのサイズとは関係ありません。"}],"refs":"<a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.1 コスト管理ツールの使い分け</a>"},{"n":14,"topic":"予測できない利用量のテーブル","level":2,"body":["新しいサービスのバックエンドにDynamoDBを使います。公開直後は利用がほとんどない時間も長く、<b>いつ、どれだけ利用が増えるかは予測できません</b>。急なアクセスの増加にも対応でき、<b>使った分だけ</b>を支払いたいと考えています。最も適切なキャパシティの設定はどれですか。"],"options":[{"l":"A","html":"プロビジョンドモードで、想定される最大の読み書きのキャパシティを設定する"},{"l":"B","html":"オンデマンドモードを使う"},{"l":"C","html":"プロビジョンドモードでリザーブドキャパシティを購入する"},{"l":"D","html":"プロビジョンドモードで最小のキャパシティを設定し、スロットリングされたら手動で増やす"}],"answer":["B"],"multi":false,"req":"","key":"オンデマンドモードは、キャパシティを事前に決めずに<b>リクエストの数だけ課金</b>されます。利用が少ない時間の費用は小さく、急な増加にも自動で対応するため、<b>利用量が予測できない新しいサービス</b>に適しています。利用が安定して予測できるようになったら、プロビジョンドモードとAuto Scalingへの切り替えを検討します。","kw":"予測できない・使った分だけ → DynamoDBのオンデマンドモード","reasons":[{"l":"A","html":"利用が少ない時間も最大のキャパシティの料金を払い続けることになります。"},{"l":"C","html":"リザーブドキャパシティは、安定した利用量を長期で約束する場合の割引です。予測できない利用には合いません。"},{"l":"D","html":"スロットリングが起きてから手動で増やすまで、利用者のリクエストが失敗します。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.4 データベースのコスト最適化</a>"},{"n":15,"topic":"共有ファイルシステムの保管費用","level":2,"body":["複数のLinuxのEC2インスタンスからAmazon EFSのファイルシステムを共有しています。保存されている数十TBのファイルのうち、<b>大半は作成から1か月を過ぎるとほとんど読まれません</b>が、ときどき読まれることがあり、その場合はすぐに使える必要があります。アプリケーションを変えずに、<b>保管の費用を下げたい</b>と考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"ライフサイクル管理で、アクセスのないファイルをIAクラスへ移す"},{"l":"B","html":"古いファイルを毎月S3 Glacier Deep Archiveへ移し、EFSからは削除する"},{"l":"C","html":"EFSのスループットモードをプロビジョンドに変更する"},{"l":"D","html":"EFSをやめ、各インスタンスのEBSボリュームにファイルを分けて保存する"}],"answer":["A"],"multi":false,"req":"","key":"EFSのライフサイクル管理は、<b>指定した日数アクセスのないファイルを、保管料金の安い低頻度アクセス（IA）クラスへ自動で移し</b>ます。ファイルのパスは変わらないため、アプリケーションはそのまま読み書きでき、読まれたファイルをStandardへ戻す設定もできます。","kw":"EFSのアクセスが減ったファイル → ライフサイクル管理でIAクラスへ","reasons":[{"l":"B","html":"ファイルのパスが変わり、アプリケーションから読めなくなります。取り出しにも最大で数十時間かかります。"},{"l":"C","html":"スループットモードは性能の設定で、保管の費用は下がりません。むしろ料金が増えます。"},{"l":"D","html":"インスタンス間でファイルを共有できなくなり、アプリケーションの前提が崩れます。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.3 Amazon EFS</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"}]},{"id":"exam-set-32","file":"set-32.md","num":"問題セット32","title":"実戦演習⑧（本番の分野比率・15問）","questions":[{"n":1,"topic":"開発者が作るロールの上限","level":3,"body":["開発者に、自分のLambda関数用の<b>IAMロールを作成する権限</b>を与えたいと考えています。ただし、開発者が作ったロールが<b>管理者権限などを持たない</b>よう、あらかじめ決めた範囲を超える権限は付けられないようにする必要があります。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"開発者にIAMのフルアクセスを与え、作成されたロールをAWS Configで毎日確認する"},{"l":"B","html":"開発者が作ったロールを、セキュリティ担当者が手作業で承認してから使わせる"},{"l":"C","html":"アクセス許可境界を付けたロールだけを作成できるようにする"},{"l":"D","html":"開発者のIAMポリシーから <code>iam:CreateRole</code> を外し、ロールはすべて管理者が作る"}],"answer":["C"],"multi":false,"req":"","key":"アクセス許可境界（Permissions Boundary）は、ロールやユーザーが<b>持てる権限の上限</b>を決めるポリシーです。開発者の <code>iam:CreateRole</code> に「<code>iam:PermissionsBoundary</code> が指定の境界であること」という条件を付ければ、開発者は自由にロールを作れても、境界を超える権限は実際には使えません。<b>権限の委任</b>の定番の方法です。","kw":"権限の作成を委任しつつ上限を決める → アクセス許可境界","reasons":[{"l":"A","html":"事後の確認で、強い権限のロールが作られて使われるまでの間は防げません。"},{"l":"B","html":"手作業の承認は開発の速度を落とし、承認漏れも起こり得ます。"},{"l":"D","html":"安全ですが、開発者にロールの作成を任せるという要件を満たしません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":2,"topic":"暗号化されたAMIの共有","level":3,"body":["共有サービス用のアカウントで作成したAMIを、ワークロード用のアカウントで起動できるようにしたいと考えています。AMIのEBSスナップショットは、共有サービス用のアカウントの<b>KMSカスタマー管理キー</b>で暗号化されています。どの組み合わせが必要ですか。（<b>2つ選択してください</b>）"],"options":[{"l":"A","html":"AMIの起動許可に、ワークロード用のアカウントを追加する"},{"l":"B","html":"AMIを公開（パブリック）にする"},{"l":"C","html":"スナップショットをS3にエクスポートし、ワークロード用のアカウントのバケットへコピーする"},{"l":"D","html":"KMSのキーポリシーで、ワークロード用のアカウントにキーの使用を許可する"},{"l":"E","html":"AMIをAWS管理キー（aws/ebs）で暗号化し直してから共有する"}],"answer":["A","D"],"multi":true,"req":"","key":"暗号化されたAMIを別のアカウントで使うには、<b>AMIそのものの共有（起動許可）</b>と、<b>スナップショットを暗号化したキーの使用許可</b>の両方が必要です。キーの使用許可はキーポリシーで相手のアカウントに与え、相手のアカウントでもIAMポリシーで許可します。","kw":"暗号化AMIの共有 → 起動許可 ＋ カスタマー管理キーの共有","reasons":[{"l":"B","html":"暗号化されたAMIは公開できません。社内のAMIを公開すること自体も不適切です。"},{"l":"C","html":"AMIの共有には不要な手順で、そのままではAMIとして起動できません。"},{"l":"E","html":"AWS管理キーはキーポリシーを変更できないため、<b>AWS管理キーで暗号化したAMIは別のアカウントと共有できません</b>。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.8 AWS KMS</a> ／ <a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a>"},{"n":3,"topic":"改ざんできない記録の保管","level":2,"body":["金融機関は、取引の記録をS3に保存し、規制により<b>7年間は誰も削除や上書きができない</b>状態で保管しなければなりません。この制約は、<b>ルートユーザーを含むどの管理者も解除できない</b>ものである必要があります。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"オブジェクトロックをガバナンスモードで設定し、保持期間を7年にする"},{"l":"B","html":"オブジェクトロックをコンプライアンスモードで設定し、保持期間を7年にする"},{"l":"C","html":"バケットポリシーで、すべてのプリンシパルの <code>s3:DeleteObject</code> を拒否する"},{"l":"D","html":"バージョニングとMFA削除を有効にし、ライフサイクルで7年後に削除する"}],"answer":["B"],"multi":false,"req":"","key":"オブジェクトロックの<b>コンプライアンスモード</b>では、保持期間が終わるまで<b>ルートユーザーを含めて誰も</b>オブジェクトのバージョンを削除・上書きできず、保持期間を短くすることもできません。WORM（書き込みは1回、読み込みは何度でも）の規制要件に対応する設定です。","kw":"誰も解除できないWORM → オブジェクトロックのコンプライアンスモード","reasons":[{"l":"A","html":"ガバナンスモードは、特別な権限（<code>s3:BypassGovernanceRetention</code>）を持つユーザーが解除できるため、要件を満たしません。"},{"l":"C","html":"バケットポリシーは権限のある管理者が変更・削除できます。"},{"l":"D","html":"MFA削除はバージョンの削除に多要素認証を求めるだけで、MFAを持つルートユーザーは削除できます。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":4,"topic":"社内アプリへのログインの追加","level":2,"body":["ALBの背後で動く社内向けのWebアプリケーションには、ログインの機能がありません。社員は会社のIDプロバイダー（<b>OpenID Connect</b>に対応）でサインインしています。アプリケーションの<b>コードをほとんど変えずに</b>、サインインした社員だけがアプリケーションにアクセスできるようにしたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"アプリケーションにOIDCのライブラリを組み込み、ログイン画面とセッション管理を実装する"},{"l":"B","html":"ALBのセキュリティグループで、社内のIPアドレスからのアクセスだけを許可する"},{"l":"C","html":"CloudFrontを前段に置き、Lambda@EdgeでIDプロバイダーとの認証の処理を実装する"},{"l":"D","html":"ALBのHTTPSリスナーのルールに、OIDCのIDプロバイダーによる認証のアクションを追加する"}],"answer":["D"],"multi":false,"req":"","key":"ALBは、HTTPSリスナーのルールで<b>OIDCのIDプロバイダー（またはCognito）による認証を行う</b>ことができます。未認証の利用者はIDプロバイダーのサインイン画面へ転送され、認証が済んだリクエストだけがターゲットに届きます。アプリケーションはヘッダーで利用者の情報を受け取れます。","kw":"コードを変えずにサインインを追加 → ALBの認証アクション（OIDC／Cognito）","reasons":[{"l":"A","html":"実現はできますが、コードの大きな変更が必要で、要件に反します。"},{"l":"B","html":"場所による制限で、利用者の認証にはなりません。在宅勤務の社員も使えなくなります。"},{"l":"C","html":"認証の処理を自前で実装・保守することになり、ALBの標準機能より手間がかかります。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.5 負荷分散</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.4 Amazon Cognito</a>"},{"n":5,"topic":"危険な設定の自動修復","level":2,"body":["セキュリティ部門は、どのセキュリティグループでも<b>SSH（22番ポート）が0.0.0.0/0に開放された場合、自動的にそのルールを削除</b>したいと考えています。準拠状況も継続的に記録したいと考えています。<b>運用上のオーバーヘッドが最も少ない</b>方法はどれですか。"],"options":[{"l":"A","html":"毎日、全セキュリティグループを確認するスクリプトをEC2のcronで実行する"},{"l":"B","html":"Amazon GuardDutyで、SSHへの総当たり攻撃を検出して通知する"},{"l":"C","html":"Configルールで検出し、SSM Automationで自動修復する"},{"l":"D","html":"Amazon Inspectorのネットワーク到達性の評価を毎週実行する"}],"answer":["C"],"multi":false,"req":"","key":"AWS Configは、リソースの設定の変更を捉えて<b>ルールへの準拠を継続的に評価・記録</b>します。SSHの無制限の開放を検出するマネージドルールに、<b>Systems Manager Automationのランブックを修復アクションとして関連付ける</b>と、違反したルールを自動で削除できます。","kw":"設定の違反の検出と自動修復 → Config ＋ SSM Automation","reasons":[{"l":"A","html":"仕組みを自前で保守することになり、最大1日の間は開放されたままになります。"},{"l":"B","html":"GuardDutyは攻撃などの脅威を検知するサービスで、設定の準拠の評価や修復は行いません。"},{"l":"D","html":"到達性の評価は定期的な点検で、自動の修復はしません。週1回では開放の期間も長くなります。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.7 AWS Config</a> ／ <a href=\"#management\" data-go=\"management\">第8章 8.4 AWS Systems Manager</a>"},{"n":6,"topic":"口座ごとの順序と重複の防止","level":2,"body":["銀行のシステムは、入出金の依頼をキューに入れて処理します。<b>同じ口座の依頼は、送られた順に処理</b>しなければならず、<b>同じ依頼が二重に処理されてはいけません</b>。口座の数は数十万あり、異なる口座の依頼は並行して処理したいと考えています。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"SQSのFIFOキューを使い、口座番号をメッセージグループIDにする"},{"l":"B","html":"SQSの標準キューを使い、コンシューマーでタイムスタンプ順に並べ替える"},{"l":"C","html":"SQSのFIFOキューを使い、すべてのメッセージに同じメッセージグループIDを付ける"},{"l":"D","html":"SNSの標準トピックに発行し、Lambda関数で処理する"}],"answer":["A"],"multi":false,"req":"","key":"FIFOキューは<b>メッセージグループの中で順序を保証</b>し、重複排除IDにより<b>5分以内の重複した送信を取り除きます</b>。口座番号をグループIDにすれば、口座ごとの順序を守りながら、異なる口座の依頼は並行して処理できます。","kw":"順序の保証・重複の防止・グループ単位の並行処理 → FIFOキュー ＋ メッセージグループID","reasons":[{"l":"B","html":"標準キューは順序を保証せず、重複して配信されることもあります。並べ替えでは遅れて届いた依頼に対応できません。"},{"l":"C","html":"全体が1つのグループになり、1件ずつしか処理できないため、並行処理の要件を満たしません。"},{"l":"D","html":"標準トピックは順序も重複の防止も保証しません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a>"},{"n":7,"topic":"フェイルオーバー後の接続の遅れ","level":2,"body":["Lambda関数から、マルチAZ配置のRDS for MySQLに接続しています。フェイルオーバーのテストでは、データベースの切り替え自体は短時間で終わりましたが、<b>アプリケーションがエラーから回復するまでに数分かかり</b>、その間に大量の新しい接続が試みられました。フェイルオーバーの影響を<b>最小限に</b>したいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"リードレプリカを追加し、読み込みをリードレプリカへ向ける"},{"l":"B","html":"DBインスタンスのクラスを大きくし、最大接続数を増やす"},{"l":"C","html":"マルチAZ配置をやめ、スナップショットからの復元で障害に備える"},{"l":"D","html":"RDS Proxyを経由して接続する"}],"answer":["D"],"multi":false,"req":"","key":"RDS Proxyは、アプリケーションからの接続を保ったまま、<b>フェイルオーバー後の新しいプライマリへの接続を肩代わり</b>します。DNSの変更を待つ必要がなく、フェイルオーバーの時間を短縮できます。接続を<b>プールして再利用</b>するため、Lambdaの同時実行数が増えても接続が枯渇しにくくなります。","kw":"フェイルオーバーの影響の軽減・Lambdaからの大量の接続 → RDS Proxy","reasons":[{"l":"A","html":"読み込みの分散で、書き込みを含む接続の切り替えの問題は解決しません。"},{"l":"B","html":"接続の上限を上げても、DNSの切り替えを待つ時間と接続の殺到は変わりません。"},{"l":"C","html":"復旧にかかる時間が大幅に長くなり、可用性が下がります。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":8,"topic":"別のリージョンへのオブジェクトの複製","level":1,"body":["東京リージョンのS3バケットに保存される<b>新しいオブジェクト</b>を、災害対策のために大阪リージョンのバケットへ<b>自動で複製</b>したいと考えています。複製先ではストレージの費用を抑えるため、低頻度アクセスのストレージクラスで保存したいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"大阪のバケットで、東京のバケットをオリジンにしたCloudFrontを作成する"},{"l":"B","html":"バージョニングを有効にし、クロスリージョンレプリケーションを設定する"},{"l":"C","html":"毎晩、AWS CLIの <code>sync</code> で東京から大阪へコピーするcronジョブを実行する"},{"l":"D","html":"東京のバケットでS3 Transfer Accelerationを有効にする"}],"answer":["B"],"multi":false,"req":"","key":"クロスリージョンレプリケーション（CRR）は、<b>新しく書き込まれたオブジェクトを別のリージョンのバケットへ自動で非同期に複製</b>します。<b>複製元と複製先の両方でバージョニングが必要</b>で、複製先のストレージクラスも指定できます。既存のオブジェクトを複製するにはS3バッチレプリケーションを使います。","kw":"別リージョンへのオブジェクトの自動複製 → CRR（バージョニングが前提）","reasons":[{"l":"A","html":"CloudFrontはキャッシュの配信で、別のリージョンにデータの複製は作りません。"},{"l":"C","html":"最大1日分の遅れが生じ、仕組みも自前で保守することになります。"},{"l":"D","html":"Transfer Accelerationは遠距離からのアップロードの高速化で、複製の機能ではありません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":9,"topic":"アクセスの急増からバックエンドを守る","level":3,"body":["API GatewayとLambda関数で受け付けた応募のデータを、Lambda関数がRDSへ書き込んでいます。キャンペーンの開始直後には<b>数分間で通常の100倍</b>のリクエストが届き、データベースの接続が枯渇して応募の多くが失敗します。応募の書き込みは<b>数分遅れてもかまいません</b>が、<b>受け付けた応募を失ってはいけません</b>。どの組み合わせが適切ですか。（<b>2つ選択してください</b>）"],"options":[{"l":"A","html":"Lambda関数のタイムアウトを最大の15分に延ばす"},{"l":"B","html":"RDSのインスタンスクラスを、キャンペーンの最大の負荷に合わせて常に大きくしておく"},{"l":"C","html":"API GatewayからSQSのキューへ直接メッセージを送る統合にし、応募をキューに蓄える"},{"l":"D","html":"API Gatewayのキャッシュを有効にし、同じ応募への応答を再利用する"},{"l":"E","html":"イベントソースマッピングの最大同時実行数を設定する"}],"answer":["C","E"],"multi":true,"req":"","key":"受け付けと書き込みの間に<b>SQSのキュー</b>を入れると、急増したリクエストは<b>キューにたまるだけ</b>で失われません。書き込み側は、イベントソースマッピングの<b>最大同時実行数</b>で同時に動く関数の数を抑えれば、データベースが処理できる速さで順に書き込めます。「受けるのは速く、処理はゆっくり」の平準化です。","kw":"急増の平準化・失わない → SQSでバッファリング ＋ 消費の速さの制御","reasons":[{"l":"A","html":"関数の実行が長くなるほど接続を持つ時間が延び、接続の枯渇は悪化します。"},{"l":"B","html":"ピークに合わせた常時の大型化はコストが大きく、急増の規模が変われば再び失敗します。"},{"l":"D","html":"応募は一件ごとに内容が違い、書き込みはキャッシュできません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a> ／ <a href=\"#others\" data-go=\"others\">第10章 10.1 Amazon API Gateway</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.2 疎結合アーキテクチャ</a>"},{"n":10,"topic":"レポートのクエリの切り離し","level":1,"body":["RDS for MySQLを使う業務システムで、営業部門が日中に<b>重いレポートのクエリ</b>を実行すると、注文の処理が遅くなります。レポートは<b>数秒前のデータ</b>で問題ありません。アプリケーションの変更は、レポートの接続先を変えることだけにしたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"マルチAZ配置に変更し、スタンバイでレポートを実行する"},{"l":"B","html":"レポートの実行を夜間だけに制限する"},{"l":"C","html":"リードレプリカを作成し、レポートの接続先をリードレプリカにする"},{"l":"D","html":"データベースをDynamoDBへ移行する"}],"answer":["C"],"multi":false,"req":"","key":"リードレプリカは<b>非同期で複製される読み込み専用のコピー</b>で、別のエンドポイントを持ちます。レポートの接続先をリードレプリカに変えれば、重い読み込みがプライマリの注文処理に影響しなくなります。複製の遅れは通常数秒以内で、要件の範囲に収まります。","kw":"読み込みの負荷の分離・多少古くてよい → リードレプリカ","reasons":[{"l":"A","html":"マルチAZ配置のスタンバイ（DBインスタンスの場合）は読み込みに使えません。"},{"l":"B","html":"日中にレポートを使いたいという業務の要件を満たしません。"},{"l":"D","html":"大規模な移行とアプリケーションの書き換えが必要で、要件に反します。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#database\" data-go=\"database\">第4章 4.5 データベースの性能問題の切り分け</a>"},{"n":11,"topic":"長時間かかるファイルの処理","level":2,"body":["S3にアップロードされた動画ファイルを、アップロードのたびに変換しています。現在はLambda関数で処理していますが、大きなファイルでは<b>処理に30分以上かかり、途中で終了</b>してしまいます。サーバーの管理はしたくありません。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"Lambda関数のメモリを最大にして、処理を15分以内に終わらせる"},{"l":"B","html":"変換の処理をLambda関数の非同期呼び出しに変え、再試行の回数を増やす"},{"l":"C","html":"変換用のEC2インスタンスを常時起動し、S3を定期的に確認させる"},{"l":"D","html":"EventBridgeからFargateのタスクを起動して変換する"}],"answer":["D"],"multi":false,"req":"","key":"Lambda関数の実行時間は<b>最大15分</b>です。それを超える処理は、<b>サーバーの管理が不要なFargate</b>のタスクで実行します。S3のイベントをEventBridgeで受け、ルールのターゲットにECSのタスクを指定すれば、アップロードのたびに自動でタスクが起動し、処理が終われば停止します。","kw":"15分を超える処理・サーバー管理なし → Fargateのタスク","reasons":[{"l":"A","html":"速くはなっても、30分以上かかる処理が15分以内に収まる保証はありません。"},{"l":"B","html":"非同期にしても実行時間の上限は同じで、同じところで終了して再試行を繰り返すだけです。"},{"l":"C","html":"サーバーの管理が必要で、ファイルがない時間も料金がかかります。"}],"refs":"<a href=\"#container\" data-go=\"container\">第9章 9.3 AWS Fargate</a> ／ <a href=\"#compute\" data-go=\"compute\">第1章 1.6 AWS Lambda</a> ／ <a href=\"#integration\" data-go=\"integration\">第6章 6.3 Amazon EventBridge</a>"},{"n":12,"topic":"急ぎのオンプレミスとの接続","level":2,"body":["ある企業は、オンプレミスのデータセンターとVPCを<b>2週間後から</b>プライベートに接続する必要があります。長期的には、<b>安定した帯域と低いレイテンシー</b>のために専用線を使いたいと考えています。最も適切な計画はどれですか。"],"options":[{"l":"A","html":"当面はVPNで接続し、開通後にDirect Connectへ切り替える"},{"l":"B","html":"Direct Connectを申し込み、開通までは接続を待つ"},{"l":"C","html":"インターネットゲートウェイ経由のパブリックな通信で代用する"},{"l":"D","html":"Snowball Edgeでデータを運び、開通までの通信の代わりにする"}],"answer":["A"],"multi":false,"req":"","key":"Direct Connectの開通には、回線の手配などで<b>数週間から数か月</b>かかることがあります。Site-to-Site VPNはインターネットを使って<b>すぐに構成できる</b>ため、当面の接続に使い、専用線の開通後は主経路をDirect Connectに移します。VPNはそのまま予備の経路として残すこともできます。","kw":"すぐに必要 → VPN／長期的に安定した帯域 → Direct Connect","reasons":[{"l":"B","html":"2週間後に接続するという要件に間に合わない可能性があります。"},{"l":"C","html":"プライベートな接続という要件を満たさず、公開による危険も生じます。"},{"l":"D","html":"Snowballはデータの一括の移送で、システム同士の継続的な通信の代わりにはなりません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続</a>"},{"n":13,"topic":"常時稼働するデータベースの割引","level":2,"body":["本番のRDS for PostgreSQLは、<b>24時間365日稼働</b>し、少なくとも今後3年間は同じ規模で使い続ける見込みです。データベースの<b>費用を最も下げたい</b>と考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"3年のCompute Savings Plansを購入する"},{"l":"B","html":"RDSのリザーブドインスタンス（3年・全額前払い）を購入する"},{"l":"C","html":"夜間はDBインスタンスを停止し、朝に起動する"},{"l":"D","html":"EC2のスポットでPostgreSQLを自前で運用する"}],"answer":["B"],"multi":false,"req":"","key":"常時稼働し、長期間使い続けるRDSには、<b>RDSのリザーブドインスタンス</b>が定番の割引です。3年・全額前払いが最も割引率が高く、同じエンジンのインスタンスファミリーの中ではサイズの柔軟性も使えます。","kw":"常時稼働のRDS・長期間 → RDSのリザーブドインスタンス","reasons":[{"l":"A","html":"Compute Savings Plansの対象はEC2・Fargate・Lambdaで、RDSには適用されません。"},{"l":"C","html":"24時間の稼働が必要な本番のデータベースは止められません。停止しても7日で自動的に起動します。"},{"l":"D","html":"中断されるスポットでデータベースを動かすのは危険で、運用も自前になります。"}],"refs":"<a href=\"#d4\" data-go=\"d4\">第14章 14.4 データベースのコスト最適化</a> ／ <a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a>"},{"n":14,"topic":"めったに読まないがすぐ必要なデータ","level":2,"body":["病院は、医療画像をS3に保存しています。画像は作成から数か月後には<b>四半期に1回程度</b>しか参照されませんが、参照するときは<b>ミリ秒単位ですぐに</b>表示できなければなりません。保存期間は長期にわたります。保管の費用を<b>最も下げる</b>ストレージクラスはどれですか。"],"options":[{"l":"A","html":"S3 Standard"},{"l":"B","html":"S3 Glacier Flexible Retrieval"},{"l":"C","html":"S3 Glacier Instant Retrieval"},{"l":"D","html":"S3 Glacier Deep Archive"}],"answer":["C"],"multi":false,"req":"","key":"Glacier Instant Retrievalは、<b>ミリ秒での取り出し</b>ができるアーカイブ用のクラスで、四半期に1回程度しか読まれない長期保管のデータで保管の費用が最も安くなります（Standard-IAより保管料金が安く、取り出し料金は高い）。最低保存期間は90日です。","kw":"めったに読まない・ミリ秒ですぐに → Glacier Instant Retrieval","reasons":[{"l":"A","html":"頻繁に使うデータ向けで、保管の費用が最も高くなります。"},{"l":"B","html":"取り出しに数分から数時間かかり、すぐに表示できません。"},{"l":"D","html":"取り出しに標準で最大12時間（大容量の取り出しでは最大48時間）かかり、要件を満たしません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":15,"topic":"ほとんど使われないAPI","level":1,"body":["社内の申請システムのAPIは、1台のEC2インスタンスで<b>24時間稼働</b>していますが、リクエストは<b>1日に数百件</b>しかありません。1回の処理は1秒ほどで終わります。サーバーの管理もなくし、<b>費用を最も下げたい</b>と考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"EC2インスタンスを最小のサイズに変更し、1年のリザーブドインスタンスを購入する"},{"l":"B","html":"EC2インスタンスをスポットインスタンスに変え、中断時は自動で再起動する"},{"l":"C","html":"ECS on Fargateで常時1つのタスクを動かす"},{"l":"D","html":"API GatewayとLambda関数に移行する"}],"answer":["D"],"multi":false,"req":"","key":"リクエストが少なく処理も短いAPIは、<b>リクエストの数と実行時間だけ課金されるAPI GatewayとLambda</b>が最も安くなります。待機している時間の料金がかからず、サーバーの管理も不要です。","kw":"利用が少ない・待機時間の無駄 → サーバーレス（API Gateway ＋ Lambda）","reasons":[{"l":"A","html":"安くはなりますが、使わない時間も料金を払い続け、サーバーの管理も残ります。"},{"l":"B","html":"中断のたびにAPIが止まり、サーバーの管理も残ります。"},{"l":"C","html":"サーバーの管理はなくなりますが、タスクが常時動く分の料金がかかります。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.6 AWS Lambda</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"}]},{"id":"exam-set-33","file":"set-33.md","num":"問題セット33","title":"模擬試験①（本番形式・65問）","questions":[{"n":1,"topic":"常に高負荷の処理の実行基盤","level":3,"body":["画像認識のバックエンドは、<b>24時間、ほぼ一定の高い負荷</b>で動き続け、リクエストの処理にはそれぞれ数秒かかります。現在はLambda関数で動いていますが、毎月の料金が高くなっています。今後数年は同じ負荷が続く見込みで、サーバーの運用はある程度受け入れられます。<b>費用を最も下げる</b>方法はどれですか。"],"options":[{"l":"A","html":"Lambda関数のメモリを最大にする"},{"l":"B","html":"EC2に移してSavings Plansを適用する"},{"l":"C","html":"Lambda関数のプロビジョニング済み同時実行数を増やす"},{"l":"D","html":"API Gatewayのキャッシュを有効にする"}],"answer":["B"],"multi":false,"req":"","key":"Lambdaは<b>使った分だけ払う</b>ので、アイドルの時間が長いワークロードで有利です。逆に、<b>24時間ほぼ一定で高い負荷</b>が続く場合は、同じ処理能力のEC2を常時動かし、Savings Plansで割り引くほうが一般に安くなります。負荷の変動はAuto Scalingで吸収します。","kw":"常に高く一定の負荷・長期間 → EC2 ＋ Savings Plans（Lambdaは変動やアイドルに強い）","reasons":[{"l":"A","html":"実行時間が縮んでも、CPUを使い続ける処理では料金はほとんど下がらず、上がることもあります。"},{"l":"C","html":"初期化の待ち時間の対策で、料金はむしろ増えます。"},{"l":"D","html":"画像ごとに内容が違う処理は、キャッシュの効果がほとんどありません。"}],"refs":"<a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a> ／ <a href=\"#container\" data-go=\"container\">第9章 コンピューティングサービスの選定フロー</a>"},{"n":2,"topic":"起動に時間がかかるインスタンス","level":2,"body":["Auto Scalingグループのインスタンスは、起動後にアプリケーションの初期化とキャッシュの読み込みで<b>約10分</b>かかります。そのため、負荷が急に増えたときにスケールアウトが間に合わず、応答が遅くなります。常に多めの台数を<b>稼働させ続けることは避けたい</b>と考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"希望容量を常にピーク時の台数に設定する"},{"l":"B","html":"ウォームプールを設定する"},{"l":"C","html":"ヘルスチェックの猶予期間を短くする"},{"l":"D","html":"スケールアウトのクールダウン期間を長くする"}],"answer":["B"],"multi":false,"req":"","key":"ウォームプールは、<b>初期化を済ませたインスタンスを停止（または休止）した状態で待機</b>させておく機能です。スケールアウトのときはそこから起動するため、ゼロから起動するより大幅に早く処理に加われます。停止中のインスタンスにはEC2の料金がかからず（EBSの料金はかかる）、常に稼働させるより安く済みます。","kw":"起動・初期化に時間がかかる → ウォームプール","reasons":[{"l":"A","html":"常にピーク時の台数を稼働させることになり、要件に反します。"},{"l":"C","html":"初期化の時間は変わらず、初期化の途中で異常と判定されて入れ替えが繰り返される危険があります。"},{"l":"D","html":"次のスケーリングまでの待ち時間が延びるだけで、起動の遅さは解決しません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.2 EC2 Auto Scaling</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a>"},{"n":3,"topic":"機器ごとの順序と複数の処理","level":2,"body":["数万台の機器が、毎秒大量の測定値を送信します。<b>同じ機器の測定値は届いた順に</b>処理し、<b>異常検知・ダッシュボード・長期保存の3つのアプリケーション</b>がそれぞれ同じデータを読みます。障害が起きたアプリケーションは、<b>過去24時間分のデータを読み直せる</b>必要があります。最も適切なサービスはどれですか。"],"options":[{"l":"A","html":"Kinesis Data Streams"},{"l":"B","html":"SQSの標準キュー"},{"l":"C","html":"SQSのFIFOキュー（機器IDをメッセージグループIDにする）"},{"l":"D","html":"SNSの標準トピック"}],"answer":["A"],"multi":false,"req":"","key":"Kinesis Data Streamsは、<b>同じパーティションキーのレコードを同じシャードに順序どおり</b>保存します。データは保持期間の間ストリームに残り、<b>複数のコンシューマーがそれぞれ独立して読み</b>、必要なら位置を戻して<b>読み直せます</b>。3つの要件をすべて満たすのはKinesis Data Streamsです。","kw":"順序・複数のコンシューマー・読み直し → Kinesis Data Streams","reasons":[{"l":"B","html":"順序を保証せず、受信して削除したメッセージは読み直せません。1つのメッセージを3つのアプリケーションで読むこともできません。"},{"l":"C","html":"順序は守れますが、処理したメッセージは削除され、複数のアプリケーションで同じデータを読むことも読み直すこともできません。"},{"l":"D","html":"配信した後にデータは残らず、読み直しはできません。標準トピックは順序も保証しません。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.1 Amazon Kinesis</a> ／ <a href=\"#integration\" data-go=\"integration\">第6章 アプリケーション統合サービスの横断まとめ</a>"},{"n":4,"topic":"予算を超えたときの自動の対処","level":2,"body":["研究部門のアカウントでは、検証用のEC2インスタンスの起動し忘れで<b>費用が予算を超える</b>ことがあります。月の予算を超えたら、<b>通知に加えて、対象のEC2インスタンスを自動で停止</b>したいと考えています。仕組みは<b>できるだけ作り込みたくありません</b>。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"Cost Explorerのレポートを毎日確認し、担当者がインスタンスを停止する"},{"l":"B","html":"Cost and Usage Reportを毎時集計するLambda関数を作り、しきい値を超えたらインスタンスを停止する"},{"l":"C","html":"AWS Budgetsで予算を作成し、予算のアクションでEC2インスタンスの停止を設定する"},{"l":"D","html":"Cost Anomaly Detectionで異常を検知し、SNSで通知する"}],"answer":["C"],"multi":false,"req":"","key":"AWS Budgetsの<b>予算のアクション</b>は、実績や予測がしきい値を超えたときに、<b>IAMポリシーやSCPの適用、特定のEC2・RDSのインスタンスの停止</b>を自動で（または承認を経て）実行できます。通知と対処を、作り込みなしで設定できます。","kw":"予算の超過で自動の対処 → AWS Budgetsの予算のアクション","reasons":[{"l":"A","html":"手作業で、対応の遅れや漏れが起きます。"},{"l":"B","html":"実現はできますが、集計と停止の仕組みを自分で作って保守することになります。"},{"l":"D","html":"普段と違う支出の検知と通知はできますが、予算に基づく停止は行いません。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.9〜10.11 コスト管理サービス</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.1 コスト管理ツールの使い分け</a>"},{"n":5,"topic":"特定のIPアドレス範囲の遮断","level":1,"body":["Webサーバーのログを調べたところ、特定のIPアドレス範囲（203.0.113.0/24）から不正なアクセスが繰り返されていることがわかりました。WebサーバーはパブリックサブネットのEC2で、セキュリティグループでは0.0.0.0/0からのHTTPSを許可しています。この範囲からの通信を<b>すぐに遮断</b>する最も適切な方法はどれですか。"],"options":[{"l":"A","html":"ネットワークACLに、この範囲を拒否するルールを追加する"},{"l":"B","html":"セキュリティグループに、203.0.113.0/24からの通信を拒否するルールを追加する"},{"l":"C","html":"VPCのルートテーブルで、203.0.113.0/24宛ての経路を削除する"},{"l":"D","html":"インスタンスのOSのファイアウォールに設定するよう、アプリケーションチームに依頼する"}],"answer":["A"],"multi":false,"req":"","key":"特定の送信元を<b>拒否</b>できるのはネットワークACLです。ネットワークACLはルールを<b>番号の小さい順に評価</b>し、最初に一致したルールを適用するため、拒否のルールを許可のルールより小さい番号にする必要があります。","kw":"特定のIPアドレスの拒否 → ネットワークACL（番号の小さい順）","reasons":[{"l":"B","html":"セキュリティグループには許可のルールしかなく、拒否のルールは書けません。"},{"l":"C","html":"ルートテーブルは宛先による経路の制御です。戻りの通信が届かなくなるだけで、送信元からの通信を確実に止める方法ではありません。"},{"l":"D","html":"インスタンスごとの設定になり、設定漏れや時間の遅れが起きます。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.2 セキュリティグループとネットワークACL</a>"},{"n":6,"topic":"コンテナのスケーリングの指標","level":2,"body":["ALBの背後で、ECS on Fargateのサービスが動いています。アプリケーションは外部のAPIの応答を待つ時間が長いため、<b>CPU使用率はあまり上がらないのに、リクエストが増えると応答が遅く</b>なります。負荷テストでは、1タスクあたり毎分600リクエストまでなら応答が安定していました。最も適切なスケーリングの設定はどれですか。"],"options":[{"l":"A","html":"CPU使用率70%を目標にしたターゲット追跡スケーリング"},{"l":"B","html":"メモリ使用率70%を目標にしたターゲット追跡スケーリング"},{"l":"C","html":"毎日決まった時刻にタスク数を増やすスケジュールされたスケーリング"},{"l":"D","html":"ALBのターゲットあたりのリクエスト数で追跡する"}],"answer":["D"],"multi":false,"req":"","key":"負荷の実態は<b>リクエストの数</b>で、CPUには表れていません。ALBのターゲットあたりのリクエスト数を目標値（例えば1タスクあたり毎分600）にしたターゲット追跡にすれば、リクエストが増えるとタスクが増え、1タスクの負荷が安定する範囲に保たれます。","kw":"CPUに表れない負荷・リクエスト数で決まる → ALBRequestCountPerTarget","reasons":[{"l":"A","html":"CPU使用率が上がらないため、リクエストが増えてもスケールアウトしません。"},{"l":"B","html":"メモリ使用率も負荷の実態を表していません。"},{"l":"C","html":"リクエストの増減が決まった時刻に起きるとは限らず、予期しない増加に対応できません。"}],"refs":"<a href=\"#container\" data-go=\"container\">第9章 9.1 Amazon ECS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a>"},{"n":7,"topic":"組織全体の機密データの把握","level":2,"body":["ある企業は、AWS Organizationsの数十のアカウントに、数千のS3バケットを持っています。どのバケットに<b>個人情報（氏名・住所・クレジットカード番号など）</b>が含まれているかを継続的に把握し、結果を1つのアカウントで確認したいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"Amazon Inspectorを全アカウントで有効にする"},{"l":"B","html":"Amazon Macieを組織で有効にする"},{"l":"C","html":"S3のサーバーアクセスログをAthenaで検索する"},{"l":"D","html":"AWS Configのルールで、暗号化されていないバケットを検出する"}],"answer":["B"],"multi":false,"req":"","key":"Macieは、機械学習とパターン照合で<b>S3の中の個人情報などの機密データを検出</b>するサービスです。Organizationsと統合して<b>委任管理者のアカウントから全アカウントを一元管理</b>でき、自動の機密データの検出でバケットを継続的に調べられます。","kw":"S3の中の個人情報の検出 → Macie（組織での一元管理）","reasons":[{"l":"A","html":"Inspectorはソフトウェアの脆弱性を評価するサービスで、データの中身は調べません。"},{"l":"C","html":"アクセスログはリクエストの記録で、オブジェクトの中に何が含まれているかはわかりません。"},{"l":"D","html":"暗号化の有無はわかっても、個人情報が含まれているかどうかはわかりません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.9 Amazon Macie</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.13 検出系の整理</a>"},{"n":8,"topic":"Auroraのフェイルオーバーの時間","level":2,"body":["Aurora MySQLのクラスターは、ライターインスタンス1台だけで構成されています。ライターのインスタンスに障害が起きた場合の<b>復旧時間を最も短く</b>したいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"ストレージのバックトラックを有効にする"},{"l":"B","html":"自動バックアップの保持期間を延ばす"},{"l":"C","html":"別のAZにAuroraレプリカを追加する"},{"l":"D","html":"インスタンスクラスを大きくする"}],"answer":["C"],"multi":false,"req":"","key":"Auroraは、ライターに障害が起きると<b>Auroraレプリカを新しいライターに昇格</b>させます。レプリカがあれば切り替えは通常数十秒程度で終わります。レプリカがない場合は新しいインスタンスを作り直すため、復旧に時間がかかります（通常10分程度）。レプリカはクラスターの共有ストレージを使うため、データの欠落もありません。","kw":"Auroraのフェイルオーバーを速く → 別のAZにAuroraレプリカ","reasons":[{"l":"A","html":"バックトラックは誤操作からの巻き戻しの機能で、インスタンスの障害からの復旧を速めるものではありません。"},{"l":"B","html":"バックアップからの復元は、フェイルオーバーより時間がかかります。"},{"l":"D","html":"インスタンスの障害への備えにはならず、復旧の時間も変わりません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.2 Amazon Aurora</a>"},{"n":9,"topic":"顧客ごとのS3のプレフィックス","level":2,"body":["Amazon Data Firehoseで受け取ったイベントをS3に保存しています。イベントのJSONには <code>customer_id</code> が含まれ、分析チームは<b>顧客ごとにAthenaで検索</b>します。現在はすべての顧客のデータが日付のプレフィックスだけで保存されており、1人の顧客を調べるにも全体をスキャンしています。変換用のサーバーやジョブは追加したくありません。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"Firehoseのバッファのサイズを大きくする"},{"l":"B","html":"S3のイベント通知でLambda関数を起動し、ファイルを顧客ごとのプレフィックスへコピーする"},{"l":"C","html":"AWS GlueのETLジョブを毎時実行し、データを顧客ごとに並べ替える"},{"l":"D","html":"Firehoseの動的パーティショニングを使う"}],"answer":["D"],"multi":false,"req":"","key":"Firehoseの<b>動的パーティショニング</b>は、レコードの中のキー（<code>customer_id</code> など）を取り出して、<b>S3のプレフィックスを分けて配信</b>する機能です。顧客ごとのプレフィックスにパーティションとして保存されるため、Athenaは対象の顧客のデータだけを読めます。追加のサーバーやジョブも要りません。","kw":"レコードの値でS3のプレフィックスを分ける → Firehoseの動的パーティショニング","reasons":[{"l":"A","html":"ファイルの大きさが変わるだけで、顧客ごとには分かれません。"},{"l":"B","html":"コピーの処理とデータの重複が増え、保管の費用も2倍になります。"},{"l":"C","html":"ETLジョブの追加は要件に反し、反映も最大1時間遅れます。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.1 Amazon Kinesis</a> ／ <a href=\"#analytics\" data-go=\"analytics\">第7章 7.3 Amazon Athena</a>"},{"n":10,"topic":"オリジンへのリクエストの集中","level":3,"body":["動画配信サービスは、CloudFrontでS3以外のカスタムオリジン（EC2）の動画を配信しています。世界中の利用者に人気の動画が公開されると、<b>多くのエッジロケーションから同じファイルの取得がオリジンに集中</b>し、オリジンの負荷が高くなります。オリジンへのリクエストを<b>最も減らす</b>方法はどれですか。"],"options":[{"l":"A","html":"CloudFront Origin Shieldを有効にする"},{"l":"B","html":"CloudFrontの価格クラスを「すべてのエッジロケーション」にする"},{"l":"C","html":"オリジンのEC2のインスタンスタイプを大きくする"},{"l":"D","html":"キャッシュのTTLを0秒にする"}],"answer":["A"],"multi":false,"req":"","key":"Origin Shieldは、<b>エッジロケーションとオリジンの間にもう1段のキャッシュ層</b>を置く機能です。各エッジからのキャッシュミスはOrigin Shieldに集まり、そこでもキャッシュされるため、<b>オリジンに届く同じファイルのリクエストが大幅に減ります</b>。","kw":"多くのエッジからオリジンへの集中 → Origin Shield","reasons":[{"l":"B","html":"使うエッジロケーションが増えると、オリジンへの取得はかえって増える可能性があります。"},{"l":"C","html":"負荷に耐えやすくはなりますが、リクエストの数は減りません。"},{"l":"D","html":"キャッシュされなくなり、すべてのリクエストがオリジンに届きます。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFront と Global Accelerator</a>"},{"n":11,"topic":"新しいボリュームの暗号化","level":1,"body":["あるリージョンで、今後作成される<b>すべてのEBSボリュームとスナップショットを必ず暗号化</b>したいと考えています。開発者が暗号化の指定を忘れても、暗号化されるようにする必要があります。<b>運用上のオーバーヘッドが最も少ない</b>方法はどれですか。"],"options":[{"l":"A","html":"暗号化されていないボリュームをAWS Configで検出し、担当者に通知する"},{"l":"B","html":"開発者向けの手順書に、暗号化の指定を必須と明記する"},{"l":"C","html":"EBSの既定の暗号化を有効にする"},{"l":"D","html":"毎晩、暗号化されていないボリュームのスナップショットを暗号化してコピーするLambda関数を実行する"}],"answer":["C"],"multi":false,"req":"","key":"EBSの既定の暗号化を有効にすると、そのアカウントのそのリージョンで<b>新しく作成されるボリュームとスナップショットのコピーが自動的に暗号化</b>されます。指定を忘れても暗号化され、設定は1回で済みます。既存のボリュームは暗号化されないため、別途スナップショットを経由して移行します。","kw":"今後のEBSを必ず暗号化 → EBSの既定の暗号化（リージョン単位）","reasons":[{"l":"A","html":"作成された後の検出で、暗号化されていない状態を防げません。"},{"l":"B","html":"人の注意に頼る方法で、漏れを防げません。"},{"l":"D","html":"暗号化されていない期間が生じ、仕組みの保守も必要です。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.2 Amazon EBS</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":12,"topic":"古くならないキャッシュ","level":2,"body":["ECサイトの商品ページは、RDSの商品情報をElastiCacheにキャッシュして表示しています。現在は遅延読み込み（キャッシュになければDBから読んでキャッシュに入れる）だけを使っているため、価格を更新した後もしばらく<b>古い価格が表示</b>されます。読み込みの速さを保ったまま、<b>更新がすぐにキャッシュに反映</b>されるようにしたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"キャッシュのTTLを長くする"},{"l":"B","html":"キャッシュをやめ、すべてDBから読み込む"},{"l":"C","html":"書き込みスルーでキャッシュも更新する"},{"l":"D","html":"ElastiCacheのノードを増やす"}],"answer":["C"],"multi":false,"req":"","key":"書き込みスルーは、<b>DBへの書き込みと同時にキャッシュも更新</b>する方式で、キャッシュの内容が古くなりません。読み込みはこれまでどおりキャッシュから速く返せます。使われないデータがキャッシュにたまらないよう、TTLと組み合わせるのが一般的です。","kw":"キャッシュを古くしない → 書き込みスルー（＋TTL）","reasons":[{"l":"A","html":"古い値が残る時間がさらに長くなります。"},{"l":"B","html":"読み込みが遅くなり、DBの負荷も増えます。"},{"l":"D","html":"処理能力は増えても、キャッシュの内容が古くなる問題は変わりません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.4 Amazon ElastiCache</a>"},{"n":13,"topic":"多数のVPCの接続","level":2,"body":["ある企業には、複数のアカウントに<b>80のVPC</b>があり、さらにオンプレミスのデータセンターともDirect Connectで接続しています。VPC同士とオンプレミスの間で<b>相互に通信</b>でき、VPCが増えても<b>接続の管理が増えすぎない</b>構成にしたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"すべてのVPCの組み合わせでVPCピアリングを結ぶ"},{"l":"B","html":"各VPCに仮想プライベートゲートウェイを付け、それぞれのVPCとオンプレミスをVPNで接続する"},{"l":"C","html":"Transit Gatewayを中心に、VPCとDirect Connectをつなぐ"},{"l":"D","html":"1つのVPCをハブにして、ほかのVPCとピアリングし、ハブ経由で通信させる"}],"answer":["C"],"multi":false,"req":"","key":"Transit Gatewayは、<b>VPCとオンプレミスの接続を1か所に集めるハブ</b>です。各VPCは1回アタッチするだけで相互に通信でき、Direct Connect GatewayやVPNとも接続できます。ルートテーブルで通信の範囲を分けることもできます。","kw":"多数のVPC ＋ オンプレミスの相互接続 → Transit Gateway","reasons":[{"l":"A","html":"80のVPCでは3,000以上のピアリングが必要になり、管理が破綻します。"},{"l":"B","html":"VPCの数だけVPNを管理することになり、VPC同士の通信も実現しません。"},{"l":"D","html":"ピアリングは<b>推移的な経路をサポートしない</b>ため、ハブのVPCを経由して別のVPCと通信することはできません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.4 ネットワークパフォーマンスの最適化</a>"},{"n":14,"topic":"インスタンスの単価の見直し","level":2,"body":["Javaで書かれたWebアプリケーションが、x86のEC2インスタンス（Auto Scalingグループ）で動いています。アプリケーションは特定のCPUに依存するネイティブのライブラリを使っていません。<b>アーキテクチャを大きく変えずに、同じ性能あたりの費用を下げたい</b>と考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"インスタンスをすべてDedicated Hostsへ移す"},{"l":"B","html":"AWS Graviton（Arm）ベースのインスタンスタイプに変更する"},{"l":"C","html":"インスタンスのサイズを1段階大きくし、台数を減らす"},{"l":"D","html":"拡張ネットワーキングを無効にする"}],"answer":["B"],"multi":false,"req":"","key":"Graviton（Arm）ベースのインスタンスは、同等のx86のインスタンスより<b>性能あたりの価格が良い</b>（AWSは最大40％の価格性能の向上をうたっています）のが特長です。JavaやPythonなどで、特定のCPUに依存するネイティブのコードがなければ、起動テンプレートのインスタンスタイプとAMIを変えるだけで移行できることが多くあります。","kw":"性能あたりの費用を下げる・CPUに依存しない → Graviton","reasons":[{"l":"A","html":"ライセンスや規制のための物理サーバーの専有で、費用はむしろ上がります。"},{"l":"C","html":"台数が減っても費用が下がるとは限らず、1台あたりの障害の影響も大きくなります。"},{"l":"D","html":"拡張ネットワーキングに追加の料金はなく、無効にしても性能が落ちるだけです。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":15,"topic":"APIの利用者の認証","level":2,"body":["モバイルアプリの利用者は、Amazon Cognitoのユーザープールでサインインします。アプリはAPI Gateway（REST API）経由でバックエンドのLambda関数を呼び出します。<b>サインインした利用者だけ</b>がAPIを呼び出せるようにし、トークンの検証の処理は<b>自分で実装したくありません</b>。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"APIキーと使用量プランを作成し、アプリに同じAPIキーを埋め込む"},{"l":"B","html":"API GatewayにCognitoユーザープールのオーソライザーを設定する"},{"l":"C","html":"Lambda関数の中で、トークンの署名を検証する処理を実装する"},{"l":"D","html":"API Gatewayのリソースポリシーで、アプリの利用者のIPアドレスだけを許可する"}],"answer":["B"],"multi":false,"req":"","key":"Cognitoユーザープールのオーソライザーを使うと、<b>API Gatewayがリクエストに付いたトークン（JWT）を自動で検証</b>し、正しいトークンを持つリクエストだけをバックエンドへ通します。検証のコードは不要です。","kw":"ユーザープールでサインインした利用者だけ → Cognitoオーソライザー","reasons":[{"l":"A","html":"APIキーは利用者の識別や使用量の管理のためのもので、認証の手段ではありません。アプリに埋め込んだキーは抜き取られます。"},{"l":"C","html":"実現はできますが、検証の処理を自分で実装・保守することになり、要件に反します。"},{"l":"D","html":"モバイルの利用者のIPアドレスは変わり続けるため、管理できません。IPアドレスでは利用者の認証もできません。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.1 Amazon API Gateway</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.4 Amazon Cognito</a>"},{"n":16,"topic":"最小権限のIAMポリシー","level":2,"body":["Lambda関数が、Amazon DynamoDBの <code>Orders</code> テーブルに項目を<b>追加・更新・削除</b>します。関数の実行ロールに付けるIAMポリシーは、<code>Orders</code> テーブルへのこの3つの操作だけを許可し、ほかのテーブルやほかの操作は許可しないようにする必要があります。<b>最小権限</b>を満たすポリシーはどれですか。"],"options":[{"l":"A","html":"<code>Action</code> に <code>dynamodb:*</code>、<code>Resource</code> に <code>Orders</code> テーブルのARNを指定する"},{"l":"B","html":"<code>Action</code> に <code>dynamodb:PutItem</code>・<code>dynamodb:UpdateItem</code>・<code>dynamodb:DeleteItem</code>、<code>Resource</code> に <code>Orders</code> テーブルのARNを指定する"},{"l":"C","html":"<code>Action</code> に <code>dynamodb:PutItem</code>・<code>dynamodb:UpdateItem</code>・<code>dynamodb:DeleteItem</code>、<code>Resource</code> に <code>*</code> を指定する"},{"l":"D","html":"<code>Action</code> に <code>dynamodb:PutItem</code>・<code>dynamodb:UpdateItem</code>・<code>dynamodb:DeleteItem</code>・<code>dynamodb:GetItem</code>、<code>Resource</code> に <code>Orders</code> テーブルのARNを指定する"}],"answer":["B"],"multi":false,"req":"","key":"最小権限は「<b>必要な操作（Action）だけを、必要なリソース（Resource）だけに</b>」許可することです。操作は追加・更新・削除の3つ、リソースは <code>Orders</code> テーブルのARN（<code>arn:aws:dynamodb:リージョン:アカウントID:table/Orders</code>）に絞ります。ポリシーの問題は、Action と Resource の両方を1つずつ確かめると外しにくくなります。","kw":"最小権限 ＝ Action と Resource の両方を絞る","reasons":[{"l":"A","html":"<code>dynamodb:*</code> はテーブルの削除や読み込みなど、不要な操作まで許可します。"},{"l":"C","html":"<code>Resource</code> が <code>*</code> のため、アカウント内のすべてのテーブルに書き込めてしまいます。"},{"l":"D","html":"要件にない読み込み（<code>GetItem</code>）まで許可しています。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":17,"topic":"大量のデータセットの共有の費用","level":2,"body":["ある研究機関は、数百TBの公開データセットをS3で保管し、<b>ほかの研究機関のAWSアカウント</b>からダウンロードしてもらっています。ダウンロードが増えるにつれて、<b>データ転送とリクエストの料金</b>が自機関の負担として増え続けています。データを使う側に、その料金を負担してもらいたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"CloudFrontで配信し、キャッシュのTTLを長くする"},{"l":"B","html":"データをS3 Glacier Deep Archiveに移す"},{"l":"C","html":"各研究機関のアカウントへ、データを毎月コピーする"},{"l":"D","html":"バケットでリクエスタ支払いを有効にする"}],"answer":["D"],"multi":false,"req":"","key":"リクエスタ支払いを有効にすると、<b>リクエストとデータのダウンロードの料金を、取得する側（リクエスタ）が負担</b>します。取得する側は、AWSアカウントで認証したうえで、リクエスタ支払いを了承するヘッダーを付けて取得します。保管の料金はバケットの所有者の負担のままです。","kw":"データを使う側に料金を負担させる → リクエスタ支払い","reasons":[{"l":"A","html":"配信の単価は下がる場合がありますが、料金を負担するのは自機関のままです。"},{"l":"B","html":"取り出しに時間がかかるうえ、取り出しの料金が増えます。"},{"l":"C","html":"コピーの転送の料金と手間がかかり、データも重複します。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":18,"topic":"国の制限とリクエスト数の制限","level":2,"body":["CloudFrontで配信しているWebサイトについて、次の2つを実現したいと考えています。①取引のない特定の国からのアクセスを遮断する ②それ以外の国からでも、<b>1つのIPアドレスから短時間に大量に届くリクエスト</b>を自動で遮断する。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"CloudFrontの地理的制限を設定し、AWS Shield Standardで大量のリクエストを防ぐ"},{"l":"B","html":"オリジンのALBのセキュリティグループで、対象の国と大量に送ってくるIPアドレスを拒否する"},{"l":"C","html":"WAFで地理的一致とレートベースのルールを設定する"},{"l":"D","html":"Route 53の位置情報ルーティングで、対象の国からの名前解決に応答しない"}],"answer":["C"],"multi":false,"req":"","key":"AWS WAFの<b>地理的一致ルール</b>で国単位の遮断ができ、<b>レートベースルール</b>で一定時間あたりのリクエスト数が上限を超えたIPアドレスを自動で遮断できます。1つのWeb ACLで両方の要件を満たし、CloudFrontに関連付ければエッジで止められます。","kw":"国の遮断 ＋ IPアドレスごとのリクエスト数の制限 → WAF（地理的一致 ＋ レートベース）","reasons":[{"l":"A","html":"地理的制限で①は満たせますが、Shield StandardはL3/L4のDDoS攻撃への基本的な防御で、IPアドレスごとのリクエスト数の制限はしません。"},{"l":"B","html":"セキュリティグループには拒否ルールがなく、国単位の指定もできません。CloudFront経由の通信では送信元もCloudFrontのIPアドレスです。"},{"l":"D","html":"DNSの応答を変えるだけで、ほかのDNSを使えば回避できます。②も満たせません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.5 AWS WAF</a> ／ <a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFront と Global Accelerator</a>"},{"n":19,"topic":"ガバナンスのルールの一括展開","level":2,"body":["クラウド運用チームは、AWS Organizationsの<b>すべてのメンバーアカウント</b>に、同じ<b>設定の評価ルールと修復のアクションのセット</b>を展開したいと考えています。アカウントが追加された場合も同じセットを適用し、準拠状況をまとめて確認したいと考えています。<b>運用上のオーバーヘッドが最も少ない</b>方法はどれですか。"],"options":[{"l":"A","html":"各アカウントでAWS Configのルールを1つずつ作成する"},{"l":"B","html":"AWS Trusted Advisorのチェックを毎週確認する"},{"l":"C","html":"AWS Configのコンフォーマンスパックを組織全体にデプロイする"},{"l":"D","html":"CloudTrailの組織の証跡を作成し、設定の変更をAthenaで調べる"}],"answer":["C"],"multi":false,"req":"","key":"コンフォーマンスパックは、<b>複数のConfigルールと修復のアクションを1つにまとめた</b>ものです。Organizationsと統合して組織全体にデプロイでき、新しいアカウントにも自動で展開されます。準拠状況はパック単位でまとめて確認できます。","kw":"ルールと修復のセットを組織に一括展開 → Configのコンフォーマンスパック","reasons":[{"l":"A","html":"アカウントごとの手作業で、アカウントが増えるたびに作業と設定の漏れが生じます。"},{"l":"B","html":"Trusted Advisorは決まった項目の点検で、自社で定めたルールや修復は展開できません。"},{"l":"D","html":"変更の記録を調べるだけで、評価や修復の仕組みにはなりません。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.7 AWS Config</a> ／ <a href=\"#management\" data-go=\"management\">第8章 8.5 AWS Organizations</a>"},{"n":20,"topic":"予測できないファイルアクセスの増減","level":2,"body":["機械学習の前処理を行う数十台のEC2が、Amazon EFSのファイルシステムを共有しています。処理はときどき集中し、そのときだけ<b>非常に高いスループット</b>が必要になりますが、いつ集中するかは予測できません。現在はバーストスループットモードで、集中した後に<b>バーストクレジットを使い切って処理が遅く</b>なります。使った分だけ支払う形で性能の問題を解消したいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"プロビジョンドスループットモードに変更し、最大の負荷に合わせた値を設定する"},{"l":"B","html":"エラスティックスループットモードに変更する"},{"l":"C","html":"EFSをEBSのgp3ボリュームに置き換え、各インスタンスに付ける"},{"l":"D","html":"性能モードを汎用から最大I/Oに変更する"}],"answer":["B"],"multi":false,"req":"","key":"エラスティックスループットは、<b>負荷に応じてスループットを自動で増減</b>し、読み書きしたデータ量に応じて課金されるモードです。予測できない急な集中に向き、バーストクレジットの枯渇も起きません。","kw":"予測できない・急な集中・使った分だけ → EFSのエラスティックスループット","reasons":[{"l":"A","html":"性能は満たせますが、集中していない時間も最大の値の料金を払い続けることになります。負荷が予測できて一定の場合に向くモードです。"},{"l":"C","html":"EBSは複数のインスタンスで共有できず（マルチアタッチは同じAZのio1/io2に限られる）、ファイルの共有という前提が崩れます。"},{"l":"D","html":"最大I/Oは非常に多くのクライアントからの並列アクセスのためのモードで、スループットの不足は解決しません（現在は多くの場合、汎用が推奨されます）。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.3 Amazon EFS</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":21,"topic":"ストリームの書き込みの上限","level":2,"body":["Kinesis Data Streamsを<b>プロビジョンドモード（シャード数4）</b>で使っています。キャンペーンの時期にはデータ量が予測できないほど増え、書き込みで <code>ProvisionedThroughputExceededException</code> が頻発します。シャード数の計算と変更の運用はしたくありません。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"プロデューサーの再試行の回数を増やす"},{"l":"B","html":"ストリームをオンデマンドモードに切り替える"},{"l":"C","html":"データの保持期間を7日に延ばす"},{"l":"D","html":"コンシューマーに拡張ファンアウトを設定する"}],"answer":["B"],"multi":false,"req":"","key":"オンデマンドモードでは、<b>書き込みと読み込みの量に応じてKinesisが自動でキャパシティを調整</b>します。シャード数を計算・変更する必要がなく、予測できない増加に向いています。","kw":"予測できないデータ量・シャードの管理をしない → Kinesis Data Streamsのオンデマンドモード","reasons":[{"l":"A","html":"再試行しても書き込みの上限は変わらず、遅れと失敗が増えるだけです。"},{"l":"C","html":"保持期間はデータを読み直せる期間で、書き込みの上限とは関係ありません。"},{"l":"D","html":"拡張ファンアウトは読み込みの帯域を増やす機能で、書き込みの上限は解消しません。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.1 Amazon Kinesis</a>"},{"n":22,"topic":"大量のログの順次読み込み","level":2,"body":["ログの集計処理は、毎晩EC2で数TBのログファイルを<b>先頭から順番に読み込み</b>ます。重視するのは<b>大きなスループットと低い費用</b>で、ランダムな読み書きの性能は必要ありません。このボリュームは起動用ではありません。最も適切なEBSボリュームのタイプはどれですか。"],"options":[{"l":"A","html":"プロビジョンドIOPS SSD（io2）"},{"l":"B","html":"汎用SSD（gp3）"},{"l":"C","html":"コールドHDD（sc1）"},{"l":"D","html":"スループット最適化HDD（st1）"}],"answer":["D"],"multi":false,"req":"","key":"st1は、<b>大きなデータを順番に読み書きする処理（ログの処理、ビッグデータ、データウェアハウス）</b>のためのHDDで、SSDより容量あたりの料金が安く、大きなスループットを出せます。起動用には使えませんが、この用途には合います。","kw":"大量の順次アクセス・スループット・低コスト → st1","reasons":[{"l":"A","html":"ランダムな読み書きで高いIOPSが必要なデータベース向けで、料金が最も高くなります。"},{"l":"B","html":"汎用的に使えますが、大容量を順番に読む用途では容量あたりの料金がst1より高くなります。"},{"l":"C","html":"sc1は最も安いHDDですが、アクセスの少ないデータ向けで、毎晩数TBを読む処理にはスループットが足りません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.2 Amazon EBS</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":23,"topic":"新しいバージョンの安全な切り替え","level":2,"body":["Elastic Beanstalkで動くWebアプリケーションの新しいバージョンを公開します。<b>本番のトラフィックを流す前に、新しい環境で動作を確認</b>し、問題があればすぐに元の環境へ戻せるようにしたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"環境を複製して新しいバージョンをデプロイし、確認後に環境のURLを入れ替える"},{"l":"B","html":"一括（All at once）のデプロイで、すべてのインスタンスを同時に更新する"},{"l":"C","html":"ローリングのデプロイで、インスタンスを1台ずつ更新する"},{"l":"D","html":"本番の環境にSSHで接続し、アプリケーションのファイルを直接置き換える"}],"answer":["A"],"multi":false,"req":"","key":"Beanstalkのブルー/グリーンデプロイは、<b>現在の環境を複製した別の環境</b>に新しいバージョンをデプロイし、確認が済んだら<b>環境のURL（CNAME）を入れ替え</b>ます。本番のトラフィックは切り替えるまで元の環境に流れ、問題があればURLを入れ替え直すだけで戻せます。","kw":"切り替え前に確認・すぐに戻す → ブルー/グリーン（環境のURLの入れ替え）","reasons":[{"l":"B","html":"更新の間はサービスが止まり、確認する前に本番のトラフィックが新しいバージョンに流れます。"},{"l":"C","html":"本番の環境の中で順に置き換えるため、切り替え前の確認ができず、戻すにも再びデプロイが必要です。"},{"l":"D","html":"手作業で環境の状態が不明確になり、戻すのも困難です。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.3 AWS Elastic Beanstalk</a>"},{"n":24,"topic":"見えないストレージの料金","level":2,"body":["大きな動画ファイルをマルチパートアップロードでS3に保存するアプリケーションがあります。S3の請求額が、バケットに見えているオブジェクトの合計サイズから想定されるより<b>明らかに高い</b>状態が続いています。調べたところ、ネットワークの切断で<b>途中で止まったアップロード</b>が多数あることがわかりました。最も適切な対策はどれですか。"],"options":[{"l":"A","html":"バケットでバージョニングを無効にする"},{"l":"B","html":"バケットのストレージクラスをS3 Standard-IAに変更する"},{"l":"C","html":"未完了のマルチパートアップロードを中止するルールを設定する"},{"l":"D","html":"Transfer Accelerationを有効にする"}],"answer":["C"],"multi":false,"req":"","key":"完了していないマルチパートアップロードの<b>アップロード済みのパートは、オブジェクトとして一覧に見えないまま保存され、料金がかかり続けます</b>。ライフサイクルの <code>AbortIncompleteMultipartUpload</code> で、開始から一定日数が過ぎた未完了のアップロードを自動で中止すれば、残ったパートが削除されます。S3 Storage Lensでも未完了のアップロードの量を確認できます。","kw":"見えないのに料金がかかる → 未完了のマルチパートアップロード（ライフサイクルで中止）","reasons":[{"l":"A","html":"未完了のアップロードのパートとは関係がありません。すでに作られた古い版も残ったままです。"},{"l":"B","html":"残ったパートは削除されず、読み込みのたびに取り出しの料金もかかるようになります。"},{"l":"D","html":"転送が速くなっても、すでに残っているパートは消えません。料金も追加でかかります。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":25,"topic":"スケールインで終了するインスタンス","level":3,"body":["Auto Scalingグループは3つのAZにまたがり、AZ-aに4台、AZ-bに3台、AZ-cに3台のインスタンスがあります。AZ-aの4台のうち2台は<b>古い起動テンプレートのバージョン</b>、2台は新しいバージョンで起動されています。終了ポリシーは<b>デフォルト</b>で、スケールインから保護されたインスタンスはありません。スケールインで1台を終了するとき、どのインスタンスが選ばれますか。"],"options":[{"l":"A","html":"3つのAZのすべてのインスタンスの中から、ランダムに1台"},{"l":"B","html":"3つのAZのすべてのインスタンスの中で、最も新しく起動された1台"},{"l":"C","html":"AZ-bかAZ-cの中で、古い起動テンプレートのバージョンを使う1台"},{"l":"D","html":"AZ-aの中で、古い起動テンプレートのバージョンを使う2台のうちの1台"}],"answer":["D"],"multi":false,"req":"","key":"デフォルトの終了ポリシーは、まず<b>AZの間の台数の偏りをなくす</b>ことを優先し、インスタンスが最も多いAZ（AZ-a）を選びます。次にそのAZの中で<b>古い起動テンプレート（または起動設定）を使うインスタンス</b>を選び、それでも複数あれば<b>次の課金時間に最も近い</b>ものを終了します。","kw":"デフォルトの終了ポリシー → 台数の多いAZ → 古い起動テンプレート → 次の課金時間","reasons":[{"l":"A","html":"ランダムに選ぶのは、ほかの条件で1台に絞れなかった場合の最後の手段です。"},{"l":"B","html":"最も新しいインスタンスから終了させるのは <code>NewestInstance</code> を指定した場合で、デフォルトではありません。"},{"l":"C","html":"AZ-bとAZ-cから終了させると、AZの間の偏りが大きくなります。デフォルトはまず台数の多いAZを選びます。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.2 EC2 Auto Scaling</a>"},{"n":26,"topic":"別アカウントへのデプロイ権限","level":2,"body":["CI/CDのパイプラインは、ツール用のアカウントで動いています。パイプラインから、本番用のアカウントのCloudFormationスタックを更新できるようにしたいと考えています。<b>長期のアクセスキーは使わず</b>、本番用のアカウントでは与える権限を管理したいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"本番用のアカウントにIAMユーザーを作成し、そのアクセスキーをパイプラインの環境変数に設定する"},{"l":"B","html":"ツール用のアカウントのパイプラインのロールに、本番用のアカウントの管理者権限をIAMポリシーで直接付ける"},{"l":"C","html":"本番用のアカウントのロールを、信頼ポリシーで許可して引き受ける"},{"l":"D","html":"両方のアカウントをVPCピアリングで接続し、パイプラインから本番用のアカウントのAPIを呼び出す"}],"answer":["C"],"multi":false,"req":"","key":"アカウントをまたぐ操作は、<b>操作される側（本番）にロールを作り、信頼ポリシーで引き受けてよい相手（パイプラインのロール）を指定</b>します。パイプラインは <code>sts:AssumeRole</code> で一時的な認証情報を得て操作します。本番で許す範囲は、そのロールの権限ポリシーで本番側が管理できます。","kw":"クロスアカウント → 相手側のロール ＋ 信頼ポリシー ＋ AssumeRole","reasons":[{"l":"A","html":"長期のアクセスキーを使うことになり、要件に反します。"},{"l":"B","html":"あるアカウントのIAMポリシーだけで、別のアカウントのリソースへの権限を与えることはできません。相手側での許可（ロールの信頼など）が必要です。"},{"l":"D","html":"VPCピアリングはネットワークの経路で、APIの操作の認可とは関係ありません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a> ／ <a href=\"#foundations\" data-go=\"foundations\">第0章 0.4 通信経路の疎通と操作の認可の区別</a>"},{"n":27,"topic":"利用者ごとのアップロード先","level":3,"body":["写真共有のモバイルアプリで、利用者が<b>自分専用のS3のプレフィックスだけ</b>に直接アップロードできるようにしたいと考えています。利用者はCognitoのユーザープールでサインインしています。アプリには長期の認証情報を持たせず、アップロードの処理のためのサーバーも置きたくありません。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"利用者ごとにIAMユーザーを作成し、アクセスキーをアプリに配布する"},{"l":"B","html":"アプリ用に1つのIAMユーザーを作成し、全利用者で共通のアクセスキーを使う"},{"l":"C","html":"EC2上にアップロード用のAPIを作り、サーバーからS3へ書き込む"},{"l":"D","html":"Cognito IDプールの一時的な認証情報を、ポリシー変数で絞る"}],"answer":["D"],"multi":false,"req":"","key":"IDプールは、サインインした利用者に<b>IAMロールの一時的な認証情報</b>を発行します。ロールのポリシーで <code>${cognito-identity.amazonaws.com:sub}</code> などのポリシー変数を使えば、<b>1つのポリシーで利用者ごとに異なるプレフィックス</b>へのアクセスだけを許可できます。","kw":"利用者ごとのAWSリソースへの直接アクセス → Cognito IDプール ＋ ポリシー変数","reasons":[{"l":"A","html":"利用者の数だけ長期の認証情報を配ることになり、管理も漏えいの危険も大きくなります。"},{"l":"B","html":"全員が同じ権限を持つため、利用者ごとの分離ができません。キーの漏えいの影響も全体に及びます。"},{"l":"C","html":"アップロードのためのサーバーを置かないという要件に反します。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.4 Amazon Cognito</a>"},{"n":28,"topic":"大規模なDDoS攻撃への備え","level":2,"body":["ECサイトは、CloudFront・ALB・EC2で構成されています。過去に大規模なDDoS攻撃を受け、<b>攻撃によるスケールアウトで料金が急増</b>しました。今後は、攻撃時に<b>AWSの専門チームの支援</b>を受けられ、攻撃に起因する料金の増加も補償される仕組みを用意したいと考えています。最も適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS Shield Advanced"},{"l":"B","html":"AWS Shield Standard"},{"l":"C","html":"Amazon GuardDuty"},{"l":"D","html":"AWS Firewall Manager"}],"answer":["A"],"multi":false,"req":"","key":"Shield Advancedは、CloudFront・ALB・Route 53などを対象に高度なDDoSの検知と緩和を行い、<b>Shield Response Team（SRT）の24時間の支援</b>と、<b>DDoS攻撃によるスケーリングの料金の補償（コスト保護）</b>を提供します。","kw":"DDoSの専門チームの支援・料金の補償 → Shield Advanced","reasons":[{"l":"B","html":"Standardはすべての利用者に自動で適用される基本的な防御で、専門チームの支援や料金の補償はありません。"},{"l":"C","html":"GuardDutyは脅威の検知のサービスで、DDoS攻撃の緩和や補償は行いません。"},{"l":"D","html":"Firewall ManagerはWAFやShieldの設定を複数のアカウントに一括で適用する管理のサービスで、それ自体が支援や補償を提供するものではありません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.6 AWS Shield</a>"},{"n":29,"topic":"VPCから使えるバケットの限定","level":2,"body":["プライベートサブネットのEC2は、S3用のゲートウェイ型VPCエンドポイントを経由して、業務用の2つのバケットだけを使います。セキュリティ部門は、このVPCから<b>それ以外のバケットにはアクセスできない</b>ようにしたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"業務用の2つのバケットのバケットポリシーで、このVPCのエンドポイントからのアクセスだけを許可する"},{"l":"B","html":"VPCエンドポイントポリシーで、業務用の2つのバケットへのアクセスだけを許可する"},{"l":"C","html":"EC2のセキュリティグループのアウトバウンドで、業務用のバケットのIPアドレスだけを許可する"},{"l":"D","html":"プライベートサブネットのネットワークACLで、S3のIPアドレスの範囲を拒否する"}],"answer":["B"],"multi":false,"req":"","key":"エンドポイントポリシーは、そのエンドポイントを通るリクエストが<b>どのリソースに届いてよいか</b>を制限します。業務用の2つのバケットだけを <code>Resource</code> に指定すれば、このVPCからほかのバケットへのアクセスはエンドポイントで拒否されます。","kw":"VPCから外への行き先を限定 → VPCエンドポイントポリシー","reasons":[{"l":"A","html":"業務用のバケットへの入り口を絞る設定で、<b>ほかのバケット</b>へのアクセスは防げません。守る向きが逆です。"},{"l":"C","html":"S3のIPアドレスはバケットごとに固定されておらず、バケット単位の制御はできません。"},{"l":"D","html":"業務用のバケットへのアクセスまで止まってしまいます。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.5 機密データへの安全な内部アクセス</a>"},{"n":30,"topic":"保存できないバケットポリシー","level":2,"body":["管理者が、S3バケット <code>example-logs</code> に次のバケットポリシーを保存しようとしたところ、エラーになりました。目的は、別のアカウント（111122223333）にこのバケットへの<b>オブジェクトの書き込みだけ</b>を許可することです。","<code>{\"Version\":\"2012-10-17\",\"Statement\":[{\"Effect\":\"Allow\",\"Action\":\"s3:PutObject\",\"Resource\":\"arn:aws:s3:::example-logs/*\"}]}</code>","エラーを解消し、目的を満たすための修正として最も適切なものはどれですか。"],"options":[{"l":"A","html":"<code>Resource</code> を <code>arn:aws:s3:::example-logs</code> に変更する"},{"l":"B","html":"<code>Action</code> を <code>s3:*</code> に変更する"},{"l":"C","html":"<code>Effect</code> を <code>Deny</code> に変更し、<code>NotAction</code> で <code>s3:PutObject</code> を除外する"},{"l":"D","html":"<code>Principal</code> 要素を追加し、アカウント111122223333を指定する"}],"answer":["D"],"multi":false,"req":"","key":"バケットポリシーのような<b>リソースベースのポリシーには、「誰に」許可するかを示す <code>Principal</code> が必須</b>です。IAMユーザーやロールに付けるアイデンティティベースのポリシーは付けた相手が主体になるため <code>Principal</code> を書きませんが、リソース側のポリシーでは省略できません。","kw":"リソースベースのポリシー → <code>Principal</code> が必須","reasons":[{"l":"A","html":"<code>s3:PutObject</code> の対象はオブジェクトなので、<code>バケット名/*</code> の指定が正しい形です。バケット自体のARNに変えると、書き込みが許可されなくなります。"},{"l":"B","html":"必要以上の操作を許可するうえ、<code>Principal</code> がない問題は解決しません。"},{"l":"C","html":"拒否の文になり、書き込みを許可するという目的と逆です。<code>Principal</code> がない問題も残ります。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a> ／ <a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a>"},{"n":31,"topic":"管理者でも消せないバックアップ","level":3,"body":["ランサムウェアの対策として、AWS Backupで取得したバックアップが、<b>侵害された管理者の認証情報を使っても削除・変更できない</b>ようにしたいと考えています。監査の要件により、保持期間が終わるまでは<b>ルートユーザーを含めて誰も</b>削除できないことを示す必要があります。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"バックアップボールトのアクセスポリシーで、管理者のロールによる削除を拒否する"},{"l":"B","html":"バックアップを別のリージョンのボールトにもコピーする"},{"l":"C","html":"バックアップボールトにVault Lockをコンプライアンスモードで設定する"},{"l":"D","html":"バックアップの削除をCloudTrailで監視し、SNSで通知する"}],"answer":["C"],"multi":false,"req":"","key":"AWS Backup Vault Lockを<b>コンプライアンスモード</b>で設定すると、猶予期間が過ぎた後は<b>ルートユーザーやAWSを含めて誰もロックを解除できず</b>、保持期間が終わるまで復旧ポイントを削除できません。WORMの状態でバックアップを守る機能です。","kw":"誰も消せないバックアップ → AWS Backup Vault Lock（コンプライアンスモード）","reasons":[{"l":"A","html":"アクセスポリシーは、十分な権限を持つ管理者が変更・削除できます。"},{"l":"B","html":"コピー先のボールトも、同じ認証情報で削除される可能性があります。"},{"l":"D","html":"削除を事後に知るだけで、削除そのものは防げません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.5 AWS Backup</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":32,"topic":"通信と保管の暗号化の強制","level":2,"body":["S3バケットに保存する顧客データについて、次の2つを<b>強制</b>したいと考えています。①バケットへのアクセスは暗号化された通信（HTTPS）だけにする ②保存するオブジェクトは、KMSのカスタマー管理キーで暗号化されるようにする。どの組み合わせが適切ですか。（<b>2つ選択してください</b>）"],"options":[{"l":"A","html":"バケットポリシーで、<code>aws:SecureTransport</code> が <code>false</code> のリクエストを拒否する"},{"l":"B","html":"バケットのブロックパブリックアクセスを有効にする"},{"l":"C","html":"Amazon Macieを有効にし、暗号化されていないオブジェクトを検出する"},{"l":"D","html":"バケットの既定の暗号化を、カスタマー管理キーによるSSE-KMSに設定する"},{"l":"E","html":"CloudFrontのディストリビューションを作成し、ビューワープロトコルポリシーでHTTPSを必須にする"}],"answer":["A","D"],"multi":true,"req":"","key":"①は、バケットポリシーで<b>HTTPで届いたリクエストを拒否</b>して強制します。②は、既定の暗号化にカスタマー管理キーのSSE-KMSを設定すれば、暗号化の指定がないアップロードも自動でそのキーで暗号化されます。","kw":"通信の暗号化の強制 → <code>aws:SecureTransport</code>／保管時の暗号化 → 既定の暗号化（SSE-KMS）","reasons":[{"l":"B","html":"公開を防ぐ設定で、通信の暗号化も保管時の暗号化も強制しません。"},{"l":"C","html":"Macieは機密データを検出するサービスで、暗号化を強制する機能ではありません。"},{"l":"E","html":"CloudFrontを経由するアクセスにしか効かず、バケットへ直接届くHTTPのリクエストは防げません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":33,"topic":"セキュリティの検出結果の集約","level":2,"body":["ある企業は、複数のアカウントでGuardDuty・Inspector・Macieを使っています。セキュリティ部門は、これらの<b>検出結果を1か所に集約</b>して優先度を付けて確認し、あわせて<b>AWSのベストプラクティスの基準に沿っているかを自動で点検</b>したいと考えています。最も適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS Trusted Advisor"},{"l":"B","html":"Amazon Detective"},{"l":"C","html":"AWS CloudTrail"},{"l":"D","html":"AWS Security Hub"}],"answer":["D"],"multi":false,"req":"","key":"Security Hubは、GuardDuty・Inspector・Macieなどの<b>検出結果を共通の形式で集約</b>し、複数のアカウントとリージョンを1つの管理者アカウントで確認できます。AWS基礎セキュリティのベストプラクティスやCISなどの<b>基準に沿った自動のチェック</b>も行います。","kw":"検出結果の集約 ＋ 基準に沿った点検 → Security Hub","reasons":[{"l":"A","html":"Trusted Advisorはコストや性能を含むベストプラクティスの点検で、ほかのサービスの検出結果は集約しません。"},{"l":"B","html":"Detectiveは、検出結果の原因をログの関連から調べる<b>調査</b>のためのサービスです。"},{"l":"C","html":"CloudTrailはAPI操作の記録で、検出結果の集約や基準の点検はしません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.13 検出系の整理</a>"},{"n":34,"topic":"Javaの関数の初回の遅さ","level":2,"body":["Javaで書かれたLambda関数は、新しい実行環境で最初のリクエストを処理するときに、<b>初期化に数秒</b>かかります。利用はまばらで予測しにくく、<b>待機のための追加の料金はかけたくありません</b>。コードの大きな変更もしたくありません。初回の応答を速くする最も適切な方法はどれですか。"],"options":[{"l":"A","html":"プロビジョニング済み同時実行数を設定する"},{"l":"B","html":"関数のメモリを最小にする"},{"l":"C","html":"Lambda SnapStartを有効にする"},{"l":"D","html":"関数をVPCの中に配置する"}],"answer":["C"],"multi":false,"req":"","key":"SnapStartは、<b>初期化が済んだ実行環境のスナップショットを保存</b>しておき、新しい実行環境をそこから再開する機能です。Javaなどの初期化に時間がかかる関数のコールドスタートを大きく短縮でき、プロビジョニング済み同時実行数のような待機の料金もかかりません（Javaの場合）。","kw":"Javaの初期化・待機の料金をかけない → Lambda SnapStart","reasons":[{"l":"A","html":"初回の遅さは解消できますが、待機させている間も料金がかかるため、要件に反します。"},{"l":"B","html":"CPUも減るため、初期化はさらに遅くなります。"},{"l":"D","html":"VPCへの配置はネットワークの到達性のための設定で、初期化の時間は短くなりません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.6 AWS Lambda</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.2 コンピューティングとパフォーマンス</a>"},{"n":35,"topic":"利用量が安定したテーブル","level":2,"body":["基幹システムのDynamoDBのテーブルは、<b>オンデマンドモード</b>で動いています。この1年、読み書きの量は<b>ほぼ一定で予測しやすく</b>、今後数年も同じ傾向が続く見込みです。テーブルの費用を下げたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"プロビジョンドモードとリザーブドキャパシティに切り替える"},{"l":"B","html":"DAXを導入し、読み込みをキャッシュする"},{"l":"C","html":"グローバルテーブルに変更する"},{"l":"D","html":"テーブルのデータを毎日S3へエクスポートし、テーブルを作り直す"}],"answer":["A"],"multi":false,"req":"","key":"オンデマンドモードは予測できない利用に向く反面、<b>安定した利用ではプロビジョンドモードより割高</b>になります。利用量が予測できるならプロビジョンドモードに切り替え、Auto Scalingで小さな変動に追従させます。長期で安定している分は<b>リザーブドキャパシティ</b>でさらに割り引けます。","kw":"安定・予測できる → プロビジョンドモード（＋リザーブドキャパシティ）","reasons":[{"l":"B","html":"DAXのノードの費用が加わり、書き込みの費用は変わりません。"},{"l":"C","html":"レプリカの分だけ費用が増えます。"},{"l":"D","html":"業務のテーブルを毎日作り直すことはできず、手間も費用もかかります。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.4 データベースのコスト最適化</a>"},{"n":36,"topic":"上書きと削除からの復旧","level":1,"body":["S3に保存している設計書のファイルが、利用者の操作ミスで<b>上書き</b>されたり<b>削除</b>されたりすることがあります。誤った操作の後でも、<b>以前の版を簡単に取り戻せる</b>ようにしたいと考えています。古い版が増え続けて費用がかさむことも避けたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"クロスリージョンレプリケーションを設定する"},{"l":"B","html":"オブジェクトロックをコンプライアンスモードで設定する"},{"l":"C","html":"毎晩、バケットの内容を別のバケットへコピーする"},{"l":"D","html":"バージョニングと、古い版のライフサイクルを設定する"}],"answer":["D"],"multi":false,"req":"","key":"バージョニングを有効にすると、上書きしても<b>以前の版が残り</b>、削除しても<b>削除マーカーが付くだけ</b>なので、以前の版を取り戻せます。ライフサイクルで「最新ではなくなってから一定日数が過ぎた版」を削除すれば、古い版による費用の増加も抑えられます。","kw":"上書き・削除からの復旧 → バージョニング（＋古い版のライフサイクル）","reasons":[{"l":"A","html":"レプリケーションは複製で、上書きや削除も複製先に反映されることがあります。複製にもバージョニングが必要です。"},{"l":"B","html":"保持期間中は削除も上書きもできなくなり、通常の業務での更新まで妨げます。規制のための機能です。"},{"l":"C","html":"最大1日分の変更を失い、コピーの費用と手間もかかります。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a>"},{"n":37,"topic":"SCPで許可しても使えない","level":2,"body":["ある企業は、開発用のOUに <code>s3:*</code> を許可するSCPを適用しました。ところが、開発用のアカウントの新しいIAMユーザーは、S3のバケットの一覧を取得しようとすると <b>AccessDenied</b> になります。このユーザーにはまだIAMポリシーが付いていません。原因と対処として最も適切なものはどれですか。"],"options":[{"l":"A","html":"SCPは上限にすぎないため、IAMポリシーで許可する"},{"l":"B","html":"SCPの反映に時間がかかっているため、24時間待つ"},{"l":"C","html":"SCPはルートユーザーにしか効かないため、ルートユーザーで操作する"},{"l":"D","html":"SCPの <code>Effect</code> を <code>Allow</code> から <code>Deny</code> に変更する"}],"answer":["A"],"multi":false,"req":"","key":"SCPは、アカウントで使える権限の<b>上限（ガードレール）を決めるだけで、権限そのものは与えません</b>。実際に操作するには、上限の範囲内で、IAMポリシー（またはリソースベースのポリシー）による許可が必要です。有効な権限は「SCPの許可」と「IAMの許可」の重なる部分です。","kw":"SCPは上限 → 実際の許可はIAMポリシー","reasons":[{"l":"B","html":"待っても、IAMポリシーによる許可がない限りアクセスはできません。"},{"l":"C","html":"SCPはメンバーアカウントのすべてのプリンシパル（ルートユーザーを含む）に効きます。日常の操作にルートユーザーを使うのも避けるべきです。"},{"l":"D","html":"拒否にすればS3の操作がさらにできなくなります。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.5 AWS Organizations</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a>"},{"n":38,"topic":"単一AZのボリュームの備え","level":2,"body":["社内のファイル変換サーバーは、1台のEC2とEBSボリュームで動いています。AZの障害でデータを失うことは避けたいものの、<b>復旧に数時間かかっても業務上の問題はなく</b>、費用はできるだけ抑えたいと考えています。<b>運用上のオーバーヘッドが最も少ない</b>方法はどれですか。"],"options":[{"l":"A","html":"EBSのマルチアタッチで、別のAZのインスタンスにも同じボリュームを接続する"},{"l":"B","html":"別のAZに同じ構成のインスタンスを常時稼働させ、rsyncで同期する"},{"l":"C","html":"データをすべてインスタンスストアに移す"},{"l":"D","html":"DLMでEBSのスナップショットを定期的に取得する"}],"answer":["D"],"multi":false,"req":"","key":"EBSのスナップショットは<b>リージョン内の複数のAZに冗長化されたS3に保存</b>されるため、AZの障害でも失われません。障害時は別のAZでスナップショットからボリュームを作ればよく、数時間の復旧が許されるならこれで十分です。Data Lifecycle Managerを使えば、取得と古いスナップショットの削除も自動化できます。","kw":"AZ障害への備え・復旧に時間をかけてよい → EBSスナップショット（DLMで自動化）","reasons":[{"l":"A","html":"マルチアタッチは同じAZのインスタンスにしか接続できず、AZの障害への備えにはなりません。"},{"l":"B","html":"常に2台分の費用がかかり、同期の仕組みの保守も必要です。要件に対して過剰です。"},{"l":"C","html":"インスタンスストアは停止や障害でデータが消える一時的な領域で、耐久性はむしろ下がります。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.2 Amazon EBS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":39,"topic":"密結合のHPCの通信","level":3,"body":["気象シミュレーションは、MPIを使って数百のプロセスが<b>ノード間で頻繁に通信</b>します。ノード間の通信の<b>レイテンシーを最小にし、OSを経由しない高速な通信</b>を使いたいと考えています。どの組み合わせが適切ですか。（<b>2つ選択してください</b>）"],"options":[{"l":"A","html":"インスタンスを3つのAZに分散させる"},{"l":"B","html":"Elastic Fabric Adapter（EFA）に対応したインスタンスタイプを使い、EFAを有効にする"},{"l":"C","html":"スプレッドプレイスメントグループを使う"},{"l":"D","html":"インスタンスごとにElastic IPアドレスを割り当てる"},{"l":"E","html":"クラスタープレイスメントグループに配置する"}],"answer":["B","E"],"multi":true,"req":"","key":"EFAは、MPIなどのHPCのアプリケーションが<b>OSのカーネルを経由せずにネットワークと通信</b>できるネットワークインターフェースで、ノード間の通信のレイテンシーを大きく下げます。<b>クラスタープレイスメントグループ</b>でインスタンスを1つのAZの中で近くに配置すれば、低レイテンシー・高スループットの効果を最大にできます。","kw":"密結合のHPC → EFA ＋ クラスタープレイスメントグループ","reasons":[{"l":"A","html":"AZをまたぐ通信は遅延が大きくなり、性能を優先する要件に反します。"},{"l":"C","html":"スプレッドは障害の影響を分散させるための配置で、ノード同士の距離は遠くなります。"},{"l":"D","html":"Elastic IPアドレスはインターネットからの接続のためのもので、ノード間の通信の性能とは関係ありません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.2 コンピューティングとパフォーマンス</a>"},{"n":40,"topic":"コンテナイメージの取得とNATの料金","level":3,"body":["プライベートサブネットのECS on Fargateのタスクは、起動のたびにAmazon ECRのプライベートリポジトリから大きなコンテナイメージを取得します。通信はNAT Gateway経由のため、<b>NAT Gatewayのデータ処理の料金</b>が高くなっています。NAT Gatewayを経由せずにイメージを取得できるようにするには、どの組み合わせが必要ですか。（<b>2つ選択してください</b>）"],"options":[{"l":"A","html":"DynamoDB用のゲートウェイ型VPCエンドポイントを作成する"},{"l":"B","html":"ECRのAPI（ecr.api）とDockerレジストリ（ecr.dkr）のインターフェース型VPCエンドポイントを作成する"},{"l":"C","html":"各AZにNAT Gatewayを追加し、AZをまたぐ通信をなくす"},{"l":"D","html":"タスクをパブリックサブネットに移し、パブリックIPアドレスを割り当てる"},{"l":"E","html":"S3用のゲートウェイ型VPCエンドポイントを作成する"}],"answer":["B","E"],"multi":true,"req":"","key":"ECRからの取得には、<b>認証などのAPI（ecr.api）とイメージの取得（ecr.dkr）のインターフェース型エンドポイント</b>が必要です。さらに、<b>イメージのレイヤーの実体はS3に保存</b>されているため、S3用のゲートウェイ型エンドポイント（無料）も必要です。これでイメージの取得がNAT Gatewayを通らなくなります。","kw":"プライベートサブネットからECR → ecr.api ＋ ecr.dkr（インターフェース型） ＋ S3（ゲートウェイ型）","reasons":[{"l":"A","html":"ECRのイメージの取得にはDynamoDBを使いません。"},{"l":"C","html":"NAT Gatewayの数が増えるだけで、データ処理の料金は減りません（AZをまたぐ転送は減りますが、要件の解決にはなりません）。"},{"l":"D","html":"タスクをインターネットに直接さらすことになり、プライベートサブネットに置く前提に反します。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続</a> ／ <a href=\"#container\" data-go=\"container\">第9章 9.4 Amazon ECR</a>"},{"n":41,"topic":"誤って削除した項目の復旧","level":2,"body":["運用担当者のスクリプトの誤りで、DynamoDBのテーブルから<b>多数の項目が削除</b>されました。削除は2時間前で、その直前の状態に戻したいと考えています。今後も同じ事故に備えて、<b>直近の任意の時点に戻せる</b>ようにしたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"PITRを有効にし、削除の直前の時点に復元する"},{"l":"B","html":"DynamoDB Streamsを有効にし、削除のイベントから項目を作り直す"},{"l":"C","html":"グローバルテーブルにし、別のリージョンのレプリカから項目をコピーする"},{"l":"D","html":"DAXを導入し、キャッシュに残った項目から復元する"}],"answer":["A"],"multi":false,"req":"","key":"PITRを有効にすると、<b>過去35日以内の任意の秒の時点</b>に戻せます。復元は<b>新しいテーブル</b>として作られるため、内容を確かめてからアプリケーションの接続先を切り替えるか、必要な項目を書き戻します。","kw":"誤った削除・任意の時点に戻す → PITR（新しいテーブルに復元）","reasons":[{"l":"B","html":"Streamsの記録は24時間で消え、復元の仕組みも自前で作る必要があります。有効にする前の削除には使えません。"},{"l":"C","html":"グローバルテーブルは変更をすぐに複製するため、削除も別のリージョンに反映されます。誤操作への備えにはなりません。"},{"l":"D","html":"DAXはキャッシュで、すべての項目が残っている保証はなく、復元の手段ではありません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a> ／ <a href=\"#foundations\" data-go=\"foundations\">第0章 0.2 冗長化・レプリケーション・バックアップの区別</a>"},{"n":42,"topic":"外部と共有されたリソースの発見","level":2,"body":["ある企業には、何年も使われてきたS3バケット・KMSキー・IAMロールが多数あります。セキュリティ部門は、これらのうち<b>組織の外のアカウントや一般に公開されている</b>ものを洗い出し、今後も新たに共有されたら検知したいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"CloudTrailのログから、外部のアカウントによるアクセスを手作業で探す"},{"l":"B","html":"Amazon GuardDutyを有効にする"},{"l":"C","html":"すべてのバケットポリシーとキーポリシーを担当者が読んで確認する"},{"l":"D","html":"IAM Access Analyzerの外部アクセスの分析を使う"}],"answer":["D"],"multi":false,"req":"","key":"IAM Access Analyzerは、リソースベースのポリシーを<b>自動推論で分析</b>し、信頼ゾーン（アカウントや組織）の外からアクセスできるS3バケット・KMSキー・IAMロールなどを<b>検出結果として一覧化</b>します。ポリシーが変わるたびに継続して分析するため、新しい共有も検知できます。","kw":"外部と共有されたリソースの洗い出し → IAM Access Analyzer","reasons":[{"l":"A","html":"実際にアクセスされた記録しかわからず、アクセス<b>できる状態</b>のリソースは見つけられません。"},{"l":"B","html":"GuardDutyは脅威の検知で、ポリシーの共有範囲の分析はしません。"},{"l":"C","html":"多数のポリシーを人が読むのは漏れが出やすく、継続的な検知にもなりません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.13 検出系の整理</a>"},{"n":43,"topic":"暗号化キーの一時的な使用停止","level":2,"body":["セキュリティの調査のため、KMSのカスタマー管理キーで暗号化しているデータへのアクセスを<b>一時的に止めたい</b>と考えています。調査が終われば、同じキーで暗号化したデータをまた使えるようにする必要があります。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"キーの削除をスケジュールし、調査が終わったらキーを作り直す"},{"l":"B","html":"キーの自動ローテーションを有効にする"},{"l":"C","html":"キーを無効にし、調査が終わったら有効に戻す"},{"l":"D","html":"キーのエイリアスを削除する"}],"answer":["C"],"multi":false,"req":"","key":"KMSキーを<b>無効にすると、そのキーでの暗号化・復号がすべて失敗</b>するため、データへのアクセスを即座に止められます。有効に戻せば、同じキーでまた復号できます。削除と違って、元に戻せる操作です。","kw":"一時的に止めて後で戻す → キーの無効化（削除は元に戻せない）","reasons":[{"l":"A","html":"待機期間（7〜30日）が過ぎて削除されると、そのキーで暗号化したデータは<b>二度と復号できません</b>。作り直したキーは別のキーです。"},{"l":"B","html":"ローテーションは新しい鍵素材を追加するだけで、以前のデータも引き続き復号できます。アクセスは止まりません。"},{"l":"D","html":"エイリアスは別名にすぎません。キーIDやARNを指定すれば、キーは使い続けられます。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.8 AWS KMS</a>"},{"n":44,"topic":"Lambdaのメモリと料金","level":3,"body":["Lambda関数は現在、メモリ1,024MBで1回の実行に60秒かかり、毎月数百万回実行されます。メモリを変えて計測した結果は、次の4つのうちのどれかでした。Lambdaの料金は<b>メモリ（GB）×実行時間（秒）</b>に比例するものとします（リクエストの料金は同じ）。<b>料金を下げ、実行時間も短くなる</b>のはどれですか。"],"options":[{"l":"A","html":"メモリ2,048MBで、実行時間が25秒になった"},{"l":"B","html":"メモリ512MBで、実行時間が130秒になった"},{"l":"C","html":"メモリ2,048MBで、実行時間が35秒になった"},{"l":"D","html":"メモリ3,072MBで、実行時間が22秒になった"}],"answer":["A"],"multi":false,"req":"","key":"現在は 1GB × 60秒 ＝ <b>60GB秒</b>です。各案は、A：2GB × 25秒 ＝ <b>50GB秒</b>、B：0.5GB × 130秒 ＝ 65GB秒、C：2GB × 35秒 ＝ 70GB秒、D：3GB × 22秒 ＝ 66GB秒 です。Lambdaでは<b>メモリに比例してCPUも増える</b>ため、CPUを使う処理ではメモリを増やすと実行時間が大きく縮み、料金まで下がることがあります。料金と時間の両方が下がるのはAだけです。","kw":"Lambdaの料金 ＝ メモリ × 実行時間（メモリを増やすとCPUも増える）","reasons":[{"l":"B","html":"料金が増え（65GB秒）、実行時間も長くなります。"},{"l":"C","html":"実行時間は短くなりますが、料金が増えます（70GB秒）。"},{"l":"D","html":"実行時間は最も短くなりますが、料金が増えます（66GB秒）。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.6 AWS Lambda</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":45,"topic":"月末の同時クエリの集中","level":2,"body":["Amazon Redshiftのプロビジョンドクラスターで、BIツールからのダッシュボードのクエリを処理しています。普段は問題ありませんが、<b>月末の数日間は数百人が同時にダッシュボードを開く</b>ため、クエリが待たされて表示が遅くなります。普段の性能とコストは今のままで、月末の集中にだけ対応したいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"同時実行スケーリングを有効にする"},{"l":"B","html":"月末に合わせてクラスターのノード数を常に2倍にしておく"},{"l":"C","html":"ダッシュボードのデータをすべてDynamoDBへ移す"},{"l":"D","html":"クエリの結果をS3にアンロードし、Athenaで表示する"}],"answer":["A"],"multi":false,"req":"","key":"同時実行スケーリングは、<b>同時に実行されるクエリが増えたときだけ、一時的なクラスターの処理能力を自動で追加</b>する機能です。待たされていたクエリがそちらで実行され、集中が終われば元に戻ります。使った時間だけ課金され、1日あたり一定の無料枠もあります。","kw":"同時に多数のクエリ・一時的な集中 → Redshiftの同時実行スケーリング","reasons":[{"l":"B","html":"月末以外も2倍の費用がかかり続けます。"},{"l":"C","html":"DynamoDBは分析のクエリ向けではなく、BIツールの集計には向きません。"},{"l":"D","html":"データの鮮度とBIの運用が変わり、アンロードの仕組みも必要になります。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.4 Amazon Redshift</a>"},{"n":46,"topic":"AWS上のディレクトリサービス","level":3,"body":["ある企業は、Windowsのアプリケーションサーバー（EC2）をAWSへ移行します。サーバーはActive Directoryのドメインに参加し、社員はオンプレミスのADのアカウントでアクセスします。<b>オンプレミスとの回線が切れても、AWS上のサーバーの認証を続けられる</b>必要があり、ドメインコントローラーの管理の負担は減らしたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"AD Connectorを作成し、オンプレミスのADに認証を中継する"},{"l":"B","html":"AWS Managed Microsoft ADを作成し、オンプレミスのADと信頼関係を結ぶ"},{"l":"C","html":"EC2にドメインコントローラーを構築し、パッチとバックアップを自分で管理する"},{"l":"D","html":"IAM Identity Centerで社員のユーザーを作成し、Windowsのサーバーにサインインさせる"}],"answer":["B"],"multi":false,"req":"","key":"AWS Managed Microsoft ADは、<b>AWSが管理する本物のActive Directoryのドメインコントローラー</b>を複数のAZに提供します。オンプレミスのADと<b>信頼関係</b>を結べば、社員はオンプレミスのアカウントのまま使えます。AWS側にドメインコントローラーがあるため、回線が切れてもAWSのドメインでの認証は続けられます。","kw":"AWS上に本物のAD・信頼関係・管理を減らす → AWS Managed Microsoft AD","reasons":[{"l":"A","html":"AD Connectorは認証をオンプレミスのADへ<b>中継するだけ</b>で、自分ではディレクトリを持ちません。回線が切れると認証できなくなります。"},{"l":"C","html":"実現はできますが、ドメインコントローラーの管理の負担が大きく、要件に反します。"},{"l":"D","html":"Identity CenterはAWSアカウントや業務アプリへのシングルサインオンのサービスで、Windowsのドメインの認証の代わりにはなりません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.3 AWS Directory Service</a>"},{"n":47,"topic":"バッチの一部の失敗","level":3,"body":["SQSのキューをイベントソースにしたLambda関数は、一度に10件のメッセージを受け取って処理します。1件でも失敗すると関数がエラーを返すため、<b>成功した9件も再びキューに戻り、二重に処理</b>されています。失敗したメッセージだけを再処理させたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"バッチサイズを1にする"},{"l":"B","html":"部分的なバッチレスポンスを有効にする"},{"l":"C","html":"キューの可視性タイムアウトを短くする"},{"l":"D","html":"関数のタイムアウトを延ばす"}],"answer":["B"],"multi":false,"req":"","key":"イベントソースマッピングで<b>部分的なバッチレスポンス（<code>ReportBatchItemFailures</code>）</b>を有効にすると、関数は<b>失敗したメッセージのIDだけ</b>を返せます。成功したメッセージはキューから削除され、失敗したものだけが再び処理されます。","kw":"バッチの一部だけ再処理 → 部分的なバッチレスポンス","reasons":[{"l":"A","html":"二重処理はなくなりますが、呼び出しの回数が10倍になり、処理の効率とコストが悪化します。"},{"l":"C","html":"失敗したバッチが早く再び見えるようになるだけで、成功した分まで戻る問題は変わりません。"},{"l":"D","html":"失敗の原因が時間切れでない限り効果がなく、成功した分まで戻る問題も残ります。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.6 AWS Lambda</a> ／ <a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a>"},{"n":48,"topic":"週末の開発用データベース","level":2,"body":["開発用のRDS for MySQLのインスタンスは、<b>平日の日中だけ</b>使われ、<b>週末は誰も使いません</b>。インスタンスクラスやエンジンは変えずに、<b>最も手軽に</b>費用を下げたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"3年のリザーブドインスタンスを購入する"},{"l":"B","html":"マルチAZ配置に変更する"},{"l":"C","html":"リードレプリカを作成し、週末はプライマリを削除する"},{"l":"D","html":"週末だけ停止するスケジュールを設定する"}],"answer":["D"],"multi":false,"req":"","key":"RDSのインスタンスは<b>停止している間はインスタンスの料金がかかりません</b>（ストレージとバックアップの料金はかかります）。停止できるのは<b>最大7日間</b>で、それを過ぎると自動で起動しますが、金曜の夜から月曜の朝までの停止なら問題ありません。スケジュールで停止・起動を自動化するのが最も手軽です。","kw":"使わない時間の停止（RDSは最大7日まで） → スケジュールで停止・起動","reasons":[{"l":"A","html":"使わない週末の分まで支払う約束になり、開発用には割高です。"},{"l":"B","html":"スタンバイの分だけ費用が増えます。"},{"l":"C","html":"レプリカを作って削除する運用は手間がかかり、毎週の昇格や作り直しも必要です。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.4 データベースのコスト最適化</a>"},{"n":49,"topic":"移行のタイミングの判断","level":2,"body":["ある企業は、S3の共有データのバケットに<b>ライフサイクルルールを設定したい</b>と考えていますが、オブジェクトが作成から何日くらいでアクセスされなくなるかがわかりません。<b>実際のアクセスの傾向を観察</b>して、Standard-IAへ移すのに適した日数を判断したいと考えています。最も適切な機能はどれですか。"],"options":[{"l":"A","html":"S3のサーバーアクセスログ"},{"l":"B","html":"S3インベントリ"},{"l":"C","html":"AWS Budgets"},{"l":"D","html":"S3のストレージクラス分析"}],"answer":["D"],"multi":false,"req":"","key":"ストレージクラス分析は、バケット（またはプレフィックスやタグ）の<b>アクセスの傾向を観察</b>し、オブジェクトの経過日数ごとのアクセスの量を示して、<b>Standard-IAへ移すのに適した時期</b>の判断を助けます。結果はライフサイクルルールの日数の決定にそのまま使えます。","kw":"Standard-IAへ移す日数の判断 → ストレージクラス分析","reasons":[{"l":"A","html":"個々のリクエストの記録で、傾向を知るには自分で集計・分析する必要があります。"},{"l":"B","html":"オブジェクトの一覧とメタデータの定期的なレポートで、アクセスの傾向はわかりません。"},{"l":"C","html":"予算の超過を通知する機能で、アクセスの傾向とは関係ありません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.1 コスト管理ツールの使い分け</a>"},{"n":50,"topic":"遅いクエリの特定","level":2,"body":["RDS for PostgreSQLのデータベースで、特定の時間帯に応答が遅くなります。CPU使用率はそれほど高くありません。<b>どのSQLがデータベースの負荷の原因になっているか、何を待っているか</b>を、追加のツールを導入せずに特定したいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"CloudTrailのデータイベントを有効にする"},{"l":"B","html":"拡張モニタリングを有効にし、OSのプロセスの一覧を見る"},{"l":"C","html":"CloudWatchのCPU使用率のアラームを作成する"},{"l":"D","html":"Performance Insightsで負荷を分析する"}],"answer":["D"],"multi":false,"req":"","key":"Performance Insights（現在はCloudWatch Database Insightsに統合）は、データベースの負荷を<b>SQL文ごと・待機イベントごと</b>に分けて表示します。どのSQLが、ロック・I/O・CPUなどの何を待って負荷になっているかを、時間帯を指定して調べられます。","kw":"負荷の原因のSQL・待機イベント → Performance Insights（Database Insights）","reasons":[{"l":"A","html":"CloudTrailはAWSのAPIの操作の記録で、データベースの中で実行されたSQLの負荷はわかりません。"},{"l":"B","html":"OSのレベルの情報はわかりますが、どのSQLが原因かまではわかりません。"},{"l":"C","html":"CPUが高くない状況では役に立たず、原因の特定もできません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.5 データベースの性能問題の切り分け</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.5 データベースボトルネックの切り分け</a>"},{"n":51,"topic":"DNSによる簡易な分散と除外","level":2,"body":["社内向けのAPIは、Elastic IPアドレスを持つ4台のEC2インスタンスで動いています。ロードバランサーは使わず、Route 53で<b>複数のインスタンスのIPアドレスを返して負荷を分散</b>し、<b>異常なインスタンスのIPアドレスは応答から外したい</b>と考えています。最も適切なルーティングポリシーはどれですか。"],"options":[{"l":"A","html":"シンプルルーティングで、4つのIPアドレスを1つのレコードに登録する"},{"l":"B","html":"複数値回答ルーティングにヘルスチェックを付ける"},{"l":"C","html":"フェイルオーバールーティングで、1台をプライマリ、3台をセカンダリにする"},{"l":"D","html":"位置情報ルーティングで、地域ごとに1台ずつ割り当てる"}],"answer":["B"],"multi":false,"req":"","key":"複数値回答ルーティングは、<b>ヘルスチェックに合格したレコードの中から最大8つをランダムに返します</b>。クライアントは返されたIPアドレスのいずれかに接続するため簡易な分散になり、異常なインスタンスは応答から自動で外れます。","kw":"複数のIPアドレスを返す・異常なものを除外 → 複数値回答ルーティング","reasons":[{"l":"A","html":"シンプルルーティングはヘルスチェックに対応しておらず、異常なインスタンスのIPアドレスも返し続けます。"},{"l":"C","html":"正常なときはプライマリの1台だけに集中し、負荷の分散になりません。"},{"l":"D","html":"地域で振り分けるだけで、異常なインスタンスの除外や均等な分散にはなりません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.4 Route 53 と Resolver</a>"},{"n":52,"topic":"外部への通信のAZの独立性","level":2,"body":["アプリケーションは、2つのAZのプライベートサブネットのEC2で動き、インターネット上の外部のAPIを呼び出します。現在はAZ-aのパブリックサブネットにある<b>1つのNAT Gateway</b>を両方のAZで使っています。<b>どちらかのAZが停止しても、もう一方のAZからは外部のAPIを呼び出せる</b>ようにする必要があります。どの組み合わせが必要ですか。（<b>2つ選択してください</b>）"],"options":[{"l":"A","html":"AZ-bのパブリックサブネットにもNAT Gatewayを作成する"},{"l":"B","html":"既存のNAT Gatewayを、より帯域の大きいものに変更する"},{"l":"C","html":"各AZのプライベートサブネットのルートテーブルで、<code>0.0.0.0/0</code> を同じAZのNAT Gatewayに向ける"},{"l":"D","html":"プライベートサブネットのルートテーブルで、<code>0.0.0.0/0</code> をインターネットゲートウェイに向ける"},{"l":"E","html":"NAT Gatewayをプライベートサブネットに移動する"}],"answer":["A","C"],"multi":true,"req":"","key":"NAT Gatewayは<b>作成したAZの中で冗長化</b>されるリソースで、AZが停止すればそのNAT Gatewayも使えなくなります。AZの障害から独立させるには、<b>AZごとにNAT Gatewayを置き</b>、各AZのプライベートサブネットの経路を<b>同じAZのNAT Gateway</b>に向けます。","kw":"AZに依存しない外向きの通信 → AZごとのNAT Gateway ＋ AZごとのルートテーブル","reasons":[{"l":"B","html":"帯域を増やしても、AZ-aの障害で使えなくなる問題は変わりません。"},{"l":"D","html":"プライベートサブネットのインスタンスはパブリックIPアドレスを持たないため、インターネットゲートウェイへの経路だけでは外部と通信できません。サブネットもパブリックになってしまいます。"},{"l":"E","html":"NAT Gatewayはインターネットゲートウェイへの経路を持つパブリックサブネットに置く必要があります。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":53,"topic":"S3の読み書きのレイテンシー","level":3,"body":["機械学習の学習ジョブは、1つのAZのEC2から、数百万の小さなファイルに<b>毎秒数十万回</b>アクセスします。S3 Standardでは1回ごとのレイテンシーがボトルネックになっており、<b>1桁ミリ秒</b>のレイテンシーを求めています。データは元のデータから作り直せます。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"S3 Transfer Accelerationを有効にする"},{"l":"B","html":"CloudFrontを前段に置き、ファイルをキャッシュする"},{"l":"C","html":"同じAZにS3 Express One Zoneのバケットを作る"},{"l":"D","html":"S3 Intelligent-Tieringに移す"}],"answer":["C"],"multi":false,"req":"","key":"S3 Express One Zoneは、<b>1つのAZにデータを置く高性能のストレージクラス</b>で、S3 Standardより大幅に低い1桁ミリ秒のレイテンシーと、非常に多くのリクエストに対応します。計算と同じAZに置くのが前提で、1つのAZにしか保存されないため、作り直せるデータに向いています。","kw":"1桁ミリ秒・大量のリクエスト・同じAZの計算 → S3 Express One Zone","reasons":[{"l":"A","html":"遠距離のアップロードを速くする機能で、同じリージョンの中のアクセスのレイテンシーは改善しません。"},{"l":"B","html":"CloudFrontは利用者への配信のためのサービスで、同じリージョンのEC2からの大量のアクセスを速くする用途ではありません。"},{"l":"D","html":"コストを最適化するクラスで、レイテンシーは改善しません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":54,"topic":"S3からの配信のデータ転送料金","level":2,"body":["ソフトウェアの配布サイトは、S3のバケットからインストーラーを<b>インターネットへ直接</b>配信しています。利用者は世界中にいて、同じファイルが繰り返しダウンロードされるため、<b>S3からのデータ転送の料金</b>が月額の大部分を占めています。費用を最も下げる方法はどれですか。"],"options":[{"l":"A","html":"バケットのストレージクラスをS3 One Zone-IAに変更する"},{"l":"B","html":"S3 Transfer Accelerationを有効にする"},{"l":"C","html":"CloudFrontを経由して配信する"},{"l":"D","html":"リクエスタ支払いを有効にする"}],"answer":["C"],"multi":false,"req":"","key":"<b>S3からCloudFrontへのデータ転送には料金がかからず</b>、CloudFrontからインターネットへの転送は、一般にS3から直接配信するより安い単価です。繰り返しダウンロードされるファイルはエッジでキャッシュされるため、S3へのリクエストも減り、利用者への配信も速くなります。","kw":"S3からの配信の転送料金 → CloudFront（S3→CloudFrontの転送は無料）","reasons":[{"l":"A","html":"保管の料金は下がりますが、支配的なデータ転送の料金は変わらず、読み込みのたびに取り出しの料金も増えます。"},{"l":"B","html":"アップロードを速くする機能で、追加の料金がかかります。"},{"l":"D","html":"リクエスタ支払いは、取得する側がAWSアカウントで認証して料金を払う仕組みで、一般の利用者への配信には使えません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFront と Global Accelerator</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.5 コスト削減の3つの観点</a>"},{"n":55,"topic":"SaaSへのプライベートな接続","level":2,"body":["ある企業は、別のAWSアカウントで提供されているSaaSの決済サービスを利用します。提供元は、このサービスを<b>VPCエンドポイントサービス（PrivateLink）</b>として公開しています。自社のVPCと提供元のVPCは<b>CIDRが重複</b>しており、通信はインターネットを経由させてはいけません。最も適切な接続方法はどれですか。"],"options":[{"l":"A","html":"提供元のVPCとVPCピアリングを結び、ルートテーブルに経路を追加する"},{"l":"B","html":"Transit Gatewayで両方のVPCを接続する"},{"l":"C","html":"NAT Gateway経由で、提供元のサービスのパブリックエンドポイントに接続する"},{"l":"D","html":"提供元のサービスへのインターフェース型エンドポイントを作る"}],"answer":["D"],"multi":false,"req":"","key":"PrivateLinkでは、利用する側が<b>自分のVPCにインターフェース型エンドポイント（自分のCIDRのIPアドレスを持つENI）</b>を作り、そこへ接続します。VPC同士を経路でつなぐわけではないので、<b>CIDRが重複していても</b>使え、通信はAWSのネットワークの中にとどまります。","kw":"提供元のエンドポイントサービス・CIDRの重複 → インターフェース型エンドポイント（PrivateLink）","reasons":[{"l":"A","html":"CIDRが重複しているVPC同士はピアリングできません。"},{"l":"B","html":"Transit Gatewayでも、重複したCIDRへの経路は衝突します。VPC全体をつなぐため、公開範囲も広すぎます。"},{"l":"C","html":"インターネットを経由することになり、要件に反します。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続</a>"},{"n":56,"topic":"DNSのキャッシュに左右されない切り替え","level":2,"body":["TCPで接続する業務用のアプリケーションが、東京と大阪のリージョンのNLBの背後で動いています。現在はRoute 53のフェイルオーバールーティングで切り替えていますが、<b>クライアントがDNSの結果を長くキャッシュ</b>するため、障害時の切り替えに時間がかかります。クライアントの設定は変えられません。切り替えの時間を<b>最も短く</b>する方法はどれですか。"],"options":[{"l":"A","html":"Route 53のレコードのTTLを0秒にする"},{"l":"B","html":"AWS Global Acceleratorで両方のリージョンのNLBをエンドポイントにする"},{"l":"C","html":"CloudFrontのオリジングループで、両方のNLBを登録する"},{"l":"D","html":"両方のリージョンのNLBにElastic IPアドレスを付け、クライアントに両方のアドレスを登録させる"}],"answer":["B"],"multi":false,"req":"","key":"Global Acceleratorは、<b>固定のエニーキャストIPアドレス</b>で接続を受け、ヘルスチェックの結果に応じて正常なリージョンのエンドポイントへ振り分けます。クライアントが接続するIPアドレスは変わらないため、<b>DNSのキャッシュに左右されず</b>、障害時は数十秒以内に切り替わります。","kw":"DNSのキャッシュに左右されない切り替え・TCP → Global Accelerator","reasons":[{"l":"A","html":"TTLを短くしても、TTLを守らずにキャッシュするクライアントやリゾルバーには効きません。問い合わせの料金も増えます。"},{"l":"C","html":"CloudFrontはHTTP／HTTPSの配信のためのサービスで、TCPの業務アプリケーションの通信には使えません。"},{"l":"D","html":"クライアントの設定を変える必要があり、要件に反します。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFront と Global Accelerator</a>"},{"n":57,"topic":"順序を保ったファンアウト","level":3,"body":["株式の注文のイベントを、約定の処理と監査の記録の2つのシステムへ届けたいと考えています。どちらのシステムでも、<b>同じ口座のイベントは発生した順に</b>処理し、<b>同じイベントが重複して処理されない</b>ようにする必要があります。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"SNSの標準トピックから、2つのSQS標準キューへファンアウトする"},{"l":"B","html":"1つのSQS FIFOキューに送り、2つのシステムが同じキューから受信する"},{"l":"C","html":"EventBridgeのイベントバスから、2つのLambda関数を直接呼び出す"},{"l":"D","html":"SNSのFIFOトピックから、2つのSQS FIFOキューへファンアウトする"}],"answer":["D"],"multi":false,"req":"","key":"SNSのFIFOトピックは、<b>メッセージグループの中の順序を保ち、重複を取り除いて</b>、サブスクライブした<b>SQSのFIFOキュー</b>へ配信します。口座IDをメッセージグループIDにすれば、2つのシステムがそれぞれ自分のキューから、口座ごとの順序どおりに重複なく処理できます。","kw":"ファンアウト ＋ 順序 ＋ 重複の排除 → SNS FIFO ＋ SQS FIFO","reasons":[{"l":"A","html":"標準のトピックとキューは順序を保証せず、重複して配信されることもあります。"},{"l":"B","html":"1つのキューのメッセージは受信したシステムが処理して削除するため、2つのシステムの両方には届きません。"},{"l":"C","html":"順序の保証も重複の排除もなく、呼び出しに失敗したイベントを後から処理し直す仕組みもありません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.2 Amazon SNS</a> ／ <a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a>"},{"n":58,"topic":"構成が決まっている常時稼働","level":2,"body":["ある企業は、東京リージョンで<b>M7iファミリーのEC2インスタンス</b>を数十台、24時間稼働させています。今後3年間、リージョンもインスタンスファミリーも<b>変える予定はありません</b>（サイズやOSは変わる可能性があります）。<b>割引率を最も高く</b>したいと考えています。最も適切な購入方法はどれですか。"],"options":[{"l":"A","html":"EC2 Instance Savings Plans（3年）"},{"l":"B","html":"Compute Savings Plans（3年）"},{"l":"C","html":"スポットインスタンス"},{"l":"D","html":"オンデマンドキャパシティ予約"}],"answer":["A"],"multi":false,"req":"","key":"EC2 Instance Savings Plansは、<b>特定のリージョンの特定のインスタンスファミリー</b>にコミットする代わりに、Compute Savings Plansより<b>割引率が高く</b>なります（最大72％）。ファミリーの中であれば、サイズやOSが変わっても割引が適用されます。","kw":"リージョンとファミリーが決まっている・最大の割引 → EC2 Instance Savings Plans","reasons":[{"l":"B","html":"ファミリーやリージョン、FargateやLambdaへの変更にも追従できる柔軟さの代わりに、割引率はEC2 Instance Savings Plansより低くなります（最大66％）。"},{"l":"C","html":"中断される可能性があり、24時間稼働の業務には向きません。"},{"l":"D","html":"キャパシティ予約は容量の確保で、それ自体に割引はありません。"}],"refs":"<a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a> ／ <a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a>"},{"n":59,"topic":"別の属性での検索","level":2,"body":["DynamoDBの <code>Orders</code> テーブルは、パーティションキーが注文IDです。新しい画面で、<b>顧客IDを指定して、その顧客の注文を日付順に</b>取得する必要があります。テーブルはすでに本番で使われています。現在は <code>Scan</code> とフィルター式で取得しており、遅く高価です。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"顧客IDをパーティションキー、注文日をソートキーにしたローカルセカンダリインデックス（LSI）を追加する"},{"l":"B","html":"顧客IDと注文日をキーにしたGSIを追加する"},{"l":"C","html":"並列スキャンに変更する"},{"l":"D","html":"DAXを導入して <code>Scan</code> の結果をキャッシュする"}],"answer":["B"],"multi":false,"req":"","key":"<b>パーティションキーが異なる検索</b>にはGSIを使います。顧客IDをパーティションキー、注文日をソートキーにすれば、<code>Query</code> で必要な項目だけを日付順に読めます。GSIは<b>既存のテーブルにも後から追加</b>できます。","kw":"別の属性で検索・既存のテーブル → GSI（LSIは作成時だけ・パーティションキーは同じ）","reasons":[{"l":"A","html":"LSIは<b>テーブルの作成時にしか作れず</b>、パーティションキーも元のテーブルと同じ（注文ID）でなければなりません。"},{"l":"C","html":"速くはなっても、テーブル全体を読むことに変わりはなく、消費するキャパシティ（費用）はむしろ増えます。"},{"l":"D","html":"<code>Scan</code> の非効率はそのままで、条件が変われば結果もキャッシュから返せません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a>"},{"n":60,"topic":"数分で切り替える災害対策","level":3,"body":["基幹のWebシステム（ALB・EC2・RDS for MySQL）について、リージョン障害への備えを検討しています。要件は <b>RTOは5分以内、RPOは1分以内</b>です。平常時の費用は、本番と同じ規模の環境を2つ動かすよりは抑えたいと考えています。最も適切な方式はどれですか。"],"options":[{"l":"A","html":"ウォームスタンバイ（別のリージョンに縮小した環境を常時稼働させ、データを継続的に複製する）"},{"l":"B","html":"パイロットライト（データだけを複製し、アプリケーション層は障害時に起動する）"},{"l":"C","html":"バックアップと復元（バックアップを別のリージョンへコピーし、障害時に復元する）"},{"l":"D","html":"マルチサイトのアクティブ/アクティブ（両方のリージョンで同じ規模の環境を稼働させる）"}],"answer":["A"],"multi":false,"req":"","key":"RTO5分では、障害が起きてから環境を起動していては間に合いません。<b>縮小した規模で常に動いている環境</b>があれば、Route 53で切り替えて台数を増やすだけで済みます。データはクロスリージョンリードレプリカなどで継続的に複製すれば、RPO1分も満たせます。同じ規模を2つ動かすマルチサイトより費用を抑えられます。","kw":"RTO数分・費用はマルチサイトより抑える → ウォームスタンバイ","reasons":[{"l":"B","html":"アプリケーション層の起動と準備に時間がかかり、RTO5分には通常間に合いません（RTOが数十分から1時間程度の場合に選びます）。"},{"l":"C","html":"RPOはバックアップの間隔に、RTOは復元の時間に縛られ、どちらの要件も満たせません。"},{"l":"D","html":"要件は満たしますが、本番と同じ規模を2つ動かすため、費用の条件に反します。"}],"refs":"<a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a> ／ <a href=\"#foundations\" data-go=\"foundations\">第0章 0.3 RTOとRPO</a>"},{"n":61,"topic":"半年前の操作の調査","level":2,"body":["監査部門から、<b>半年前に</b>あるセキュリティグループのルールを誰が変更したかを調べるよう依頼されました。調査は今後も定期的に発生します。CloudTrailのイベント履歴を確認しましたが、該当の記録は見つかりませんでした。今後同じ調査に対応するため、最も適切な方法はどれですか。"],"options":[{"l":"A","html":"証跡を作ってS3に保存し、Athenaで検索する"},{"l":"B","html":"CloudTrailのイベント履歴の保持期間を1年に延ばす"},{"l":"C","html":"VPCフローログを有効にし、セキュリティグループへの通信を記録する"},{"l":"D","html":"AWS Configで、セキュリティグループの現在の設定を確認する"}],"answer":["A"],"multi":false,"req":"","key":"CloudTrailのイベント履歴で確認できるのは<b>過去90日間の管理イベントだけ</b>です。それより長く調べられるようにするには、<b>証跡を作成してS3に保存</b>します。保存したログは、Athenaを使えばSQLで検索できます。","kw":"90日より前の操作の調査 → CloudTrailの証跡 ＋ S3 ＋ Athena","reasons":[{"l":"B","html":"イベント履歴の保持期間（90日）は変更できません。"},{"l":"C","html":"フローログは通信の記録で、誰がAPIでルールを変えたかはわかりません。"},{"l":"D","html":"Configは設定の変更履歴を記録しますが、「誰が変えたか」はCloudTrailの記録です。現在の設定を見るだけでは過去の変更者はわかりません。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.2 AWS CloudTrail</a>"},{"n":62,"topic":"過剰な性能のボリューム","level":2,"body":["Cost Explorerで、本番のアプリケーションサーバーの<b>io2ボリューム</b>の料金が高いことがわかりました。多くのボリュームは、プロビジョニングしたIOPSのごく一部しか使っていないようです。<b>アプリケーションを止めずに</b>、根拠に基づいて費用を下げたいと考えています。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"スナップショットを取得して、S3 Glacier Deep Archiveへ移す"},{"l":"B","html":"Compute OptimizerのEBSの推奨を確認し、Elastic Volumesでgp3などに変更する"},{"l":"C","html":"ボリュームを停止中にデタッチし、小さなボリュームを作り直してデータをコピーする"},{"l":"D","html":"すべてのボリュームのサイズを半分に縮小する"}],"answer":["B"],"multi":false,"req":"","key":"Compute Optimizerは、CloudWatchのメトリクス（IOPSやスループットの実績）から<b>EBSボリュームの適切なタイプと設定を推奨</b>します。推奨に従って、<b>Elastic Volumesで接続したまま</b>タイプ（io2 → gp3など）やIOPSを変更すれば、アプリケーションを止めずに費用を下げられます。","kw":"使用実績に基づく推奨 ＋ 止めずに変更 → Compute Optimizer ＋ Elastic Volumes","reasons":[{"l":"A","html":"稼働中のボリュームの料金は下がらず、アーカイブからの復元にも時間がかかります。EBSのスナップショットをGlacierのストレージクラスへ直接移す機能もありません。"},{"l":"C","html":"アプリケーションを止める必要があり、要件に反します。"},{"l":"D","html":"EBSボリュームのサイズは<b>縮小できません</b>（増やすことだけができます）。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.2 Amazon EBS</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":63,"topic":"停止中も発生する料金","level":2,"body":["開発チームは、夜間と週末に開発用のEC2インスタンスを<b>停止</b>しています。インスタンスにはEBSボリュームが付いており、一部のインスタンスにはElastic IPアドレスが関連付けられています。停止している間も<b>料金が発生するもの</b>はどれですか。（<b>2つ選択してください</b>）"],"options":[{"l":"A","html":"インスタンスに付いているEBSボリューム"},{"l":"B","html":"EC2インスタンスの使用時間"},{"l":"C","html":"Auto Scalingグループそのもの"},{"l":"D","html":"割り当てたままのElastic IPアドレス"},{"l":"E","html":"起動時に自動で割り当てられたパブリックIPv4アドレス"}],"answer":["A","D"],"multi":true,"req":"","key":"インスタンスを停止しても、<b>EBSボリュームは残るため容量の料金がかかり続けます</b>。<b>Elastic IPアドレスも、割り当てたままであれば料金がかかります</b>（パブリックIPv4アドレスは使用中かどうかにかかわらず課金されます）。不要なら、スナップショットを取ってボリュームを削除したり、Elastic IPアドレスを解放したりします。","kw":"停止しても残るもの → EBSボリューム・割り当てたままのElastic IP","reasons":[{"l":"B","html":"停止中のインスタンスには、使用時間の料金はかかりません。"},{"l":"C","html":"Auto Scalingグループ自体は無料で、料金は起動したリソースにかかります。"},{"l":"E","html":"自動で割り当てられたパブリックIPv4アドレスは、停止すると解放されるため料金はかかりません（起動し直すと別のアドレスになります）。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":64,"topic":"途中で失敗した注文の取り消し","level":2,"body":["注文の処理は、在庫の確保・決済・配送の手配の3つの手順を順に行います。途中の手順が失敗した場合は、<b>それまでに完了した手順を取り消す</b>（在庫を戻す、決済を返金する）必要があります。各手順はLambda関数で実装されています。状態の管理とエラー時の処理を<b>自分で作り込みたくありません</b>。最も適切な方法はどれですか。"],"options":[{"l":"A","html":"3つのLambda関数をSNSトピックでつなぎ、失敗時は担当者にメールで通知する"},{"l":"B","html":"1つのLambda関数から3つの関数を順に呼び出し、失敗時の取り消しもその関数に実装する"},{"l":"C","html":"Step Functionsのステートマシンで手順を定義し、Catchで失敗時に取り消しの手順へ進める"},{"l":"D","html":"3つの関数をSQSのキューでつなぎ、失敗したメッセージをデッドレターキューへ送る"}],"answer":["C"],"multi":false,"req":"","key":"Step Functionsは、手順の順序・分岐・再試行・エラー処理を<b>ステートマシンとして定義</b>できます。各手順の <b>Catch</b> で失敗を捕まえ、完了済みの手順を取り消す処理（補償トランザクション）へ進めれば、状態の管理を自前で作らずに取り消しを実現できます（Sagaパターン）。","kw":"複数の手順・失敗時の取り消し → Step Functions（Catch ＋ 補償の手順）","reasons":[{"l":"A","html":"取り消しが手作業になり、自動化されていません。"},{"l":"B","html":"状態の管理とエラー処理をすべて自分で作ることになり、呼び出し元の関数の実行時間の上限（15分）にも縛られます。"},{"l":"D","html":"失敗したメッセージを隔離するだけで、完了済みの手順の取り消しは行われません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.4 AWS Step Functions</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.4 イベント駆動型アーキテクチャ</a>"},{"n":65,"topic":"緊急の処理を先に","level":2,"body":["監視システムは、機器から届くイベントをSQSのキューに入れ、EC2のワーカーが処理しています。イベントには<b>緊急</b>と<b>通常</b>の2種類があり、緊急のイベントは、通常のイベントが大量にたまっていても<b>先に処理</b>しなければなりません。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"1つのFIFOキューを使い、緊急のイベントに別のメッセージグループIDを付ける"},{"l":"B","html":"1つの標準キューを使い、緊急のイベントの遅延秒数を0、通常のイベントの遅延秒数を最大にする"},{"l":"C","html":"緊急用と通常用の2つのキューを作り、ワーカーは緊急用のキューを先に確認する"},{"l":"D","html":"1つの標準キューを使い、緊急のイベントの可視性タイムアウトを短くする"}],"answer":["C"],"multi":false,"req":"","key":"SQSには<b>メッセージの優先度の機能がありません</b>。優先度が必要な場合は、<b>優先度ごとにキューを分け</b>、ワーカーが優先度の高いキューから先に受信するように実装します。緊急用のキューが空のときだけ通常用のキューを処理すれば、通常のイベントが大量にたまっていても緊急のイベントを先に処理できます。","kw":"SQSで優先度を付ける → 優先度ごとのキュー ＋ 高いほうから受信","reasons":[{"l":"A","html":"メッセージグループは順序を守る単位で、グループの間に優先度はありません。"},{"l":"B","html":"遅延キューは受信できるまでの時間を遅らせるだけで、最大でも15分です。通常のイベントの処理を不必要に遅らせるうえ、たまった通常のイベントより先に処理される保証もありません。"},{"l":"D","html":"可視性タイムアウトは受信した後に再び見えるまでの時間で、受信の順番には影響しません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a>"}]}];
